/// Reads an absent list, a `null` list and an empty list as the same thing: nothing.
///
/// `#[serde(default)]` alone covers only the ABSENT case, and Go's `encoding/json` writes a nil
/// slice as `null` rather than omitting it. That gap ate a real inbox: the sidecar read the mail,
/// the núcleo answered 422, and the batch replayed into the same wall every five minutes. It
/// survived the tests because the fixtures omitted the field, which is a shape the sidecar never
/// sends. There is no message these three encodings could carry that differs.
fn absent_or_null_is_empty<'de, D, T>(deserializer: D) -> Result<Vec<T>, D::Error>
where
    D: serde::Deserializer<'de>,
    T: Deserialize<'de>,
{
    Ok(Option::<Vec<T>>::deserialize(deserializer)?.unwrap_or_default())
}

/// The sidecar's delivery envelope (spec §4.3).
#[derive(Deserialize)]
struct EmailIncomingRequest {
    mailbox: String,
    uidvalidity: i64,
    /// The highest uid the sidecar LOOKED AT, which is what lets the cursor move past a message it
    /// could not read. Not the same as the highest uid delivered.
    max_uid_examined: i64,
    /// Absent, `null` and `""` all mean inbound — see `absent_or_null_is_empty` above for why the
    /// empty case has to be spelled out: Go writes an unset string field as `""` rather than
    /// omitting it, and `daemon.Batch.Direction` has no `omitempty`.
    #[serde(default)]
    direction: Option<String>,
    #[serde(default, deserialize_with = "absent_or_null_is_empty")]
    skipped: Vec<crate::email::SkippedMessage>,
    #[serde(default, deserialize_with = "absent_or_null_is_empty")]
    messages: Vec<crate::email::IncomingMessage>,
}

/// Paging belongs to the sidecar; a batch this large means it stopped doing its job, and the
/// núcleo should say so rather than quietly ingest whatever arrives.
const MAX_MESSAGES_PER_BATCH: usize = 200;

/// Body ceiling for `/email/incoming`, in bytes.
///
/// `MAX_MESSAGES_PER_BATCH` x the sidecar's 32 KiB per-body cap is ~6.4 MB of text; doubling it
/// covers subjects, addresses, headers and JSON escaping without turning the route into an
/// unbounded sink. It is a backstop, not the real limit — the count check in the handler is.
const EMAIL_BATCH_BODY_LIMIT: usize = 16 * 1024 * 1024;

/// How much of the mailbox the queue hands back. Generous because a first sync pulls a week at
/// once, and a list that silently stops at its limit is indistinguishable from mail that never
/// arrived — which is the exact confusion this pillar has already cost once.
const EMAIL_QUEUE_LIMIT: i64 = 200;

async fn get_email_cursor(
    State(state): State<AppState>,
    Query(query): Query<MailboxQuery>,
) -> Result<Json<serde_json::Value>, StatusCode> {
    let cursor = crate::email::get_cursor(&state.pool, &query.mailbox)
        .await
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    Ok(Json(match cursor {
        Some(cursor) => serde_json::json!({
            "uidvalidity": cursor.uidvalidity,
            "last_uid": cursor.last_uid,
        }),
        None => serde_json::Value::Null,
    }))
}

async fn post_email_incoming(
    State(state): State<AppState>,
    Json(body): Json<EmailIncomingRequest>,
) -> Result<Json<crate::email::IngestOutcome>, StatusCode> {
    if body.messages.len() > MAX_MESSAGES_PER_BATCH {
        return Err(StatusCode::BAD_REQUEST);
    }
    let direction = match body.direction.as_deref().map(str::trim) {
        None | Some("") => crate::contacts::MessageDirection::Inbound,
        Some(value) if value.eq_ignore_ascii_case("inbound") => {
            crate::contacts::MessageDirection::Inbound
        }
        Some(value) if value.eq_ignore_ascii_case("outbound") => {
            crate::contacts::MessageDirection::Outbound
        }
        // Defaulting would store the user's sent bodies as inbound; refusal keeps the cursor in
        // place so the retry makes the mailbox complain instead of quietly mis-filing them.
        Some(_) => return Err(StatusCode::BAD_REQUEST),
    };
    // Ingestion is one transaction over untrusted content and it moves the cursor. A client that
    // disconnects mid-request must not be able to leave that half-done.
    let pool = state.pool.clone();
    let retain_bodies_days = state.email.retain_bodies_days;
    // Resolved here and never accepted from the body, for the same reason the direction is not: a
    // sidecar that could name the owner could tell the núcleo that a stranger's message was the
    // owner's own, and `outbound_ever` is what `priority.rs` reads to lower a brake.
    let owner_address = state.email.username.clone();
    uncancellable(async move {
        crate::email::ingest_batch(
            &pool,
            direction,
            &body.mailbox,
            body.uidvalidity,
            body.max_uid_examined,
            &body.skipped,
            &body.messages,
            &owner_address,
            retain_bodies_days,
            chrono::Utc::now(),
        )
        .await
        .map(Json)
        // Logged, not discarded. `|_|` here made a failed ingest into a 500 with an empty body and
        // no line anywhere: the sidecar reported `daemon returned 500:` on every cycle, the cursor
        // stayed put, and the mailbox went eight days unread with nothing in the log to say why.
        // The message names the mailbox and the batch, because the two things worth knowing next
        // are which mailbox stalled and whether it is one message or the whole batch that cannot
        // land. It never names what a message SAYS — see `redact.rs`.
        .map_err(|error| {
            tracing::warn!(
                mailbox = %body.mailbox,
                batch = body.messages.len(),
                %error,
                "email ingest failed — the cursor stays put and the sidecar will retry"
            );
            StatusCode::INTERNAL_SERVER_ERROR
        })
    })
    .await?
}

/// Triage what is waiting, now.
///
/// Reading the mailbox happens on its own because it is free; spending a run does not. This is the
/// request — so it launches a batch immediately rather than raising a flag and waiting up to a
/// minute for the loop's own tick to notice.
///
/// It answers with what it started, not with verdicts: a run takes minutes, and holding an HTTP
/// request open for it would only make the caller's timeout the deadline for the mail.
async fn post_email_triage(
    State(state): State<AppState>,
) -> Result<Json<crate::triage::TriageOutcome>, StatusCode> {
    if !state.email.armed.load(std::sync::atomic::Ordering::Relaxed) {
        // Not an error the caller can fix by retrying: the pillar is off, or its barrier failed
        // verification at startup and it is deliberately staying off.
        return Ok(Json(crate::triage::TriageOutcome {
            queued: 0,
            run_id: None,
            reason: Some("the email pillar is not armed".to_string()),
        }));
    }

    // Launching writes a claim across the batch's rows; a client that disconnects must not leave
    // that half-written.
    let state = state.clone();
    uncancellable(async move {
        let mut loop_state = crate::triage::LoopState::default();
        crate::triage::triage_now(&state, &mut loop_state, chrono::Utc::now()).await
    })
    .await
    .map(Json)
}

#[derive(serde::Serialize, sqlx::FromRow)]
struct QueuedEmail {
    id: i64,
    from_addr: String,
    from_name: Option<String>,
    subject: Option<String>,
    received_at: String,
    triage_class: Option<String>,
    triage_summary: Option<String>,
    triaged_at: Option<String>,
    has_attachments: i64,
    /// The standing human decision about this sender — `pin`, `mute`, or none.
    ///
    /// Carried on the row rather than fetched per sender, because it is what the button in the list
    /// has to be drawn from: without it every row would have to ask separately, and a list of forty
    /// messages would open forty requests to render forty small pieces of state.
    sender_verdict: Option<String>,
}

/// How many correspondents the roster returns. Enough to find anyone; short enough to draw.
const CONTACTS_LIMIT: i64 = 200;

/// Who writes to you, busiest first, with each one's standing decision.
///
/// `contacts.rs` has recorded this since it existed — every inbound message updates a count and a
/// last-seen, and `priority.rs` reads it to tell a stranger from someone you know. None of it was
/// readable: the module still carries `#[allow(dead_code)]` on three fields "consumed by the later
/// contact display surface", and this is that surface for the part that is actually finished.
///
/// Deliberately NOT the merged view. `propose_merges` and `merge` exist and nothing in production
/// calls either, so two addresses belonging to one person are still two rows — and reporting them
/// as one would be reporting a judgement nobody has made.
async fn get_contacts(
    State(state): State<AppState>,
) -> Result<Json<Vec<crate::contacts::Correspondent>>, StatusCode> {
    crate::contacts::roster(&state.pool, CONTACTS_LIMIT)
        .await
        .map(Json)
        .map_err(|error| {
            tracing::warn!(%error, "reading the contact roster failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })
}

/// The things departments have asked for and nobody has answered yet.
///
/// A door of its own rather than a slice of `/proposals`, which filters to `action-approval` and
/// would need widening — and widening it would put two decisions with the same button next to each
/// other: one resumes a paused run holding a worktree, the other authorises an email from a
/// department that finished hours ago. `list_skipped_items` split off for exactly this reason.
async fn get_team_action_proposals(
    State(state): State<AppState>,
) -> Result<Json<Vec<crate::proposals::Proposal>>, StatusCode> {
    crate::proposals::list_pending_team_actions(&state.pool)
        .await
        .map(Json)
        .map_err(|error| {
            tracing::warn!(%error, "reading pending team actions failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })
}

/// The specialists directors asked for and nobody has answered.
///
/// A fourth door, and separate for the reason the third is: the button says "Hire", not "Approve",
/// because what it does is different from the rest of the queue — and unlike every other proposal
/// in the house, this one is EDITABLE at the moment of decision. Sharing a list with things that
/// are not editable would mean one form that pretends the fields are read-only half the time.
async fn get_recruit_proposals(
    State(state): State<AppState>,
) -> Result<Json<Vec<crate::proposals::Proposal>>, StatusCode> {
    crate::proposals::list_pending_recruits(&state.pool, None)
        .await
        .map(Json)
        .map_err(|error| {
            tracing::warn!(%error, "reading pending recruitments failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })
}

/// Suggestions that two addresses are one person, waiting on an answer.
///
/// Its own route rather than a slice of `/proposals`, because the two kinds share a table and
/// nothing else — see `contacts::pending_merges`. It also puts the question where the context is:
/// deciding whether two addresses are the same person is a thing you do while looking at your
/// correspondents, not while looking at a queue of paused runs.
async fn get_contact_merges(
    State(state): State<AppState>,
) -> Result<Json<Vec<crate::contacts::MergeSuggestion>>, StatusCode> {
    crate::contacts::pending_merges(&state.pool)
        .await
        .map(Json)
        .map_err(|error| {
            tracing::warn!(%error, "reading pending contact merges failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })
}

#[derive(Deserialize)]
struct UnmergeRequest {
    address: String,
}

/// Splits one address back out into a person of its own.
///
/// The undo for an approved merge, and the reason approving one is a safe thing to offer: the join
/// is a pointer move, so undoing it restores exactly what was there — counters included, since a
/// merge never moved them. Without this route the merge was still exact and still undoable in
/// principle, and unreachable in practice.
///
/// Answers 204 whether or not the address was merged with anything. Splitting an address that is
/// already alone is the state the caller asked for, and a caller that had to tell those apart would
/// be handling somebody else's bookkeeping.
async fn post_contact_unmerge(
    State(state): State<AppState>,
    Json(body): Json<UnmergeRequest>,
) -> Result<StatusCode, StatusCode> {
    let known: Option<i64> =
        sqlx::query_scalar("SELECT 1 FROM contact_addresses WHERE address = ?")
            .bind(crate::contacts::normalize_address(&body.address))
            .fetch_optional(&state.pool)
            .await
            .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    if known.is_none() {
        return Err(StatusCode::NOT_FOUND);
    }

    crate::contacts::unmerge(&state.pool, &body.address)
        .await
        .map(|()| StatusCode::NO_CONTENT)
        .map_err(|error| {
            tracing::warn!(%error, "splitting a contact failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })
}

#[derive(Deserialize)]
struct SenderVerdictRequest {
    address: String,
    /// `pin`, `mute`, or `null` to withdraw the decision entirely.
    verdict: Option<String>,
}

/// Records what a person has decided about a sender, once, for all their future mail.
///
/// This is the only writer of `contact_overrides` outside a test. The table has been read by
/// `priority::adjust` since it existed — a pin outranks the model and a mute outranks it the other
/// way — so until now the highest-authority rule in triage was one nothing could set.
///
/// An unknown verdict is refused rather than stored. `priority::adjust` falls through for anything
/// it does not recognise, which means a typo would be accepted, saved, and then do nothing at all
/// for as long as it sat there; a 400 now is the only moment that mistake is visible.
///
/// An address nobody has written from is a 404 for a related reason: a contact exists because mail
/// arrived, and inventing one here would let a mistyped address become a permanent row that never
/// matches anything and never explains why.
async fn post_sender_verdict(
    State(state): State<AppState>,
    Json(body): Json<SenderVerdictRequest>,
) -> Result<StatusCode, StatusCode> {
    if let Some(verdict) = body.verdict.as_deref()
        && !crate::priority::is_known_verdict(verdict)
    {
        return Err(StatusCode::BAD_REQUEST);
    }

    match crate::contacts::set_verdict(&state.pool, &body.address, body.verdict.as_deref()).await {
        Ok(crate::contacts::VerdictOutcome::Applied) => Ok(StatusCode::NO_CONTENT),
        Ok(crate::contacts::VerdictOutcome::UnknownAddress) => Err(StatusCode::NOT_FOUND),
        Err(error) => {
            tracing::warn!(%error, "recording a sender verdict failed");
            Err(StatusCode::INTERNAL_SERVER_ERROR)
        }
    }
}

/// One attachment, described. The bytes are not here and are not stored (migration 0021).
#[derive(serde::Serialize, sqlx::FromRow)]
struct EmailAttachment {
    position: i64,
    filename: Option<String>,
    mime_type: Option<String>,
    size_bytes: i64,
}

/// One message in full.
///
/// Separate from the queue's row because the body is the expensive and sensitive half: a mailbox
/// list has no business carrying a mailbox's worth of third-party text, and this way opening a
/// message is the moment that text is read out of the database, not a side effect of drawing a list.
#[derive(serde::Serialize, sqlx::FromRow)]
struct EmailDetail {
    id: i64,
    from_addr: String,
    from_name: Option<String>,
    subject: Option<String>,
    received_at: String,
    triage_class: Option<String>,
    triage_summary: Option<String>,
    triaged_at: Option<String>,
    /// What the model answered; NULL when the row was never triaged.
    model_class: Option<String>,
    /// Which rule decided the stored class; NULL when none fired or the row was never triaged.
    priority_rule: Option<String>,
    /// NULL once retention has pruned it (§7.2), which is a state the reader must show rather than
    /// mistake for an empty message.
    body_text: Option<String>,
    has_attachments: i64,
    /// The standing human decision about this sender — `pin`, `mute`, or none — the same field the
    /// queue row carries. The message page is where that decision is changed, and a control that
    /// cannot show which way it is set can only be pressed blind.
    sender_verdict: Option<String>,
}

#[derive(serde::Serialize)]
struct EmailDetailResponse {
    #[serde(flatten)]
    message: EmailDetail,
    attachments: Vec<EmailAttachment>,
}

/// One message, body included — what "open the mail" reads.
async fn get_email(
    State(state): State<AppState>,
    Path(id): Path<i64>,
) -> Result<Json<EmailDetailResponse>, StatusCode> {
    let mut message: EmailDetail = sqlx::query_as(
        "SELECT id, from_addr, from_name, subject, received_at, triage_class, triage_summary,
                triaged_at, model_class, priority_rule, body_text, has_attachments,
                NULL AS sender_verdict
           FROM emails WHERE id = ?",
    )
    .bind(id)
    .fetch_optional(&state.pool)
    .await
    .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?
    .ok_or(StatusCode::NOT_FOUND)?;

    // Matched through `contacts::normalize_address`, for the reason `get_email_queue` gives: one
    // definition of "the same sender", applied in Rust, rather than a second one written in SQL.
    message.sender_verdict = sqlx::query_scalar(
        "SELECT overrides.verdict
           FROM contact_overrides AS overrides
           JOIN contact_addresses AS addresses
             ON addresses.contact_id = overrides.contact_id
          WHERE addresses.address = ?",
    )
    .bind(crate::contacts::normalize_address(&message.from_addr))
    .fetch_optional(&state.pool)
    .await
    .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;

    let attachments: Vec<EmailAttachment> = sqlx::query_as(
        "SELECT position, filename, mime_type, size_bytes
           FROM email_attachments WHERE email_id = ? ORDER BY position",
    )
    .bind(id)
    .fetch_all(&state.pool)
    .await
    .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;

    Ok(Json(EmailDetailResponse {
        message,
        attachments,
    }))
}

/// How long the núcleo waits for the sidecar to go and get a file. Generous because the sidecar
/// opens a fresh TLS connection and may be fetching 25 MB over someone's home connection.
const ATTACHMENT_TIMEOUT: std::time::Duration = std::time::Duration::from_secs(120);

/// PURE: builds a `Content-Disposition` for a filename chosen by a stranger.
///
/// Always `attachment`, never `inline`: the bytes came from outside and nothing renders them in
/// place. The name goes out twice — a conservative ASCII form for old clients and the RFC 6266
/// `filename*` form for everything else — and both are built from `safe_filename`'s output, so a
/// name carrying a carriage return cannot end this header and begin one of the sender's choosing.
fn content_disposition(filename: &str) -> String {
    let safe = crate::email::safe_filename(filename);
    // The quoted form cannot carry a quote or a backslash without escaping them, and a filename is
    // not worth the escaping rules — anything outside a plain set becomes an underscore, and the
    // faithful version travels in `filename*` alongside it.
    let ascii: String = safe
        .chars()
        .map(|c| {
            if c.is_ascii_alphanumeric() || matches!(c, '.' | '_' | '-') {
                c
            } else {
                '_'
            }
        })
        .collect();
    let mut encoded = String::with_capacity(safe.len());
    for byte in safe.as_bytes() {
        if byte.is_ascii_alphanumeric() || matches!(byte, b'.' | b'_' | b'-' | b'~') {
            encoded.push(*byte as char);
        } else {
            encoded.push_str(&format!("%{byte:02X}"));
        }
    }
    format!("attachment; filename=\"{ascii}\"; filename*=UTF-8''{encoded}")
}

/// One attachment's bytes, fetched from the mailbox at the moment they are asked for.
///
/// Nothing is cached on the way through. The file exists in exactly one place — the mailbox it
/// arrived in — and keeping a copy would mean a stranger's executable sitting on disk because
/// someone once clicked a filename.
async fn get_email_attachment(
    State(state): State<AppState>,
    Path((id, position)): Path<(i64, i64)>,
) -> Result<axum::response::Response, StatusCode> {
    let (bytes, filename) = fetch_attachment(&state, id, position).await?;

    Ok((
        [
            (
                axum::http::header::CONTENT_TYPE,
                "application/octet-stream".to_string(),
            ),
            (
                axum::http::header::CONTENT_DISPOSITION,
                content_disposition(&filename),
            ),
        ],
        bytes,
    )
        .into_response())
}

/// One attachment as the sidecar hands it over in bulk.
#[derive(serde::Deserialize, serde::Serialize)]
struct BulkAttachment {
    position: i64,
    #[serde(default)]
    filename: Option<String>,
    #[serde(default)]
    mime_type: Option<String>,
    size_bytes: i64,
    content_base64: String,
    /// True when `content_base64` is only the first part of the file (`size_bytes` is the true
    /// size). Absent from older sidecars, which means complete.
    #[serde(default)]
    truncated: bool,
}

/// Every attachment of one message, read in a single pass over the mailbox.
///
/// One route rather than the caller looping, because each single fetch downloads the WHOLE message:
/// a loop over eight attachments pulled the same eight files eight times, over eight connections.
async fn get_email_attachments(
    State(state): State<AppState>,
    Path(id): Path<i64>,
) -> Result<Json<Vec<BulkAttachment>>, StatusCode> {
    fetch_all_attachments(&state, id).await.map(Json)
}

async fn fetch_all_attachments(
    state: &AppState,
    id: i64,
) -> Result<Vec<BulkAttachment>, StatusCode> {
    let uid: Option<i64> = sqlx::query_scalar("SELECT uid FROM emails WHERE id = ?")
        .bind(id)
        .fetch_optional(&state.pool)
        .await
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    let uid = uid.ok_or(StatusCode::NOT_FOUND)?;

    let client = reqwest::Client::builder()
        .timeout(ATTACHMENT_TIMEOUT)
        .build()
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    let response = client
        .get(format!(
            "http://{}/attachments?uid={uid}",
            crate::sidecar::EMAIL_FETCH_ADDR
        ))
        .bearer_auth(&state.token.0)
        .send()
        .await
        .map_err(|_| StatusCode::BAD_GATEWAY)?;
    if !response.status().is_success() {
        return Err(StatusCode::BAD_GATEWAY);
    }
    response
        .json::<Vec<BulkAttachment>>()
        .await
        .map_err(|_| StatusCode::BAD_GATEWAY)
}

#[derive(serde::Serialize)]
struct SaveAllOutcome {
    folder: String,
    /// The names actually stored, in the order the message carries them.
    filenames: Vec<String>,
}

/// Files every attachment of one message into a folder.
///
/// Partial success is not a state this reports: the write happens after all the bytes are in hand,
/// so the failure that matters — the mailbox being unreachable — happens before anything lands.
/// What can still fail per file is the disk, and a folder holding three of eight files with no word
/// about the other five is worse than a refusal.
async fn post_email_attachments_save_all(
    State(state): State<AppState>,
    Path(id): Path<i64>,
    Json(body): Json<SaveAttachmentRequest>,
) -> Result<Json<SaveAllOutcome>, StatusCode> {
    let root = files_root(&state)?.to_path_buf();
    let attachments = fetch_all_attachments(&state, id).await?;
    // A cut-off file would be filed as if it were whole. Refuse before anything is written, in the
    // same spirit as the no-partial-success rule above.
    if attachments.iter().any(|a| a.truncated) {
        return Err(StatusCode::PAYLOAD_TOO_LARGE);
    }

    let decoded: Vec<(String, Vec<u8>)> = attachments
        .into_iter()
        .map(|attachment| {
            use base64::Engine;
            let bytes = base64::engine::general_purpose::STANDARD
                .decode(&attachment.content_base64)
                .map_err(|_| StatusCode::BAD_GATEWAY)?;
            Ok((attachment.filename.unwrap_or_default(), bytes))
        })
        .collect::<Result<_, StatusCode>>()?;

    let saved = uncancellable(async move {
        tokio::task::spawn_blocking(move || {
            let mut filenames = Vec::with_capacity(decoded.len());
            for (filename, bytes) in &decoded {
                filenames.push(crate::files::write_file(
                    &root,
                    &body.folder,
                    filename,
                    bytes,
                )?);
            }
            Ok::<_, crate::files::PathError>(SaveAllOutcome {
                folder: body.folder,
                filenames,
            })
        })
        .await
    })
    .await?
    .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;

    saved.map(Json).map_err(folder_status)
}

/// Asks the sidecar for one attachment's bytes, and reports the name it was described under.
///
/// Shared by the route that hands a file to a person and the one that files it into a folder,
/// because those must never diverge on WHICH file they mean.
async fn fetch_attachment(
    state: &AppState,
    id: i64,
    position: i64,
) -> Result<(Vec<u8>, String), StatusCode> {
    let row: Option<(i64, Option<String>)> = sqlx::query_as(
        "SELECT emails.uid, email_attachments.filename
           FROM email_attachments
           JOIN emails ON emails.id = email_attachments.email_id
          WHERE email_attachments.email_id = ? AND email_attachments.position = ?",
    )
    .bind(id)
    .bind(position)
    .fetch_optional(&state.pool)
    .await
    .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    let (uid, filename) = row.ok_or(StatusCode::NOT_FOUND)?;

    let client = reqwest::Client::builder()
        .timeout(ATTACHMENT_TIMEOUT)
        .build()
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    let response = client
        .get(format!(
            "http://{}/attachment?uid={uid}&position={position}",
            crate::sidecar::EMAIL_FETCH_ADDR
        ))
        .bearer_auth(&state.token.0)
        .send()
        .await
        // The sidecar not answering is not the same as the file not existing, and telling a person
        // "not found" when the truth is "nothing went to look" sends them hunting in the mailbox.
        .map_err(|_| StatusCode::BAD_GATEWAY)?;

    if !response.status().is_success() {
        return Err(if response.status() == reqwest::StatusCode::NOT_FOUND {
            // The stored description and the live message disagree: the mail was deleted or
            // replaced since it was read.
            StatusCode::NOT_FOUND
        } else if response.status() == reqwest::StatusCode::PAYLOAD_TOO_LARGE {
            // The attachment is over the sidecar's cap and it refused to hand over a cut-off file.
            StatusCode::PAYLOAD_TOO_LARGE
        } else {
            StatusCode::BAD_GATEWAY
        });
    }

    let bytes = response
        .bytes()
        .await
        .map_err(|_| StatusCode::BAD_GATEWAY)?;

    Ok((bytes.to_vec(), filename.unwrap_or_default()))
}

/// Turns a folder refusal into a status. `Escapes` and `Unsafe` are both 400: the request named
/// something it may not name, and which of the two rules caught it is not the caller's business —
/// a distinction here would be a probe for how the guard is built.
///
/// The three 409s are not one answer either, and they do not need to be: a caller knows which of
/// the four operations it just asked for, so "conflict" reads as one sentence per route — this is
/// not a folder, this name is taken, this folder still has things in it.
fn folder_status(error: crate::files::PathError) -> StatusCode {
    use crate::files::PathError;
    match error {
        PathError::Escapes | PathError::Unsafe => StatusCode::BAD_REQUEST,
        PathError::NotFound => StatusCode::NOT_FOUND,
        PathError::NotADirectory | PathError::NotEmpty | PathError::Exists => StatusCode::CONFLICT,
        PathError::Io(_) => StatusCode::INTERNAL_SERVER_ERROR,
    }
}

/// The trash beside the root, or the same 503 when startup could not make it. A delete with no
/// trash refuses rather than removing for good — see `AppState::files_trash`.
fn files_trash(state: &AppState) -> Result<&std::path::Path, StatusCode> {
    state
        .files_trash
        .as_deref()
        .ok_or(StatusCode::SERVICE_UNAVAILABLE)
}

#[derive(Deserialize)]
struct FolderQuery {
    /// Relative to the root. Absent means the root itself.
    #[serde(default)]
    path: String,
}

async fn get_files(
    State(state): State<AppState>,
    Query(query): Query<FolderQuery>,
) -> Result<Json<Vec<crate::files::Entry>>, StatusCode> {
    let root = files_root(&state)?;
    crate::files::list(root, &query.path)
        .map(Json)
        .map_err(folder_status)
}

#[derive(Deserialize)]
struct CreateFolderRequest {
    path: String,
}

async fn post_files_folder(
    State(state): State<AppState>,
    Json(body): Json<CreateFolderRequest>,
) -> Result<StatusCode, StatusCode> {
    let root = files_root(&state)?;
    crate::files::create_folder(root, &body.path)
        .map(|()| StatusCode::CREATED)
        .map_err(folder_status)
}

#[derive(Deserialize)]
struct SearchQuery {
    /// Where the walk starts. Absent means the root itself.
    #[serde(default)]
    path: String,
    q: String,
}

/// Finds entries by name, in one folder and everything under it.
///
/// A folder this size is searched by walking it — there is no index, and building one would be a
/// second copy of the truth to keep honest. The ceilings live in `files::search`, and the answer
/// says when one of them cut in rather than passing a partial result off as the whole.
async fn get_files_search(
    State(state): State<AppState>,
    Query(query): Query<SearchQuery>,
) -> Result<Json<crate::files::Found>, StatusCode> {
    let root = files_root(&state)?.to_path_buf();

    // Off the async runtime: a deep tree is a long blocking walk, and holding a runtime thread for
    // it would stall every other request on that thread.
    let found =
        tokio::task::spawn_blocking(move || crate::files::search(&root, &query.path, &query.q))
            .await
            .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;

    found.map(Json).map_err(folder_status)
}

/// Hands back one file's bytes, streamed rather than gathered.
///
/// `attachment`, never `inline`, and `application/octet-stream` whatever the extension says — the
/// same rule the attachment route follows, and for a stronger reason: half of what is in this
/// folder arrived as mail from a stranger, and a webview asked to render it in place would be
/// executing a file this system exists to keep at arm's length.
async fn get_file_download(
    State(state): State<AppState>,
    Query(query): Query<FolderQuery>,
) -> Result<axum::response::Response, StatusCode> {
    let root = files_root(&state)?;
    let target = crate::files::resolve_file(root, &query.path).map_err(folder_status)?;

    // The name comes off the resolved path, not the query string: `resolve_within` has already
    // decided the last component is a name a filesystem carries, and `content_disposition` makes it
    // safe for a header again.
    let filename = target
        .file_name()
        .and_then(|name| name.to_str())
        .unwrap_or("file")
        .to_string();

    let file = tokio::fs::File::open(&target)
        .await
        // Gone between resolving and opening: rare, and it is the same answer as never having been
        // there.
        .map_err(|_| StatusCode::NOT_FOUND)?;
    let length = file.metadata().await.ok().map(|metadata| metadata.len());

    let mut headers = axum::http::HeaderMap::new();
    headers.insert(
        axum::http::header::CONTENT_TYPE,
        axum::http::HeaderValue::from_static("application/octet-stream"),
    );
    headers.insert(
        axum::http::header::CONTENT_DISPOSITION,
        axum::http::HeaderValue::from_str(&content_disposition(&filename))
            .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?,
    );
    if let Some(length) = length {
        headers.insert(axum::http::header::CONTENT_LENGTH, length.into());
    }

    let stream = tokio_util::io::ReaderStream::new(file);
    Ok((headers, axum::body::Body::from_stream(stream)).into_response())
}

#[derive(Deserialize)]
struct UploadQuery {
    /// Which folder under the root. Absent means the root itself.
    #[serde(default)]
    folder: String,
    /// What the browser called the file. Made safe on the way to disk, like a sender's name is.
    filename: String,
}

/// The other way bytes enter this folder: a person picking a file of their own.
///
/// It goes through the same `write_file` as filing an attachment — same name rule, same numbered
/// collisions — because the folder's guarantee is about the folder, not about who is writing. The
/// stored name is reported back for the same reason it is there: it can differ from what was sent.
async fn post_file_upload(
    State(state): State<AppState>,
    Query(query): Query<UploadQuery>,
    bytes: axum::body::Bytes,
) -> Result<Json<SavedFile>, StatusCode> {
    let root = files_root(&state)?.to_path_buf();

    // Blocking file I/O off the async runtime, and uncancellable for the same reason as filing: a
    // client that disconnects mid-write must not leave half a file under a name that says it is
    // whole.
    let saved = uncancellable(async move {
        tokio::task::spawn_blocking(move || {
            crate::files::write_file(&root, &query.folder, &query.filename, &bytes).map(|stored| {
                SavedFile {
                    filename: stored,
                    folder: query.folder,
                }
            })
        })
        .await
    })
    .await?
    .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;

    saved.map(Json).map_err(folder_status)
}

#[derive(Deserialize)]
struct MoveRequest {
    from: String,
    to: String,
}

/// Renames or moves one entry. Both ends are resolved against the root, so neither can name a
/// destination outside it.
async fn post_files_move(
    State(state): State<AppState>,
    Json(body): Json<MoveRequest>,
) -> Result<StatusCode, StatusCode> {
    let root = files_root(&state)?.to_path_buf();

    let moved = uncancellable(async move {
        tokio::task::spawn_blocking(move || crate::files::move_entry(&root, &body.from, &body.to))
            .await
    })
    .await?
    .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;

    moved
        .map(|()| StatusCode::NO_CONTENT)
        .map_err(folder_status)
}

#[derive(Deserialize)]
struct DeleteQuery {
    path: String,
    /// Required to remove a folder that still has something in it — see `files::delete`.
    #[serde(default)]
    recursive: bool,
}

/// Moves one entry into the trash and answers with what was moved — the `id` is what an undo, or a
/// restore from the "Recently deleted" list later, sends back. 200 with a body rather than the 204
/// it was while this removed for good: the caller now has something to keep.
async fn delete_file(
    State(state): State<AppState>,
    Query(query): Query<DeleteQuery>,
) -> Result<Json<crate::files::Trashed>, StatusCode> {
    let root = files_root(&state)?.to_path_buf();
    let trash = files_trash(&state)?.to_path_buf();

    let deleted = uncancellable(async move {
        tokio::task::spawn_blocking(move || {
            crate::files::delete(&root, &trash, &query.path, query.recursive)
        })
        .await
    })
    .await?
    .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;

    deleted.map(Json).map_err(folder_status)
}

/// What can still be brought back, newest first. Blocking work off the runtime like search: it
/// reads one small record per entry, and a trash holds up to thirty days of deletes.
async fn get_files_trash(
    State(state): State<AppState>,
) -> Result<Json<Vec<crate::files::Trashed>>, StatusCode> {
    let trash = files_trash(&state)?.to_path_buf();
    tokio::task::spawn_blocking(move || crate::files::list_trash(&trash))
        .await
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?
        .map(Json)
        .map_err(folder_status)
}

#[derive(Deserialize)]
struct RestoreRequest {
    /// An id from `DELETE /files` or `GET /files/trash`, and nothing else — `files::restore`
    /// refuses anything not shaped like one before it touches a path.
    id: String,
}

#[derive(serde::Serialize)]
struct Restored {
    /// Where it is again, relative to the root: the recorded path, which the shell can open.
    path: String,
}

/// Puts one trashed entry back where it was. A taken name is 409 and a folder that is no longer
/// there is 404 — both leave the entry in the trash, so the caller can make room and ask again.
/// Uncancellable like a move, for the same reason: a restore half-observed by a dropped connection
/// has still happened.
async fn post_files_restore(
    State(state): State<AppState>,
    Json(body): Json<RestoreRequest>,
) -> Result<Json<Restored>, StatusCode> {
    let root = files_root(&state)?.to_path_buf();
    let trash = files_trash(&state)?.to_path_buf();

    let restored = uncancellable(async move {
        tokio::task::spawn_blocking(move || crate::files::restore(&root, &trash, &body.id)).await
    })
    .await?
    .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;

    restored
        .map(|path| Json(Restored { path }))
        .map_err(folder_status)
}

#[derive(Deserialize)]
struct SaveAttachmentRequest {
    /// Which folder under the root. Empty means the root itself.
    #[serde(default)]
    folder: String,
}

#[derive(serde::Serialize)]
struct SavedFile {
    /// The name it was ACTUALLY stored under, which can differ from the one it arrived with twice
    /// over: once because the name was made safe, once because it collided. True of a sender's
    /// attachment and of a file the user picked themselves — this is the answer to "where did it
    /// go", and guessing it is how a caller ends up naming a file that is not there.
    filename: String,
    folder: String,
}

/// Fetches an attachment and files it into the folder — the one path where a stranger's bytes are
/// written to this disk, and it happens because a person asked for it by name.
async fn post_email_attachment_save(
    State(state): State<AppState>,
    Path((id, position)): Path<(i64, i64)>,
    Json(body): Json<SaveAttachmentRequest>,
) -> Result<Json<SavedFile>, StatusCode> {
    let root = files_root(&state)?.to_path_buf();
    let (bytes, filename) = fetch_attachment(&state, id, position).await?;

    // Blocking file I/O off the async runtime, and uncancellable: a client that disconnects
    // mid-write must not leave half a file behind under a name that says it is whole.
    let saved = uncancellable(async move {
        tokio::task::spawn_blocking(move || {
            crate::files::write_file(&root, &body.folder, &filename, &bytes).map(|stored| {
                SavedFile {
                    filename: stored,
                    folder: body.folder,
                }
            })
        })
        .await
    })
    .await?
    .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;

    saved.map(Json).map_err(folder_status)
}

/// The mail the pillar knows about: what is waiting, and what it most recently said.
#[derive(Deserialize)]
struct EmailQueueQuery {
    q: Option<String>,
}

async fn get_email_queue(
    State(state): State<AppState>,
    Query(query): Query<EmailQueueQuery>,
) -> Result<Json<Vec<QueuedEmail>>, StatusCode> {
    // Newest arrival first — the order a mailbox is read in. Deliberately NOT by triage time: a
    // verdict landing now would otherwise drag a week-old message to the top, and a list that
    // reorders itself while you read it is one you lose your place in. Waiting mail is marked
    // rather than floated for the same reason; the count and the button live above the list.
    //
    // This list is the mail that came in. The user's own sent mail is held for what it says about a
    // correspondent, not read back to them; filtering it also stops sent mail consuming
    // `EMAIL_QUEUE_LIMIT` slots.
    //
    // Sorting `received_at` as text is a chronological sort because the sidecar normalises the
    // server's INTERNALDATE to UTC (`...Z`), so every value shares one offset. `id` breaks ties
    // within a second, which a bulk delivery produces routinely.
    //
    // `failed` sorts with the rest rather than being hidden: it is the class most likely to be
    // requeued, so it is the one that must stay findable.
    // Searching narrows this list rather than being a list of its own, so the ordering, the limit
    // and the `inbound` filter above are stated once and hold either way. 0058 indexes only what
    // survives triage — sender, subject, and the locally-written summary — so a search for a word
    // that was only ever in a body finds nothing, which is the correct answer once the body is gone
    // rather than a gap in the index.
    let search = query
        .q
        .as_deref()
        .map(str::trim)
        .filter(|q| !q.is_empty())
        .map(|q| (q.to_string(), crate::search::fts_query(q)));

    let mut builder = sqlx::QueryBuilder::<sqlx::Sqlite>::new(
        "SELECT id, from_addr, from_name, subject, received_at, triage_class, triage_summary,
                triaged_at, has_attachments, NULL AS sender_verdict
           FROM emails
          WHERE direction = 'inbound'",
    );
    if let Some((raw, fts)) = &search {
        builder
            .push(" AND (subject LIKE ")
            .push_bind(format!("%{}%", crate::search::escape_like(raw)))
            .push(" ESCAPE '\\' OR from_addr LIKE ")
            .push_bind(format!("%{}%", crate::search::escape_like(raw)))
            .push(" ESCAPE '\\'");
        if fts.is_empty() {
            builder.push(" OR 0");
        } else {
            builder
                .push(" OR id IN (SELECT rowid FROM emails_fts WHERE emails_fts MATCH ")
                .push_bind(fts)
                .push(")");
        }
        builder.push(")");
    }
    builder
        .push(" ORDER BY received_at DESC, id DESC LIMIT ")
        .push_bind(EMAIL_QUEUE_LIMIT);

    let mut queue = builder
        .build_query_as::<QueuedEmail>()
        .fetch_all(&state.pool)
        .await
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;

    // Filled in afterwards rather than joined in SQL, because matching `emails.from_addr` to a
    // contact means applying `contacts::normalize_address` — which strips a display name's angle
    // brackets as well as lowercasing. Writing that as `LOWER(TRIM(...))` in the query would be a
    // second, subtly different definition of the same rule, and it would disagree exactly for the
    // senders whose header carries a name. One definition, applied here.
    //
    // The set is every address whose contact carries a standing verdict — only what a human pinned
    // or muted, so it is small regardless of how much mail there is.
    let overrides: Vec<(String, String)> = sqlx::query_as(
        "SELECT addresses.address, overrides.verdict
           FROM contact_overrides AS overrides
           JOIN contact_addresses AS addresses
             ON addresses.contact_id = overrides.contact_id",
    )
    .fetch_all(&state.pool)
    .await
    .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    let by_address: std::collections::HashMap<String, String> = overrides.into_iter().collect();
    for message in &mut queue {
        message.sender_verdict = by_address
            .get(&crate::contacts::normalize_address(&message.from_addr))
            .cloned();
    }

    Ok(Json(queue))
}

async fn post_email_requeue(
    State(state): State<AppState>,
    Path(id): Path<i64>,
) -> Result<StatusCode, StatusCode> {
    use crate::email::RequeueError;
    let pool = state.pool.clone();
    uncancellable(async move { crate::email::requeue(&pool, id).await })
        .await?
        .map(|()| StatusCode::NO_CONTENT)
        .map_err(|error| match error {
            RequeueError::UnknownEmail => StatusCode::NOT_FOUND,
            RequeueError::BodyPurged | RequeueError::ClaimedByRun(_) => StatusCode::CONFLICT,
        })
}

async fn post_assistant_message(
    State(state): State<AppState>,
    Json(body): Json<AssistantMessageRequest>,
) -> Result<Json<serde_json::Value>, (StatusCode, Json<serde_json::Value>)> {
    // Uncancellable for the same reason `create_run` is: `send_message` writes the turn's `running`
    // row and only then spawns the task that will finish it. A client that disconnects mid-request
    // drops this future exactly the way `abort()` drops a run's, and a drop landing between those
    // two leaves a `running` assistant row with no task and no abort handle — `/assistant/{id}`
    // reports it running forever and `/cancel` answers 404. The Telegram sidecar is the caller, and
    // it gives up on a turn after a timeout, so the disconnect is routine rather than theoretical.
    let wait = body.wait_if_busy;
    let outcome = uncancellable(async move {
        let origin = crate::assistant::Origin::from_wire(body.origin.as_deref());
        // The window's shape becomes the runner's here, at the edge, so nothing inside the daemon
        // has to know what a request body looks like.
        let images: Vec<crate::runner::Attachment> = body
            .images
            .into_iter()
            .map(|image| crate::runner::Attachment {
                media_type: image.media_type,
                data: image.data,
            })
            .collect();
        match wait {
            true => {
                crate::assistant::send_or_queue(&state, &body.chat_id, &body.text, &images, origin)
                    .await
            }
            false => crate::assistant::send_message_with(
                &state,
                &body.chat_id,
                &body.text,
                &images,
                origin,
            )
            .await
            .map(crate::assistant::Sent::Turn),
        }
    })
    .await
    .map_err(|status| refusal(status, "internal"))?;

    match outcome {
        Ok(crate::assistant::Sent::Turn(turn_id)) => {
            Ok(Json(serde_json::json!({ "turn_id": turn_id })))
        }
        // Not a turn id and not a refusal: the words were kept and will be sent without anybody
        // pressing anything again. `queued` rather than a null id, because a caller has something
        // different to do about each and a null says neither.
        Ok(crate::assistant::Sent::Queued) => Ok(Json(serde_json::json!({ "queued": true }))),
        // Clears by waiting, which is what makes it the one refusal here that needs no gesture from
        // anybody — and what makes it dangerous to confuse with the one below.
        Err(msg) if msg == crate::assistant::TURN_IN_PROGRESS => {
            Err(refusal(StatusCode::CONFLICT, "turn_in_progress"))
        }
        // Not a 500: nothing broke. The conversation asked to be answered on this machine and this
        // machine has nothing that can — a fact about how it is configured, which the caller can
        // act on by choosing the other model. A 500 would send them looking for a crash.
        Err(msg) if msg == crate::assistant::NO_LOCAL_MODEL => {
            Err(refusal(StatusCode::SERVICE_UNAVAILABLE, "no_local_model"))
        }
        // The hosted route's twin of the arm above, 503 for the same reason and with a slug of
        // its own: both say "this machine cannot answer that", and what to DO about each is
        // different — one is fixed by installing a model, this one by naming one in the config.
        Err(msg) if msg == crate::assistant::NO_HOSTED_MODEL => {
            Err(refusal(StatusCode::SERVICE_UNAVAILABLE, "no_hosted_model"))
        }
        // Half-configured rather than unconfigured: a hosted model IS named, and the key needed
        // to reach it is not stored. `assistants::Refusal` keeps these two apart deliberately —
        // telling somebody "no model configured" when the model is configured points them at
        // the wrong half of the setup — and folding them together here would undo that at the
        // one place a person actually reads it.
        Err(msg) if msg == crate::assistants::HOSTED_KEY_MISSING => Err(refusal(
            StatusCode::SERVICE_UNAVAILABLE,
            "no_openrouter_key",
        )),
        Err(_) => Err(refusal(StatusCode::INTERNAL_SERVER_ERROR, "internal")),
    }
}

/// The body `POST /assistant/chats/{chat_id}/relay` takes — nothing more than what a model chose
/// when it called `send_to_chat`. Everything else `relay::admit` needs to decide (who is asking,
/// and from where) comes off the request's own context rather than off anything a body could say;
/// see the route's own comment in `build_router` and `sending_run_id_of` below.
#[derive(Deserialize)]
struct RelayMessageRequest {
    text: String,
}

/// The body `POST /assistant/chats/{chat_id}/forward` takes: which turn is being forwarded, and
/// what to say.
///
/// `text` rather than the turn's own words re-read here, so the window can offer them for editing
/// before they travel. What a person forwards is what they chose to forward, and a route that
/// re-read the turn would quietly send something other than what they saw in the box.
///
/// `from_turn_id` is what makes this a relay rather than a plain message. `chat_relays` requires a
/// `sending_run_id` and a turn IS a run, so forwarding one fits the table exactly — and, more to
/// the point, `relay::chain_of` can then walk back through it, so a person's forward is bounded by
/// the same cycle and depth rules a model's is. Sending free-standing text would have needed that
/// column to become nullable, which in SQLite means rebuilding the table, and would have left the
/// forwarded message outside every brake.
#[derive(Deserialize)]
struct ForwardRequest {
    from_turn_id: i64,
    text: String,
}

/// Which conversation `run_id` is answering, and which client sent the message it is answering —
/// the two facts `relay::admit` needs about the SENDER and takes as parameters rather than reading
/// for itself.
///
/// One read for both, because they come off the same row and a second query could only race the
/// first. `hooks::chat_of_run` makes the chat half of this read for its own purpose and stays where
/// it is: each caller of "which chat is this run in" has so far needed it alongside something
/// different, and a shared home would be a dependency between them that does not otherwise exist.
///
/// Two different absences, deliberately kept apart rather than folded into one `Option`:
///
/// * no row, or a row with no `chat_id` — `None`. The header named a run this daemon cannot
///   attribute to any conversation, so there is no `from_chat_id` to relay from.
/// * a row whose `origin` is NULL — `Some((chat, None))`. The run exists and belongs to a
///   conversation, but nothing recorded where its message came from. See 0119 for why that reads
///   as "unknown" and never as "shell".
///
/// `Origin::from_wire` is deliberately NOT used on the value read back, and this is the one reader
/// of the column that departs from it. That function resolves an unknown spelling to `Shell` —
/// right for a client that said nothing, since a caller stating no origin is the old shell path —
/// but here the same leniency would answer the very question this gate exists to ask. The two
/// spellings are matched exactly; anything else is unknown, and unknown is refused.
async fn sending_turn_of(
    pool: &sqlx::SqlitePool,
    run_id: i64,
) -> Option<(String, Option<crate::assistant::Origin>)> {
    let row: Option<(Option<String>, Option<String>)> =
        sqlx::query_as("SELECT chat_id, origin FROM runs WHERE id = ?")
            .bind(run_id)
            .fetch_optional(pool)
            .await
            .ok()
            .flatten();
    let (chat_id, origin) = row?;
    let origin = match origin.as_deref() {
        Some("telegram") => Some(crate::assistant::Origin::Telegram),
        Some("shell") => Some(crate::assistant::Origin::Shell),
        _ => None,
    };
    Some((chat_id?, origin))
}

/// `relay::admit`'s five refusals, turned into a status and a body that names which one fired —
/// see `Refusal`'s own doc for what each means. 409 for the four the gate actually DECIDED (the
/// destination is gone or archived, the sender is Telegram, the chain refuses the hop, the owner is
/// away): a caller can read the slug and know why, the same way `post_assistant_message` already
/// answers 409 for a chat mid-turn. 500 for `Unreadable` alone, because that
/// variant is not a decision about the relay — the gate could not read enough to make one — and
/// there is nothing about THIS relay for a caller to act on differently next time.
fn relay_refusal_response(cause: crate::relay::Refusal) -> (StatusCode, Json<serde_json::Value>) {
    use crate::relay::{Refusal, Verdict};
    match cause {
        Refusal::NoSuchDestination { to_chat_id } => (
            StatusCode::CONFLICT,
            Json(serde_json::json!({
                "refusal": "no_such_destination",
                "to_chat_id": to_chat_id,
            })),
        ),
        Refusal::TelegramOrigin => refusal(StatusCode::CONFLICT, "telegram_origin"),
        Refusal::Chain(Verdict::Itself) => refusal(StatusCode::CONFLICT, "relay_to_self"),
        Refusal::Chain(Verdict::Cycle { at }) => (
            StatusCode::CONFLICT,
            Json(serde_json::json!({ "refusal": "relay_cycle", "at": at })),
        ),
        Refusal::Chain(Verdict::TooDeep) => refusal(StatusCode::CONFLICT, "relay_too_deep"),
        // `admit` constructs `Refusal::Chain` only from a `Verdict` that is not `Ok` (see its own
        // body: the `Ok` case falls through to the INSERT instead). Reached only if that invariant
        // is ever broken elsewhere, and 500 is the honest answer to a refusal that cannot say what
        // it is refusing.
        Refusal::Chain(Verdict::Ok) => refusal(StatusCode::INTERNAL_SERVER_ERROR, "internal"),
        Refusal::OwnerAway => refusal(StatusCode::CONFLICT, "owner_away"),
        Refusal::Unreadable { step, error } => {
            tracing::warn!(step, %error, "a relay could not be decided");
            refusal(StatusCode::INTERNAL_SERVER_ERROR, "internal")
        }
    }
}

/// `assistant::send_relayed_message`'s refusals, mapped the same way `post_assistant_message` above
/// already maps `send_message_with`'s — the two share every constant because a relayed turn is
/// refused by the same brakes an ordinary one is (a chat mid-turn, neither route configured, an
/// OpenRouter key missing, the kill switch). Kept as its own small match rather than a shared function with that
/// route's: the two bodies are one line apart today, and a shared helper here would be reaching
/// into `post_assistant_message` for four string constants it would have imported anyway.
fn relayed_send_refusal(msg: String) -> (StatusCode, Json<serde_json::Value>) {
    match msg {
        _ if msg == crate::assistant::TURN_IN_PROGRESS => {
            refusal(StatusCode::CONFLICT, "turn_in_progress")
        }
        _ if msg == crate::assistant::NO_LOCAL_MODEL => {
            refusal(StatusCode::SERVICE_UNAVAILABLE, "no_local_model")
        }
        _ if msg == crate::assistant::NO_HOSTED_MODEL => {
            refusal(StatusCode::SERVICE_UNAVAILABLE, "no_hosted_model")
        }
        _ if msg == crate::assistants::HOSTED_KEY_MISSING => {
            refusal(StatusCode::SERVICE_UNAVAILABLE, "no_openrouter_key")
        }
        _ => refusal(StatusCode::INTERNAL_SERVER_ERROR, "internal"),
    }
}

/// What `admit` and `send_relayed_or_queue` can come back with, folded into one type so the
/// `uncancellable` block below has exactly one thing to return and the match after it is one
/// decision per line rather than a chain of `if let`.
enum RelayAttempt {
    /// `sending_run_id` names no run this daemon can find a chat for — a header that parsed as a
    /// number but not as a live run, which `relay::admit` has no way to be asked about since it
    /// takes `from_chat_id` already resolved.
    UnknownSender,
    /// The sending run exists and records no origin. Its own refusal rather than folded into
    /// `UnknownSender` above, because the two are different failures wearing similar words: that
    /// one means the daemon cannot say WHICH conversation is asking, this one means it knows
    /// exactly which and cannot say where that conversation's message came from. Collapsing them
    /// would send an operator looking for a bad run id when the answer is a row that predates 0119.
    ///
    /// Refused rather than defaulted, which is that migration's whole argument: a run whose origin
    /// nobody wrote down is not a run known to be safe, and `relay::admit`'s Telegram brake is
    /// worth exactly as much as the honesty of what is handed to it.
    UnknownOrigin,
    Refused(crate::relay::Refusal),
    NotSent(String),
}

/// `POST /assistant/chats/{chat_id}/relay`. Sequences `relay::admit` and, if it grants the hop,
/// `assistant::send_relayed_or_queue` with the id it wrote — and does nothing else: every refusal
/// either of those two can produce is already argued in `relay.rs` and `assistant.rs`, and
/// reproducing any part of that argument here would be a second copy of a decision that belongs in
/// one place. What this function owns is entirely transport: reading who is asking off the request,
/// and turning what comes back into a status and a body.
///
/// `send_relayed_or_queue` rather than `send_relayed_message` directly: `admit` grants the HOP, not
/// a guarantee that the destination has a turn free the instant this handler runs, and calling the
/// plain send here would answer `turn_in_progress` for exactly the case — a busy destination — that
/// an ordinary message already has a door for. See that function's own doc for the rest of the
/// argument, and `assistant::drain_queued` for what happens when the wait ends.
async fn relay_send_to_chat(
    State(state): State<AppState>,
    Path(chat_id): Path<String>,
    headers: axum::http::HeaderMap,
    Json(body): Json<RelayMessageRequest>,
) -> Result<Json<serde_json::Value>, (StatusCode, Json<serde_json::Value>)> {
    let Some(sending_run_id) = sending_run_id_of(&headers) else {
        return Err(refusal(StatusCode::BAD_REQUEST, "missing_run_id"));
    };

    // Uncancellable for the reason `post_assistant_message` is, above: `send_relayed_message`
    // writes the new turn's `running` row and only then spawns the task that finishes it, and a
    // client that disconnects mid-request must not be able to strand that row by dropping this
    // future between the two.
    let outcome = uncancellable(async move {
        let Some((from_chat_id, sending_origin)) =
            sending_turn_of(&state.pool, sending_run_id).await
        else {
            return Err(RelayAttempt::UnknownSender);
        };
        let Some(sending_origin) = sending_origin else {
            return Err(RelayAttempt::UnknownOrigin);
        };

        // The two origins below are different facts and only look like one argument passed twice.
        //
        // `admit` is asked about the SENDER: where the message asking for this relay came from,
        // read off `runs.origin` above rather than asserted here. That read is what makes
        // `relay::Refusal::TelegramOrigin` reachable at all — before 0119 the column did not exist,
        // this handler had nothing truer than `Origin::Shell` to pass, and the brake was live in
        // its own unit tests and dead everywhere else.
        //
        // `send_relayed_or_queue` is told about the message being DELIVERED, and that one is
        // `Origin::Shell` unconditionally. `Origin` names which client sent a message; this one was
        // sent by another conversation through this daemon, which is the shell path by definition,
        // and never Telegram — a Telegram sender does not get past the line above. It matters
        // because the destination routes on it: `send_message_inner`'s `wants_local` falls back to
        // the origin for a conversation with no brain of its own, so passing the sender's origin
        // through would let one conversation decide which model answers in another.
        match crate::relay::admit(
            &state.pool,
            &from_chat_id,
            &chat_id,
            sending_run_id,
            sending_origin,
            &body.text,
            chrono::Utc::now(),
        )
        .await
        {
            Ok(relay_id) => crate::assistant::send_relayed_or_queue(
                &state,
                &chat_id,
                &body.text,
                crate::assistant::Origin::Shell,
                relay_id,
            )
            .await
            .map_err(RelayAttempt::NotSent),
            Err(cause) => Err(RelayAttempt::Refused(cause)),
        }
    })
    .await
    .map_err(|status| refusal(status, "internal"))?;

    relay_outcome_response(outcome)
}

/// What either relay route answers, once the attempt has resolved.
///
/// Shared because the two differ only in who is asking — a run, through a header it cannot forge,
/// or a person, through a body — and not at all in what a granted, queued, or refused hop means.
/// Two copies of this match is two places for the queued case to be forgotten in.
fn relay_outcome_response(
    outcome: Result<crate::assistant::Sent, RelayAttempt>,
) -> Result<Json<serde_json::Value>, (StatusCode, Json<serde_json::Value>)> {
    match outcome {
        Ok(crate::assistant::Sent::Turn(turn_id)) => {
            Ok(Json(serde_json::json!({ "turn_id": turn_id })))
        }
        // Not a turn id and not a refusal: `send_relayed_or_queue` found the destination mid-turn
        // and kept the words rather than losing them — see that function's own doc for why a relay
        // gets the same try-then-queue door an ordinary message already has. `queued` matches the
        // field `post_assistant_message` answers with for the identical outcome, so a caller reading
        // either route learns the same shape.
        Ok(crate::assistant::Sent::Queued) => Ok(Json(serde_json::json!({ "queued": true }))),
        Err(RelayAttempt::UnknownSender) => Err(refusal(StatusCode::BAD_REQUEST, "unknown_sender")),
        // 409 and not the 400 above it. A missing run id is a malformed request and the caller can
        // fix it; a run whose origin was never recorded is a well-formed request this daemon
        // declines to certify, which is the shape every other refusal here answers 409 for.
        Err(RelayAttempt::UnknownOrigin) => Err(refusal(StatusCode::CONFLICT, "unknown_origin")),
        Err(RelayAttempt::Refused(cause)) => Err(relay_refusal_response(cause)),
        Err(RelayAttempt::NotSent(msg)) => Err(relayed_send_refusal(msg)),
    }
}

/// `POST /assistant/chats/{chat_id}/forward`. A person hands a turn to another conversation.
///
/// `chat_id` is the DESTINATION, matching `/relay` beside it and every other
/// `/assistant/chats/{id}/...` route on this server. The source is derived from the turn rather
/// than stated, because a turn belongs to exactly one conversation and asking the caller to name it
/// too would be inviting the two to disagree.
///
/// **The gate is the same gate, and reads the same facts.** `relay::admit` is asked about the
/// origin of the TURN being forwarded, not about the person doing the forwarding — so forwarding a
/// turn that arrived from Telegram is refused, exactly as a model relaying from one would be.
/// Passing `Origin::Shell` here because a human is at the window was the alternative, and it would
/// have been telling the gate something untrue about the turn in order to get a different answer.
/// One rule, read one way, from one column.
///
/// What this does NOT do is give the person a way past the chain: `sending_run_id` is the forwarded
/// turn, so `chain_of` walks straight through it, and a forward that would close a cycle or exceed
/// `MAX_RELAY_DEPTH` is refused like any other hop.
async fn forward_to_chat(
    State(state): State<AppState>,
    Path(chat_id): Path<String>,
    Json(body): Json<ForwardRequest>,
) -> Result<Json<serde_json::Value>, (StatusCode, Json<serde_json::Value>)> {
    // Uncancellable for the reason `relay_send_to_chat` is: the send writes a `running` row and
    // only then spawns the task that finishes it, and a window that closes mid-request must not be
    // able to strand that row between the two.
    let outcome = uncancellable(async move {
        let Some((from_chat_id, sending_origin)) =
            sending_turn_of(&state.pool, body.from_turn_id).await
        else {
            return Err(RelayAttempt::UnknownSender);
        };
        let Some(sending_origin) = sending_origin else {
            return Err(RelayAttempt::UnknownOrigin);
        };

        match crate::relay::admit(
            &state.pool,
            &from_chat_id,
            &chat_id,
            body.from_turn_id,
            sending_origin,
            &body.text,
            chrono::Utc::now(),
        )
        .await
        {
            // `Origin::Shell` on the delivery for the reason `/relay` gives: the message is
            // arriving through this daemon, which is the shell path by definition, and the
            // destination routes its own brain on that value.
            Ok(relay_id) => crate::assistant::send_relayed_or_queue(
                &state,
                &chat_id,
                &body.text,
                crate::assistant::Origin::Shell,
                relay_id,
            )
            .await
            .map_err(RelayAttempt::NotSent),
            Err(cause) => Err(RelayAttempt::Refused(cause)),
        }
    })
    .await
    .map_err(|status| refusal(status, "internal"))?;

    relay_outcome_response(outcome)
}

/// One conversation on a relayed turn's path.
#[derive(Serialize)]
struct ChainStep {
    chat_id: String,
    /// Null on a conversation nobody has named. It keeps its place in the path regardless — a
    /// chain with a hole in it is a chain that lies about its own length.
    title: Option<String>,
}

/// `GET /assistant/chats/{chat_id}/turns/{turn_id}/chain`. Where a turn came from, all the way back.
///
/// The transcript already names the conversation that handed a turn over, and with
/// `MAX_RELAY_DEPTH` at three that is a different question from "where did this start". "B spoke to
/// me" hides that A began it, and A is the conversation somebody actually typed into.
///
/// `relay::chain_of` does the walk; this adds only the names. A turn nothing relayed answers a
/// chain of one — its own conversation — which is honest rather than empty: that IS its whole path.
///
/// The `chat_id` in the path is checked against the turn's own, and it is not a security boundary:
/// the control token permits every route. It catches a window bug — a stale turn id from a
/// conversation the person has navigated away from — which would otherwise answer with somebody
/// else's path under the title of the chat on screen.
async fn get_relay_chain(
    State(state): State<AppState>,
    Path((chat_id, turn_id)): Path<(String, i64)>,
) -> Result<Json<serde_json::Value>, StatusCode> {
    let owner: Option<Option<String>> = sqlx::query_scalar("SELECT chat_id FROM runs WHERE id = ?")
        .bind(turn_id)
        .fetch_optional(&state.pool)
        .await
        .map_err(|error| {
            tracing::warn!(%error, "reading which conversation a turn belongs to failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })?;
    if owner.flatten().as_deref() != Some(chat_id.as_str()) {
        return Err(StatusCode::NOT_FOUND);
    }

    // A walk that cannot complete is a 500 and not an empty chain, for the reason `chain_of`'s own
    // doc gives: a short chain reads as a safe one, and answering a shortened path here would be
    // the same lie in a place a person reads rather than a gate.
    let chain = crate::relay::chain_of(&state.pool, turn_id)
        .await
        .map_err(|error| {
            tracing::warn!(%error, turn_id, "a relay chain could not be walked");
            StatusCode::INTERNAL_SERVER_ERROR
        })?;

    // One read for the names, not one per hop: the chain is at most `MAX_RELAY_DEPTH + 1` long, so
    // the difference is small — but a loop of queries here would be the shape that stops being
    // small the day somebody raises that constant.
    let mut named = Vec::with_capacity(chain.len());
    let mut titles = sqlx::QueryBuilder::<sqlx::Sqlite>::new(
        "SELECT chat_id, title FROM chats WHERE chat_id IN (",
    );
    let mut separated = titles.separated(", ");
    for step in &chain {
        separated.push_bind(step);
    }
    titles.push(")");
    let rows: Vec<(String, Option<String>)> = titles
        .build_query_as()
        .fetch_all(&state.pool)
        .await
        .unwrap_or_default();
    for step in chain {
        // A conversation with no `chats` row at all reads as unnamed rather than dropping out. The
        // walk found it, so it is part of the path whatever the `chats` table has to say.
        let title = rows
            .iter()
            .find(|(id, _)| *id == step)
            .and_then(|(_, title)| title.clone());
        named.push(ChainStep {
            chat_id: step,
            title,
        });
    }

    Ok(Json(serde_json::json!({ "chain": named })))
}

/// What the PII shadow pass has seen, by column and class.
///
/// `none` is a class here and not an absence: it counts the fields that were looked at and found
/// clean, which is the denominator. A tally without it says how often personal data was found and
/// not how often it was looked for, and only the second answers whether a class is worth enforcing.
///
/// The column comes with it because the three are not one population. A `name` in `from_name` is
/// nearly a certainty and a `name` in a subject line is a finding; added together they answer
/// nothing, and the denominator would mix three base rates into one meaningless total.
async fn get_pii_observations(
    State(state): State<AppState>,
) -> Result<Json<Vec<serde_json::Value>>, StatusCode> {
    let tally = crate::pii_shadow::tally(&state.pool)
        .await
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;

    Ok(Json(
        tally
            .into_iter()
            .map(|(column, class, count)| {
                serde_json::json!({"column": column, "class": class, "count": count})
            })
            .collect(),
    ))
}

/// `GET /notifications/policy` — the stored selection policy, verbatim (spec §5.3). A fresh
/// database has no rows, so this answers `{"families": [], "kinds": []}` rather than 404: absence
/// of a rule is the resolution's own "passes" default, not an error.
async fn get_notify_policy(State(state): State<AppState>) -> impl IntoResponse {
    match notify_policy::load(&state.pool).await {
        Ok(policy) => Json(policy).into_response(),
        Err(error) => {
            tracing::warn!(%error, "notify_policy: reading the stored policy failed");
            (StatusCode::INTERNAL_SERVER_ERROR, "database error").into_response()
        }
    }
}

/// The refusal name `PUT /notifications/policy` reports for each `ValidationError` variant, kept
/// beside the status/reason split `create_run_status`/`create_run_reason` already use for
/// `CreateRunError`: one place decides what a refusal is CALLED, so the name and the message
/// cannot drift apart.
fn notify_policy_refusal_name(error: &notify_policy::ValidationError) -> &'static str {
    match error {
        notify_policy::ValidationError::EmptySelector { .. } => "empty_selector",
        notify_policy::ValidationError::MalformedSelector { .. } => "malformed_selector",
        notify_policy::ValidationError::SelectorTooLong { .. } => "selector_too_long",
        notify_policy::ValidationError::DuplicateSelector { .. } => "duplicate_selector",
        notify_policy::ValidationError::TooManyRules { .. } => "too_many_rules",
    }
}

/// `PUT /notifications/policy` — replaces the whole policy (spec §5.3). Validates BEFORE writing;
/// `notify_policy::replace` itself never calls `validate`, so a rejected shape and a database
/// error cannot share a code path. A `400` names the refusal and the selector in question, so the
/// shell can point at the offending row instead of saying "invalid" (§7.4). A `500` means the
/// transaction never committed, so the table is exactly as it was.
async fn put_notify_policy(
    State(state): State<AppState>,
    Json(policy): Json<notify_policy::Policy>,
) -> impl IntoResponse {
    if let Err(error) = notify_policy::validate(&policy) {
        return (
            StatusCode::BAD_REQUEST,
            // `detail`, not `message`: the shell's `refusalFrom` reads `body.detail` beside a
            // `refusal` and never looks at `message`, so naming it wrong throws the selector away
            // and leaves the page showing the code twice. Same pair every refusal in this file
            // sends.
            Json(serde_json::json!({
                "refusal": notify_policy_refusal_name(&error),
                "detail": error.to_string(),
            })),
        )
            .into_response();
    }

    match notify_policy::replace(&state.pool, &policy).await {
        Ok(()) => StatusCode::NO_CONTENT.into_response(),
        Err(error) => {
            tracing::warn!(%error, "notify_policy: writing the new policy failed");
            (StatusCode::INTERNAL_SERVER_ERROR, "database error").into_response()
        }
    }
}

/// `GET /notifications/kinds` — the kinds THIS machine has written, deduplicated and ordered
/// (spec §4.2, §5.2). Only an observation of the feed's retention window; the union with kinds
/// that only exist as a stored rule is the shell's job (§7.2), not this route's.
async fn get_notify_kinds(State(state): State<AppState>) -> impl IntoResponse {
    match notify_policy::observed_kinds(&state.pool).await {
        Ok(kinds) => Json(kinds).into_response(),
        Err(error) => {
            tracing::warn!(%error, "notify_policy: reading observed kinds failed");
            (StatusCode::INTERNAL_SERVER_ERROR, "database error").into_response()
        }
    }
}

#[derive(Deserialize)]
struct PressureQuery {
    /// A equipa, por nome. Resolve para o job mais recente dela.
    team: Option<String>,
    /// Ou um job em concreto, por `team_runs.id`. Ganha ao nome quando ambos vem.
    job: Option<String>,
}

/// Quanta janela custou a cada agente da equipa, por round.
///
/// `protected` e nao publica: e telemetria da maquina de agentes, e nomeia agentes, rounds e
/// quanto contexto cada um gastou.
///
/// Nenhum dos dois parametros por omissao. Adivinhar uma equipa daria uma resposta sobre a equipa
/// errada, que e pior do que nenhuma -- e quem pergunta nao teria como notar.
async fn get_team_pressure(
    State(state): State<AppState>,
    Query(query): Query<PressureQuery>,
) -> Result<Json<crate::pressure::Report>, StatusCode> {
    let scope = match (query.job, query.team) {
        (Some(job), _) => crate::pressure::Scope::Job(job),
        (None, Some(team)) => crate::pressure::Scope::Team(team),
        (None, None) => return Err(StatusCode::BAD_REQUEST),
    };
    match crate::pressure::measure(&state.pool, scope).await {
        Ok(report) => Ok(Json(report)),
        // Errar o nome e nunca ter corrido sao coisas diferentes: esta e a primeira, e a outra sai
        // daqui com 200 e `never_ran`.
        Err(sqlx::Error::RowNotFound) => Err(StatusCode::NOT_FOUND),
        Err(_) => Err(StatusCode::INTERNAL_SERVER_ERROR),
    }
}

async fn get_autopilot_state(
    State(state): State<AppState>,
    Query(query): Query<ProjectQuery>,
) -> Result<Json<AutopilotStateResponse>, StatusCode> {
    let mode = autopilot::project_mode(&state.pool, &query.project_id)
        .await
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    Ok(Json(AutopilotStateResponse {
        project_id: query.project_id,
        mode,
    }))
}

async fn post_autopilot_state(
    State(state): State<AppState>,
    Json(body): Json<AutopilotStateRequest>,
) -> Result<Json<AutopilotStateResponse>, axum::response::Response> {
    let mode = Mode::from_db_str(&body.mode).ok_or(StatusCode::BAD_REQUEST.into_response())?;
    let project_root = body.project_root.as_deref().map(std::path::Path::new);
    autopilot::set_project_mode(
        &state.pool,
        state.machine_config_root.as_deref(),
        &body.project_id,
        mode,
        project_root,
    )
    .await
    .map_err(activation_status)?;
    let mode = autopilot::project_mode(&state.pool, &body.project_id)
        .await
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR.into_response())?;

    Ok(Json(AutopilotStateResponse {
        project_id: body.project_id,
        mode,
    }))
}

#[derive(Deserialize)]
struct AutopilotJudgeRequest {
    project_id: String,
    judge: String,
}

#[derive(Serialize)]
struct AutopilotJudgeResponse {
    project_id: String,
    judge: crate::judge::JudgeMode,
    /// Review item G: `Some` when this project's `autopilot.yaml` cannot be read, which leaves
    /// the judge without effect (every call falls back to the classifier, D7/D10).
    rules_error: Option<String>,
    /// D11: how far the project is from being allowed to enforce, with the classes beside it.
    readiness: crate::judge::JudgeReadiness,
}

/// One project's judge, as both handlers answer it. A readiness that cannot be read is a 500, like
/// the mode: a panel shown a made-up zero would read "nothing reviewed yet".
async fn judge_status(
    state: &AppState,
    project_id: String,
) -> Result<AutopilotJudgeResponse, StatusCode> {
    let judge = autopilot::autopilot_judge_mode(&state.pool, &project_id)
        .await
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    let readiness = crate::judge::readiness(&state.pool, &project_id)
        .await
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    let rules_error =
        crate::judge::rules_problem(state.machine_config_root.clone(), &project_id).await;
    Ok(AutopilotJudgeResponse {
        project_id,
        judge,
        rules_error,
        readiness,
    })
}

/// Spec A: one project's judge setting. Its own route beside `/autopilot/state` rather than a
/// field on the roster: the panel reads one project at a time, and a field on `ProjectSummary`
/// would touch nine literals and the CLI's deserialiser for nothing the roster shows.
///
/// Admin-only, by appearing in no table in `auth.rs` (not in `READ_ONLY_ROUTES`): it reveals and
/// changes what a model may decide for a project, and default-deny is the safe side of that.
async fn get_autopilot_judge(
    State(state): State<AppState>,
    Query(query): Query<ProjectQuery>,
) -> Result<Json<AutopilotJudgeResponse>, StatusCode> {
    judge_status(&state, query.project_id).await.map(Json)
}

async fn post_autopilot_judge(
    State(state): State<AppState>,
    Json(body): Json<AutopilotJudgeRequest>,
) -> Result<Json<AutopilotJudgeResponse>, (StatusCode, Json<serde_json::Value>)> {
    let judge = crate::judge::JudgeMode::from_db_str(&body.judge)
        .ok_or_else(|| refusal(StatusCode::BAD_REQUEST, "invalid"))?;
    match autopilot::set_project_judge(&state.pool, &body.project_id, judge).await {
        Ok(_) => judge_status(&state, body.project_id)
            .await
            .map(Json)
            .map_err(|status| refusal(status, "internal")),
        Err(autopilot::JudgeActivationError::UnknownProject) => {
            Err(refusal(StatusCode::NOT_FOUND, "unknown_project"))
        }
        Err(autopilot::JudgeActivationError::NotActive) => {
            Err(refusal(StatusCode::CONFLICT, "not_active"))
        }
        Err(autopilot::JudgeActivationError::NotReady { reviewed, agree }) => {
            tracing::info!(
                reviewed,
                agree,
                "enforce refused: the judge's bar is not met"
            );
            Err(refusal(StatusCode::CONFLICT, "not_ready"))
        }
        Err(autopilot::JudgeActivationError::Database(error)) => {
            tracing::warn!(%error, "setting a project's judge failed");
            Err(refusal(StatusCode::INTERNAL_SERVER_ERROR, "internal"))
        }
    }
}

#[derive(Deserialize)]
struct JudgeResolveRequest {
    project_id: String,
    judge_resolve: String,
}

#[derive(Serialize)]
struct JudgeResolveResponse {
    project_id: String,
    judge_resolve: crate::judge::JudgeMode,
    readiness: crate::judge::resolve_review::ResolveReadiness,
}

/// Spec B D11: one project's resolver setting. Admin-only like `/autopilot/judge`, by appearing
/// in no table in `auth.rs`.
async fn get_autopilot_judge_resolve(
    State(state): State<AppState>,
    Query(query): Query<ProjectQuery>,
) -> Result<Json<JudgeResolveResponse>, StatusCode> {
    let judge_resolve = autopilot::autopilot_judge_resolve_mode(&state.pool, &query.project_id)
        .await
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    let readiness = crate::judge::resolve_review::readiness(&state.pool, &query.project_id)
        .await
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    Ok(Json(JudgeResolveResponse {
        project_id: query.project_id,
        judge_resolve,
        readiness,
    }))
}

async fn post_autopilot_judge_resolve(
    State(state): State<AppState>,
    Json(body): Json<JudgeResolveRequest>,
) -> Result<Json<JudgeResolveResponse>, (StatusCode, Json<serde_json::Value>)> {
    let mode = crate::judge::JudgeMode::from_db_str(&body.judge_resolve)
        .ok_or_else(|| refusal(StatusCode::BAD_REQUEST, "invalid"))?;
    // `enforce` is accepted now that the shell shows its residual risk (spec D11). The bar is
    // enforced by `set_project_judge_resolve`, whatever door asks.
    match autopilot::set_project_judge_resolve(&state.pool, &body.project_id, mode).await {
        Ok(judge_resolve) => {
            let readiness = crate::judge::resolve_review::readiness(&state.pool, &body.project_id)
                .await
                .map_err(|_| refusal(StatusCode::INTERNAL_SERVER_ERROR, "internal"))?;
            Ok(Json(JudgeResolveResponse {
                project_id: body.project_id,
                judge_resolve,
                readiness,
            }))
        }
        Err(autopilot::ResolveActivationError::UnknownProject) => {
            Err(refusal(StatusCode::NOT_FOUND, "unknown_project"))
        }
        Err(autopilot::ResolveActivationError::NotActive) => {
            Err(refusal(StatusCode::CONFLICT, "not_active"))
        }
        Err(autopilot::ResolveActivationError::NotReady(readiness)) => {
            tracing::info!(
                reviewed = readiness.reviewed,
                agree = readiness.agree,
                less_cautious = readiness.less_cautious,
                "enforce refused: the resolver's bar is not met"
            );
            Err(refusal(StatusCode::CONFLICT, "not_ready"))
        }
        Err(autopilot::ResolveActivationError::Database(error)) => {
            tracing::error!(%error, project_id = %body.project_id, "setting judge_resolve failed");
            Err(refusal(StatusCode::INTERNAL_SERVER_ERROR, "internal"))
        }
    }
}

async fn get_autopilot_kill(
    State(state): State<AppState>,
) -> Result<Json<AutopilotKillResponse>, StatusCode> {
    let engaged = autopilot::kill_switch_engaged(&state.pool)
        .await
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    Ok(Json(AutopilotKillResponse { engaged }))
}

async fn post_autopilot_kill(
    State(state): State<AppState>,
    Json(body): Json<AutopilotKillRequest>,
) -> Result<StatusCode, StatusCode> {
    autopilot::set_kill_switch(&state.pool, body.engaged)
        .await
        .map(|()| StatusCode::NO_CONTENT)
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)
}

async fn get_autopilot_kill_scoped(
    State(state): State<AppState>,
) -> Result<Json<Vec<ScopedKill>>, StatusCode> {
    autopilot::list_scoped_kills(&state.pool)
        .await
        .map(Json)
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)
}

async fn post_autopilot_kill_scoped(
    State(state): State<AppState>,
    Json(body): Json<ScopedKillRequest>,
) -> Result<StatusCode, StatusCode> {
    if body.scope_type != "project" && body.scope_type != "trigger" {
        return Err(StatusCode::BAD_REQUEST);
    }
    autopilot::set_scoped_kill(&state.pool, &body.scope_type, &body.scope_id, body.engaged)
        .await
        .map(|()| StatusCode::NO_CONTENT)
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)
}

/// The quota readings, live from the sidecar or — when it cannot be reached — from the table.
///
/// Never an error: a sidecar that is down is an answer about the sidecar, and `quota::report`
/// carries it in the body as `source: "stored"` plus the reason. Returning a 5xx would have the
/// shell draw nothing, which looks exactly like a quota that has not been touched.
async fn get_quota(State(state): State<AppState>) -> Json<crate::quota::QuotaReport> {
    Json(crate::quota::report(&state.quota, &state.pool, chrono::Utc::now()).await)
}

async fn get_autopilot_budget(
    State(state): State<AppState>,
) -> Result<Json<BudgetResponse>, StatusCode> {
    budget_response(&state).await.map(Json)
}

async fn post_autopilot_budget(
    State(state): State<AppState>,
    Json(body): Json<BudgetRequest>,
) -> Result<Json<BudgetResponse>, StatusCode> {
    let period = budget::BudgetPeriod::from_db_str(&body.period).ok_or(StatusCode::BAD_REQUEST)?;
    let config = budget::BudgetConfig {
        limit_usd: body.limit_usd,
        period,
        hourly_limit_usd: body.hourly_limit_usd,
        per_run_reserve_usd: body.per_run_reserve_usd,
        time_cost_per_hour_usd: body.time_cost_per_hour_usd,
    };
    budget::set_budget_config(&state.pool, &config)
        .await
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    budget_response(&state).await.map(Json)
}

async fn get_quota_brake(
    State(state): State<AppState>,
) -> Result<Json<QuotaBrakeResponse>, StatusCode> {
    quota_brake_response(&state).await.map(Json)
}

async fn post_quota_brake(
    State(state): State<AppState>,
    Json(body): Json<QuotaBrakeRequest>,
) -> Result<Json<QuotaBrakeResponse>, StatusCode> {
    if !(1..=100).contains(&body.pause_above_percent_5h)
        || !(1..=100).contains(&body.pause_above_percent_7d)
    {
        return Err(StatusCode::UNPROCESSABLE_ENTITY);
    }
    crate::quota::set_brake_policy(
        &state.pool,
        crate::quota::BrakePolicy {
            enabled: body.enabled,
            pause_above_percent_5h: body.pause_above_percent_5h,
            pause_above_percent_7d: body.pause_above_percent_7d,
        },
    )
    .await
    .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    quota_brake_response(&state).await.map(Json)
}

async fn quota_brake_response(state: &AppState) -> Result<QuotaBrakeResponse, StatusCode> {
    let policy = crate::quota::load_brake_policy(&state.pool)
        .await
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    Ok(QuotaBrakeResponse {
        enabled: policy.enabled,
        pause_above_percent_5h: policy.pause_above_percent_5h,
        pause_above_percent_7d: policy.pause_above_percent_7d,
        provider: state.quota.provider.clone(),
    })
}

async fn post_attention_heartbeat(
    State(state): State<AppState>,
    Json(body): Json<AttentionHeartbeatRequest>,
) -> Result<StatusCode, StatusCode> {
    let scope = match body.project_id {
        None => AttentionScope::Global,
        Some(project_id) if project_id.trim().is_empty() => return Err(StatusCode::BAD_REQUEST),
        Some(project_id) => AttentionScope::Project(project_id),
    };
    attention::record_heartbeat(&state.pool, &scope, chrono::Utc::now())
        .await
        .map(|()| StatusCode::NO_CONTENT)
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)
}

async fn budget_response(state: &AppState) -> Result<BudgetResponse, StatusCode> {
    let now = chrono::Utc::now();
    let config = budget::load_budget_config(&state.pool)
        .await
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    let window_spend_usd = budget::window_spend(&state.pool, now)
        .await
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    let hourly_spend_usd = budget::hourly_spend(&state.pool, now)
        .await
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    let (paused, reason) = match budget::budget_permits_new_run(&state.pool, now).await {
        budget::BudgetDecision::Allow => (false, None),
        budget::BudgetDecision::Pause { reason, .. } => (true, Some(reason)),
    };
    Ok(BudgetResponse {
        limit_usd: config.limit_usd,
        period: config.period.as_db_str().to_string(),
        hourly_limit_usd: config.hourly_limit_usd,
        per_run_reserve_usd: config.per_run_reserve_usd,
        time_cost_per_hour_usd: config.time_cost_per_hour_usd,
        window_spend_usd,
        hourly_spend_usd,
        paused,
        reason,
    })
}

/// The mode door's refusals on the wire.
///
/// Three of the four prerequisites are still the bare 422 they always were, and the shell's copy
/// for that answer names all of them. `NotOnboarded` alone carries a name, `not_onboarded`, because
/// it is the one refusal the shell can resolve in place — by running onboarding
/// (`POST /projects/{id}/onboard`) — and a status shared with three other causes could not tell it
/// to. The name is opaque on purpose: it says what is missing, never where a file would have been.
fn activation_status(error: ActivationError) -> axum::response::Response {
    match error {
        ActivationError::NotOnboarded => {
            refusal(StatusCode::UNPROCESSABLE_ENTITY, "not_onboarded").into_response()
        }
        ActivationError::NotAGitRepo
        | ActivationError::ProjectRootRequired
        | ActivationError::HookNotRegistered => StatusCode::UNPROCESSABLE_ENTITY.into_response(),
        ActivationError::Database(_) => StatusCode::INTERNAL_SERVER_ERROR.into_response(),
    }
}

fn inspect_status(error: inspect::InspectError) -> StatusCode {
    match error {
        inspect::InspectError::NotFound => StatusCode::NOT_FOUND,
        inspect::InspectError::UnsafePath => StatusCode::BAD_REQUEST,
        // The only one the caller cannot diagnose from the status code alone, so it is the only one
        // worth a line in the log.
        inspect::InspectError::Io(error) => {
            tracing::warn!(%error, "project inspection failed");
            StatusCode::INTERNAL_SERVER_ERROR
        }
    }
}

/// Where a read of this project should happen: the project itself, or one run's worktree.
///
/// **The subject of a review is the run, not the repository**, so every reader in this family takes
/// an optional `run` and answers from that run's checkout when it is given. Without it they answer
/// from the project root exactly as before, which is what every existing caller gets.
///
/// **The `project_id` in the lookup is the guard, and it is the whole security argument here.** A
/// worktree path is otherwise reachable by asking any project for any run id — the daemon holds
/// worktrees for every project in one table — so the row must match the project being asked, not
/// merely exist. A run whose worktree has been released has `removed_at` set and is refused too:
/// the directory is gone, and answering from a stale path would read whatever has since been put
/// there.
async fn resolve_read_root(
    state: &AppState,
    id: &str,
    run: Option<i64>,
) -> Result<PathBuf, StatusCode> {
    let Some(run) = run else {
        return resolve_project_root(state, id).await;
    };
    let path: Option<String> = sqlx::query_scalar(
        "SELECT path FROM worktrees \
          WHERE owner_kind = 'run' AND owner_id = ? AND project_id = ? AND removed_at IS NULL",
    )
    .bind(run)
    .bind(id)
    .fetch_optional(&state.pool)
    .await
    .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;

    path.map(PathBuf::from).ok_or(StatusCode::NOT_FOUND)
}

/// The base commit a run's worktree was cut from, and the path to it.
///
/// Both or neither: a worktree with no `base_sha` cannot be measured — the column is nullable, and
/// a NULL there means the daemon never recorded where the branch started. Answering "nothing
/// changed" for it would be the worst possible reading of "we do not know".
async fn resolve_run_worktree(
    state: &AppState,
    id: &str,
    run: i64,
) -> Result<(PathBuf, String), StatusCode> {
    let row: Option<(String, Option<String>)> = sqlx::query_as(
        "SELECT path, base_sha FROM worktrees \
          WHERE owner_kind = 'run' AND owner_id = ? AND project_id = ? AND removed_at IS NULL",
    )
    .bind(run)
    .bind(id)
    .fetch_optional(&state.pool)
    .await
    .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;

    match row {
        Some((path, Some(base))) => Ok((PathBuf::from(path), base)),
        // A worktree with no recorded base is a different answer from a worktree that is not there,
        // and both are refusals the caller has to be able to tell apart from an empty change set.
        Some((_, None)) => Err(StatusCode::UNPROCESSABLE_ENTITY),
        None => Err(StatusCode::NOT_FOUND),
    }
}

/// Which documents this project has, from the table first and the folder second.
///
/// **The union, and the order of the two words is the whole argument.** `map_intent::specs_in`
/// answers *what is in `.ai/specs` right now*; `map_store::slugs` answers *what this project has
/// ever extracted decisions from*. Only the second is durable — spec files are gitignored working
/// material that gets archived, renamed and reorganised, and the slug is the FILENAME, so a rename
/// silently retires every slug the approved rows still carry.
///
/// What the list is for is [`crate::map_join::evidence`]'s one refusal: a citation whose candidate
/// names a DIFFERENT document of this project is evidence against, and is skipped rather than
/// counted. A list that lost a slug therefore does not fail loudly — it quietly stops being able to
/// tell two documents apart, every anchor degrades to ambiguous, and nothing on screen says why.
/// That is the silent wrong answer this feature exists to refuse, arriving through a file rename.
///
/// **The folder still contributes**, because a spec sitting there with no decisions yet is a real
/// document of this project and a citation naming it must still be refused for the others. Union
/// never loses a slug; either source alone does.
///
/// Sorted and deduplicated so two reads of an unchanged project cannot produce two different lists,
/// which `map_join::join`'s determinism rests on.
async fn document_slugs(
    state: &AppState,
    id: &str,
    on_disk: Vec<String>,
) -> Result<Vec<String>, StatusCode> {
    let mut all: std::collections::BTreeSet<String> = on_disk.into_iter().collect();
    all.extend(crate::map_store::slugs(&state.pool, id).await.map_err(
        |error| {
            tracing::warn!(%error, project_id = %id, "reading this project's document slugs failed");
            StatusCode::INTERNAL_SERVER_ERROR
        },
    )?);
    Ok(all.into_iter().collect())
}

async fn resolve_project_root(state: &AppState, id: &str) -> Result<PathBuf, StatusCode> {
    match inspect::project_root(&state.pool, id).await {
        Ok(Some(root)) => Ok(PathBuf::from(root)),
        Ok(None) => Err(StatusCode::NOT_FOUND),
        Err(_) => Err(StatusCode::INTERNAL_SERVER_ERROR),
    }
}

/// One rule's recorded scheduler state, as the tick writes it.
///
/// Named rather than left as a five-element tuple because the fields are read by position in three
/// places here, and `fires_date` and `fires_today` are the pair whose meaning depends entirely on
/// being read together — a count carrying yesterday's date is a count of nothing.
#[derive(sqlx::FromRow)]
struct RuleRunState {
    rule_name: String,
    last_fired_at: String,
    last_head_sha: Option<String>,
    fires_date: Option<String>,
    fires_today: i64,
}

/// One scheduled rule, with what the daemon knows about it having run.
#[derive(serde::Serialize)]
struct ScheduleView {
    name: String,
    cron: String,
    prompt: String,
    cwd: Option<String>,
    timezone: Option<String>,
    /// When this fires next, counted from the last time it did — the same anchor the tick uses.
    next_fire_at: Option<String>,
    /// Why it will never fire, when that is the answer instead.
    ///
    /// An unparseable cron or an unknown timezone makes the tick skip the rule and log at debug,
    /// 2,880 times a day. The rule simply never runs and nothing says so; this is where that stops
    /// being invisible.
    problem: Option<String>,
    last_fired_at: Option<String>,
    /// How many times it has fired today, against the daemon's own per-rule daily cap.
    fires_today: i64,
    daily_cap: u32,
}

/// One repo trigger, with the commit it last saw.
#[derive(serde::Serialize)]
struct RepoTriggerView {
    name: String,
    branch: String,
    prompt: String,
    /// The SHA recorded the last time this trigger was evaluated. `null` means it is armed and has
    /// not yet seen a first commit to compare against — which fires nothing, by design.
    last_sha: Option<String>,
}

/// Everything a project will do without being asked, and everything currently holding it back.
#[derive(serde::Serialize)]
struct ProjectRules {
    project_id: String,
    project_root: Option<String>,
    /// `present`, `absent`, or `unreadable` — the three states the project's `autopilot.yaml` can
    /// be in.
    rules_file: &'static str,
    /// Where that file is, as a person is shown it: `~/.nucleos/projects/<id>/autopilot.yaml`.
    ///
    /// Served rather than spelled by the page, because the page used to carry `.ai/autopilot.yaml`
    /// as a literal and was wrong the day the file moved. The daemon is the one that knows where it
    /// reads from.
    rules_path: String,
    /// Why the file could not be read, when it could not be.
    ///
    /// `config.rs` uses `deny_unknown_fields` precisely so a typo is an error rather than a silently
    /// empty ruleset — but that error only reached a log line, so writing `schedule:` for
    /// `schedules:` stopped all autonomy for the project and looked like nothing had happened.
    rules_error: Option<String>,
    gate_command: Option<String>,
    /// Whether the VCS queue measures a merge into this project's target branch before publishing
    /// it. Served beside `gate_command` because it decides whether that command runs at a second
    /// moment entirely — and a brake nobody can see through this route is one nobody thinks to
    /// check when a landing takes twenty minutes.
    gate_before_publish: bool,
    /// Who answers an approval a conversation on `auto` would otherwise put to a person.
    judge: JudgeView,
    schedules: Vec<ScheduleView>,
    repo_triggers: Vec<RepoTriggerView>,
    /// The effective open-proposal ceiling: the project's own, else the global default. `null` means
    /// the brake is off.
    wip_limit: Option<i64>,
    open_review_items: i64,
    /// The two queues that total is made of, so the panel can name the screen that clears it.
    /// A total alone reads as "the proposals list", which on this project was empty while the
    /// brake held: all of it was unreviewed shadow decisions (`wip::OpenReviewItems`).
    open_proposals: i64,
    open_shadow_decisions: i64,
    /// Whether that ceiling is currently refusing new autonomous work.
    queue_full: bool,
}

/// What a project does on its own.
///
/// The rules live in `~/.nucleos/projects/<id>/autopilot.yaml` and were readable only by opening
/// the file; the WIP ceiling lives in the database and was readable only through the roster's
/// summary. Both decide whether autonomous work happens at all, so they answer one question and are
/// served together.
async fn get_project_rules(
    State(state): State<AppState>,
    Path(id): Path<String>,
) -> Result<Json<ProjectRules>, StatusCode> {
    let project_root: Option<String> =
        sqlx::query_scalar("SELECT project_root FROM autopilot_state WHERE project_id = ?")
            .bind(&id)
            .fetch_optional(&state.pool)
            .await
            .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?
            .flatten();

    // Read whether or not the project has a root. The file is keyed by the project's id, so an
    // `off` project — which has no root on record — can still have rules waiting for the day it is
    // switched back on, and saying `absent` about a file that is there would be the wrong fact.
    let machine_root = state.machine_config_root.clone();
    let rules_id = id.clone();
    let (rules_file, rules_error, loaded) = tokio::task::spawn_blocking(move || {
        match crate::config::load_schedule_rules(machine_root.as_deref(), &rules_id) {
            Ok(rules) => {
                let present = crate::project_state::file(
                    machine_root.as_deref(),
                    &rules_id,
                    crate::project_state::AUTOPILOT_FILE,
                )
                .is_some_and(|path| path.exists());
                (if present { "present" } else { "absent" }, None, rules)
            }
            Err(error) => (
                "unreadable",
                Some(error.to_string()),
                crate::config::AutopilotRules::default(),
            ),
        }
    })
    .await
    .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    let rules_path = crate::project_state::display_path(&id, crate::project_state::AUTOPILOT_FILE);

    let state_rows: Vec<RuleRunState> = sqlx::query_as(
        "SELECT rule_name, last_fired_at, last_head_sha, fires_date, fires_today
           FROM scheduler_state
          WHERE project_id = ?",
    )
    .bind(&id)
    .fetch_all(&state.pool)
    .await
    .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;

    let now = chrono::Utc::now();
    let today = now.date_naive().to_string();
    // One table holds both kinds of rule, keyed by name, so schedules and repo triggers read their
    // recorded state out of the same map.
    let by_rule: std::collections::HashMap<&str, &RuleRunState> = state_rows
        .iter()
        .map(|row| (row.rule_name.as_str(), row))
        .collect();

    let schedules = loaded
        .schedules
        .iter()
        .map(|rule| {
            let recorded = by_rule.get(rule.name.as_str());
            let last_fired_at = recorded.map(|row| row.last_fired_at.clone());
            // Anchored on the last fire when there is one, exactly as the tick anchors it. Counting
            // from now instead would quietly skip a window that is already overdue, and show the run
            // due tomorrow when it is due this minute.
            let since = last_fired_at
                .as_deref()
                .and_then(|stamp| chrono::DateTime::parse_from_rfc3339(stamp).ok())
                .map(|stamp| stamp.with_timezone(&chrono::Utc))
                .unwrap_or(now);
            let (next_fire_at, problem) = match crate::scheduler::next_fire(rule, since) {
                Ok(next) => (Some(next.to_rfc3339()), None),
                Err(problem) => (None, Some(problem)),
            };
            // A count carrying another day's date is a count of nothing — the daemon resets by
            // comparing rather than by sweeping at midnight, so this reads it the same way.
            let fires_today = recorded
                .filter(|row| row.fires_date.as_deref() == Some(today.as_str()))
                .map_or(0, |row| row.fires_today);
            ScheduleView {
                name: rule.name.clone(),
                cron: rule.cron.clone(),
                prompt: rule.prompt.clone(),
                cwd: rule.cwd.clone(),
                timezone: rule.timezone.clone(),
                next_fire_at,
                problem,
                last_fired_at,
                fires_today,
                daily_cap: crate::scheduler::DAILY_CAP,
            }
        })
        .collect();

    let repo_triggers = loaded
        .repo_triggers
        .iter()
        .map(|trigger| RepoTriggerView {
            name: trigger.name.clone(),
            branch: trigger.branch.clone(),
            prompt: trigger.prompt.clone(),
            last_sha: by_rule
                .get(trigger.name.as_str())
                .and_then(|row| row.last_head_sha.clone()),
        })
        .collect();

    let wip_limit = crate::wip::wip_limit(&state.pool, &id)
        .await
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    let items = crate::wip::open_review_items(&state.pool, &id)
        .await
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    let open_review_items = items.total();

    // Read before the struct takes `id`, which is what the borrow checker was pointing at and is
    // also the clearer order: every other field here is gathered above.
    let judge: JudgeView = crate::project_policy::judge(&state.pool, &id).await.into();

    Ok(Json(ProjectRules {
        project_id: id,
        project_root,
        rules_file,
        rules_path,
        rules_error,
        gate_command: loaded.gate_command.clone(),
        gate_before_publish: loaded.gate_before_publish,
        judge,
        schedules,
        repo_triggers,
        wip_limit,
        open_review_items,
        open_proposals: items.proposals,
        open_shadow_decisions: items.shadow_decisions,
        queue_full: crate::wip::queue_full(open_review_items, wip_limit),
    }))
}

#[derive(Deserialize)]
struct ExclusionRequest {
    job_a: i64,
    job_b: i64,
    /// The files that motivated the request, as `collision.rs` reported them. Optional, and kept
    /// rather than acted on — see the migration.
    #[serde(default)]
    paths: Vec<String>,
}

#[derive(Deserialize)]
struct ExclusionQuery {
    /// Absent means every project, which is what the canvas asks for.
    project_id: Option<String>,
}

/// The rules in force, for the canvas to draw.
///
/// Only the live ones. A revoked rule is kept in the table so the decision stays readable, but a
/// screen that drew it would be showing a constraint that is not constraining anything.
async fn get_fleet_exclusions(
    State(state): State<AppState>,
    Query(query): Query<ExclusionQuery>,
) -> Result<Json<Vec<crate::exclusion::Exclusion>>, StatusCode> {
    crate::exclusion::live(&state.pool, query.project_id.as_deref())
        .await
        .map(Json)
        .map_err(|error| {
            tracing::warn!(%error, "reading the fleet exclusions failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })
}

/// The requests waiting on an answer.
///
/// `/proposals` cannot carry these: it serves `action-approval` alone, deliberately, because
/// approving one of those resumes a paused run and approving one of these resumes nothing — the
/// argument `list_pending` and `get_contact_merges` both make at length. So this follows the door
/// `contact-merge` opened, which also puts the question where the context is: whether two jobs
/// should be serialised is decided while looking at the fleet.
async fn get_fleet_exclusion_requests(
    State(state): State<AppState>,
) -> Result<Json<Vec<crate::proposals::Proposal>>, StatusCode> {
    crate::exclusion::pending_requests(&state.pool)
        .await
        .map(Json)
        .map_err(|error| {
            tracing::warn!(%error, "reading the pending exclusion requests failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })
}

/// Lifts a rule.
///
/// 409 and not 404 when it is already revoked: the row is there, and the difference between "no such
/// rule" and "somebody lifted this before you" is the difference between a stale screen and a wrong
/// id.
async fn delete_fleet_exclusion(
    State(state): State<AppState>,
    Path(id): Path<i64>,
) -> Result<StatusCode, StatusCode> {
    match crate::exclusion::revoke(&state.pool, id).await {
        Ok(true) => Ok(StatusCode::NO_CONTENT),
        Ok(false) => Err(StatusCode::CONFLICT),
        Err(error) => {
            tracing::warn!(exclusion_id = id, %error, "revoking an exclusion failed");
            Err(StatusCode::INTERNAL_SERVER_ERROR)
        }
    }
}

/// Asks that two jobs of one project not run at the same time.
///
/// It answers 201 with a PROPOSAL id, not with a rule id, and the difference is the design. Drawing
/// this edge changes nothing about how the fleet schedules until somebody approves it in the same
/// queue every other decision passes through. An edge that took effect on being drawn would be a way
/// to change scheduling without passing through approval, which is exactly the property this
/// pillar's canvas was meant not to copy from october.dev.
///
/// Every refusal carries a sentence, following `post_proposal_approve`: three of the five mean
/// different things a person can act on — a pair already asked about, a pair already excluded, and
/// two jobs that share no project — and a bare 409 tells them apart from nothing.
async fn post_fleet_exclusion(
    State(state): State<AppState>,
    Json(body): Json<ExclusionRequest>,
) -> Result<(StatusCode, Json<serde_json::Value>), (StatusCode, String)> {
    use crate::exclusion::ProposeError;
    match crate::exclusion::propose(&state.pool, body.job_a, body.job_b, &body.paths).await {
        Ok(proposal_id) => Ok((
            StatusCode::CREATED,
            Json(serde_json::json!({ "proposal_id": proposal_id })),
        )),
        Err(ProposeError::SameJob) => Err((
            StatusCode::BAD_REQUEST,
            "a job cannot be excluded from itself".to_owned(),
        )),
        Err(ProposeError::UnknownJob(id)) => {
            Err((StatusCode::NOT_FOUND, format!("there is no job {id}")))
        }
        Err(ProposeError::DifferentProjects) => Err((
            StatusCode::BAD_REQUEST,
            "these jobs belong to different projects, so they share no slots to serialise"
                .to_owned(),
        )),
        Err(ProposeError::AlreadyAsked) => Err((
            StatusCode::CONFLICT,
            "these two jobs already have a request waiting for a decision".to_owned(),
        )),
        Err(ProposeError::AlreadyExcluded) => Err((
            StatusCode::CONFLICT,
            "these two jobs are already excluded from running at the same time".to_owned(),
        )),
        Err(ProposeError::Db(error)) => {
            tracing::warn!(%error, "asking for a fleet exclusion failed");
            Err((
                StatusCode::INTERNAL_SERVER_ERROR,
                "the request could not be recorded".to_owned(),
            ))
        }
    }
}

#[derive(Deserialize)]
struct WipLimitRequest {
    /// `null` switches the brake off for this project.
    limit: Option<i64>,
}

/// Sets one project's open-proposal ceiling.
///
/// The brake it controls is self-clearing — it releases the moment you review something — so the
/// number is the answer to "how much unreviewed work am I willing to be holding", and until now it
/// could only be changed with sqlite3. A negative ceiling is refused rather than stored: `queue_is_full`
/// compares `open >= limit`, so a negative one would mean "never start anything again" while reading
/// like a number somebody chose.
async fn post_project_wip_limit(
    State(state): State<AppState>,
    Path(id): Path<String>,
    Json(body): Json<WipLimitRequest>,
) -> Result<StatusCode, StatusCode> {
    if body.limit.is_some_and(|limit| limit < 0) {
        return Err(StatusCode::BAD_REQUEST);
    }
    let updated = sqlx::query("UPDATE autopilot_state SET wip_limit = ? WHERE project_id = ?")
        .bind(body.limit)
        .bind(&id)
        .execute(&state.pool)
        .await
        .map_err(|error| {
            tracing::warn!(project_id = %id, %error, "setting a project WIP limit failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })?;
    if updated.rows_affected() == 0 {
        return Err(StatusCode::NOT_FOUND);
    }
    Ok(StatusCode::NO_CONTENT)
}

/// Every supervised sidecar and what has happened to it.
///
/// A sidecar that keeps failing to start was previously invisible: `sidecar.rs` restarts it with a
/// backoff and writes one warning per attempt to a log nobody reads while using the app. For the
/// email poller in particular that meant the Mail tab looked like a quiet mailbox — which is what an
/// empty inbox looks like too.
async fn get_sidecars() -> Json<Vec<crate::sidecar::SidecarState>> {
    Json(crate::sidecar::states())
}

/// Ask a sidecar's supervisor to stop waiting and start it now.
///
/// **The kill switch covers this**, for [`delete_project_folder`]'s reason and with its wording:
/// everything else the switch stops is autonomous and this is a person pressing a button, but the
/// switch means *nothing that changes anything happens right now*, and spawning an operating-system
/// process is a change. What it does NOT do is stop the supervisor's own retry loop, which the switch
/// has never governed — so this refuses the button and says so, and the shell says the rest rather
/// than implying the machine is frozen. Project brakes are not consulted: a sidecar belongs to no
/// project, and `scoped_kill_engaged` wants a project id this route does not have.
///
/// `{name}` is the SUPERVISOR's key (`browser`), which is what `GET /sidecars` calls a sidecar. The
/// health readout's row name (`browser_sidecar`) is the shell's to translate, and a wrong translation
/// arrives here as `not_supervised` — a sentence in the row — rather than as silence.
async fn post_sidecar_restart(
    State(state): State<AppState>,
    Path(name): Path<String>,
) -> Result<(StatusCode, Json<serde_json::Value>), (StatusCode, Json<serde_json::Value>)> {
    let halted = crate::autopilot::kill_switch_engaged(&state.pool)
        .await
        .map_err(|_| {
            (
                StatusCode::INTERNAL_SERVER_ERROR,
                Json(serde_json::json!({ "refusal": "internal" })),
            )
        })?;
    if halted {
        return Err((
            StatusCode::LOCKED,
            Json(serde_json::json!({ "refusal": "kill_switch" })),
        ));
    }

    match crate::sidecar::ask_to_restart(&name) {
        crate::sidecar::RestartOutcome::Asked => {
            tracing::info!(sidecar = %name, "a restart was asked for");
            // 202 and not 200: what this promises is that the supervisor was told, not that the
            // sidecar is up. The spawn happens in the supervisor's own task, and the readout is
            // where the answer to "did it work" lives.
            Ok((
                StatusCode::ACCEPTED,
                Json(serde_json::json!({ "name": name, "asked": true })),
            ))
        }
        crate::sidecar::RestartOutcome::AlreadyRunning => Err((
            StatusCode::CONFLICT,
            Json(serde_json::json!({ "refusal": "running" })),
        )),
        crate::sidecar::RestartOutcome::NotSupervised => Err((
            StatusCode::NOT_FOUND,
            Json(serde_json::json!({ "refusal": "not_supervised" })),
        )),
    }
}

/// The email pillar's settings, minus everything secret.
///
/// No password: it comes from Credential Manager, is handed to the sidecar process, and does not
/// pass through here. The host and account are named because "which mailbox is this" is the question
/// the rest of the panel's numbers are about.
#[derive(serde::Serialize)]
struct EmailConfigView {
    enabled: bool,
    /// True only once the hook barrier has been PROVEN at startup. Enabled but unarmed is a real
    /// state — the pillar owns retention either way — and it is why triage can be stopped while
    /// mail keeps arriving.
    armed: bool,
    host: String,
    username: String,
    mailbox: String,
    sent_mailbox: Option<String>,
    poll_interval_secs: u64,
    notify_classes: Vec<String>,
    digest_hour_utc: u8,
    retain_bodies_days: u8,
    /// Why local triage is unavailable when a local model was configured but could not be trusted.
    local_triage_disabled: Option<String>,
}

/* --------------------------------------------------- this machine's settings -- */

/// The root every row in [`crate::machine_config`] is relative to, or a refusal when startup could
/// not name one. See [`crate::state::AppState::machine_config_root`].
fn machine_config_root(
    state: &AppState,
) -> Result<std::path::PathBuf, (StatusCode, Json<serde_json::Value>)> {
    state
        .machine_config_root
        .clone()
        .ok_or_else(|| refusal(StatusCode::INTERNAL_SERVER_ERROR, "no_machine_root"))
}

/// This machine's settings: the fence, and what is currently inside it.
///
/// The whole table every time, including rows whose file does not exist, because "this pillar has
/// never been configured" is the answer the page most needs and an absent row cannot give it. That
/// is the same reason `GET /projects/{id}/ownership` serves claims rather than files.
///
/// `display` is the spelling a person is shown (`~/.nucleos/voice.yaml`) and `resolved` the file the
/// daemon actually opens. The second used to matter more than it does: when these files were
/// relative to the working directory, twenty worktrees meant twenty candidate files, and the
/// absolute path was the only thing that said which one the page was editing. It is still served,
/// because "which file is this" deserves an answer that is not an abbreviation.
///
/// No secret is in any of these files by construction — every one of them lives in the OS
/// credential store instead, and each config type's doc says so where the temptation was closest.
/// So the contents go over the wire as they are.
async fn get_machine_config(
    State(state): State<AppState>,
) -> Result<Json<serde_json::Value>, (StatusCode, Json<serde_json::Value>)> {
    let root = machine_config_root(&state)?;
    let read_root = root.clone();
    let rows = tokio::task::spawn_blocking(move || {
        crate::machine_config::SETTINGS
            .iter()
            .map(|setting| {
                let target = read_root.join(setting.path);
                let contents = std::fs::read_to_string(&target).ok();
                serde_json::json!({
                    "path": setting.path,
                    "display": crate::machine_config::display_path(setting.path),
                    "area": setting.area,
                    "what": setting.what,
                    "takes_effect": setting.takes_effect,
                    "exists": contents.is_some(),
                    "contents": contents,
                    "resolved": target.display().to_string(),
                })
            })
            .collect::<Vec<_>>()
    })
    .await
    .map_err(|_| refusal(StatusCode::INTERNAL_SERVER_ERROR, "internal"))?;

    Ok(Json(serde_json::json!({
        "root": root.display().to_string(),
        "root_display": crate::machine_config::ROOT_DISPLAY,
        "settings": rows,
    })))
}

/// Writes one of this machine's settings files, having first made it prove it parses.
///
/// Deliberately the same shape as [`post_project_write`] — same refusal names, same validate-then-
/// write order, same atomic rename — because it is the same act against a different root, and two
/// write routes that disagreed about what `invalid` means would be two contracts for one page.
///
/// **Admin, by appearing in no table in `auth.rs`.** `permits` is default-deny, which is what
/// protects a route nobody thought about; this one was thought about, and the answer is the same.
/// It matters more here than for a project's rules file: `~/.nucleos/github.yaml` names what a run may do
/// on GitHub without asking, and `~/.nucleos/nucleos-models.yaml` names the models every route is built
/// from. The control token reaches this, and `assistant.rs` hands that token to an MCP-only
/// assistant turn — which is precisely why the kill switch is consulted below.
///
/// The global kill switch only. There is no project-scoped one to ask about: this file is not any
/// project's, which is the whole reason it has its own registry.
async fn post_machine_config(
    State(state): State<AppState>,
    Json(body): Json<WriteRequest>,
) -> Result<StatusCode, (StatusCode, Json<serde_json::Value>)> {
    // Unreadable reads as engaged, the rule `assistant.rs` already pins: a stop nobody can ask
    // about is not a stop anybody may assume is off.
    if crate::autopilot::kill_switch_engaged(&state.pool)
        .await
        .unwrap_or(true)
    {
        return Err(refusal(StatusCode::LOCKED, "kill_switch"));
    }

    let Some(setting) = crate::machine_config::setting_for(&body.path) else {
        return Err(refusal(StatusCode::FORBIDDEN, "not_ours"));
    };

    let root = machine_config_root(&state)?;
    // The root may not exist yet — it is created by the first file anybody writes into it — and
    // `safe_write_target` canonicalises the root before it will answer. Created only once the path
    // is known to be a row, so a refused path still leaves nothing behind.
    std::fs::create_dir_all(&root).map_err(|error| {
        tracing::warn!(%error, "could not create this machine's settings directory");
        refusal(StatusCode::INTERNAL_SERVER_ERROR, "internal")
    })?;
    // `setting.path` and not `body.path`: the caller's spelling has been matched against the table
    // and has done its job. Joining the table's own string is what makes a path that normalises to
    // a row unable to reach a file the row does not name.
    let target = inspect::safe_write_target(&root, setting.path)
        .map_err(|error| refusal(inspect_status(error), "unwritable"))?;

    if let Err(detail) = (setting.validate)(&body.contents) {
        return Err((
            StatusCode::UNPROCESSABLE_ENTITY,
            Json(serde_json::json!({ "refusal": "invalid", "detail": detail })),
        ));
    }

    let contents = body.contents;
    tokio::task::spawn_blocking(move || crate::project_state::write_atomically(&target, &contents))
        .await
        .map_err(|_| refusal(StatusCode::INTERNAL_SERVER_ERROR, "internal"))?
        .map_err(|error| {
            tracing::warn!(%error, path = %setting.path, "writing a machine settings file failed");
            refusal(StatusCode::INTERNAL_SERVER_ERROR, "internal")
        })?;

    // `None` for the project, because there is not one — this is the machine's own line. After the
    // write and loudly on failure, for the reason `post_project_write` gives: a feed line about a
    // write that then failed claims something that did not happen.
    if let Err(error) = feed::append(
        &state.pool,
        None,
        "config_written",
        &format!(
            "{} written from the app",
            crate::machine_config::display_path(setting.path)
        ),
        None,
        // A machine setting or a credential: nothing a run, a job or a council owns.
        None,
    )
    .await
    {
        tracing::error!(%error, path = %setting.path, "the settings file was written but the feed line was lost");
    }

    Ok(StatusCode::NO_CONTENT)
}

/// The credentials this machine holds, by whether they are set — never by what they are.
///
/// The listing carries no value and there is no route that serves one, which is enforced a layer
/// down: [`crate::secrets::SecretStore`] has no method that returns a secret, so a future handler
/// cannot serve one by accident. Presence is the only question a settings page has.
async fn get_machine_secrets(
    State(state): State<AppState>,
) -> Result<Json<serde_json::Value>, (StatusCode, Json<serde_json::Value>)> {
    let rows = crate::machine_config::SECRETS
        .iter()
        .map(|secret| {
            // A store that cannot answer is reported as unknown rather than as absent. "Not set"
            // is a fact somebody would act on by pasting a credential they have already pasted.
            let present = state.secrets.present(secret.key).ok();
            serde_json::json!({
                "key": secret.key,
                "area": secret.area,
                "what": secret.what,
                "present": present,
            })
        })
        .collect::<Vec<_>>();
    Ok(Json(serde_json::json!({ "secrets": rows })))
}

/// A credential on its way in. Deliberately derives no `Debug`.
///
/// `Debug` is how a secret ends up in a log: one `tracing::warn!(?body, …)` written in a hurry by
/// somebody debugging an unrelated failure, and the credential is on disk in the daemon's rotating
/// log file. Not deriving it makes that line refuse to compile.
#[derive(Deserialize)]
struct SecretRequest {
    value: String,
}

/// Stores one credential, or refuses.
///
/// **Why the app may write these at all**, given that `--set-*` reads from stdin precisely to keep
/// a token off a command line: that reasoning is about ARGV. A Windows command line is readable by
/// any process running as the same user and is recorded verbatim in PSReadLine's history, so a
/// token passed as an argument lands on disk in cleartext at the moment somebody was securely
/// storing it. None of that is true of a request body over loopback to the one process that
/// already holds every one of these credentials and hands them to the sidecars it starts.
///
/// Admin, by appearing in no table in `auth.rs`, on the same default-deny footing as everything
/// else under `/config`. The kill switch is consulted for the same reason the settings write
/// consults it: the control token reaches here, and a credential is a capability.
async fn put_machine_secret(
    State(state): State<AppState>,
    Path(key): Path<String>,
    Json(body): Json<SecretRequest>,
) -> Result<StatusCode, (StatusCode, Json<serde_json::Value>)> {
    if crate::autopilot::kill_switch_engaged(&state.pool)
        .await
        .unwrap_or(true)
    {
        return Err(refusal(StatusCode::LOCKED, "kill_switch"));
    }

    // `daemon-token` takes this path: it is not in the table, so it is `not_ours` like any other
    // key nobody declared. That is deliberate rather than incidental — see `SECRETS`.
    let Some(secret) = crate::machine_config::secret_for(&key) else {
        return Err(refusal(StatusCode::FORBIDDEN, "not_ours"));
    };

    // An empty value is refused rather than stored. Storing one would leave a credential that
    // exists and does not work, which reads as "configured" everywhere it is asked about — the
    // worst of the three available states. Forgetting it is what DELETE is for.
    if body.value.is_empty() {
        return Err((
            StatusCode::UNPROCESSABLE_ENTITY,
            Json(serde_json::json!({
                "refusal": "invalid",
                "detail": "an empty value is not a credential; use DELETE to forget one",
            })),
        ));
    }

    state
        .secrets
        .store(secret.key, &body.value)
        .map_err(|error| {
            // `error` and never the value.
            tracing::warn!(%error, key = %secret.key, "storing a credential failed");
            refusal(StatusCode::INTERNAL_SERVER_ERROR, "internal")
        })?;

    // The key, never the value, and no length either — a length is a hint about a secret.
    if let Err(error) = feed::append(
        &state.pool,
        None,
        "secret_stored",
        &format!("the {} credential was set from the app", secret.key),
        None,
        // A machine setting or a credential: nothing a run, a job or a council owns.
        None,
    )
    .await
    {
        tracing::error!(%error, key = %secret.key, "the credential was stored but the feed line was lost");
    }

    Ok(StatusCode::NO_CONTENT)
}

/// Forgets one credential.
///
/// Idempotent, because [`crate::secrets::delete_secret`] already treats a missing entry as done:
/// a page that had to distinguish "forgotten" from "was not there" would be asking a question
/// whose two answers call for the same next step.
async fn delete_machine_secret(
    State(state): State<AppState>,
    Path(key): Path<String>,
) -> Result<StatusCode, (StatusCode, Json<serde_json::Value>)> {
    if crate::autopilot::kill_switch_engaged(&state.pool)
        .await
        .unwrap_or(true)
    {
        return Err(refusal(StatusCode::LOCKED, "kill_switch"));
    }

    let Some(secret) = crate::machine_config::secret_for(&key) else {
        return Err(refusal(StatusCode::FORBIDDEN, "not_ours"));
    };

    state.secrets.forget(secret.key).map_err(|error| {
        tracing::warn!(%error, key = %secret.key, "forgetting a credential failed");
        refusal(StatusCode::INTERNAL_SERVER_ERROR, "internal")
    })?;

    if let Err(error) = feed::append(
        &state.pool,
        None,
        "secret_forgotten",
        &format!("the {} credential was forgotten from the app", secret.key),
        None,
        // A machine setting or a credential: nothing a run, a job or a council owns.
        None,
    )
    .await
    {
        tracing::error!(%error, key = %secret.key, "the credential was forgotten but the feed line was lost");
    }

    Ok(StatusCode::NO_CONTENT)
}

async fn get_email_config(State(state): State<AppState>) -> Json<EmailConfigView> {
    Json(EmailConfigView {
        enabled: state.email.enabled,
        armed: state.email.armed.load(std::sync::atomic::Ordering::Relaxed),
        host: state.email.host.clone(),
        username: state.email.username.clone(),
        mailbox: state.email.mailbox.clone(),
        sent_mailbox: state.email.sent_mailbox.clone(),
        poll_interval_secs: state.email.poll_interval_secs,
        notify_classes: state.email.notify_classes.clone(),
        digest_hour_utc: state.email.digest_hour_utc,
        retain_bodies_days: state.email.retain_bodies_days,
        local_triage_disabled: state.local_triage_disabled.clone(),
    })
}

/// One roster row, plus the one thing about it that is not in the database.
///
/// `#[serde(flatten)]` so the wire shape stays the summary with a field added, rather than a
/// nesting the shell would have to reach through — the same arrangement `GraphView` uses.
#[derive(serde::Serialize)]
struct RosterEntry {
    /// Whether the recorded folder is actually on the disk.
    ///
    /// **Three states and not two, because the page that reads this used to collapse two of them.**
    /// `None` means no folder was ever named — the project exists in the daemon and nobody has
    /// pointed it anywhere, which is a thing to finish, not a thing that broke. `Some(false)` means
    /// a folder WAS named and is not there, which is a thing that broke. `Some(true)` is fine.
    ///
    /// Answered here rather than by the shell, which used to ask for a directory listing per
    /// project to find this out: on a roster of twenty-five that was twenty-five requests on every
    /// load, to learn one bit each. It is also what makes the page's headline and its rows agree —
    /// the headline counted *recorded roots* and the rows probed the *folder*, both worded
    /// "folder", so a roster could say "all with a folder" above seven rows saying it was gone.
    root_exists: Option<bool>,
    #[serde(flatten)]
    summary: ProjectSummary,
}

async fn get_projects(State(state): State<AppState>) -> Result<Json<Vec<RosterEntry>>, StatusCode> {
    let summaries = autopilot::project_roster(&state.pool)
        .await
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;

    /*
       On the blocking pool, and it is not superstition: this route is polled every three seconds,
       most of these roots are ordinary local folders answering in microseconds, and one of them on
       a disconnected network share is a `stat` that blocks for as long as the OS feels like. One
       such project would stall the executor thread this future is on, for every caller.
    */
    tokio::task::spawn_blocking(move || {
        summaries
            .into_iter()
            .map(|summary| RosterEntry {
                root_exists: summary
                    .project_root
                    .as_deref()
                    .map(|root| std::path::Path::new(root).is_dir()),
                summary,
            })
            .collect::<Vec<_>>()
    })
    .await
    .map(Json)
    .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)
}

/// What a project would lose by leaving, and what is stopping it.
///
/// Fetched by the roster's remove control when somebody opens it, and not before: it is nine
/// `COUNT(*)`s that only matter once a person is deciding, and a roster of twenty-five would
/// otherwise run them all every three seconds to draw a button nobody pressed.
async fn get_project_record(
    State(state): State<AppState>,
    Path(id): Path<String>,
) -> Result<Json<crate::project_exit::ProjectRecord>, StatusCode> {
    // No `resolve_project_root` here, and that is not an oversight: it 404s a project with no
    // folder named, and `charlie` — registered, switched off, never pointed anywhere — is exactly
    // the project somebody most wants to remove. The store answers whether the roster knows the
    // name, which is the only thing this route needs to be sure of.
    match crate::project_exit::record(&state.pool, &id).await {
        Ok(Some(record)) => Ok(Json(record)),
        Ok(None) => Err(StatusCode::NOT_FOUND),
        Err(error) => {
            tracing::warn!(project_id = %id, %error, "reading a project's record failed");
            Err(StatusCode::INTERNAL_SERVER_ERROR)
        }
    }
}

/// Whether the history goes with the roster row.
///
/// A query and not a body, because this is a DELETE and the default has to be the safe one: a
/// caller that sends nothing keeps everything. `serde`'s default gives exactly that, and it is the
/// owner's standing decision — history stays unless somebody says otherwise, at the moment they say
/// it.
#[derive(Deserialize)]
struct RemoveProjectQuery {
    #[serde(default)]
    forget_history: bool,
}

/// Take a project off the roster.
///
/// **Nothing on the disk is touched here, and there is no flag that would make it be.** Deleting a
/// folder is a second act with its own route, its own confirmation and its own refusals; a
/// `?delete_folder=true` on this one would be the same weight for two very different things, and
/// the caller that eventually passed it would be a caller that meant the reversible one.
async fn delete_project(
    State(state): State<AppState>,
    Path(id): Path<String>,
    Query(query): Query<RemoveProjectQuery>,
) -> Result<StatusCode, (StatusCode, Json<serde_json::Value>)> {
    match crate::project_exit::remove(&state.pool, &id, query.forget_history).await {
        Ok(crate::project_exit::Removed::Done { forgotten }) => {
            tracing::info!(project_id = %id, forgotten, "a project left the roster");
            Ok(StatusCode::NO_CONTENT)
        }
        Ok(crate::project_exit::Removed::NotRegistered) => Err((
            StatusCode::NOT_FOUND,
            Json(serde_json::json!({ "refusal": "not_registered" })),
        )),
        // 409 and not 423: the kill switch's `locked` means a standing decision that a person took,
        // and this is the opposite — work in progress that clears itself by finishing. The detail
        // names what is holding it, because "try again later" over an unnamed obstacle is how
        // somebody ends up pressing a button every minute.
        Ok(crate::project_exit::Removed::Held(holds)) => Err((
            StatusCode::CONFLICT,
            Json(serde_json::json!({
                "refusal": "in_flight",
                "detail": held_by(&holds),
                "holds": holds,
            })),
        )),
        // Only reachable with `forget_history`, and the sentence says the escape rather than the
        // constraint: "FOREIGN KEY constraint failed" is true and useless, and the thing to do is
        // one untick away.
        Ok(crate::project_exit::Removed::Referenced) => Err((
            StatusCode::CONFLICT,
            Json(serde_json::json!({
                "refusal": "history_referenced",
                "detail": "something outside this project still points at its history — \
                           removing it without forgetting works, and nothing was touched",
            })),
        )),
        Err(error) => {
            tracing::warn!(project_id = %id, %error, "removing a project failed");
            Err((
                StatusCode::INTERNAL_SERVER_ERROR,
                Json(serde_json::json!({ "refusal": "internal" })),
            ))
        }
    }
}

/// A guard that would refuse, named so the screen can say it before anybody presses anything.
#[derive(serde::Serialize)]
struct FolderBlock {
    refusal: &'static str,
    detail: String,
}

/// What deleting this project's folder would take, and whether it would be allowed at all.
///
/// **Three separate questions, kept apart in three fields**, because a screen has to say a different
/// sentence for each and a single "can I?" boolean would collapse them. `only_here` is what would be
/// lost for ever; `blocked` is a standing refusal about the path itself; `holds` is work in flight,
/// which clears on its own.
#[derive(serde::Serialize)]
struct FolderView {
    /// The recorded root, or `null` for a project nobody ever pointed anywhere.
    root: Option<String>,
    /// Whether that folder is actually on this disk. A project pointed at a folder that has already
    /// gone has nothing to delete, and the screen says so rather than offering the button.
    exists: bool,
    /// What is in there and nowhere else, or `null` for a folder git knows nothing about — which is
    /// the more serious answer and not a missing one.
    only_here: Option<crate::inspect::OnlyHere>,
    blocked: Option<FolderBlock>,
    holds: crate::project_exit::Holds,
}

async fn get_project_folder(
    State(state): State<AppState>,
    Path(id): Path<String>,
) -> Result<Json<FolderView>, StatusCode> {
    let recorded: Option<Option<String>> =
        sqlx::query_scalar("SELECT project_root FROM autopilot_state WHERE project_id = ?")
            .bind(&id)
            .fetch_optional(&state.pool)
            .await
            .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    let Some(recorded) = recorded else {
        return Err(StatusCode::NOT_FOUND);
    };

    let blocked = match crate::project_exit::folder_check(&state.pool, &id, recorded.as_deref())
        .await
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?
    {
        Ok(_) => None,
        Err(refusal) => Some(FolderBlock {
            refusal: refusal.code(),
            detail: refusal.detail(),
        }),
    };

    let record = crate::project_exit::record(&state.pool, &id)
        .await
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?
        .ok_or(StatusCode::NOT_FOUND)?;

    /*
       Two `git` subprocesses and a `stat`, on the blocking pool for the reason `get_projects` puts
       its own probe there: a project root on a disconnected network share blocks for as long as the
       operating system feels like, and this future is on an executor thread shared by every caller.
       Asked only when the folder is really there — git in a directory that does not exist answers
       with an error nobody would learn anything from.
    */
    let root = recorded.clone();
    let (exists, only_here) = tokio::task::spawn_blocking(move || match root {
        None => (false, None),
        Some(root) => {
            let path = std::path::Path::new(&root);
            if !path.is_dir() {
                return (false, None);
            }
            (true, crate::inspect::only_here(path).ok().flatten())
        }
    })
    .await
    .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;

    Ok(Json(FolderView {
        root: recorded,
        exists,
        only_here,
        blocked,
        holds: record.holds,
    }))
}

/// Delete a project's folder, and take it off the roster.
///
/// **The kill switch covers this, and it is the clearest case there is for it.** Everything else the
/// switch stops is autonomous — this is a person pressing a button — but it is also the largest
/// thing this app can do, and the switch's meaning is *nothing that changes anything happens right
/// now*. A folder deletion sailing past an engaged emergency stop would be the one exception nobody
/// would expect.
async fn delete_project_folder(
    State(state): State<AppState>,
    Path(id): Path<String>,
    Query(query): Query<RemoveProjectQuery>,
) -> Result<StatusCode, (StatusCode, Json<serde_json::Value>)> {
    let halted = crate::autopilot::kill_switch_engaged(&state.pool)
        .await
        .map_err(|_| {
            (
                StatusCode::INTERNAL_SERVER_ERROR,
                Json(serde_json::json!({ "refusal": "internal" })),
            )
        })?;
    if halted {
        return Err((
            StatusCode::LOCKED,
            Json(serde_json::json!({ "refusal": "kill_switch" })),
        ));
    }

    match crate::project_exit::delete_folder(&state.pool, &id, query.forget_history).await {
        Ok(crate::project_exit::Deleted::Done { forgotten }) => {
            tracing::info!(project_id = %id, forgotten, "a project's folder was deleted");
            Ok(StatusCode::NO_CONTENT)
        }
        Ok(crate::project_exit::Deleted::NotRegistered) => Err((
            StatusCode::NOT_FOUND,
            Json(serde_json::json!({ "refusal": "not_registered" })),
        )),
        Ok(crate::project_exit::Deleted::Held(holds)) => Err((
            StatusCode::CONFLICT,
            Json(serde_json::json!({
                "refusal": "in_flight",
                "detail": held_by(&holds),
                "holds": holds,
            })),
        )),
        Ok(crate::project_exit::Deleted::Refused(refusal)) => Err((
            StatusCode::CONFLICT,
            Json(serde_json::json!({
                "refusal": refusal.code(),
                "detail": refusal.detail(),
            })),
        )),
        // Logged at `error` and not `warn`: this is the state that needs a person, and it is the
        // only outcome in this file where the machine is left partway through something.
        Ok(crate::project_exit::Deleted::Partial { root, error }) => {
            tracing::error!(project_id = %id, %root, %error, "a folder was only partly deleted");
            Err((
                StatusCode::INTERNAL_SERVER_ERROR,
                Json(serde_json::json!({
                    "refusal": "partly_deleted",
                    "detail": format!(
                        "{id} is off the roster and {root} did not fully delete: {error}. \
                         What is left has to be removed by hand."
                    ),
                })),
            ))
        }
        Err(error) => {
            tracing::warn!(project_id = %id, %error, "deleting a project folder failed");
            Err((
                StatusCode::INTERNAL_SERVER_ERROR,
                Json(serde_json::json!({ "refusal": "internal" })),
            ))
        }
    }
}

/// The refusal's sentence, built where the numbers are rather than in the shell.
///
/// Both halves are named when both are non-zero. They are genuinely two facts — a run can hold a
/// slot before it has checked anything out, and a checkout can outlive the run that made it — and a
/// sentence that mentioned only the larger number would send somebody to wait for work that had
/// already finished.
fn held_by(holds: &crate::project_exit::Holds) -> String {
    fn plural(count: i64, one: &str, many: &str) -> String {
        format!("{count} {}", if count == 1 { one } else { many })
    }

    let mut parts = Vec::new();
    if holds.slots > 0 {
        parts.push(format!(
            "{} still working here",
            plural(holds.slots, "slot", "slots")
        ));
    }
    if holds.worktrees > 0 {
        parts.push(format!(
            "{} still checked out",
            plural(holds.worktrees, "worktree", "worktrees")
        ));
    }
    format!("{} — nothing was removed", parts.join(" and "))
}

async fn get_concurrency(
    State(state): State<AppState>,
) -> Result<Json<crate::concurrency::Readout>, StatusCode> {
    crate::concurrency::readout(&state.pool)
        .await
        .map(Json)
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)
}

#[derive(Deserialize)]
struct WaveRequest {
    /// Where the controller stands. The project is resolved from it the way the session hook
    /// resolves one, so a controller never has to know an id the daemon made up.
    cwd: String,
    workers: i64,
}

async fn post_wave(
    State(state): State<AppState>,
    Json(body): Json<WaveRequest>,
) -> Result<Json<crate::wave::Grant>, (StatusCode, String)> {
    if !(1..=crate::wave::MAX_WORKERS).contains(&body.workers) {
        return Err((
            StatusCode::BAD_REQUEST,
            format!(
                "a wave asks for 1 to {} workers, not {}",
                crate::wave::MAX_WORKERS,
                body.workers
            ),
        ));
    }
    let deadline = std::time::Instant::now() + crate::git_exec::OPERATION_TIMEOUT;
    let root = crate::git_exec::toplevel(std::path::Path::new(&body.cwd), deadline)
        .await
        .map_err(|error| {
            (
                StatusCode::BAD_REQUEST,
                format!("{} is not inside a git checkout: {error}", body.cwd),
            )
        })?;
    // 404 and not 400: the request is well formed, and the answer is that this daemon cannot vouch
    // for that repository's capacity — not on its roster, or the roster could not be read. Both fail
    // the safe way: the controller reads either as `no_capacity_authority` and runs one worker.
    let project_id = vcs::project_for_worktree(&state.pool, &root, deadline)
        .await
        .map_err(|error| (StatusCode::NOT_FOUND, error))?;
    crate::wave::grant(&state.pool, &project_id, body.workers, chrono::Utc::now())
        .await
        .map(Json)
        .map_err(|error| {
            tracing::warn!(%project_id, %error, "granting a wave its slots failed");
            (
                StatusCode::INTERNAL_SERVER_ERROR,
                "could not grant the wave its slots".to_owned(),
            )
        })
}

/// 204 renewed; 410 lapsed or released, and its slots are given back; 404 no such wave.
async fn post_wave_renew(
    State(state): State<AppState>,
    Path(id): Path<i64>,
) -> Result<StatusCode, StatusCode> {
    match crate::wave::renew(&state.pool, id, chrono::Utc::now()).await {
        Ok(crate::wave::Renewal::Renewed) => Ok(StatusCode::NO_CONTENT),
        Ok(crate::wave::Renewal::Lapsed) => Err(StatusCode::GONE),
        Ok(crate::wave::Renewal::Unknown) => Err(StatusCode::NOT_FOUND),
        Err(error) => {
            tracing::warn!(wave_id = id, %error, "renewing a wave's lease failed");
            Err(StatusCode::INTERNAL_SERVER_ERROR)
        }
    }
}

/// 204 released, including a second time; 404 no such wave.
async fn delete_wave(
    State(state): State<AppState>,
    Path(id): Path<i64>,
) -> Result<StatusCode, StatusCode> {
    match crate::wave::release(&state.pool, id, chrono::Utc::now()).await {
        Ok(true) => Ok(StatusCode::NO_CONTENT),
        Ok(false) => Err(StatusCode::NOT_FOUND),
        Err(error) => {
            tracing::warn!(wave_id = id, %error, "releasing a wave's slots failed");
            Err(StatusCode::INTERNAL_SERVER_ERROR)
        }
    }
}

/// The four readings the project workspace leads with, in one answer.
///
/// One route and not four because all four are aggregations over the same rows in the same window —
/// this project's finished runs — and four routes would be four walks of one table for one panel.
///
/// No 404 for a project with no root. Unlike `ls` and `cat`, this asks nothing of the disk: a
/// project whose folder has moved still has a history of runs, and a reading of it is exactly what
/// somebody looking at a broken project wants. `resolve_project_root` would refuse it.
async fn get_project_readings(
    State(state): State<AppState>,
    Path(id): Path<String>,
    Query(query): Query<WindowQuery>,
) -> Result<Json<crate::project_readings::Readings>, StatusCode> {
    let days = query
        .days
        .unwrap_or(crate::project_readings::DEFAULT_WINDOW_DAYS);
    crate::project_readings::readings(&state.pool, &id, days, chrono::Utc::now())
        .await
        .map(Json)
        .map_err(|error| {
            tracing::warn!(%error, project_id = %id, "project readings failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })
}

/// The structure layer and the junction over it, in one answer.
///
/// **Flattened, so this is additive on the wire.** Every field the shell already reads — `modules`,
/// `imports`, `unread`, `foreign` — stays exactly where it was and `junction` is simply new beside
/// them. Nesting the structure under a key to make room would be a rewrite wearing the word
/// "extension", and would break a window nobody asked to change.
#[derive(Serialize)]
struct MapAnswer {
    #[serde(flatten)]
    structure: crate::project_map::Structure,
    /// §16.4's L0: the boundary between the two sides of this product, read from both ends.
    ///
    /// **On this answer and not on a route of its own, unlike `map/items`, and the difference is
    /// which question it belongs to.** Items are asked about one file once somebody opens it, so
    /// their cost lands on a click. The seam is the top of the picture and is on screen the moment
    /// the map is, so a route of its own would be a second request fired every time — and it would
    /// walk the tree again to learn what `structure` above already knows. It is computed from
    /// exactly those modules for the same reason: one definition of *which files are this
    /// project*.
    seam: crate::map_seam::Seam,
    junction: crate::map_join::Junction,
    /// Where each decision stands, by `decision_id`.
    ///
    /// **A map and never a parallel array.** Two arrays that must stay index-aligned is a bug
    /// waiting for the first re-sort, and the re-sort duly arrived: `junction.decisions` leaves
    /// [`crate::map_join::join`] in `spec_slug, ordinal, id` and leaves this handler in §10's
    /// recency order. Keyed by id, the client survived that; keyed by position it would now be
    /// drawing one decision's verdict against another's text, and nothing on the screen would look
    /// wrong.
    standings: std::collections::BTreeMap<i64, crate::map_stamp::Standing>,
    /// §5.3's header, tallied from exactly the standings above.
    stamps: crate::map_stamp::StampCounts,
    /// What the triager said about each decision, by `decision_id` — and only where that is still
    /// an answer about this map.
    ///
    /// **Two filters stand between [`crate::map_store::judgements`] and this field, and both are
    /// required for §5.3's numbers to add up.** [`crate::map_triage::reconcile`] argues them in
    /// full; the short of it is that a judgement about a decision somebody has since stamped
    /// describes a decision that has left triage's scope (§10), and a judgement whose
    /// `inputs_digest` no longer matches describes code that has since moved. Counting either
    /// reports something that is not true now — the first as a decision tallied in `settled` **and**
    /// in `flagged`, the second as a model's opinion of a file it never saw.
    ///
    /// **A map and never a parallel array**, for [`MapAnswer::standings`]'s reason: this list gets
    /// re-sorted into §10's order after the join.
    ///
    /// **The staleness test is three-valued, and the third value is why a judgement is kept rather
    /// than dropped when git will not answer.** A judgement whose digest cannot be COMPUTED — the
    /// decision's anchors came back [`crate::map_stamp::Anchors::Failed`] — is neither current nor
    /// expired, so it arrives here [`crate::map_triage::Held::checked`] `false` and counts in
    /// whichever pile it was already in. Dropping it was the first shape of this field and it was
    /// wrong at the scale of the whole project: every stored judgement is written against a
    /// `Computed(...)` reading, so one git hiccup made all of them stale at once and the map
    /// reported a three-hundred-row backlog as *nunca vista* — a fact about this daemon presented
    /// as a fact about the project. A flag we could not re-verify is still a flag; a flag we
    /// discarded becomes a claim that nobody ever looked. [`MapAnswer::git_would_not_answer`] is on
    /// the same answer and says why the flags are unchecked.
    ///
    /// A judgement that WAS tested and failed is genuinely dropped, and the decision reads
    /// untriaged, which is what it is: §10 sends the triager back over it.
    triage: std::collections::BTreeMap<i64, crate::map_triage::Held>,
    /// §5.3's `J à tua espera` and `K nunca vistas`, tallied in the same pass that built `triage`.
    ///
    /// **Beside [`MapAnswer::stamps`] rather than inside it**, which is
    /// [`crate::map_triage::TriageCounts`]'s own argument: `stamps` is the denominator these numbers
    /// are checked against, and one function producing both sides of `flagged + silenced + untriaged
    /// == never` could not be checked by anything.
    triage_counts: crate::map_triage::TriageCounts,
    /// **One fact about this whole reading, and never a fact about any single decision.**
    ///
    /// `map_stamp::digest` is all-or-nothing on purpose — one record it cannot parse takes the
    /// entire call to a failure, because dropping an anchor would read as `gone`, a file that never
    /// went anywhere. Correct for one anchor set; combined with this route calling it **once** for
    /// the union of every decision's anchors, it means a git that will not answer takes every
    /// settled stamp in the project to [`crate::map_stamp::Lapse::Unreadable`] at the same instant.
    ///
    /// That blast radius is accepted — the alternative is up to 350 process spawns on a route the
    /// window calls every time the map opens — and this flag is the price of accepting it. The
    /// owner meets one sentence saying git would not answer, rather than a screen of identical rows
    /// saying it 350 times, which is a wall of noise nobody reads to the bottom of and is how the
    /// one real lapse underneath it goes unseen.
    ///
    /// **Named for git refusing, and it was renamed from `anchors_unreadable` to make one thing
    /// impossible: printing *try again* at somebody with nothing to retry.** This flag is
    /// [`crate::map_stamp::Anchors::Failed`] and nothing else. A project with no git repository at
    /// all — §11's ordinary case — leaves it `false`, because there is nothing wrong there and no
    /// retry that could help; what that project gets instead is
    /// [`crate::map_stamp::Watch::NoRepository`] on each of its greens, which is a permanent fact
    /// and reads as one. The older name covered both, and the sentence a shell would have written
    /// under it was false for exactly the project that could do least about it.
    ///
    /// A decision with no anchor paths is untouched by this either way: git was never asked about
    /// it, so its digest is `""` however git is faring, and it stays
    /// [`crate::map_stamp::Watch::NoAnchor`] rather than flapping every time this goes up.
    git_would_not_answer: bool,
    /// §10's ordering — what `junction.decisions` is sorted by, and how far that sort can see.
    ///
    /// **Beside the list rather than folded into it, because the order is only half the answer.**
    /// A list carries the sequence and nothing about which part of it is a fact: on this repository
    /// 83 of the 112 anchor files fall inside the window and every decision behind the other 29
    /// ties, so a panel drawing this without [`crate::map_recency::Recency::window`] would present
    /// a mostly arbitrary tail with the same confidence as the head. §10 offers this ordering as
    /// *um facto do git*, and the honest way to keep that true is to say how far the git looked.
    recency: crate::map_recency::Recency,
    /// When this project's triager last answered anything, or `null` if it never has.
    ///
    /// **The one thing `triage` and `triage_counts` cannot say, and a panel was reduced to guessing
    /// it.** Both of those describe what is true NOW: a run that flagged everything and whose
    /// answers have all since gone stale leaves `triage` empty and §6.2's pile empty, which is
    /// indistinguishable from a project nobody has ever pressed the button on. Those two are not the
    /// same fact — the first says the triager's work expired, the second says none was ever done —
    /// and the panel wrote *as far as this map can see, it has never run* because that was the
    /// strongest true sentence available to it. A hedge is what an honest surface produces when the
    /// daemon declines a question it could answer.
    ///
    /// **Deliberately unfiltered by staleness and by standing.** See
    /// [`crate::map_store::last_triaged`]: filtering either way would make `null` mean *nothing it
    /// said still stands*, which is a different sentence and one the numbers already carry.
    last_triaged_at: Option<String>,
}

/// The project's whole graph: modules, imports, and what the approved decisions do or do not
/// anchor to.
///
/// Derived on every request and never stored — decision 1 of the spec. The walk and the join are
/// [`project_junction`], which the stamp route shares; the digest, the standings and §5.3's header
/// are this route's own.
///
/// **Three axes arrive beside one another and none is merged into the others.** §5 refuses to
/// flatten them — *"achatá-las numa só punha o triador e o dono a falar pela mesma boca"* — so
/// `junction` still says only what can be known without anybody looking, `standings` says what the
/// owner said and whether it is still true, and `triage` says what a model thought was worth their
/// eyes. A client is free to draw them together; it is not free to be handed one number that has
/// already decided how they combine. That is why `triage` is a map of verdicts and not a colour,
/// and why §6.1 spends a paragraph on the one combination that may never be drawn: *silenciado* is
/// a claim about the triager, and a green is the owner's.
///
/// **What this now answers that it did not: which decisions nothing implements.** The structure
/// alone cannot say it — it has never heard of a decision — and the pile alone cannot say it
/// either. Only the two read against each other can, and doing that by eye across a thousand-line
/// plan is precisely what the owner cannot do; decision 3 says the nodes that matter are the ones
/// that do not match, so a route that returned only the halves returned everything except the
/// product.
///
/// **The join is computed here and never by whoever draws it** — §9.3 makes `core/` the single
/// owner of that logic. A shell redoing it in TypeScript would be a second implementation, free to
/// drift from this one, and the drift would surface as a screen quietly confident about the wrong
/// nodes: the disease with better pixels. It also means `map_join`'s tests are tests of what ships,
/// rather than of a library the product bypasses.
///
/// **Nothing here filters on `approved_at`.** [`crate::map_store::approved`] already selects
/// `approved_at IS NOT NULL AND retired_at IS NULL`, and a second filter in this handler is the
/// one that goes stale — the argument [`crate::map_store::decide`] makes about checks that live in
/// handlers, and the failure `from_row` next door already had once.
///
/// A missing folder is a 404 and a failed query is a 500 — see [`project_junction`], which is where
/// both now happen.
async fn get_project_map(
    State(state): State<AppState>,
    Path(id): Path<String>,
) -> Result<Json<MapAnswer>, StatusCode> {
    let root = resolve_read_root(&state, &id, None).await?;
    let (structure, mut junction) = project_junction(&state, &id, root.clone()).await?;

    // Re-reads the sources `structure` already opened, and that is the cheaper of the two options
    // rather than an oversight: holding every file of a thousand-file project in memory to save one
    // pass would trade a bounded read for an unbounded allocation on a route somebody is waiting
    // on. `spawn_blocking` because it is file IO in an async handler, the same reason the walk
    // above is one.
    let seam = {
        let root = root.clone();
        let modules = structure.modules.clone();
        tokio::task::spawn_blocking(move || crate::map_seam::seam(&root, &modules))
            .await
            .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?
            .map_err(|error| {
                tracing::warn!(%error, project_id = %id, "reading the seam failed");
                StatusCode::INTERNAL_SERVER_ERROR
            })?
    };

    // One `git ls-files` for the union of every decision's anchor paths, sliced per decision
    // afterwards, and the same reading `POST /map/triage` shows the model. See [`anchor_digests`]
    // for why it is one call and one function.
    let (readings, anchors) = anchor_digests(&root, &junction.decisions).await;

    // §10's order, and the SAME call `POST /map/triage` makes before its sweep. Two orderings would
    // be two answers to one sentence of the spec, and the one deciding which twenty decisions get a
    // model call spent on them would be the one nobody ever looked at.
    let walked = crate::map_recency::walk(&root).await;
    let recency = crate::map_recency::order(&mut junction.decisions, &walked);

    let stamped = crate::map_store::stamps(&state.pool, &id)
        .await
        .map_err(|error| {
            tracing::warn!(%error, project_id = %id, "project map stamps failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })?;
    let latest: std::collections::BTreeMap<i64, &crate::map_store::Stamp> = stamped
        .iter()
        .map(|stamp| (stamp.decision_id, stamp))
        .collect();

    // Read beside the judgements and never derived from them, because it answers the question they
    // cannot: `answered` is what still describes this map, and a run whose every answer has since
    // gone stale comes back from it empty — identical to a project nobody ever pressed the button
    // on. One `MAX` over the table tells those two apart, and it is the difference between a panel
    // saying *it has never run here* and a panel hedging.
    let last_triaged_at = crate::map_store::last_triaged(&state.pool, &id)
        .await
        .map_err(|error| {
            tracing::warn!(%error, project_id = %id, "reading the last triage run failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })?;

    // The whole pile, stale rows and all, and the staleness decided below where the reading of the
    // repository is. `map_store::judgements` cannot decide it — see `Judged`, which argues why the
    // comparison belongs to whoever holds that reading, and what a store that filtered would have
    // cost §6.2's pile.
    let answered = crate::map_store::judgements(&state.pool, &id)
        .await
        .map_err(|error| {
            tracing::warn!(%error, project_id = %id, "reading the triage pile failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })?;
    let mut stored: std::collections::BTreeMap<i64, crate::map_store::Judged> = answered
        .into_iter()
        .map(|judged| (judged.decision_id, judged))
        .collect();

    // One clock for the whole answer rather than one per decision. Two amber stamps on either side
    // of `NOTE_LIFETIME` must be judged against the same instant, or the header can report a total
    // that was never true at any single moment.
    let now = chrono::Utc::now();
    let mut standings = std::collections::BTreeMap::new();
    // The judgements that survived the staleness test, in the order the decisions come in.
    // `map_triage::reconcile` applies the other filter — the one about standing — and tallies what
    // is left in the same pass that builds the map this answer ships.
    let mut current = Vec::new();
    for anchored in &junction.decisions {
        let anchors = anchor_reading(&readings, anchored.decision_id);
        standings.insert(
            anchored.decision_id,
            crate::map_stamp::standing(
                latest.get(&anchored.decision_id).copied(),
                crate::map_stamp::Anchoring {
                    current: anchors,
                    named: anchored.modules.len(),
                    // `Declared` and not merely *something names this section*. §8 is unfixed, so
                    // this is `false` for every decision in this repository today, and that is the
                    // measurement rather than a defect — see `Watch::Guessed`.
                    declared: anchored.anchor == crate::map_join::Anchor::Declared,
                },
                now,
            ),
        );

        // The digest is computed only for decisions that actually have a judgement, which is what
        // keeps this loop's cost proportional to the pile rather than to the map: on day one there
        // are ~350 decisions and no judgements at all, and a hash per decision would be 350 of them
        // to compare against nothing. The evidence is the SAME `Evidence` `POST /map/triage`
        // builds — one derivation, or a judgement could read current on one route and stale on the
        // other with nothing having happened.
        if let Some(judged) = stored.remove(&anchored.decision_id) {
            // **Three answers and not two.** With `Anchors::Failed` there is no digest to compare
            // against — `inputs_digest` would hash the `git-failed` tag, which every stored
            // judgement mismatches by construction — so asking `is_current` here would not be a
            // staleness test at all, it would be a guaranteed *no* dressed as one. The judgement is
            // kept and marked instead, exactly as `POST /map/triage` skips such a decision rather
            // than triaging it under a digest that dies when git recovers.
            if matches!(anchors, crate::map_stamp::Anchors::Failed) {
                current.push(crate::map_triage::Held {
                    checked: false,
                    judged,
                });
                continue;
            }
            let digest = crate::map_triage::inputs_digest(crate::map_triage::Evidence {
                decision: anchored,
                anchors,
            });
            if crate::map_triage::is_current(&judged.inputs_digest, &digest) {
                current.push(crate::map_triage::Held {
                    checked: true,
                    judged,
                });
            }
        }
    }

    let stamps = crate::map_stamp::counts(&standings.values().cloned().collect::<Vec<_>>());
    // The map the panel draws and the two numbers above it, out of one pass over one reading. Two
    // calls — one to filter, one to tally — would be two chances to ship one set and count another,
    // and the screen would look entirely correct while doing it.
    let crate::map_triage::Reconciled {
        judgements: triage,
        counts: triage_counts,
    } = crate::map_triage::reconcile(&standings, &stamps, current);
    // The two header lines on that screen come from different places — this one from
    // `standings.len()`, the other from the join — and they can only agree if the loop above put
    // exactly one standing against every approved decision. A test asserts it too, because a
    // `debug_assert` says nothing in the build the owner runs.
    debug_assert_eq!(
        stamps.decisions, junction.counts.decisions,
        "one standing per approved decision, or the header disagrees with itself"
    );

    Ok(Json(MapAnswer {
        structure,
        seam,
        junction,
        standings,
        stamps,
        triage,
        triage_counts,
        git_would_not_answer: anchors == crate::map_stamp::Anchors::Failed,
        recency,
        last_triaged_at,
    }))
}

/// Every decision's anchor code as it stands now, from ONE `git ls-files` for the union of their
/// paths.
///
/// **One function and not a second walk, for the reason [`project_junction`] is one.** `GET /map`
/// asks this to say where a decision stands and `POST /map/triage` asks it to say what the triager
/// was shown and whether its last answer is still about that. Two derivations would be two answers
/// to one question, free to disagree — and the disagreement would surface as a judgement about
/// files the map does not think are anchors, or as a stamp expired against a set nobody stamped it
/// over.
///
/// **The union call, sliced per decision afterwards** — and the obvious later refactor is the
/// per-decision loop, so both reasons it is not written that way are here rather than left to be
/// rediscovered.
///
/// The first is cost. This repository has ~350 approved decisions and the map is read every time
/// the window opens, so a call each would be ~350 process spawns on a route somebody is waiting
/// on. The second is the ceiling: the union of this repository's paths measures 732 entries and
/// **24 224 characters of argv — 75 % of the 32 767 Windows allows** — so the chunking
/// `map_stamp::digest` already does is load-bearing here rather than decorative, and a project a
/// third larger than this one goes over it.
///
/// The union must produce exactly what the per-decision loop would have, or it is an optimisation
/// that changes answers. Two rules keep that true: the slice below is **by path**, never by the
/// order git happened to answer in, and a decision with no anchor paths gets `Some("")` without
/// consulting the call at all — which is what `digest` itself does with an empty list, and is why
/// a git failure leaves those decisions on `Watch::NoAnchor` instead of flapping to *unreadable*.
///
/// Answers the per-decision reading **and** the union call's own result. The second is not
/// derivable from the first: a project where every decision names no file has a map full of
/// `Computed("")` whatever git did, and *git would not answer* is a fact about the repository that
/// only the union call holds.
async fn anchor_digests(
    root: &std::path::Path,
    decisions: &[crate::map_join::Anchored],
) -> (
    std::collections::BTreeMap<i64, crate::map_stamp::Anchors>,
    crate::map_stamp::Anchors,
) {
    // `watched` and not `modules`, which is the whole of §14's cure reaching the expiry rule: a
    // stamp has to keep watching the files somebody wrote down even after the comment that first
    // named them is gone. Watching `modules` alone would mean a deleted comment silently shrinks
    // the set a green expires against — the green stops watching the very file it was given over.
    let per_decision_watched: std::collections::BTreeMap<i64, Vec<String>> = decisions
        .iter()
        .map(|anchored| (anchored.decision_id, anchored.watched()))
        .collect();
    let mut union: std::collections::BTreeSet<&str> = std::collections::BTreeSet::new();
    for paths in per_decision_watched.values() {
        union.extend(paths.iter().map(String::as_str));
    }
    let union: Vec<String> = union.into_iter().map(str::to_owned).collect();
    let anchors = crate::map_stamp::digest(root, &union).await;
    // Parsed once and not once per decision: 350 decisions against a 52 KB digest is 350 walks of
    // the same text for an answer that cannot change between them.
    let tracked = match &anchors {
        crate::map_stamp::Anchors::Computed(text) => Some(crate::map_stamp::parse(text)),
        _ => None,
    };

    let mut per_decision = std::collections::BTreeMap::new();
    for anchored in decisions {
        // A decision with no anchor paths is `Computed("")` whatever became of the git call, because
        // `digest` itself never asks git for an empty list — so a project with no repository leaves
        // these on `Watch::NoAnchor`, which is the fact the owner can act on, rather than on
        // `Watch::NoRepository`, which would be true about the folder and useless about the decision.
        let watched = per_decision_watched
            .get(&anchored.decision_id)
            .expect("every decision was given a watched set just above");
        let current = if watched.is_empty() {
            crate::map_stamp::Anchors::Computed(String::new())
        } else {
            match (&anchors, &tracked) {
                (crate::map_stamp::Anchors::Computed(_), Some(tracked)) => {
                    crate::map_stamp::Anchors::Computed(crate::map_stamp::canonical(
                        watched.iter().filter_map(|path| {
                            tracked
                                .get(path.as_str())
                                .map(|blob| (path.as_str(), blob.as_str()))
                        }),
                    ))
                }
                (crate::map_stamp::Anchors::NoRepository, _) => {
                    crate::map_stamp::Anchors::NoRepository
                }
                _ => crate::map_stamp::Anchors::Failed,
            }
        };
        per_decision.insert(anchored.decision_id, current);
    }
    (per_decision, anchors)
}

/// The anchor reading of one decision, or the value that claims nothing if it somehow has none.
///
/// Unreachable by construction — [`anchor_digests`] puts exactly one entry against every decision
/// of the slice it was handed, and both callers hand it `junction.decisions` — and written anyway,
/// because the alternative to a fallback here is a panic in a handler and the alternative to both
/// is dropping the decision, which would take it silently out of a header §5.3 requires to add up.
///
/// [`crate::map_stamp::Anchors::Failed`] is the one value that is safe to be wrong with. It means
/// *this daemon could not read the anchors*, which is exactly true if this were ever reached: a
/// stamp reads as unreadable rather than as green, and a judgement made against it goes stale the
/// moment git answers again. Both err towards asking, which is the direction §1 can afford.
fn anchor_reading(
    readings: &std::collections::BTreeMap<i64, crate::map_stamp::Anchors>,
    decision_id: i64,
) -> &crate::map_stamp::Anchors {
    const UNREADABLE: crate::map_stamp::Anchors = crate::map_stamp::Anchors::Failed;
    readings.get(&decision_id).unwrap_or(&UNREADABLE)
}

/// The structure layer and the approved decisions read against it, for the two routes that need
/// both.
///
/// **One function and not two copies, because a decision's anchor set is what a stamp is anchored
/// TO.** `GET /map` computes it to say where a decision stands; `POST /map/stamps` computes it to
/// know what it is putting a verdict on. If the two ever derived it differently, a stamp would be
/// written against one anchor set and expired against another — a green that lapses the instant it
/// is given, with a diff nobody can explain, which is the false-alarm failure that costs exactly
/// the trust §7 is trying to buy.
///
/// It goes to disk, so it runs on `spawn_blocking` the way `blame` and `grep` already do: walking a
/// thousand-file tree on the async executor blocks the whole daemon for a good few milliseconds,
/// and this daemon is also answering a three-second poll. `specs_in` walks directories too and
/// rides the same hop, since the thread already has the root in hand.
///
/// A missing folder is a 404 and a failed query is a 500, which is not one distinction made twice:
/// the first is something the owner did to their own machine, the second is this daemon failing.
async fn project_junction(
    state: &AppState,
    id: &str,
    root: PathBuf,
) -> Result<(crate::project_map::Structure, crate::map_join::Junction), StatusCode> {
    let walked = tokio::task::spawn_blocking(move || {
        let structure = crate::project_map::structure(&root)?;
        // Slugs and not paths, for the reason `get_project_map_specs` gives below: a decision row
        // carries the slug, and the slug is what `join` checks a citation's candidate against.
        // Handing it paths would make every candidate fail to name its document, which reads as
        // "§8 is unfixed" and is indistinguishable from it.
        let slugs: Vec<String> = crate::map_intent::specs_in(&root)
            .iter()
            .map(|path| crate::map_intent::spec_slug(path))
            .collect();
        Ok::<_, std::io::Error>((structure, slugs))
    })
    .await
    .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;

    let (structure, spec_slugs) = walked.map_err(|error| {
        // A folder that has been renamed or deleted is something its owner did, not a
        // fault of this daemon — and `ls`, `cat`, `grep` and `blame` already answer 404
        // for the very same `read_dir`. Answering 500 would put a warning in the log for
        // an ordinary Tuesday.
        if error.kind() == std::io::ErrorKind::NotFound {
            return StatusCode::NOT_FOUND;
        }
        tracing::warn!(%error, project_id = %id, "project map failed");
        StatusCode::INTERNAL_SERVER_ERROR
    })?;

    let decisions = crate::map_store::approved(&state.pool, id)
        .await
        .map_err(|error| {
            tracing::warn!(%error, project_id = %id, "project map decisions failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })?;

    let spec_slugs = document_slugs(state, id, spec_slugs).await?;

    // The recorded anchor sets, which are the only part of this junction with a memory. Read here
    // rather than merged into the payload afterwards, because `join` needs them: a file somebody
    // wrote down as a decision's code is CLAIMED, and deciding that after the fact would mean a
    // second place that knows what §5.1's two piles mean.
    let records = crate::map_store::anchors(&state.pool, id)
        .await
        .map_err(|error| {
            tracing::warn!(%error, project_id = %id, "reading the recorded anchors failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })?;

    let junction = crate::map_join::join(
        &decisions,
        &structure.modules,
        &structure.foreign,
        &spec_slugs,
        &records,
    );
    Ok((structure, junction))
}

/// Which specs this project has, named the way the owner reads them.
///
/// **Slugs and not paths.** The path is where the file happens to sit; the slug is what
/// [`crate::map_intent::spec_slug`] produces, what the owner reads, what they hand back to
/// `POST /map/extract`, and what a decision row carries forever. Two projects keeping their specs
/// in different folders name one document alike.
///
/// **Empty is an answer, not an error.** A project with no specs gets a sentence about what is
/// missing, and an empty list is that sentence's input — the same posture `map` itself takes
/// about a folder with nothing in it.
///
/// [`crate::map_intent::specs_in`] probes three conventional folders rather than reading a
/// setting, and this route inherits that whole: a project matching none of them is not broken, it
/// is unconfigured in a way nobody has to configure.
///
/// On `spawn_blocking` for the reason `get_project_map` gives above: this walks directories, and
/// the daemon is also answering a three-second poll.
async fn get_project_map_specs(
    State(state): State<AppState>,
    Path(id): Path<String>,
) -> Result<Json<Vec<String>>, StatusCode> {
    let root = resolve_read_root(&state, &id, None).await?;
    tokio::task::spawn_blocking(move || {
        crate::map_intent::specs_in(&root)
            .iter()
            .map(|path| crate::map_intent::spec_slug(path))
            .collect::<Vec<_>>()
    })
    .await
    .map(Json)
    .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)
}

/// What `GET …/map/items` is asked about: one file of the project.
#[derive(Deserialize)]
struct MapItemsQuery {
    /// Relative to the project root, with forward slashes — exactly as `GET /map` spells a module.
    ///
    /// The client sends back a path this map already gave it, which is what makes the guard below
    /// a guard against a *forged* request rather than against its own shell.
    path: String,
}

/// What one file declares, and which of those things use each other.
///
/// **A route of its own, and never a field on `GET /map`.** The whole-project answer already walks
/// the tree, asks git for every anchor's digest and reads three tables; folding every file's items
/// into it would multiply the largest response this daemon sends by the size of the project, to
/// carry a level nobody is looking at until they click into it. This is the one place in the map
/// where laziness is not a premature optimisation but the shape of the question: a reader opens one
/// file at a time.
///
/// **The path is checked and never trusted, even though the shell only ever sends one back.** A
/// route that reads a caller-supplied path is a file-disclosure hole the moment anything but that
/// shell speaks to it, and [`crate::inspect::resolved_within`] is already the answer to exactly this
/// — including the case a lexical check cannot see, where a junction inside the project resolves
/// outside it. Reusing it rather than writing a second guard is the same rule the rest of this file
/// keeps: a check that lives in a handler is a check the second caller forgets.
///
/// **A file this reader does not understand is a `200` and not a `404`**, carrying `reader: null`
/// and no items. *I cannot read Go* and *there is no such file* are opposite answers, and the
/// structure layer already spent a paragraph refusing to collapse them — [`crate::project_map`]'s
/// `unread` exists for that reason. A `404` here would reopen it one level down.
async fn get_project_map_items(
    State(state): State<AppState>,
    Path(id): Path<String>,
    Query(query): Query<MapItemsQuery>,
) -> Result<Json<crate::map_items::Items>, StatusCode> {
    let root = resolve_read_root(&state, &id, None).await?;

    // On `spawn_blocking` for the reason `get_project_map` gives: this canonicalizes and reads a
    // file, and the daemon is also answering a three-second poll.
    let asked = query.path.clone();
    tokio::task::spawn_blocking(move || {
        let full =
            crate::inspect::resolved_within(&root, &query.path).map_err(|error| match error {
                crate::inspect::InspectError::UnsafePath => StatusCode::BAD_REQUEST,
                _ => StatusCode::NOT_FOUND,
            })?;
        let source = std::fs::read_to_string(&full).map_err(|_| StatusCode::NOT_FOUND)?;
        Ok(crate::map_items::items(&asked, &source))
    })
    .await
    .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?
    .map(Json)
}

#[derive(Deserialize)]
struct MapExtractBody {
    /// The document's name, which is its filename without the extension — what
    /// [`crate::map_intent::spec_slug`] produces and what a decision row carries forever. NOT a
    /// path: two projects keeping their specs in different folders must name the same document the
    /// same way, and a path would also be a way to ask this route to read an arbitrary file.
    spec_slug: String,
    brain: String,
}

/// How many decisions one press of the triage button may put in front of a model.
///
/// **A ceiling on a wait, and it is expected to be hit rather than approached.** One model call per
/// decision: this repository's ~350 approved decisions, none of them stamped, is 350 runs of the
/// agent CLI, and the shell asks this synchronously the way `map/extract` does. Twenty is what
/// somebody watches a spinner through — minutes with a cloud brain — and it is deliberately not
/// sized to drain a backlog in one press, because nothing that drains a 350-row backlog in one
/// press finishes inside a request.
///
/// **Sized knowing the staleness rate rather than guessing it.** Counted on this repository on
/// 2026-08-26: 109 files under `core/src` and `shell/src` name a `§`, and **17 of them were touched
/// in the last 20 commits** — 26 in the last 50. An anchor set is several files, so a decision's
/// chance of going stale is HIGHER than that per-file sixth, and `map_triage::inputs_digest` covers
/// the anchor blobs precisely so it does. This repository will therefore rarely be in the "nothing
/// stale" state, and the cap will sit saturated rather than draining once.
///
/// **The silent cap is the disease, so [`TriageReport::left_over`] is not optional.** A run that
/// stopped at twenty of two hundred and said only "done" reads as *covered everything*, which is
/// §1's thousand-line plan reproduced by the feature built to cure it. The number has to reach the
/// screen, not merely the log.
///
/// **It drains rather than starves, and that is a property of the skip and not of this number.**
/// What stops the first twenty being the only twenty ever looked at is that a judgement still
/// current costs no call, so the next press starts where the last one stopped.
///
/// **Which twenty is [`crate::map_recency`]'s answer and not this constant's**, and the two were
/// separated late: the sweep used to run in `map_store::approved`'s order — `spec_slug, ordinal,
/// id` — which meant a saturated cap paid for the first twenty decisions alphabetically by
/// document, every press, for ever. §10 says the order is by recency of the anchor code's last
/// change, and until that landed this comment recorded the gap rather than pretending the order had
/// been chosen. It changes which twenty go first; it does not change whether the rest are reached.
const MAX_TRIAGE_BATCH: usize = 20;

/// Which brain the caller named, and nothing else.
///
/// Deliberately stricter than [`crate::chats::Brain::from_wire`], which reads anything unfamiliar as
/// `Cloud`. That is right for a conversation, whose default has always been the cloud and whose
/// column carries it. It is wrong here: this is the one choice the owner explicitly asked to make,
/// and quietly making it for them — in the direction that spends money and sends the document off
/// the machine — is the wrong default to inherit.
fn read_brain(value: &str) -> Option<crate::chats::Brain> {
    match value {
        "cloud" => Some(crate::chats::Brain::Cloud),
        "local" => Some(crate::chats::Brain::Local),
        _ => None,
    }
}

/// Ask a model what one spec decided, and leave the answer waiting for its owner.
///
/// **Synchronous, and the spec's §9.1 says so: it returns the list.** A cloud brain makes this a
/// slow request, and that is accepted — the owner pressed a button about one document and is
/// waiting for the thing they asked for. The alternative is a status row, a poll and a state the
/// page has to draw, for a wait measured in seconds.
///
/// **Nothing here is approved.** The list comes back so the owner can read it; it is already in the
/// table as a pile nobody has read, and it stays that way until they answer line by line — §4.
///
/// **A `local` request never becomes a cloud one.** `local` is what somebody chooses when the
/// document must not leave the machine, or when they are not paying for it, so a machine with no
/// local model refuses rather than falling back: falling back would break both promises at once,
/// silently, on the bill. The refusal is 503 and not 422 — the request was well formed and this
/// machine simply cannot serve it, which is a different thing to tell the owner from "you asked
/// wrong".
async fn post_project_map_extract(
    State(state): State<AppState>,
    Path(id): Path<String>,
    Json(body): Json<MapExtractBody>,
) -> Result<Json<Vec<crate::map_store::Decision>>, StatusCode> {
    let brain = read_brain(&body.brain).ok_or(StatusCode::UNPROCESSABLE_ENTITY)?;
    let root = resolve_read_root(&state, &id, None).await?;

    // On `spawn_blocking` for the reason `get_project_map` gives: this walks directories and reads
    // a file that may be tens of kilobytes, and the daemon is also answering a three-second poll.
    // Finding the document and reading it are one hop because they are one answer — a slug that
    // matches nothing and a file that cannot be read are the same 404 to whoever asked, and neither
    // is a fault of this daemon.
    let wanted = body.spec_slug.clone();
    let source = tokio::task::spawn_blocking(move || {
        let path = crate::map_intent::specs_in(&root)
            .into_iter()
            .find(|path| crate::map_intent::spec_slug(path) == wanted)?;
        std::fs::read_to_string(root.join(path)).ok()
    })
    .await
    .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?
    .ok_or(StatusCode::NOT_FOUND)?;

    // Bound out here because `Extractor::Loopback` borrows it and the borrow has to outlive the
    // `match` that creates it.
    let local_model;
    let asked = match brain {
        crate::chats::Brain::Cloud => crate::map_intent::Extractor::Cli(state.runner.as_ref()),
        // `read_brain` above (~3068) only ever yields `cloud` or `local` — this arm exists to
        // satisfy exhaustiveness over the full `Brain` type, not to describe a state this route can
        // reach today. Whoever makes the hosted route selectable HERE owns replacing it.
        crate::chats::Brain::OpenRouter => crate::map_intent::Extractor::Cli(state.runner.as_ref()),
        crate::chats::Brain::Local => {
            // Read per request rather than cached on `AppState`, which is the argument
            // `models_config`'s own doc comment makes: a name cached at startup is one the owner
            // cannot change without restarting the daemon.
            //
            // The field is named for triage and is being reused as "the local model this machine
            // has". That reuse is the house pattern rather than a stretch — `main.rs` already
            // hands `voice_cleanup_model` to the web pillar as its quarantine model — and there is
            // exactly one Ollama model configured on a machine.
            let Some(model) = models_config().local_triage_model else {
                tracing::warn!(
                    project_id = %id,
                    spec = %body.spec_slug,
                    "the local brain was asked for and this machine has no local model configured"
                );
                return Err(StatusCode::SERVICE_UNAVAILABLE);
            };
            local_model = model;
            crate::map_intent::Extractor::Loopback {
                client: &state.web.http,
                base_url: crate::runner::OLLAMA_BASE_URL,
                model: &local_model,
            }
        }
    };

    let decisions = crate::map_intent::extract(asked, &body.spec_slug, &source)
        .await
        .map_err(|error| {
            // 502 and not 500: the daemon did its part and the thing it asked did not answer. An
            // empty list would be the other reading, and it is the one this feature exists to
            // forbid — "this spec decided nothing" is a claim, and nobody is in a position to make
            // it when nobody read the document.
            tracing::warn!(
                %error,
                project_id = %id,
                spec = %body.spec_slug,
                brain = %brain.as_str(),
                "the extraction run failed"
            );
            StatusCode::BAD_GATEWAY
        })?;

    crate::map_store::record(&state.pool, &id, &body.spec_slug, brain, &decisions)
        .await
        .map_err(|error| {
            tracing::warn!(
                %error,
                project_id = %id,
                spec = %body.spec_slug,
                "an extraction was read but could not be recorded"
            );
            StatusCode::INTERNAL_SERVER_ERROR
        })?;

    // The whole pile and not this extraction, because the pile is what the owner reads. A window
    // handed only what just arrived would show a shrinking list every time a second spec was read.
    crate::map_store::pending(&state.pool, &id)
        .await
        .map(Json)
        .map_err(|error| {
            tracing::warn!(%error, project_id = %id, "reading the decision pile failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })
}

/// What is waiting for this project's owner, on a route of its own.
///
/// The same list `POST …/map/extract` hands back. Separate because a window that was already open
/// has to be able to refresh the pile, and the only other way to ask for it costs a model run.
///
/// Ordered by [`crate::map_store::pending`]: oldest extraction first, because a pile read in the
/// order it arrived is a pile that ends.
///
/// The project is resolved first, the way `map` and `map/extract` do it, so an id nobody registered
/// is a 404 rather than an empty list — "nothing is waiting for you" and "there is no such project"
/// are different answers, and only one of them is true. It asks nothing of the disk beyond that:
/// `resolve_project_root` reads the row and never the folder, so a project whose folder has moved
/// still has a pile, which is exactly what somebody looking at a broken project wants.
async fn get_project_map_decisions(
    State(state): State<AppState>,
    Path(id): Path<String>,
) -> Result<Json<Vec<crate::map_store::Decision>>, StatusCode> {
    resolve_project_root(&state, &id).await?;
    crate::map_store::pending(&state.pool, &id)
        .await
        .map(Json)
        .map_err(|error| {
            tracing::warn!(%error, project_id = %id, "reading the decision pile failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })
}

/// §6.2's pile: everything this project's triager has silenced, and why.
///
/// **Its own door and never a filter on the map, because §6.2 says *sempre acessível*.** A pile you
/// reach only by knowing which query parameter to add is not always accessible, and §13 rates *o
/// triador silencia o que devia mostrar* a **real** residual risk whose only mitigation is that
/// this stays visible. A mitigation with a secret entrance is not one.
///
/// **Filtered by NEITHER standing, staleness nor retirement — the exact opposite of what `GET /map`
/// does with the same table, and all three departures are deliberate.** That route answers *what is
/// true now*: a judgement about a decision the owner has since stamped, or about code that has
/// since moved, is not an answer to its question, and a retired decision is not in its map at all
/// — see [`crate::map_triage::reconcile`], which is where §5.3's numbers would otherwise stop
/// reconciling. This route answers *what the triager did*, and each of the three filters would
/// delete part of that record:
///
/// - **stamped** — the stamp is the evidence the silence was premature, so the silencing is worth
///   MORE afterwards, not less;
/// - **stale** — a silence whose reason was written about code that has since moved is exactly the
///   one somebody should reread;
/// - **retired** — auditing the triager does not care whether the decision survived, and a
///   silencing that vanished because the owner later said no is a bug report deleted by its own
///   subject. It is reported instead, as `retired` on the row.
///
/// Somebody will one day read this as an inconsistency and repair it: the repair breaks §6.2 in one
/// direction or §5.3 in the other, and
/// `the_silenced_pile_still_shows_a_silencing_of_a_decision_that_was_later_stamped` and
/// `a_silencing_survives_the_decision_being_retired` are the tests that stop it.
///
/// **Every silencing ever written and not the latest judgement per decision**, which is
/// [`crate::map_store::silencings`] rather than `judgements` and is what §6.2 literally asks for:
/// *"a razão de **cada** silenciamento"*. A decision silenced last week and flagged today has a
/// silencing in the table, and until this route read the history it had none in the pile —
/// `map_triage` was made append-only for precisely that row and nothing was reading it.
///
/// Asks nothing of the disk: `resolve_project_root` reads the row and never the folder, so a
/// project whose folder has moved still has its pile — which is *sempre acessível* meaning what it
/// says. An id nobody registered is a 404 rather than an empty list, for the reason
/// [`get_project_map_decisions`] gives: *nothing was silenced* and *there is no such project* are
/// different answers and only one of them is true.
///
/// The order is the store's — newest first, ties broken by insertion order — and the argument for
/// it is [`crate::map_store::silencings`]'s. Sorted in SQL and not here, because with the whole
/// history in the pile the tie-break has to be `id` and a handler cannot see one.
///
/// **Capped at [`crate::map_store::SILENCED_PAGE`], with the uncapped total on the answer.** *Sempre
/// acessível* is not *all at once*, and this table only grows: append-only by design, by up to
/// `MAX_TRIAGE_BATCH` rows per press of the button the feature exists to encourage, on a route the
/// window performs every time the map opens. The write side was bounded from the first commit and
/// this side was bounded by nothing. What makes the cap admissible rather than a quiet truncation is
/// that the reader is handed the number it was cut from — the same bargain
/// [`TriageReport::left_over`] strikes one route over, and the same one every capped pile in the
/// window keeps.
///
/// **It answers [`crate::map_store::Silencing`] rows and nothing wrapped around them, and the
/// wrapper's removal is a correction rather than a tidy-up.** A `SilencedRow` here added
/// `machine_written`, which could not be `true` on this route: the one producer of a daemon-written
/// reason is [`crate::map_triage::unreadable_flag`], which may only ever reach
/// [`crate::map_triage::Judgement::Flagged`], while [`crate::map_store::silencings`] selects the
/// silenced. So the payload where the answer is provably always `false` carried the field and
/// `GET /map`'s `triage` — the only place a `nucleos:` sentence can appear at all — carried nothing,
/// which made a client re-spell [`crate::map_triage::DAEMON_MARK`] in its own language to keep §6.2's
/// attribution. It now lives on [`crate::map_store::Judged`], computed at the only place a row of
/// that table becomes a value. A field that can never be true is worse than an absent one: it is a
/// promise somebody eventually relies on, and this one would have been relied on for the wrong pile.
async fn get_project_map_silenced(
    State(state): State<AppState>,
    Path(id): Path<String>,
) -> Result<Json<crate::map_store::SilencedPile>, StatusCode> {
    resolve_project_root(&state, &id).await?;

    crate::map_store::silencings(&state.pool, &id)
        .await
        .map(Json)
        .map_err(|error| {
            tracing::warn!(%error, project_id = %id, "reading the silenced pile failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })
}

/// What `GET …/map/orphan` is asked about: one section of one document.
#[derive(Deserialize)]
struct MapOrphanQuery {
    /// The document, as `map/specs` spells it and as a decision row carries it.
    slug: String,
    /// The heading the decision was copied from, **verbatim** — `## 4.1 Três tipos de decisão`.
    ///
    /// The heading and not the number, so that [`crate::map_join::section_number`] stays the one
    /// place that knows how one becomes the other. A client that sent the number would be a second
    /// implementation of that rule, and the day the two disagreed the guard would be searching the
    /// history for a section the junction never anchored anything to.
    section: String,
}

/// Whether a decision with no code was never built, or lost the comment that anchored it (§14).
///
/// **Three refusals, and each is a different sentence.** `422` for a heading carrying no number:
/// that is [`crate::map_join::Anchor::Unnumbered`], where no search ever ran, and answering
/// *nothing ever named it* about a question nobody could ask would be the silent wrong answer this
/// whole feature refuses. `404` for a slug this project has no document for — the same answer
/// `map/extract` gives it, and for its reason. Everything else is a `200` carrying one of
/// [`crate::map_orphan::Orphan`]'s six states, including the two that mean *I could not look*: a
/// git that would not answer is a finding and not a fault of this daemon.
///
/// **There is deliberately NO refusal for a document that is not on disk**, and the first version
/// of this route had one. It answered `404` when the slug was missing from `map_intent::specs_in`,
/// which made the guard the only part of this map that stops working when a spec file is archived
/// or renamed — `GET /map` keeps showing those decisions, because their text was copied into the
/// table at extraction and the folder was never where they lived. Worse, the slug IS the filename,
/// so renaming a spec would have killed the guard for every decision of that document while the
/// rows carrying the old slug sat on screen looking answerable. See [`document_slugs`]: the list of
/// this project's documents comes from the table first, so a slug an approved decision carries is a
/// document this project has, whatever happened to the file.
async fn get_project_map_orphan(
    State(state): State<AppState>,
    Path(id): Path<String>,
    Query(query): Query<MapOrphanQuery>,
) -> Result<Json<crate::map_orphan::Orphan>, StatusCode> {
    let root = resolve_read_root(&state, &id, None).await?;

    let Some(section) = crate::map_join::section_number(&query.section) else {
        return Err(StatusCode::UNPROCESSABLE_ENTITY);
    };

    // On `spawn_blocking` for `map/extract`'s reason: this reads a directory, and the daemon is
    // also answering a three-second poll. Slugs and not paths, exactly as `project_junction` does
    // it, because the slug is what a citation's candidate is checked against.
    let listing = root.clone();
    let on_disk: Vec<String> = tokio::task::spawn_blocking(move || {
        crate::map_intent::specs_in(&listing)
            .iter()
            .map(|path| crate::map_intent::spec_slug(path))
            .collect()
    })
    .await
    .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;

    let slugs = document_slugs(&state, &id, on_disk).await?;

    Ok(Json(
        crate::map_orphan::orphan(&root, &section, &query.slug, &slugs).await,
    ))
}

#[derive(Deserialize)]
struct MapDecisionBody {
    /// `true` approves the line and lets it into the map; `false` retires it, which is what stops
    /// it being proposed for that spec again. Required, with no `serde(default)`: a body that omits
    /// it is a client that has not decided, and defaulting would decide for them in a direction.
    approved: bool,
}

/// The owner's answer to ONE line.
///
/// **No bulk form, and that is §4 rather than an omission.** The list is approved line by line; a
/// route that took the whole list would be the thousand-line plan again, wearing a smaller shape.
///
/// `204` when a row changed and `404` when none did. [`crate::map_store::decide`] returns `false`
/// for three different reasons — a line belonging to another project, an id that never existed, and
/// a line somebody already answered — and they are deliberately one answer here. All three mean
/// *that line is not yours to answer now*; telling them apart would tell a caller which ids exist
/// in projects it cannot see; and none of them is a fault of this daemon worth a 500.
///
/// **No `resolve_project_root` here, unlike the GET above.** `decide` puts `project_id` in its own
/// `WHERE` and its doc comment argues for exactly that — a check that lives in a handler is a check
/// the second caller forgets. An unregistered project therefore already gets this route's 404, from
/// the store, and a resolve on top would be a second query that cannot change the answer.
/// `delete_project_command`, the same shape one pillar over, relies on its store for the same
/// reason.
async fn post_project_map_decision(
    State(state): State<AppState>,
    Path((id, decision)): Path<(String, i64)>,
    Json(body): Json<MapDecisionBody>,
) -> Result<StatusCode, StatusCode> {
    match crate::map_store::decide(&state.pool, &id, decision, body.approved).await {
        Ok(true) => Ok(StatusCode::NO_CONTENT),
        Ok(false) => Err(StatusCode::NOT_FOUND),
        Err(error) => {
            tracing::warn!(%error, project_id = %id, decision, "answering a decision failed");
            Err(StatusCode::INTERNAL_SERVER_ERROR)
        }
    }
}

#[derive(Deserialize)]
struct MapStampBody {
    decision_id: i64,
    /// The owner's verdict, parsed by serde and by nothing this handler wrote.
    ///
    /// Typed rather than taken as a `String` and read afterwards, which is where `read_brain` next
    /// door had to end up and why the two differ. `Brain::from_wire` reads anything unfamiliar as
    /// `Cloud`, so that route needed a stricter reader of its own; [`crate::map_stamp::Verdict`]'s
    /// derived `Deserialize` is already exact — §5.2 has three and `0124`'s CHECK admits three — so
    /// a fourth is refused before this function runs at all. That is the earliest place it can be
    /// refused, and the only one where nothing has yet had a chance to guess what was meant.
    verdict: crate::map_stamp::Verdict,
    /// Obligatory on amber and optional on the other two (§7).
    ///
    /// `serde(default)` so a client that has nothing to say may omit the field rather than having
    /// to spell `null`. The default is `None` and never an empty string, because *said nothing* and
    /// *said the empty string* are different, and `0124` stores the first as NULL.
    #[serde(default)]
    note: Option<String>,
}

/// The owner's verdict on one decision, and the moment they gave it (§5.2, §7).
///
/// **The daemon computes the digest and the body has no field for one.** A client that could supply
/// it is a client that could mint a green anchored to a digest nothing will ever move — a stamp that
/// never expires, which is §1's false confidence with a signature on it. The anchor set comes from
/// [`project_junction`], the same reading `GET /map` expires the stamp against, so the two cannot
/// disagree about what this verdict was given over.
///
/// Four answers, and each is a different thing to tell whoever asked:
///
/// - `204` when a row was written. Nothing to say back; §9.2 makes the current state the last row,
///   and the map is where it is read.
/// - `404` when nothing was written — a decision belonging to another project, an id that names
///   nothing, or a line nobody approved. All three mean *that decision is not yours to stamp now*,
///   none is a fault of this daemon, and telling them apart would tell a caller which ids exist in
///   projects it cannot see. §4 is why the third is in that list at all: approval is the gate, and a
///   verdict on an unapproved line would put the owner's word on something they never let in.
/// - `400` for an amber with nothing in its note. `0124`'s CHECK is the backstop and would surface
///   as a 500, which reads as this daemon having broken; a malformed request is the client's fault
///   and has to read as one. §5.2 makes the note the whole of amber — *falta migrar as páginas de
///   pilar* is worth more than the colour is — so an empty one is not a lesser amber, it is not one.
/// - `503` for a `settled` when git is there and **would not answer**. **Not `500`**: that is
///   transient, and the honest thing to tell the owner is *try again*, whereas a 500 reads as a
///   fault here and puts a warning in a log for an ordinary Tuesday. §7.1 makes *está como quero*
///   the only verdict the code moving can falsify, so it is the only one that may not be recorded
///   without knowing what it is anchored to; the other two take a NULL digest without complaint,
///   because neither has an expiry the code can reach. **A project with no git repository is not
///   this case** and gets a `204` — see the `NoRepository` arm below, and [`crate::map_stamp::Anchors`]
///   for what telling the two apart cost when they were one value.
///
/// **The tree walk on this path is deliberate, and it is the second one this click pays for.** The
/// shell will do `GET /map`, then this, then invalidate and `GET /map` again — three walks of a
/// thousand-file tree per stamp. It is not an oversight and it must not be optimised away by
/// computing the anchor set from anything cheaper: the write has to derive it **exactly** as the
/// read expires it, or a stamp is anchored to one set and compared against another and lapses the
/// instant it is given, with a diff nobody can explain. That is the false-alarm failure that costs
/// precisely the trust §7 is buying. In particular, an optimistic update in the shell may show the
/// verdict immediately and may **not** invent the `Standing` that goes with it — `Watch` is decided
/// by a git call and by the join, and a client guessing `Watched` would put a certain word on screen
/// over an anchor set nobody has read yet.
///
/// **The decision is looked up here, and that is not the handler check [`crate::map_store::decide`]
/// argues against.** `map_store::stamp` still puts `project_id`, `approved_at` and `retired_at` in
/// its own `WHERE`, and that INSERT is what actually refuses the write — this lookup cannot replace
/// it and does not try. It is forced: without finding the decision there is no anchor set to compute
/// a digest from. Short-circuiting on it also fixes an ordering that would otherwise be wrong, and
/// the wrongness is quiet: a settled verdict on a decision that does not exist, in a folder that is
/// not a repository, would answer `503` — *git is unreadable, try again* — about a request that will
/// never succeed however healthy git becomes.
async fn post_project_map_stamp(
    State(state): State<AppState>,
    Path(id): Path<String>,
    Json(body): Json<MapStampBody>,
) -> Result<StatusCode, StatusCode> {
    // Trimmed with `str::trim` against a CHECK that strips space, tab, CR and LF. Stricter, and
    // deliberately in that direction: a note of one non-breaking space is one the table would take
    // and one that says nothing, and the failure that matters is being LOOSER than the CHECK, which
    // turns a client's mistake into a 500 about this daemon.
    let note = body.note.as_deref();
    if body.verdict == crate::map_stamp::Verdict::Partial
        && !note.is_some_and(|note| !note.trim().is_empty())
    {
        return Err(StatusCode::BAD_REQUEST);
    }

    let root = resolve_read_root(&state, &id, None).await?;
    let (_, junction) = project_junction(&state, &id, root.clone()).await?;
    let anchored = junction
        .decisions
        .iter()
        .find(|anchored| anchored.decision_id == body.decision_id)
        .ok_or(StatusCode::NOT_FOUND)?;
    // `watched` and not `modules`: once a set has been written down, that is what the green expires
    // against. See `anchor_digests`, which makes the same substitution for the same reason.
    let anchors = anchored.watched();
    // **A stamp never overwrites a set the OWNER pointed at**, and that is the one rule this
    // side effect has. What a stamp can record is whatever the `§` comments happened to say at this
    // instant — which, while §8 is unfixed, is a set of guesses about which document a bare `§`
    // meant. Writing that over a choice somebody made deliberately would demote the choice to the
    // guess, silently, at the moment they were being most careful. So an owner record stands, and
    // the stamp adds nothing.
    let already_chosen = matches!(
        anchored.record.as_ref().map(|record| record.source),
        Some(crate::map_store::AnchorSource::Owner)
    );

    // `Anchored::modules` and never `foreign` beside it. `Anchor::Declared` spends a paragraph on
    // why: watching an anchor means being able to read it, and promising an expiry over a Go file
    // this map cannot parse is a promise the read side cannot keep.
    let digest = match crate::map_stamp::digest(&root, &anchors).await {
        crate::map_stamp::Anchors::Computed(text) => Some(text),
        // §11: a project added from outside may have no git repository at all, and that is not a
        // fault of anything. The stamp is **allowed**, and `''` is not a lie here — with no
        // repository there is genuinely nothing that could ever move, which is the same claim `''`
        // makes for a decision no module names. Refusing instead would make this feature useless on
        // exactly the projects §11 says must still get an honest answer, and refusing it with a
        // `503` would tell their owner to try again at something that cannot succeed.
        // `Watch::NoRepository` is what carries the reason back out, so the green is visible as one
        // that will never come and ask rather than passing for one that will.
        crate::map_stamp::Anchors::NoRepository => Some(String::new()),
        crate::map_stamp::Anchors::Failed => None,
    };
    if digest.is_none() && body.verdict == crate::map_stamp::Verdict::Settled {
        tracing::warn!(
            project_id = %id,
            decision = body.decision_id,
            anchors = anchors.len(),
            "a green was asked for and git would not say what its anchors are, so it was refused"
        );
        return Err(StatusCode::SERVICE_UNAVAILABLE);
    }

    match crate::map_store::stamp(
        &state.pool,
        &id,
        body.decision_id,
        body.verdict,
        digest.as_deref(),
        note,
    )
    .await
    {
        Ok(true) => {
            // After the stamp and never instead of it: the verdict is what the caller asked for,
            // and a record written for a stamp that then failed to land would be a memory of an
            // act that did not happen. A record that fails to write is logged and swallowed for the
            // mirror-image reason — the owner's verdict IS recorded, and answering `500` would tell
            // them their stamp did not land when it did.
            if !already_chosen
                && let Err(error) = crate::map_store::record_anchor(
                    &state.pool,
                    &id,
                    body.decision_id,
                    &anchors,
                    crate::map_store::AnchorSource::Stamp,
                )
                .await
            {
                tracing::warn!(
                    %error,
                    project_id = %id,
                    decision = body.decision_id,
                    "the stamp landed and its anchor set could not be written down"
                );
            }
            Ok(StatusCode::NO_CONTENT)
        }
        // Reachable despite the lookup above: the line could have been retired between the two, and
        // the store is the authority on that rather than the reading this handler took a moment ago.
        Ok(false) => Err(StatusCode::NOT_FOUND),
        Err(error) => {
            tracing::warn!(
                %error,
                project_id = %id,
                decision = body.decision_id,
                verdict = body.verdict.as_str(),
                "stamping a decision failed"
            );
            Err(StatusCode::INTERNAL_SERVER_ERROR)
        }
    }
}

#[derive(Deserialize)]
struct MapTriageBody {
    /// Which brain answers, exactly as `POST /map/extract` takes it. No spec slug and no decision
    /// id beside it: §10 gives the triager one scope — everything nobody has stamped — and a route
    /// that let a caller name the decisions would let it name the ones whose answer it liked.
    brain: String,
}

/// What one triage run did, and — the half that is easy to leave out — what it did not.
///
/// **Counts and never a bare `204`.** *"Corri o triador e não aconteceu nada"* and *"corri o triador
/// e estava tudo em dia"* are different facts about a project, and a route that reported only
/// success would make the second look like the first. Every field below is a thing that would
/// otherwise have happened invisibly.
///
/// **The seven after [`Self::in_scope`] are exhaustive and disjoint, and a test asserts they add
/// up.** §5.3 makes that the house rule for anything a person reads as a total — *as categorias são
/// exaustivas e disjuntas, e um teste verifica que somam ao total em vez de um comentário o
/// prometer* — and this is a report, which is exactly where a reader stops checking.
///
/// **Every one of them is a count and none is a flag**, which is the correction this type needed
/// most. [`Self::unreadable_anchors`] was a `git_would_not_answer: bool` for one commit, and a
/// boolean can say that a run was narrower than it looks without ever saying by how much — which
/// leaves the owner reading `judged: 3` off a project of three hundred with no way to learn that
/// the other two hundred and ninety-seven were skipped.
#[derive(Debug, Default, Serialize)]
struct TriageReport {
    /// Decisions in [`crate::map_stamp::Standing::Never`], which is the whole of what the triager
    /// is allowed to look at (§10). Everything below is a bucket of this number.
    in_scope: usize,
    /// Judged already, against inputs that have not moved since. Cost nothing and asked nothing.
    already_current: usize,
    /// Answered and written this run. The only field that grew the table.
    judged: usize,
    /// The model answered, the answer was not a judgement, and **a `flagged` row was written
    /// saying so**. Rows written this way, not rows withheld — the field changed meaning when the
    /// starvation was fixed, and the sentence is spelled out because the old one read the other way
    /// round.
    ///
    /// Counted apart from [`Self::unanswered`] because the two send whoever is debugging to
    /// different places: this one to the prompt, that one to the machine. See
    /// [`crate::map_triage::unreadable_flag`] for why the row exists at all and what it costs.
    unreadable: usize,
    /// Nobody answered: the run itself failed. A brain that is down fails on every decision and a
    /// brain that is confused fails on one, so folding this into [`Self::unreadable`] would report
    /// an unreachable machine as a broken prompt and send somebody to rewrite a question that was
    /// never asked.
    unanswered: usize,
    /// The decision stopped being one this project's map holds between the reading and the write.
    ///
    /// Expected to be zero, and counted rather than dropped because the six have to add up:
    /// approval cannot be taken back today — `decide` only touches rows nobody has answered and
    /// `record` supersedes only what is still pending — so nothing can retire an approved decision
    /// mid-run. A number here means that changed, which is worth finding out from a report rather
    /// than from a header that stopped reconciling.
    vanished: usize,
    /// Stale, and the cap stopped the run before reaching them. **The field this report exists
    /// for.** See [`MAX_TRIAGE_BATCH`].
    left_over: usize,
    /// In scope, and **skipped because git would not say what their anchor code is**.
    ///
    /// **Skipped and not triaged, which dissolves a storm rather than reporting one.** An earlier
    /// version of this route triaged them anyway and put a boolean on the report. The trouble is
    /// not the answer — the model reads none of its evidence from git, so an answer given during an
    /// outage is as good as any other — it is the digest: `map_triage::inputs_digest` keeps all four
    /// states of [`crate::map_stamp::Anchors`] apart on purpose, which is what `0124` was amended to
    /// require, so a judgement recorded under `git-failed` dies the moment git recovers. Every row
    /// written during an outage would have to be bought again.
    ///
    /// Skipping removes the source instead of the symptom. No judgement is ever written carrying a
    /// `git-failed` digest, so there is nothing to invalidate on recovery; the judgements already
    /// stored read stale for the length of the outage and are skipped rather than re-run, so nothing
    /// is spent; and when git answers again they match their `Computed(...)` digest and are current,
    /// untouched.
    ///
    /// It is the posture slice 4 already took with `Lapse::Unreadable`: *I could not look* is
    /// neither *unchanged* nor *changed*, and acting on either guess is the error.
    ///
    /// **Not the same as §11's project with no repository**, which is
    /// [`crate::map_stamp::Anchors::NoRepository`] and is triaged normally — with no repository
    /// there is genuinely nothing that could ever move, which is a permanent fact and an honest
    /// digest. Nor does it touch a decision no module names: that is `Computed("")`, reached without
    /// git being asked at all.
    unreadable_anchors: usize,
}

/// Ask a model which of the decisions nobody has stamped deserve their owner's eyes (§6, §10).
///
/// **Only [`crate::map_stamp::Standing::Never`], and that is §10's table rather than a shortcut.**
/// A decision whose anchor code moved — *"se estava carimbada, caducou (§7.1); se nunca foi vista,
/// o triador decide se vale o teu olhar."* A stamped decision already carries the owner's answer and
/// a lapsed one already reaches them through §5.3's `J`, so running a model over either is the model
/// second-guessing a human: the one authority §6 takes away from it, recovered through a sweep.
///
/// **And only rows whose judgement is stale or absent.** `map_triage::is_current` against a digest
/// computed now, so a second press over a repository nothing has happened to writes nothing and
/// spends nothing. That is not an optimisation: without it the bill grows with how often somebody
/// presses a button rather than with what changed, and a feature whose cost is unrelated to its
/// value is one people stop pressing.
///
/// **The anchor material is [`project_junction`] and [`anchor_digests`], the same two `GET /map`
/// reads.** Deriving it a second way here would be two answers to one question, and the disagreement
/// would arrive as a triage answer about files the map does not consider anchors — visibly
/// approximate is this feature's bargain, and two mechanisms quietly disagreeing is not that.
///
/// **A failure on one decision never abandons the rest.** A run that gave up at the first
/// unparseable answer would be useless on precisely the repositories worth running it on: three
/// hundred decisions is three hundred chances for a model to answer something odd. Each failure is
/// counted, logged with what was actually said, and the sweep carries on. That is also why the
/// route does not answer `502` the way `map/extract` does when the model fails — by then rows have
/// been written, and a status code that discarded the report would hide work actually done.
///
/// **And a decision git would not answer for is skipped rather than triaged**, which is the one
/// rule here that is about money rather than about correctness. See
/// [`TriageReport::unreadable_anchors`].
///
/// **The way out of a flag is a stamp, and §5.2 already has the right one — so no panel built on
/// this route may grow a dismiss button.** A flag stays in §5.3's `J` until its inputs move, which
/// looks like a nag with no answer until you notice that the answer is *a meio, e eu sei*, whose
/// stated purpose is *"converte um não sabia num sabia, que é metade da cura"*. The owner who reads
/// a flag and decides it is noise says so in that note. Dismissing without saying anything is
/// precisely the *não sabia* this map exists to convert, and a fourth verdict for it would be §5.2
/// widened to make the map quieter — which is the one direction it must never be widened in.
///
/// `200` with the report, and the four refusals are the ones `map/extract` already makes: `422` for
/// a brain nobody can read, `404` for a project or a folder that is not there, `503` for a `local`
/// this machine has no model for — never a quiet fall back to the cloud, which would break the two
/// promises that word carries at once — and `500` for the daemon's own failure to read or write its
/// tables.
/// Which files one decision's code is, as the owner says it.
#[derive(Deserialize)]
struct MapAnchorBody {
    decision_id: i64,
    /// Repository-relative, forward slashes. **An empty list is legal and is an assertion**,
    /// not a no-op: *these files were this decision's and now none are* is what somebody says
    /// about code they genuinely removed, and it is a different fact from never having written
    /// anything down.
    paths: Vec<String>,
}

/// Write down which files one decision's code is (§14).
///
/// **The one act in this map that gives an anchor a memory.** Everything else here is
/// recomputed from the working tree on every read: delete the `§7.1` from a file and the
/// association is gone, and the decision lands in §5.1's *declarado, sem código* looking exactly
/// like one nobody ever implemented. This is what makes that a named alarm instead of a silent
/// disappearance.
///
/// **Every path is resolved inside the project before anything is written**, through the same
/// [`crate::inspect::resolved_within`] `cat` and `grep` use — so an absolute path, a `..`, and a
/// junction pointing out of the tree are all refused by the function that already knows how,
/// rather than by a second rule written here. A path that does not exist is refused too, and
/// that is not tidiness: an anchor naming a file the project does not have would sit in
/// [`crate::map_stamp::Lapse::Moved`]'s `gone` for ever, nagging about a file that was never
/// there.
///
/// **Deliberately not restricted to files the map can READ.** [`crate::project_map::scanned`]
/// decides whose `§` this reader parses; it has no standing over which files somebody’s code
/// lives in. A Go sidecar, a migration, a stylesheet — the owner is entitled to say a
/// decision's code is there, and `map_stamp::digest` watches any tracked path perfectly well.
/// Refusing them would make this route unusable for exactly the languages §11 already admits
/// the map cannot read.
///
/// `204` when a row was written, `404` when the decision is not this project’s, not approved,
/// or retired — [`crate::map_store::decide`]'s three-reasons-one-answer, for its reason.
async fn post_project_map_anchors(
    State(state): State<AppState>,
    Path(id): Path<String>,
    Json(body): Json<MapAnchorBody>,
) -> Result<StatusCode, StatusCode> {
    let root = resolve_read_root(&state, &id, None).await?;

    let asked = body.paths.clone();
    let checked = tokio::task::spawn_blocking(move || {
        let mut kept: Vec<String> = Vec::with_capacity(asked.len());
        for path in &asked {
            // Backslashes normalised before anything looks at the string, because the map
            // spells every path with forward slashes (`project_map::collect` does the same
            // `replace`) and a record written the other way would never match an anchor again.
            let cleaned = path.trim().replace('\\', "/");
            if cleaned.is_empty() {
                return None;
            }
            let resolved = crate::inspect::resolved_within(&root, &cleaned).ok()?;
            // A directory is not a decision’s code, and recording one would put a path in the
            // digest that `git ls-files` never answers for — a permanent `gone`.
            if !resolved.is_file() {
                return None;
            }
            kept.push(cleaned);
        }
        Some(kept)
    })
    .await
    .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?
    .ok_or(StatusCode::UNPROCESSABLE_ENTITY)?;

    match crate::map_store::record_anchor(
        &state.pool,
        &id,
        body.decision_id,
        &checked,
        crate::map_store::AnchorSource::Owner,
    )
    .await
    {
        Ok(true) => Ok(StatusCode::NO_CONTENT),
        Ok(false) => Err(StatusCode::NOT_FOUND),
        Err(error) => {
            tracing::warn!(
                %error,
                project_id = %id,
                decision = body.decision_id,
                files = checked.len(),
                "writing down a decision's anchor files failed"
            );
            Err(StatusCode::INTERNAL_SERVER_ERROR)
        }
    }
}

async fn post_project_map_triage(
    State(state): State<AppState>,
    Path(id): Path<String>,
    Json(body): Json<MapTriageBody>,
) -> Result<Json<TriageReport>, StatusCode> {
    let brain = read_brain(&body.brain).ok_or(StatusCode::UNPROCESSABLE_ENTITY)?;
    let root = resolve_read_root(&state, &id, None).await?;
    let (_, mut junction) = project_junction(&state, &id, root.clone()).await?;
    let (readings, _) = anchor_digests(&root, &junction.decisions).await;

    // **§10's order, and on this route it is a spending decision rather than a display one.** The
    // sweep below caps at [`MAX_TRIAGE_BATCH`] and spends one model call per decision, so the order
    // it walks in decides which twenty of a three-hundred-row backlog get money spent on them —
    // every press, for as long as the cap stays saturated, which `MAX_TRIAGE_BATCH`'s own
    // measurement says is the state this repository lives in. `map_store::approved`'s order is
    // `spec_slug, ordinal, id`, so what that bought was the first twenty decisions alphabetically by
    // document. The answer is discarded here and kept by `GET /map`: what this route needs is the
    // order, and what the panel needs is the order plus the window it is a fact about.
    let walked = crate::map_recency::walk(&root).await;
    let _ = crate::map_recency::order(&mut junction.decisions, &walked);

    let stamped = crate::map_store::stamps(&state.pool, &id)
        .await
        .map_err(|error| {
            tracing::warn!(%error, project_id = %id, "project map stamps failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })?;
    let latest: std::collections::BTreeMap<i64, &crate::map_store::Stamp> = stamped
        .iter()
        .map(|stamp| (stamp.decision_id, stamp))
        .collect();
    // Read once, before any call. A judgement written by this very run cannot make one of its own
    // decisions "already current" — every decision is visited once — and reading per decision would
    // be one query per model call for an answer that cannot change under us.
    let answered = crate::map_store::judgements(&state.pool, &id)
        .await
        .map_err(|error| {
            tracing::warn!(%error, project_id = %id, "reading the triage pile failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })?;
    let known: std::collections::BTreeMap<i64, &crate::map_store::Judged> = answered
        .iter()
        .map(|judged| (judged.decision_id, judged))
        .collect();

    // Bound out here because `Extractor::Loopback` borrows it and the borrow has to outlive the
    // `match` that creates it, exactly as `map/extract` has it.
    let local_model;
    let (asked, model) = match brain {
        crate::chats::Brain::Cloud => (
            crate::map_intent::Extractor::Cli(state.runner.as_ref()),
            // The brain and not a model name, and the limit is worth stating rather than hiding
            // behind a plausible string. §6.2 asks for *o modelo que o produziu*; the CLI chooses
            // its own model per run and `CommandRunner::model_for_stage` answers `None` for an
            // unnamed stage, so the honest thing this daemon knows is which brain was asked.
            // `map_decisions.brain` records exactly the same word about the other half of the
            // feature, so the two piles are attributable alike.
            brain.as_str().to_owned(),
        ),
        // Unreachable today, and refused rather than given a placeholder. `read_brain` (~4050)
        // yields only `cloud` or `local`, so a hosted brain never gets this far — the 422 below is
        // the same answer it already receives one layer up, written here rather than invented.
        //
        // **Deliberately not the shape its sibling at ~4106 uses.** That route's arm falls back to
        // the CLI extractor, which is harmless there because the answer is returned and forgotten.
        // This one WRITES what answered into the triage pile, and a row recorded against the wrong
        // brain is exactly the silent lie `Brain::OpenRouter` was split out of `Local` to prevent.
        // A pile is read months later by somebody asking where their words went.
        //
        // Whoever makes the hosted route selectable here owns replacing this with a real extractor,
        // and will find no extractor to reach for: `map_intent::Extractor` has `Cli` and `Loopback`
        // and nothing hosted. That is the work, not this arm.
        crate::chats::Brain::OpenRouter => {
            tracing::warn!(
                project_id = %id,
                "the hosted brain was asked to triage, which this route has no extractor for"
            );
            return Err(StatusCode::UNPROCESSABLE_ENTITY);
        }
        crate::chats::Brain::Local => {
            // Read per request rather than cached on `AppState`, for `map/extract`'s reason: a name
            // cached at startup is one the owner cannot change without restarting the daemon.
            let Some(model) = models_config().local_triage_model else {
                tracing::warn!(
                    project_id = %id,
                    "the local brain was asked to triage and this machine has no local model \
                     configured"
                );
                return Err(StatusCode::SERVICE_UNAVAILABLE);
            };
            local_model = model;
            (
                crate::map_intent::Extractor::Loopback {
                    client: &state.web.http,
                    base_url: crate::runner::OLLAMA_BASE_URL,
                    model: &local_model,
                },
                // Here the model IS known, which is why the column takes a string rather than a
                // brain: the pile is more useful naming what answered than naming the choice.
                local_model.clone(),
            )
        }
    };

    // One clock for the whole run, as `GET /map` uses one for the whole answer: two amber stamps on
    // either side of `NOTE_LIFETIME` must be judged against the same instant, or a decision could
    // leave `Never` halfway through a sweep and be both in scope and not.
    let now = chrono::Utc::now();
    let mut report = TriageReport::default();
    let mut attempted = 0usize;

    // In §10's order, sorted above: *"dentro do que chega, a ordem é por recência de alteração do
    // código âncora, não por importância."* What that changes here is which decisions the cap
    // reaches, not whether the rest are ever reached — a judgement still current costs no call, so
    // the next press starts where this one stopped, which is the drain `MAX_TRIAGE_BATCH` describes.
    for anchored in &junction.decisions {
        let current = anchor_reading(&readings, anchored.decision_id);
        let standing = crate::map_stamp::standing(
            latest.get(&anchored.decision_id).copied(),
            crate::map_stamp::Anchoring {
                current,
                named: anchored.modules.len(),
                declared: anchored.anchor == crate::map_join::Anchor::Declared,
            },
            now,
        );
        if !matches!(standing, crate::map_stamp::Standing::Never) {
            continue;
        }
        report.in_scope += 1;

        // Before the staleness test and not after it, and the order is the point. During an outage
        // `is_current` says stale about every judgement in the project — they were stored against
        // `Computed(...)` and the reading now is `git-failed` — so a check that came second would
        // report three hundred decisions as freshly in need of a model when the only thing that
        // happened is that git hiccuped. Counted here, the number says what it is: the run was this
        // much narrower than it looks.
        if matches!(current, crate::map_stamp::Anchors::Failed) {
            report.unreadable_anchors += 1;
            continue;
        }

        let evidence = crate::map_triage::Evidence {
            decision: anchored,
            anchors: current,
        };
        let digest = crate::map_triage::inputs_digest(evidence);
        if known
            .get(&anchored.decision_id)
            .is_some_and(|judged| crate::map_triage::is_current(&judged.inputs_digest, &digest))
        {
            report.already_current += 1;
            continue;
        }

        // The cap counts ATTEMPTS and not rows, so a batch of answers nobody could read still ends
        // the run — otherwise a model returning prose would be asked three hundred times, and the
        // ceiling would protect the table instead of the owner's afternoon.
        if attempted >= MAX_TRIAGE_BATCH {
            report.left_over += 1;
            continue;
        }
        attempted += 1;

        let said = match crate::map_triage::ask(asked, evidence).await {
            Ok(said) => said,
            Err(error) => {
                tracing::warn!(
                    %error,
                    project_id = %id,
                    decision = anchored.decision_id,
                    brain = %brain.as_str(),
                    "a triage run failed, so nobody looked at this decision"
                );
                report.unanswered += 1;
                continue;
            }
        };
        // **An answer nobody could read becomes a `flagged` row that says so, and does not become
        // nothing.** Writing no row leaves the decision *not looked at*, which is honest and which
        // starves the queue: with no record that it was attempted it consumes a slot of
        // [`MAX_TRIAGE_BATCH`] on every future run, so twenty decisions that reliably confuse the
        // model mean nothing behind them is ever triaged again — a map that has stopped working
        // while going on reporting honestly that it has. See [`crate::map_triage::unreadable_flag`],
        // which argues why `flagged` is the one verdict a machine may reach for and what the trade
        // costs.
        let (answer, readable) = match crate::map_triage::parse_answer(&said) {
            Ok(answer) => (answer, true),
            Err(why) => {
                // What the model actually said travels into the log AND into the row, because
                // §6.2's argument applies hardest to the answers that were not judgements: a bug is
                // only fixable if it is visible.
                tracing::warn!(
                    project_id = %id,
                    decision = anchored.decision_id,
                    brain = %brain.as_str(),
                    "the triager answered something that is not a judgement: {why}"
                );
                (crate::map_triage::unreadable_flag(&why, &said), false)
            }
        };

        let wrote = crate::map_store::triage(
            &state.pool,
            &id,
            anchored.decision_id,
            answer.judgement,
            &answer.reason,
            &model,
            &digest,
        )
        .await
        .map_err(|error| {
            // The table refusing the row itself — a blank reason, a blank model, a blank digest —
            // is a bug in this handler and not a fact about the decision, so it is not counted and
            // swept past. `parse_answer` already refuses everything `0125` would, so reaching here
            // means the two disagree, and that is worth stopping for.
            tracing::warn!(
                %error,
                project_id = %id,
                decision = anchored.decision_id,
                "recording a judgement failed"
            );
            StatusCode::INTERNAL_SERVER_ERROR
        })?;
        if !wrote {
            report.vanished += 1;
        } else if readable {
            report.judged += 1;
        } else {
            report.unreadable += 1;
        }
    }

    Ok(Json(report))
}

/// Who last touched each line of a file, in the project or in one run's worktree.
async fn get_project_blame(
    State(state): State<AppState>,
    Path(id): Path<String>,
    Query(query): Query<ReadQuery>,
) -> Result<Json<Vec<inspect::BlameLine>>, StatusCode> {
    let root = resolve_read_root(&state, &id, query.run).await?;
    let rel = query.path.unwrap_or_default();
    tokio::task::spawn_blocking(move || inspect::blame(&root, &rel))
        .await
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?
        .map(Json)
        .map_err(inspect_status)
}

/// What `GET /projects/{id}/tests-map` answers: the state of the project's `nucleos.tests.yaml`
/// and, always, what this daemon would propose — beside a valid map too, so the owner can see
/// what a new build file would add.
#[derive(Debug, Serialize)]
struct TestsMapView {
    /// `absent`, `invalid` or `valid`.
    state: &'static str,
    errors: Vec<String>,
    groups: Vec<String>,
    proposal: crate::detect::TestsMapProposal,
}

fn tests_map_view(root: &std::path::Path) -> TestsMapView {
    let (state, errors, groups) = match crate::tests_map::load(root) {
        crate::tests_map::MapState::Absent => ("absent", Vec::new(), Vec::new()),
        crate::tests_map::MapState::Invalid(errors) => ("invalid", errors, Vec::new()),
        crate::tests_map::MapState::Valid(map) => {
            ("valid", Vec::new(), map.tests.groups.into_keys().collect())
        }
    };
    TestsMapView {
        state,
        errors,
        groups,
        proposal: crate::detect::propose_tests_map(root),
    }
}

async fn get_project_tests_map(
    State(state): State<AppState>,
    Path(id): Path<String>,
) -> Result<Json<TestsMapView>, StatusCode> {
    let root = resolve_project_root(&state, &id).await?;
    tokio::task::spawn_blocking(move || tests_map_view(&root))
        .await
        .map(Json)
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)
}

/// What one run has changed, and how big the tree it changed it in is.
///
/// `run` is required here, unlike the readers: "what changed" has no meaning against a project root
/// with no branch point to measure from. The uncommitted diff of the main checkout is a different
/// question and `/diff` already answers it.
async fn get_project_changed(
    State(state): State<AppState>,
    Path(id): Path<String>,
    Query(query): Query<ReadQuery>,
) -> Result<Json<inspect::Changed>, StatusCode> {
    let run = query.run.ok_or(StatusCode::BAD_REQUEST)?;
    let (root, base) = resolve_run_worktree(&state, &id, run).await?;
    tokio::task::spawn_blocking(move || inspect::changed(&root, &base))
        .await
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?
        .map(Json)
        .map_err(inspect_status)
}

/// Where one run's checkout is, and what it was cut from.
///
/// **The absolute path is the point of this route.** Every door to VS Code needs one — the editor's
/// URL handler takes a full path and nothing else — and the shell has no way to build one: it holds
/// repository-relative paths, and a run's worktree is not under the project root but beside it. A
/// link built from a relative path opens nothing, silently, which is the worst way for a seam to
/// fail.
///
/// The same guard as every other run-aware read: the row must belong to the project being asked.
async fn get_project_worktree(
    State(state): State<AppState>,
    Path(id): Path<String>,
    Query(query): Query<ReadQuery>,
) -> Result<Json<WorktreeView>, StatusCode> {
    let run = query.run.ok_or(StatusCode::BAD_REQUEST)?;
    let row: Option<(String, String, Option<String>, String)> = sqlx::query_as(
        "SELECT path, branch, base_sha, created_at FROM worktrees \
          WHERE owner_kind = 'run' AND owner_id = ? AND project_id = ? AND removed_at IS NULL",
    )
    .bind(run)
    .bind(&id)
    .fetch_optional(&state.pool)
    .await
    .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;

    let (path, branch, base_sha, created_at) = row.ok_or(StatusCode::NOT_FOUND)?;
    Ok(Json(WorktreeView {
        path,
        branch,
        base_sha,
        created_at,
    }))
}

/// One row of the write boundary, as the page draws it.
///
/// Owned strings now, because half the table is: an installed workflow's rows are read off its
/// manifest per project. They arrived as ROWS and not as a second shape, which is what the first
/// version of this struct said would happen.
///
/// `writable` is the field §12 asks for. Three states, not two: a file the app authors, a file
/// somebody else authors, and everything else — and the middle one needs its own answer because it
/// gets a different exit. The page must not infer it from `owner`, because `owner` is a name and
/// tomorrow there is a workflow called `core`.
#[derive(serde::Serialize)]
struct ClaimView {
    /// The row's identity: what `POST /write` and `GET /owned` are sent back. Relative to `home`.
    path: String,
    /// `state` for a file in `~/.nucleos/projects/<id>/`, `project` for one in the project's folder.
    home: &'static str,
    /// What a person is shown — `~/.nucleos/projects/<id>/autopilot.yaml` for a state file. Served
    /// rather than composed by the page, so the page never carries a location of its own.
    display: String,
    owner: String,
    what: String,
    writable: bool,
}

/// Which files in this project the app is the legitimate author of.
///
/// **Served rather than hard-coded in the shell, and that is the point of §7.3.** A boundary the
/// client carries its own copy of is a boundary that goes out of date silently: the page would
/// offer an editor for a file the daemon refuses, or hide one for a file it would accept. Here the
/// only thing that decides is `ownership.rs`, and the page draws what it is told.
///
/// The root is resolved even though the table does not depend on it. A fence drawn for a project
/// the daemon has no folder for is a fence around nothing, and the write route answers 404 on the
/// same call — so this fails in the same place rather than showing an editor that cannot save.
async fn get_project_ownership(
    State(state): State<AppState>,
    Path(id): Path<String>,
) -> Result<Json<Vec<ClaimView>>, StatusCode> {
    let root = resolve_project_root(&state, &id).await?;
    let claims = claims_for_project(&state, &id, root).await?;
    Ok(Json(
        claims
            .into_iter()
            .map(|claim| ClaimView {
                writable: claim.validate.is_some(),
                home: match claim.home {
                    crate::ownership::Home::State => "state",
                    crate::ownership::Home::Project => "project",
                },
                display: claim.display(&id),
                path: claim.path.into_owned(),
                owner: claim.owner.into_owned(),
                what: claim.what.into_owned(),
            })
            .collect(),
    ))
}

/// This project's state directory, `~/.nucleos/projects/<id>/`, or the refusal saying why there is
/// none.
///
/// Two refusals, and they are different facts: `no_machine_root` is this machine having no home
/// directory — the same name `/config/machine` refuses with — and `bad_project_id` is an id that
/// cannot name a directory without meaning another one (`project_state::valid_id`).
fn project_state_dir(
    state: &AppState,
    id: &str,
) -> Result<PathBuf, (StatusCode, Json<serde_json::Value>)> {
    let root = machine_config_root(state)?;
    crate::project_state::dir(&root, id)
        .ok_or_else(|| refusal(StatusCode::UNPROCESSABLE_ENTITY, "bad_project_id"))
}

/// Where a claimed file actually is, for the read route and the write route alike.
///
/// A state row is joined onto the state directory, a project row onto the project root — and in
/// both cases it is the REGISTRY's string that is joined, never the caller's, for the reason
/// `post_project_write` gives.
fn claim_home(
    state: &AppState,
    id: &str,
    root: &std::path::Path,
    claim: &crate::ownership::Claim,
) -> Result<PathBuf, (StatusCode, Json<serde_json::Value>)> {
    match claim.home {
        crate::ownership::Home::State => project_state_dir(state, id),
        crate::ownership::Home::Project => Ok(root.to_path_buf()),
    }
}

/// The text of one file this app declares itself the author of, from wherever the registry says it
/// lives.
///
/// **Its own route because `cat` cannot serve it any more.** `cat` reads inside the project's
/// folder, and the núcleo's own two files moved out of it, to `~/.nucleos/projects/<id>/`. The page
/// asks for a claim by its identity and this answers from the claim's home — so neither the page nor
/// the caller ever names a directory.
///
/// 404 with `absent` for a claimed file that does not exist yet: that is the ordinary state of a
/// project nobody has given rules, and the editor offers to create it. 403 `not_ours` for anything
/// the table does not name, exactly as the write route refuses it.
///
/// In no table in `auth.rs`, and so Admin's by default-deny: the rules file carries `gate_command`
/// and `GET /projects/{id}/rules`, which serves the same facts, has always been Admin's. When the
/// file lived in the project a read-only key could `cat` it; the move is where that stops, and it is
/// the right place for it to stop.
async fn get_project_owned(
    State(state): State<AppState>,
    Path(id): Path<String>,
    Query(query): Query<ReadQuery>,
) -> Result<String, (StatusCode, Json<serde_json::Value>)> {
    let root = resolve_project_root(&state, &id)
        .await
        .map_err(|status| refusal(status, "no_project_root"))?;
    let claims = claims_for_project(&state, &id, root.clone())
        .await
        .map_err(|status| refusal(status, "internal"))?;
    let rel = query.path.unwrap_or_default();
    let crate::ownership::Owner::Declared(claim) = crate::ownership::owner_of(&claims, &rel) else {
        return Err(refusal(StatusCode::FORBIDDEN, "not_ours"));
    };
    let home = claim_home(&state, &id, &root, claim)?;
    let path = claim.path.clone().into_owned();
    tokio::task::spawn_blocking(move || {
        let target = inspect::safe_join(&home, &path)
            .map_err(|error| refusal(inspect_status(error), "unreadable"))?;
        match std::fs::read_to_string(&target) {
            Ok(text) => Ok(text),
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
                Err(refusal(StatusCode::NOT_FOUND, "absent"))
            }
            Err(error) => {
                tracing::warn!(%error, "reading a claimed file failed");
                Err(refusal(StatusCode::INTERNAL_SERVER_ERROR, "internal"))
            }
        }
    })
    .await
    .map_err(|_| refusal(StatusCode::INTERNAL_SERVER_ERROR, "internal"))?
}

/// The fence in force in one project, read off the disk on the thread pool.
///
/// `spawn_blocking`, because assembling it opens the pins file and walks whatever bundles are
/// installed. Small work, but filesystem work, and the runtime this daemon shares with every
/// sidecar and every run is not the place to do it inline.
///
/// A machine with no home directory has no library, which is an empty shelf and not a failure: the
/// núcleo's own rows still stand, so the write boundary never disappears because a path lookup came
/// back empty.
///
/// The same is true of a project with no state directory: no pins file means nothing is installed,
/// and the fence is the núcleo's rows alone.
async fn claims_for_project(
    state: &AppState,
    id: &str,
    root: PathBuf,
) -> Result<Vec<crate::ownership::Claim>, StatusCode> {
    let library = state.workflow_library.clone();
    let pins = crate::project_state::file(
        state.machine_config_root.as_deref(),
        id,
        crate::project_state::PINS_FILE,
    );
    tokio::task::spawn_blocking(move || match library {
        Some(library) => crate::ownership::claims_for(&root, pins.as_deref(), &library),
        None => crate::ownership::CLAIMS.to_vec(),
    })
    .await
    .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)
}

#[derive(Deserialize)]
struct WriteRequest {
    /// A claim's identity, forward slashes. Only ever compared — never joined; see below.
    path: String,
    contents: String,
}

/// Writes one file the app declares itself the author of.
///
/// The five refusals are five different facts and none of them is "no". In order, and the order is
/// the design:
///
/// 1. **423, the emergency stop.** First, before the path is so much as looked at. A write refused
///    for a path reason while the stop is engaged would tell somebody their path was wrong when the
///    answer is that nothing acts right now. The scoped brake counts too: a project held on its own
///    is held for this as well.
///
///    The cost of this guard is one thing and it is worth naming: the rules file cannot be edited
///    HERE while the stop is engaged, which is a moment somebody might well want to edit it. It
///    costs nothing they cannot recover, because layer 2's whole premise is that the editor is one
///    click away and the file is ordinary text — and what it buys is that the shell is not a door
///    with privileges an agent lacks, which is the promise §7.5 makes.
/// 2. **404, no folder.** A project the daemon has no root for has no file to write.
/// 3. **403, not ours.** Everything the table does not name, which is nearly everything. A path
///    with `..` in it lands here rather than at the path guard, and deliberately: the app answers
///    about names it owns, and a traversal is not one — so the filesystem is never touched for a
///    path nobody claimed. **`another_author` is its own refusal beside it**, for a file an
///    installed workflow declares: the fence names it, and the app still may not write it, because
///    it has no parser for it. One code for both would tell somebody the file is nobody's when it
///    has an author standing right there, and the exit for the two is different.
/// 4. **400/404, unwritable.** The claimed path that nonetheless does not land inside its home,
///    which after (3) means one thing: a directory link or junction on the way to it. (Beside it,
///    `no_machine_root` and `bad_project_id` when the project has no state directory to write
///    into at all — see [`project_state_dir`].)
/// 5. **422, invalid, WITH the parser's words.** The one refusal carrying a detail, because the raw
///    hatch is unusable without it — "unprocessable entity" sends somebody to an editor, which is
///    the surface the hatch exists to replace.
///
/// **The file written is the one the registry names, never the string the caller sent.** The two
/// normalise to the same file by the time (3) passes, and joining the caller's spelling anyway
/// would make every future change to `normalise` a security question instead of a tidiness one.
/// It is joined onto the claim's HOME: the núcleo's own rows land in
/// `~/.nucleos/projects/<id>/`, not in the project — see `project_state.rs`.
///
/// This route is in no table in `auth.rs`, so `permits` — which is default-deny — leaves it to
/// Control and Admin. That is not an omission: the project's `autopilot.yaml` carries
/// `gate_command`, and a run able to rewrite it could decide what green means for every gate it
/// will ever face.
async fn post_project_write(
    State(state): State<AppState>,
    Path(id): Path<String>,
    Json(body): Json<WriteRequest>,
) -> Result<StatusCode, (StatusCode, Json<serde_json::Value>)> {
    // Unreadable reads as engaged, the rule `assistant.rs` already pins: a stop nobody can ask
    // about is not a stop anybody may assume is off.
    let halted = crate::autopilot::kill_switch_engaged(&state.pool)
        .await
        .unwrap_or(true)
        || crate::autopilot::scoped_kill_engaged(&state.pool, "project", &id)
            .await
            .unwrap_or(true);
    if halted {
        return Err(refusal(StatusCode::LOCKED, "kill_switch"));
    }

    let root = resolve_project_root(&state, &id)
        .await
        .map_err(|status| refusal(status, "no_project_root"))?;

    let claims = claims_for_project(&state, &id, root.clone())
        .await
        .map_err(|status| refusal(status, "internal"))?;
    let crate::ownership::Owner::Declared(claim) = crate::ownership::owner_of(&claims, &body.path)
    else {
        return Err(refusal(StatusCode::FORBIDDEN, "not_ours"));
    };
    let Some(validate) = claim.validate else {
        // The middle state of §12, said in its own words: somebody authors this file and it is not
        // this app. `detail` carries who, because the exit depends on it — a workflow's file is
        // changed where the workflow lives.
        return Err((
            StatusCode::FORBIDDEN,
            Json(serde_json::json!({
                "refusal": "another_author",
                "detail": format!("{} authors this file", claim.owner),
            })),
        ));
    };

    let path = claim.path.clone().into_owned();
    let display = claim.display(&id);
    let home = claim_home(&state, &id, &root, claim)?;
    // A state directory is created by the first file anybody writes into it, and
    // `safe_write_target` canonicalises its root before it will answer — the same order
    // `post_machine_config` takes, and created only once the path is known to be a row.
    if matches!(claim.home, crate::ownership::Home::State) {
        std::fs::create_dir_all(&home).map_err(|error| {
            tracing::warn!(
                %error,
                project_id = %id,
                "could not create this project's state directory"
            );
            refusal(StatusCode::INTERNAL_SERVER_ERROR, "internal")
        })?;
    }
    let target = inspect::safe_write_target(&home, &path)
        .map_err(|error| refusal(inspect_status(error), "unwritable"))?;

    if let Err(detail) = validate(&body.contents) {
        return Err((
            StatusCode::UNPROCESSABLE_ENTITY,
            Json(serde_json::json!({ "refusal": "invalid", "detail": detail })),
        ));
    }

    let contents = body.contents;
    tokio::task::spawn_blocking(move || crate::project_state::write_atomically(&target, &contents))
        .await
        .map_err(|_| refusal(StatusCode::INTERNAL_SERVER_ERROR, "internal"))?
        .map_err(|error| {
            tracing::warn!(%error, project_id = %id, %path, "writing a project file failed");
            refusal(StatusCode::INTERNAL_SERVER_ERROR, "internal")
        })?;

    // After the write, not before, and loudly on failure. A feed line about a write that then failed
    // claims something that did not happen; a write whose line was lost is recoverable from the log,
    // and refusing the request at this point would report a failure for work already done.
    if let Err(error) = feed::append(
        &state.pool,
        Some(&id),
        "config_written",
        &format!("{display} written from the app"),
        None,
        None,
    )
    .await
    {
        tracing::error!(
            %error,
            project_id = %id,
            %path,
            "a project file was written and its feed line was not recorded"
        );
    }

    Ok(StatusCode::NO_CONTENT)
}

/* ------------------------------------------------------------- onboarding -- */

#[derive(Deserialize)]
struct OnboardingQuery {
    /// The folder to read, for a project that has no root on record yet — one being added, or one
    /// in `off`, whose root `set_project_mode` cleared. Absent means the root on record.
    root: Option<String>,
}

#[derive(Deserialize)]
struct OnboardRequest {
    /// As [`OnboardingQuery::root`].
    #[serde(default)]
    project_root: Option<String>,
    /// The gate command a person confirmed. Absent, null or blank is "none confirmed", which leaves
    /// the project's rules exactly as they are — see `onboarding::onboard`.
    #[serde(default)]
    gate_command: Option<String>,
}

/// What a person reads before onboarding a project, and what they read after.
#[derive(Serialize)]
struct OnboardingView {
    project_id: String,
    root: String,
    /// The marker, when the project was onboarded; `null` when it was not.
    onboarded: Option<crate::onboarding::Marker>,
    /// Where the marker is, as a person is shown it.
    marker_path: String,
    harnesses: Vec<crate::detect::Harness>,
    /// The gate this app would propose from the folder (`detect::propose_gate`).
    proposed_gate: Option<crate::detect::GateProposal>,
    /// The gate the project's rules already name, which the field should start from when there is
    /// one: onboarding again must not quietly swap a gate somebody chose for a guess.
    configured_gate: Option<String>,
    /// Whether this daemon's classifier hook is wired at the root right now.
    hook_wired: bool,
}

/// The folder onboarding is about: the one the request names, or the one on record.
///
/// A named folder is held to what `GET /projects/detect` holds a path to — absolute, there, a
/// folder — because pointing at a folder is what bringing a project in IS, exactly as adding one
/// is. The same key reaches both doors, and it is the owner's.
async fn onboarding_root(
    state: &AppState,
    id: &str,
    named: Option<String>,
) -> Result<PathBuf, (StatusCode, Json<serde_json::Value>)> {
    let Some(named) = named
        .map(|root| root.trim().to_string())
        .filter(|root| !root.is_empty())
    else {
        return resolve_project_root(state, id)
            .await
            .map_err(|status| refusal(status, "no_project_root"));
    };
    let root = PathBuf::from(named);
    if !root.is_absolute() {
        return Err(refusal(StatusCode::BAD_REQUEST, "not_absolute"));
    }
    match tokio::fs::metadata(&root).await {
        Ok(meta) if meta.is_dir() => Ok(root),
        Ok(_) => Err(refusal(StatusCode::UNPROCESSABLE_ENTITY, "not_a_folder")),
        Err(_) => Err(refusal(StatusCode::NOT_FOUND, "no_such_folder")),
    }
}

async fn onboarding_view(
    state: &AppState,
    id: &str,
    root: PathBuf,
) -> Result<OnboardingView, (StatusCode, Json<serde_json::Value>)> {
    let machine_root = machine_config_root(state)?;
    let project_id = id.to_string();
    tokio::task::spawn_blocking(move || {
        let found = crate::detect::inspect_folder(&root);
        // An unreadable rules file has no gate this can name; the POST refuses it by name.
        let configured_gate = crate::config::load_schedule_rules(Some(&machine_root), &project_id)
            .ok()
            .and_then(|rules| rules.gate_command);
        OnboardingView {
            onboarded: crate::onboarding::read_marker(Some(&machine_root), &project_id),
            marker_path: crate::project_state::display_path(
                &project_id,
                crate::onboarding::MARKER_FILE,
            ),
            harnesses: found.harnesses,
            proposed_gate: found.gate,
            configured_gate,
            hook_wired: crate::autopilot::classifier_hook_is_wired(&root),
            root: root.to_string_lossy().into_owned(),
            project_id,
        }
    })
    .await
    .map_err(|_| refusal(StatusCode::INTERNAL_SERVER_ERROR, "internal"))
}

/// What onboarding would find and propose, and whether it already happened.
///
/// Reads and proposes, like `GET /projects/detect`; nothing is stored until the POST. Admin's by
/// default-deny, beside the POST: it reads the project's rules, and `GET /projects/{id}/rules`,
/// which serves the same gate, has always been Admin's.
async fn get_project_onboarding(
    State(state): State<AppState>,
    Path(id): Path<String>,
    Query(query): Query<OnboardingQuery>,
) -> Result<Json<OnboardingView>, (StatusCode, Json<serde_json::Value>)> {
    project_state_dir(&state, &id)?;
    let root = onboarding_root(&state, &id, query.root).await?;
    onboarding_view(&state, &id, root).await.map(Json)
}

/// A refusal with its reason beside its name — the shape `POST /write` uses for `invalid`.
fn refusal_with_detail(
    status: StatusCode,
    name: &'static str,
    detail: String,
) -> (StatusCode, Json<serde_json::Value>) {
    (
        status,
        Json(serde_json::json!({ "refusal": name, "detail": detail })),
    )
}

/// Onboards a project to NucleOS, with the gate command a person confirmed. Idempotent.
///
/// The one thing activation now asks of a project besides the classifier hook (`autopilot.rs`),
/// and the act is `onboarding::onboard`'s: check the gate, detect the harnesses, install the hook
/// with the same `wire_classifier_hook` every other door uses, store the gate as `gate_command` in
/// the project's `autopilot.yaml` — where the gate already lives — and write the marker last.
///
/// **In no table in `auth.rs`, so Admin's by default-deny**, for `POST /projects/{id}/write`'s
/// reason and a second one: it sets what *green* means, and it writes an executable hook into a
/// folder. The folder may be named in the body, which the two session doors that wire the hook
/// refuse to allow; here it is allowed because a project being brought in has no folder on record
/// yet, and naming one is what `GET /projects/detect` already lets this same key do.
///
/// **Kill-switch checked first, like `POST /write` and `POST /config/machine`.** Onboarding writes
/// `gate_command` into the project's `autopilot.yaml` and installs an executable classifier hook —
/// the same shape of governance write those two routes already refuse the stop for — so a stop
/// engaged here must refuse before either lands. The shell's new-project wizard used to lean on
/// this route succeeding while the stop was engaged, because registering a project runs onboarding
/// as its first step; it now catches this refusal there, registers the project anyway, and leaves
/// onboarding for the project's own Settings once the stop is released (see `NewProject.tsx`).
///
/// Refusals, all `{refusal, detail?}`: `kill_switch` (423) first, then the root's
/// (`no_project_root`, `not_absolute`, `no_such_folder`, `not_a_folder`), the state directory's
/// (`no_machine_root`, `bad_project_id`), then `invalid_gate` and `rules_unreadable` (422, with the
/// reason) before anything is written, and `hook_unwritable` (409, with the reason) for a
/// `.claude/settings.json` this cannot parse.
async fn post_project_onboard(
    State(state): State<AppState>,
    Path(id): Path<String>,
    Json(body): Json<OnboardRequest>,
) -> Result<Json<OnboardingView>, (StatusCode, Json<serde_json::Value>)> {
    // Unreadable reads as engaged, the rule `assistant.rs` already pins: a stop nobody can ask
    // about is not a stop anybody may assume is off.
    if crate::autopilot::kill_switch_engaged(&state.pool)
        .await
        .unwrap_or(true)
    {
        return Err(refusal(StatusCode::LOCKED, "kill_switch"));
    }

    project_state_dir(&state, &id)?;
    let machine_root = machine_config_root(&state)?;
    let root = onboarding_root(&state, &id, body.project_root).await?;
    let gate = body
        .gate_command
        .map(|command| command.trim().to_string())
        .filter(|command| !command.is_empty());

    let (project_id, project_root, confirmed) = (id.clone(), root.clone(), gate.clone());
    let now = chrono::Utc::now().to_rfc3339();
    tokio::task::spawn_blocking(move || {
        crate::onboarding::onboard(
            &machine_root,
            &project_id,
            &project_root,
            confirmed.as_deref(),
            &now,
        )
    })
    .await
    .map_err(|_| refusal(StatusCode::INTERNAL_SERVER_ERROR, "internal"))?
    .map_err(|error| match error {
        crate::onboarding::OnboardError::BadId => {
            refusal(StatusCode::UNPROCESSABLE_ENTITY, "bad_project_id")
        }
        crate::onboarding::OnboardError::Gate(detail) => {
            refusal_with_detail(StatusCode::UNPROCESSABLE_ENTITY, "invalid_gate", detail)
        }
        crate::onboarding::OnboardError::Rules(detail) => {
            refusal_with_detail(StatusCode::UNPROCESSABLE_ENTITY, "rules_unreadable", detail)
        }
        crate::onboarding::OnboardError::Hook(detail) => {
            refusal_with_detail(StatusCode::CONFLICT, "hook_unwritable", detail)
        }
        crate::onboarding::OnboardError::Io(error) => {
            tracing::warn!(%error, project_id = %id, "onboarding a project failed");
            refusal(StatusCode::INTERNAL_SERVER_ERROR, "internal")
        }
    })?;

    let summary = match &gate {
        Some(command) => format!(
            "onboarded at {}: classifier hook installed, gate command confirmed as `{command}`",
            root.display()
        ),
        None => format!(
            "onboarded at {}: classifier hook installed, no gate command confirmed",
            root.display()
        ),
    };
    // After the act, and loudly on failure, for `post_project_write`'s reason. Spelled as a literal
    // and not as `onboarding::FEED_KIND`, because the shell's completeness test reads feed kinds out
    // of this source; the test below holds the two equal.
    if let Err(error) = feed::append(
        &state.pool,
        Some(&id),
        "project_onboarded",
        &summary,
        None,
        None,
    )
    .await
    {
        tracing::error!(
            %error,
            project_id = %id,
            "a project was onboarded and its feed line was not recorded"
        );
    }

    onboarding_view(&state, &id, root).await.map(Json)
}

/* ------------------------------------------------------- project commands -- */

/// Everything this project can be asked to do to itself, overlay applied.
async fn get_project_commands(
    State(state): State<AppState>,
    Path(id): Path<String>,
) -> Result<Json<Vec<crate::project_commands::ProjectCommand>>, StatusCode> {
    crate::project_commands::list(&state.pool, &id)
        .await
        .map(Json)
        .map_err(|error| {
            tracing::warn!(%error, project_id = %id, "listing project commands failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })
}

#[derive(Deserialize)]
struct DeclareRequest {
    name: String,
    command: String,
    #[serde(default)]
    cwd: Option<String>,
    #[serde(default)]
    is_gate: bool,
    /// Absent means 0, which is what almost every command means by passing.
    #[serde(default)]
    pass_exit_code: Option<i64>,
    /// Absent means `person`. Default-deny: a command declared by somebody who never thought about
    /// this question must not thereby become something an autonomous run may execute.
    #[serde(default)]
    runnable_by: Option<crate::project_commands::RunnableBy>,
}

/// Declares one of this project's own commands, replacing any of the same name.
///
/// **No kill-switch check here, and the asymmetry with `POST /write` is deliberate.** That one puts
/// bytes in the project's own folder, which §7.5 says must go the way an agent's write goes. This
/// writes a database row, like `POST /wip-limit` beside it, and neither of those starts anything.
/// The stop belongs on the route that spawns a process, which is the next one down.
async fn post_project_command(
    State(state): State<AppState>,
    Path(id): Path<String>,
    Json(body): Json<DeclareRequest>,
) -> Result<Json<serde_json::Value>, (StatusCode, Json<serde_json::Value>)> {
    let root = resolve_project_root(&state, &id)
        .await
        .map_err(|status| refusal(status, "no_project_root"))?;

    if let Err(invalid) =
        crate::project_commands::validate(&body.name, &body.command, body.cwd.as_deref())
    {
        return Err((
            StatusCode::UNPROCESSABLE_ENTITY,
            Json(serde_json::json!({ "refusal": "invalid", "detail": invalid.to_string() })),
        ));
    }

    // The half `validate` cannot do: whether the directory is actually there, and is a directory.
    // Checked when it is declared so a typo is caught while the person who made it is looking at
    // it — and again when it runs, because a folder that existed on Tuesday can be gone on
    // Wednesday.
    if let Some(cwd) = body.cwd.as_deref() {
        working_directory(&root, cwd)?;
    }

    let id_for_log = id.clone();
    let new_id = crate::project_commands::declare(
        &state.pool,
        &id,
        crate::project_commands::Declaration {
            name: body.name,
            command: body.command,
            cwd: body.cwd,
            is_gate: body.is_gate,
            pass_exit_code: body.pass_exit_code.unwrap_or(0),
            runnable_by: body
                .runnable_by
                .unwrap_or(crate::project_commands::RunnableBy::Person),
        },
    )
    .await
    .map_err(|error| {
        tracing::warn!(%error, project_id = %id_for_log, "declaring a project command failed");
        refusal(StatusCode::INTERNAL_SERVER_ERROR, "internal")
    })?;

    Ok(Json(serde_json::json!({ "id": new_id })))
}

/// Forgets one of this project's commands.
async fn delete_project_command(
    State(state): State<AppState>,
    Path((id, command_id)): Path<(String, i64)>,
) -> Result<StatusCode, StatusCode> {
    match crate::project_commands::remove(&state.pool, &id, command_id).await {
        Ok(true) => Ok(StatusCode::NO_CONTENT),
        Ok(false) => Err(StatusCode::NOT_FOUND),
        Err(error) => {
            tracing::warn!(%error, project_id = %id, "forgetting a project command failed");
            Err(StatusCode::INTERNAL_SERVER_ERROR)
        }
    }
}

/// Where a command runs, resolved and refused as one answer.
///
/// `None` is the project root. A relative path is refused unless it resolves inside the project and
/// is a directory — the same guard the readers use, and it has to be re-asked at run time because
/// the declaration was checked at some earlier moment.
fn working_directory(
    root: &std::path::Path,
    cwd: &str,
) -> Result<PathBuf, (StatusCode, Json<serde_json::Value>)> {
    let resolved =
        inspect::resolved_within(root, cwd).map_err(|error| match inspect_status(error) {
            StatusCode::NOT_FOUND => refusal(StatusCode::UNPROCESSABLE_ENTITY, "cwd_missing"),
            status => refusal(status, "cwd_unsafe"),
        })?;
    if !resolved.is_dir() {
        return Err(refusal(
            StatusCode::UNPROCESSABLE_ENTITY,
            "cwd_not_a_folder",
        ));
    }
    Ok(resolved)
}

/// Runs one of this project's commands and answers before it finishes.
///
/// **202 and not the output.** A suite takes minutes; an HTTP request that held the connection for
/// them would be a request that any proxy, any sleep and any closed lid would kill halfway. The
/// result lands on the command's own row and the page reads it back — which is also what makes the
/// answer survive a reload, and what makes "is the gate green" a fact the page already has rather
/// than something it has to ask for.
///
/// The refusals, in the order they are asked:
///
/// 1. **423, the emergency stop.** First, because it is the one refusal that is about the machine
///    rather than about this request. A stop that did not stop a button spawning `cargo test` would
///    be a stop in name only.
/// 2. **404**, no folder, or no such command in THIS project — the `project_id` in the lookup being
///    what keeps an integer in a URL from naming another project's row.
/// 3. **403**, a command marked `person` reached by a key that is nobody's but an agent's.
/// 4. **422**, a working directory that has gone, or that is not a directory.
/// 5. **409**, already running. The claim is a conditional UPDATE rather than a read followed by a
///    write, so two clicks landing together cannot both start the suite in one folder.
async fn post_project_command_run(
    State(state): State<AppState>,
    Extension(scope): Extension<crate::auth::Scope>,
    Path((id, command_id)): Path<(String, i64)>,
) -> Result<StatusCode, (StatusCode, Json<serde_json::Value>)> {
    let halted = crate::autopilot::kill_switch_engaged(&state.pool)
        .await
        .unwrap_or(true)
        || crate::autopilot::scoped_kill_engaged(&state.pool, "project", &id)
            .await
            .unwrap_or(true);
    if halted {
        return Err(refusal(StatusCode::LOCKED, "kill_switch"));
    }

    let root = resolve_project_root(&state, &id)
        .await
        .map_err(|status| refusal(status, "no_project_root"))?;

    let command = crate::project_commands::get(&state.pool, &id, command_id)
        .await
        .map_err(|_| refusal(StatusCode::INTERNAL_SERVER_ERROR, "internal"))?
        .ok_or_else(|| refusal(StatusCode::NOT_FOUND, "no_such_command"))?;

    if crate::project_commands::caller_is_an_agent(&scope)
        && command.runnable_by != crate::project_commands::RunnableBy::Agent
    {
        return Err(refusal(StatusCode::FORBIDDEN, "person_only"));
    }

    let cwd = match command.cwd.as_deref() {
        Some(cwd) => working_directory(&root, cwd)?,
        None => root.clone(),
    };

    let pool = state.pool.clone();
    let project_id = id.clone();
    let name = command.name.clone();
    let text = command.command.clone();
    let pass = command.pass_exit_code;

    // The claim and the spawn together, uncancellable, for the reason `create_run` gives: a client
    // that disconnects mid-request drops this future, and a drop landing between the two would
    // leave a row saying `running` with nothing running.
    let claimed = uncancellable(async move {
        // A failed claim is a storage error, not a command already running: reporting it as
        // `already_running` would send the owner looking for a second click that never happened.
        match crate::project_commands::mark_running(&pool, &project_id, command_id).await {
            Ok(true) => {}
            Ok(false) => return Ok(false),
            Err(error) => return Err(error),
        }
        tokio::spawn(async move {
            // **The reference is the same directory the command runs in, on purpose.**
            // `run_gate`'s tamper check exists because a gate measures a run's own worktree and
            // that run could have rewritten the script it is measured by. There is no second copy
            // here — this runs in the project's own checkout, which IS the reference — so passing
            // the same path makes the check a no-op by construction rather than by luck. Passing
            // the project root instead would compare a subdirectory's scripts against paths that
            // do not exist there and report a tamper that never happened.
            //
            // In a task of its own, awaited here, so a panic inside the measurement still reaches
            // `finish` below. Without that the row would say `running` until the next restart,
            // and the conditional claim above would refuse every later click as `already_running`.
            let measured = tokio::spawn(async move {
                crate::gate::run_gate(&cwd, &cwd, &text, crate::project_commands::COMMAND_TIMEOUT)
                    .await
            })
            .await;
            let finished = match measured {
                Ok(outcome) => crate::project_commands::verdict(pass, outcome),
                Err(error) => {
                    tracing::error!(%error, command_id, "a project command's task ended without a result");
                    crate::project_commands::Finished {
                        outcome: crate::project_commands::Outcome::Errored,
                        exit_code: None,
                        output: Some(format!("the command's task ended without a result: {error}")),
                    }
                }
            };
            let said = match finished.outcome {
                crate::project_commands::Outcome::Passed => format!("{name} passed"),
                crate::project_commands::Outcome::Failed => match finished.exit_code {
                    Some(code) => format!("{name} failed with exit {code}"),
                    None => format!("{name} failed"),
                },
                // Never "failed". A command that could not be measured says nothing about the
                // project, and reporting it as a failure would stop the wrong work.
                _ => format!("{name} could not be measured"),
            };
            if let Err(error) =
                crate::project_commands::finish(&pool, command_id, finished).await
            {
                tracing::error!(%error, command_id, "a project command finished and was not recorded");
            }
            let _ = crate::feed::append(&pool, Some(&project_id), "command_finished", &said, None, None)
                .await;
        });
        Ok(true)
    })
    .await
    .map_err(|status| refusal(status, "internal"))?
    .map_err(|error: sqlx::Error| {
        tracing::warn!(%error, command_id, "claiming a project command failed");
        refusal(StatusCode::INTERNAL_SERVER_ERROR, "internal")
    })?;

    if !claimed {
        return Err(refusal(StatusCode::CONFLICT, "already_running"));
    }
    Ok(StatusCode::ACCEPTED)
}

/* ------------------------------------------ the reach a project declares -- */

/// The longest prefix, op kind or branch one declaration may carry.
///
/// A route limit rather than a schema one, and the reason is the hook's hot path: `ShellRules`
/// re-folds every stored prefix on every comparison, and that comparison runs once per tool call of
/// every run of this project. Nothing else bounds what one POST can put there. A prefix has
/// `SAFE_COMMAND_PREFIXES`' shape — `bash scripts/gates.sh` is twenty-one characters — so this is
/// generous by more than an order of magnitude and still stops a 200 KB string reaching that path.
const MAX_DECLARATION_LEN: usize = 512;

/// Refuses a project this daemon has never heard of, without requiring it to be switched ON.
///
/// **Deliberately not `resolve_project_root`, which is what the neighbouring routes use.** That one
/// reads `autopilot_state.project_root`, and `autopilot::set_project_mode` persists that column as
/// `NULL` for `Mode::Off` — so it 404s a project that is on the roster and merely paused. Declaring
/// what a project may do while it is off is a reasonable thing to want, and often the very moment
/// you would want it: the reach is what you set before you switch autonomy on.
///
/// So this asks the weaker question the roster itself asks — is there a row at all. It still closes
/// what it was added for: a typo'd id used to answer 204 and then show the rule back through the
/// GET, which is indistinguishable from a real project with no rules, so the owner's only feedback
/// loop confirmed a `deny` that nothing anywhere would ever enforce.
async fn project_is_on_the_roster(
    state: &AppState,
    id: &str,
) -> Result<(), (StatusCode, Json<serde_json::Value>)> {
    let known: Option<i64> =
        sqlx::query_scalar("SELECT 1 FROM autopilot_state WHERE project_id = ?")
            .bind(id)
            .fetch_optional(&state.pool)
            .await
            .map_err(|error| {
                tracing::warn!(%error, project_id = %id, "checking the roster failed");
                refusal(StatusCode::INTERNAL_SERVER_ERROR, "internal")
            })?;
    if known.is_none() {
        return Err((
            StatusCode::NOT_FOUND,
            Json(serde_json::json!({
                "refusal": "no_such_project",
                "detail": format!("this daemon has no project called `{id}`"),
            })),
        ));
    }
    Ok(())
}

/// The emergency stop, asked only of the declarations that WIDEN.
///
/// **`post_project_command`'s argument for needing no stop does not transfer here, and this is the
/// one route family in this file where it does not.** That one says it "writes a database row, like
/// `POST /wip-limit` beside it, and neither of those starts anything" — true, because every reader
/// of those rows is a start point, and the stop already guards every start point. The rows written
/// here are read by `hooks.rs`, per decision, with no cache and no `kill_switch_engaged` call
/// anywhere in it. `set_kill_switch` flips a flag and cancels nothing already running, so with the
/// stop engaged an `allow` declared here still binds the very next tool call of every in-flight run
/// of this project. That is a widening the stop was supposed to make impossible.
///
/// **Only the widenings.** A `deny`, and all four DELETEs, stay open with the stop engaged: an
/// emergency stop that stopped somebody NARROWING autonomy would be holding the door open on the
/// way out. It is the asymmetry `hooks::downgrade_if_unreadable` already takes, where only the
/// `allow` is touched.
///
/// `POST /land-targets` is not gated either, and that is a judgement rather than an oversight: a
/// landing target binds nothing until a landing is attempted, and a landing goes through the queue,
/// which the stop already governs at its own start point.
///
/// Both switches and `unwrap_or(true)`, copied from `post_project_command_run` rather than invented:
/// a stop nobody can read is a stop.
async fn declaration_halted(
    state: &AppState,
    id: &str,
) -> Result<(), (StatusCode, Json<serde_json::Value>)> {
    let halted = crate::autopilot::kill_switch_engaged(&state.pool)
        .await
        .unwrap_or(true)
        || crate::autopilot::scoped_kill_engaged(&state.pool, "project", id)
            .await
            .unwrap_or(true);
    if halted {
        return Err(refusal(StatusCode::LOCKED, "kill_switch"));
    }
    Ok(())
}

/// Refuses a declared value longer than anything a real one is, naming the length.
fn within_length(
    what: &'static str,
    value: &str,
) -> Result<(), (StatusCode, Json<serde_json::Value>)> {
    if value.len() > MAX_DECLARATION_LEN {
        return Err((
            StatusCode::UNPROCESSABLE_ENTITY,
            Json(serde_json::json!({
                "refusal": "too_long",
                "detail": format!(
                    "this {what} is {} bytes; the most one may carry is {MAX_DECLARATION_LEN}",
                    value.len()
                ),
            })),
        ));
    }
    Ok(())
}

/// One declared shell rule, whole.
///
/// A `View` and not a fourth `ProjectRules`. There are already two: the struct above, which answers
/// `GET /projects/{id}/rules` about the project's `autopilot.yaml`, and `hooks::ProjectRules`, which
/// is an
/// enum about whether the table could be read at all. A third spelling of that name would tell a
/// reader nothing about which of the three they are holding.
///
/// **A ROW per rule, and not the two lists of prefixes this route used to serve.** The two shapes
/// carry the same facts and only one of them survives a rule travelling alone, which is the whole
/// argument:
///
/// - The note was the reason to change anything, and it cannot ride on a `Vec<String>`. Migration
///   `0128` calls that column "a única defesa contra uma lista que daqui a seis meses ninguém sabe
///   justificar", and a defence that can only be written is no defence.
/// - A rule's verdict belongs ON the rule. In `{allow: [...], deny: [...]}` the verdict lives in the
///   CONTAINER, so the moment a page hands one rule to an edit form the verdict falls off — and
///   `POST /projects/{id}/shell-rules` rewrites BOTH `verdict` and `note` from what it is sent. That
///   is the same loss this change exists to close, one field over. Served as rows, what comes back
///   from the GET is field-for-field what the POST takes, and re-declaring is changing one of them.
/// - The split stays legible because every row says which side it is on, which is strictly more
///   than the old shape said: it named the sides once, at the top, and a page still had to
///   re-associate every prefix with the list it came out of before it could draw anything. Grouping
///   by `verdict` is what the page does instead, and `deny` beating `allow` is a sentence it can now
///   write next to a rule rather than next to a heading.
///
/// The prefixes come back FOLDED, because that is how the table stores them and how they are
/// enforced. Serving the typed spelling would show an owner a `Remove-Item` the classifier knows as
/// `remove-item`, which is the very lie `project_policy::fold_prefix` exists to stop. WHICH fold a
/// prefix got follows `tool`: a command is lower-cased and a path is not, so two rows that look
/// alike on screen were folded by two different functions and only that field says which.
///
/// **`created_at` is served, and it is not padding.** The note says WHY a rule is there; this says
/// WHEN, and the column's stated purpose is a list nobody can justify *six months from now* — which
/// is a claim about time. A list where every rule looks equally fresh has to be re-read whole; one
/// that carries dates can be triaged by age, and the oldest rules are the ones whose author has
/// most likely left. It costs nothing: same row, `NOT NULL`, already written. Note for whoever
/// draws it — this is when the prefix was FIRST declared and NOT when it was last edited, because
/// `declare_shell_rule`'s `DO UPDATE` deliberately leaves the column alone; labelling it "last
/// changed" would be a caption the daemon never agreed to.
#[derive(serde::Serialize)]
struct ShellRuleView {
    prefix: String,
    /// Which tool this rule governs the writes of, or `null` for a rule about a COMMAND prefix.
    ///
    /// **Serialised on every row, `null` included, and that is not a formality.** The two kinds of
    /// rule live in one list and a prefix alone cannot tell them apart: `deny migrations` is a
    /// command nobody may run, `deny Edit migrations` is a directory nothing may write into, and
    /// served without this field the second reads on screen as the first. That was true for exactly
    /// one chunk — `0131` gave the column to the table and to the classifier, and no route could
    /// write it — and it stops being true here, where the POST below learns to carry a tool.
    ///
    /// `null` and never `""`, for `DeclaredShellRule::tool`'s reason: the empty string is SQLite's
    /// business, forced by a UNIQUE index that treats every NULL as distinct, and a page made to
    /// compare against a magic empty string would get it wrong once.
    tool: Option<String>,
    verdict: crate::project_policy::Verdict,
    /// `null` for a rule declared with no justification — an absent note and not an absent field,
    /// so a page can tell "nobody said why" from a shape it failed to parse.
    note: Option<String>,
    created_at: String,
}

/// What this project's worktrees may run without asking, and what they may never run.
///
/// Ordered by tool and then by prefix, which is `declared_shell_rules`' `ORDER BY` and not this
/// handler's arithmetic — the verdict and the tool are on every row, so any grouping a page wants
/// is a filter it can do itself. Nothing is filtered out here either: a write rule and a command
/// rule come back in one list, because the route serves ROWS and the screen decides how to show
/// them. That is the argument `ShellRuleView` already makes about the allow/deny split, and the
/// tool is that same argument one field over.
async fn get_project_shell_rules(
    State(state): State<AppState>,
    Path(id): Path<String>,
) -> Result<Json<Vec<ShellRuleView>>, StatusCode> {
    crate::project_policy::declared_shell_rules(&state.pool, &id)
        .await
        .map(|rules| {
            Json(
                rules
                    .into_iter()
                    .map(|rule| ShellRuleView {
                        prefix: rule.prefix,
                        tool: rule.tool,
                        verdict: rule.verdict,
                        note: rule.note,
                        created_at: rule.created_at,
                    })
                    .collect(),
            )
        })
        .map_err(|error| {
            tracing::warn!(%error, project_id = %id, "reading a project's shell rules failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })
}

/// `deny_unknown_fields` on this and its three siblings, for `config.rs`'s reason rather than for
/// tidiness: a misspelled field would otherwise be dropped in silence. Here that is not a cosmetic
/// loss — `note` is the field most likely to be typed wrong, and `declare_shell_rule` overwrites
/// the stored note with whatever arrives, so `"notes"` for `"note"` currently answers 204 and
/// erases the justification the rule already carried.
#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct ShellRuleDeclaration {
    prefix: String,
    /// The tool whose writes this rule is about, or absent for a rule about a command prefix.
    ///
    /// **`#[serde(default)]` because every client that existed before this field sent none**, and a
    /// body without it is a shell rule — which is what those clients meant and what the route did.
    /// It has to be DECLARED all the same, and not merely tolerated: this struct carries
    /// `deny_unknown_fields`, so until the field exists here a client sending `"tool": "Edit"` is
    /// answered 422 by serde with a sentence about an unknown field, which reads as a malformed
    /// request rather than as a route that has not learned the word yet.
    ///
    /// Which values are admissible is decided in the handler and not by a type, because the answer
    /// is the migration's `CHECK (tool IN ('', 'Edit', 'Write'))` and a refusal that names the
    /// offending value is worth more here than an enum's parse error — see `unknown_tool`.
    #[serde(default)]
    tool: Option<String>,
    verdict: crate::project_policy::Verdict,
    /// Why, for whoever reads the list next. Never consulted by the classifier.
    #[serde(default)]
    note: Option<String>,
}

/// Declares one shell rule, or changes the verdict of one already declared.
///
/// **Idempotent, and not by this handler's arithmetic.** `declare_shell_rule`'s
/// `ON CONFLICT (project_id, tool, prefix) DO UPDATE SET verdict = excluded.verdict, note =
/// excluded.note` is what makes a second POST of the same rule an EDIT. The identity of a rule is
/// the TOOL and the prefix together and the unique index enforces that triple, so a redeclaration
/// can never become a second row — while `deny migrations` and `deny Edit migrations` are two rules
/// that may both stand, because they are two claims about two different things. The
/// two ways of losing the `DO UPDATE` cost something else instead: no `ON CONFLICT` clause at all is
/// `UNIQUE constraint failed` and a 500, and `DO NOTHING` — the spelling its two siblings in
/// `project_policy` use — is worse for being silent, leaving the first verdict standing while the
/// caller is told 204. `a_declared_shell_rule_comes_back_folded_and_then_goes` pins the edit through
/// this route; `project_policy::tests::declaring_the_same_prefix_again_changes_its_verdict` pins it
/// one layer down.
///
/// **`note = excluded.note` is the half a caller has to know about.** The clause is a plain
/// overwrite and not a `COALESCE`, deliberately: `declare_shell_rule` says "this rule is now in this
/// state", and a note that fell back to the stored one could never be REMOVED. The consequence this
/// route is the first thing to expose is that **a second POST carrying no `note` writes `NULL` over
/// an existing one** — so an editor that sends only `prefix` and `verdict` silently discards the
/// justification. Migration `0128` calls that column "a única defesa contra uma lista que daqui a
/// seis meses ninguém sabe justificar"; whoever builds the page in a later chunk must send the
/// existing note back with the verdict, or changing a verdict throws that defence away.
///
/// **The shape guard is asked of an `allow` and never of a `deny`, and the asymmetry is the whole
/// correctness of this route.** `classify_segment` reads `shell_form_is_readable(&normalized) &&
/// rules.allows(&normalized)`, so an `allow` of a shape that guard refuses could never fire, and
/// storing one would leave the owner holding a permission that does nothing. Nothing of the kind is
/// true of a `deny`: `classify_shell_command` consults `rules.denies` at the LINE level, above the
/// segment loop and with no shape guard over it, so a project can and does refuse `tail -f`,
/// `sort -o`, `find . -exec` and `curl … | sh` — precisely the shapes that otherwise reach
/// `pending_approval`, and precisely the ones a project would most want to close. Guarding the deny
/// side would refuse to store the refusals most worth writing down, and tell the owner they would
/// never be enforced while the engine went on enforcing them. Migration `0128` says the same in one
/// line: "Do lado `deny` não há nada a validar — uma recusa a mais nunca deixou correr nada."
///
/// **A write rule can only DENY, and this route is the third place that says so and the only one a
/// person meets.** The other two are silent by construction: `classifier::classify` has no allow
/// branch anywhere on a write path — "there is no `allow` counterpart here, and there must not be
/// one" — and `project_policy::shell_rules` drops a tool-carrying `allow` on its way out of the
/// table, with a `tracing::warn!` nobody standing at a screen will ever read. An owner who wrote
/// one would be holding a permission that decides nothing, believing it decides something. So an
/// `allow` that names a tool is refused at the door with `unenforceable_allow`, and the sentence
/// says what a `deny` of the same path WOULD do — the same move `unmatchable_prefix` makes one
/// paragraph up, for the same reason: a permission that is silently not one is worse than a refusal
/// somebody can act on.
///
/// The refusals name the offending value, because a refusal that does not say what was wrong sends
/// the owner to read source code to find out which of seven shape guards they tripped.
async fn post_project_shell_rule(
    State(state): State<AppState>,
    Path(id): Path<String>,
    Json(body): Json<ShellRuleDeclaration>,
) -> Result<StatusCode, (StatusCode, Json<serde_json::Value>)> {
    // The stop first, following `post_project_command_run`: it is the one refusal that is about the
    // machine rather than about this request. Asked only for an `allow`, which is the only verdict
    // here that widens — see `declaration_halted`.
    if body.verdict == crate::project_policy::Verdict::Allow {
        declaration_halted(&state, &id).await?;
    }
    project_is_on_the_roster(&state, &id).await?;

    // **Emptiness is two questions since the `tool` column existed, and this is the first.**
    //
    // What follows asks whether anything ARRIVED, and until there were write rules that was the
    // whole guard — correctly, because there was one fold and it cannot do this. A command prefix
    // goes through `project_policy::fold_prefix`, which is `classifier::normalize_command`: it
    // collapses whitespace and lower-cases, so it can shorten a string and never empty one that
    // survived `trim()`. A PATH prefix goes through `fold_path_prefix` instead, which rewrites `\`
    // as `/` and only THEN strips the trailing `/` — so `"/"`, `"\\"` and `"///"` arrive non-empty,
    // pass this check, and come out of that fold as the empty string. The second question — does
    // it survive the fold — therefore lives in the `Some(tool)` arm below, beside the fold that is
    // able to answer it no.
    let prefix = body.prefix.trim();
    within_length("prefix", prefix)?;
    if prefix.is_empty() {
        return Err((
            StatusCode::UNPROCESSABLE_ENTITY,
            Json(serde_json::json!({
                "refusal": "empty_prefix",
                "detail": "a shell rule has to name a prefix",
            })),
        ));
    }

    // Which tool's writes this rule is about, or `None` for a rule about a command prefix — which
    // is every rule anybody could declare before this handler learned the word.
    //
    // Refused BY NAME here rather than left to the table, exactly as `empty_prefix` above stands in
    // front of the column's `prefix <> ''`: `tool` is stored under a closed `CHECK`, and a value
    // the CHECK would reject must never reach the CHECK, because a constraint failure comes back
    // through the `internal` arm below as a 500 that names nothing.
    //
    // **Asked of `classifier::WRITE_TOOLS` rather than spelled again here.** This guard carried
    // its own `["Edit", "Write"]` until 2026-09-08, which is two lists for one fact, and the day
    // the classifier admitted `NotebookEdit` this door would have gone on refusing a rule the
    // write chain had just learned to enforce — a refusal nobody could have debugged from the
    // message, since the message was quoting the wrong list with complete confidence.
    //
    // The column's CHECK is still a second copy and cannot be anything else: SQL cannot read a
    // Rust const. `0138` is the migration that widened it, and the two are kept in step by the
    // test below that sends every name on this list at the real table.
    let tool = body.tool.as_deref();
    if let Some(tool) = tool
        && !crate::classifier::WRITE_TOOLS.contains(&tool)
    {
        let governed = crate::classifier::WRITE_TOOLS
            .iter()
            .map(|name| format!("`{name}`"))
            .collect::<Vec<_>>()
            .join(", ");
        return Err((
            StatusCode::UNPROCESSABLE_ENTITY,
            Json(serde_json::json!({
                "refusal": "unknown_tool",
                "detail": format!(
                    "`{tool}` is not a tool whose writes this núcleo governs: only {governed} \
                     reach the write chain in `classifier::classify`, so a rule about anything \
                     else would be stored and never consulted. Send no tool at all for a rule \
                     about a COMMAND prefix."
                ),
            })),
        ));
    }

    // The shape a prefix has to be in, and WHICH question that is depends on what kind of prefix
    // this is. Written as a match on the tool rather than as two conditions in a row, because the
    // two guards are mutually exclusive as a matter of MEANING and not of ordering: a path is not a
    // shell line, and running one through `shell_form_is_readable` would refuse ordinary directory
    // names for looking like flags and redirections.
    match tool {
        // See the doc above for why this is inside the `Allow` arm and must stay there.
        None => {
            if body.verdict == crate::project_policy::Verdict::Allow
                && !crate::classifier::shell_form_is_readable(prefix)
            {
                return Err((
                    StatusCode::UNPROCESSABLE_ENTITY,
                    Json(serde_json::json!({
                        "refusal": "unmatchable_prefix",
                        "detail": format!(
                            "`{prefix}` can never be allowed: `classify_segment` guards \
                             `rules.allows` with the same shape check this just failed, so the \
                             permission would be stored and never fire. Declared as a `deny` it \
                             would be enforced."
                        ),
                    })),
                ));
            }
        }
        Some(tool) => {
            // The rule this whole chunk is built around, refused where somebody can read it. The
            // doc above names the two silent places that already enforce it.
            if body.verdict == crate::project_policy::Verdict::Allow {
                return Err((
                    StatusCode::UNPROCESSABLE_ENTITY,
                    Json(serde_json::json!({
                        "refusal": "unenforceable_allow",
                        "detail": format!(
                            "a rule about a tool can only REFUSE. `{tool}` allowed to write to \
                             `{prefix}` would be stored and decide nothing: the write chain in \
                             `classifier::classify` ends at `read-local`, so there is no allow \
                             side for it to reach, and `project_policy::shell_rules` drops such a \
                             row on the way back out of the table. Declared as a `deny` the same \
                             path WOULD be enforced — `{tool}` would be refused at it and at \
                             everything under it."
                        ),
                    })),
                ));
            }
            // The second half of `empty_prefix`, and it is here because only this fold can reach
            // it. `fold_path_prefix` writes `\` as `/` and then strips the trailing `/`, so a
            // prefix of nothing but separators — `/`, `//`, `\`, `\\`, `///` — survives the trim
            // check above and lands on the column's `prefix CHECK (prefix <> '')` as the empty
            // string. A CHECK failure comes back through the `internal` arm below as a 500 that
            // names nothing, which is precisely what the guard above promises cannot happen: a
            // value the CHECK would reject must never reach the CHECK.
            //
            // Asked by CALLING the fold, not by restating what it does. A condition written to
            // match a fold is a second source of truth that stops matching in silence the day the
            // fold learns to strip something else, and what it lets back through is this same
            // nameless 500. `fold_for` is `pub(crate)` for exactly that reason: one function
            // answers what gets stored, and every guard about what gets stored asks that function.
            if crate::project_policy::fold_for(Some(tool), prefix).is_empty() {
                return Err((
                    StatusCode::UNPROCESSABLE_ENTITY,
                    Json(serde_json::json!({
                        "refusal": "empty_prefix",
                        "detail": format!(
                            "`{prefix}` names no path: a path prefix is stored with `\\` written \
                             as `/` and the trailing `/` dropped, so a prefix of nothing but \
                             separators folds to the empty string and there is no rule left to \
                             enforce. Write the path out, relative to the project root — there is \
                             no prefix that means the whole worktree."
                        ),
                    })),
                ));
            }
            // The three characters `classifier::lands_inside_the_workspace` refuses in a `cd` or
            // `mkdir` target, refused here for the same reason and against the same code. Nothing
            // expands them on the way to a comparison: `write_denied_by_project` puts the stored
            // prefix through `normalize_path`, which GLUES an ordinary-looking `~`, `$HOME` or
            // `%USERPROFILE%` onto the workspace — so `~/notes` would be stored as a refusal of
            // `<workspace>/~/notes`, a directory no write can ever land in. A refusal that cannot
            // match is an allow, which is why this is a 422 and not a warning.
            if prefix.starts_with('~') || prefix.contains('$') || prefix.contains('%') {
                return Err((
                    StatusCode::UNPROCESSABLE_ENTITY,
                    Json(serde_json::json!({
                        "refusal": "unmatchable_prefix",
                        "detail": format!(
                            "`{prefix}` can never match a write: a leading `~`, a `$` or a `%` \
                             arrives UNEXPANDED, and `normalize_path` joins it onto the workspace \
                             as an ordinary name — so the refusal would be about a directory that \
                             cannot exist, and a refusal that cannot match is an allow. Write the \
                             path out, relative to the project root."
                        ),
                    })),
                ));
            }
        }
    }

    // A note of nothing but whitespace is NO note, and it is folded to `NULL` here rather than
    // stored. The column exists to be "the only defence against a list nobody can justify in six
    // months", and an empty string is not a justification — it is the same absence spelled a second
    // way, which would leave two rows that mean one thing and a reader unable to tell "nobody wrote
    // one" from "somebody wrote nothing". The page renders `null` as "no justification" and an empty
    // string as a blank space, so the two are already visibly different for no reason.
    let note = body
        .note
        .as_deref()
        .map(str::trim)
        .filter(|note| !note.is_empty());

    // The tool goes down as it arrived — `None` is a shell rule and `Some` is a write rule, and
    // `declare_shell_rule` folds the prefix by whichever of the two folds that answer picks.
    crate::project_policy::declare_shell_rule(&state.pool, &id, tool, prefix, body.verdict, note)
        .await
        .map_err(|error| {
            tracing::warn!(%error, project_id = %id, "declaring a project shell rule failed");
            refusal(StatusCode::INTERNAL_SERVER_ERROR, "internal")
        })?;

    Ok(StatusCode::NO_CONTENT)
}

/// Which rule to withdraw, and it takes TWO fields for a reason worth stating.
///
/// **A prefix alone no longer names a row.** The unique index is `(project_id, tool, prefix)`, so a
/// project may hold `deny migrations` — a command — and `deny Edit migrations` — a directory — at
/// once, and they are two rules. A DELETE that carried only the prefix would have to pick one of
/// them, and whichever it picked would be right half the time; `forget_shell_rule`'s `WHERE` names
/// the triple, so the tool has to arrive for the statement to be able to name the row.
///
/// **Absent means the SHELL rule, and that is the answer that keeps the old clients honest.** Every
/// DELETE written before this field existed meant a command prefix, because a command prefix was
/// the only thing that could be declared. `#[serde(default)]` makes that reading the default one,
/// rather than "whichever row sorts first" — which is a delete that lands on a rule nobody named.
#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct ShellRuleTarget {
    prefix: String,
    /// The tool whose rule to withdraw, or absent for the rule about a command prefix.
    #[serde(default)]
    tool: Option<String>,
}

/// Withdraws one shell rule.
///
/// **404 when nothing matched, and the answer comes from the DELETE itself.** `forget_shell_rule`
/// returns `Ok(false)` off `rows_affected`, which is `project_commands::remove`'s shape one section
/// up. Asking a reader first and then deleting would be two queries answering about two moments,
/// and — worse — the presence check would have had to fold the prefix itself, which is a second
/// spelling of the key `project_policy::fold_prefix` exists to be the only one of.
///
/// **No shape guard and no kill switch.** A rule stored before either existed still has to be
/// withdrawable, and an emergency stop must never stand between somebody and narrowing what their
/// project may do. That covers the tool as well: `unknown_tool` guards the POST because a value
/// outside the CHECK cannot be STORED, while here an unknown tool simply matches no row and earns
/// the 404 it deserves — refusing it by name would put a shape guard in front of a withdrawal, and
/// the one row it could keep somebody from removing is a row written before the guard existed.
async fn delete_project_shell_rule(
    State(state): State<AppState>,
    Path(id): Path<String>,
    Json(body): Json<ShellRuleTarget>,
) -> Result<StatusCode, (StatusCode, Json<serde_json::Value>)> {
    project_is_on_the_roster(&state, &id).await?;

    let prefix = body.prefix.trim();
    within_length("prefix", prefix)?;
    if prefix.is_empty() {
        return Err((
            StatusCode::UNPROCESSABLE_ENTITY,
            Json(serde_json::json!({
                "refusal": "empty_prefix",
                "detail": "a shell rule has to name a prefix",
            })),
        ));
    }

    let tool = body.tool.as_deref();
    let forgotten = crate::project_policy::forget_shell_rule(&state.pool, &id, tool, prefix)
        .await
        .map_err(|error| {
            tracing::warn!(%error, project_id = %id, "forgetting a project shell rule failed");
            refusal(StatusCode::INTERNAL_SERVER_ERROR, "internal")
        })?;
    if !forgotten {
        // **The sentence names the tool as well as the prefix**, because with two rules able to
        // share a prefix "there is no rule for `migrations`" is a claim that can be false on the
        // very screen it is read on: the other one is still listed, and "I deleted it and it is
        // still there" has no answer without the missing word.
        //
        // The COMMAND half names the folded spelling — the answer somebody who typed the wrong case
        // needs — through `normalize_command`, which is the function `project_policy::fold_prefix`
        // wraps and therefore not a second spelling of the fold. The write half deliberately echoes
        // what was sent instead: `fold_path_prefix` is private to `project_policy`, and restating
        // its three steps here to decorate a 404 would be exactly the second spelling of a key that
        // module exists to prevent. It keeps its case either way, which is the part of a path
        // somebody could get wrong and needs to see.
        let detail = match tool {
            None => format!(
                "{id} has declared no rule for `{}`",
                crate::classifier::normalize_command(prefix)
            ),
            Some(tool) => format!("{id} has declared no `{tool}` rule for `{prefix}`"),
        };
        return Err((
            StatusCode::NOT_FOUND,
            Json(serde_json::json!({ "refusal": "no_such_rule", "detail": detail })),
        ));
    }

    Ok(StatusCode::NO_CONTENT)
}

/// Every operation kind a project may declare: the ops this núcleo can actually build, narrowed to
/// what the two compiled ceilings admit.
///
/// **The derivation lives in `github.rs` and this is its name here**, because the WRITE side is no
/// longer its only reader: `Policy::for_project` narrows a project's stored rows against the same
/// set at decision time, for the rows this route never saw — one written before a ceiling moved, or
/// written out of band. Two spellings of that set is how the two sides would come to disagree about
/// which is which, and the disagreement would be silent in the direction that grants.
///
/// Two consequences worth stating here, because both look like bugs at this route and are not:
///
/// - **`api_read` is refused.** It is deliberately outside `ACTION_CEILING` — not even
///   `~/.nucleos/github.yaml` can turn it on — so it is outside this too. A project able to declare it
///   would be a way round the ceiling wearing a different route.
/// - **`run_logs` is refused, and it is a `ReadOp` whose prefix the ceiling admits.** Its argv
///   carries `--log`, which is in `REFUSED_READ_FLAGS`; `declarable_read_ops` says why in full.
///
/// `workflow_list` used to be a third: in `READ_CEILING` and undeclarable, because no `ReadOp` built
/// it. `ReadOp::WorkflowList` made it declarable with nothing here edited, which is what "derived,
/// never written out" was supposed to buy.
fn declarable_github_ops() -> Vec<&'static str> {
    crate::github::declarable_ops()
}

/// One GitHub operation this núcleo can build, and where it stands against the ceilings.
///
/// **Every operation with a flag, and not the admitted names alone.** Two lists of strings, or one
/// list of the declarable, would have fixed a picker and left the other half unsayable — and the
/// half that cannot be said is the one that matters. `api_read` is outside `ACTION_CEILING`: no
/// route, no `~/.nucleos/github.yaml` and no owner can turn it on. A page that only knew the admitted names
/// would either omit it, which quietly claims this núcleo cannot do it at all, or draw a control for
/// it — and a checkbox that cannot be switched on is a lie about who decides. `declarable: false` is
/// how an operation gets drawn as a FACT: it exists, it is refused here, and nothing on this screen
/// is the thing that would change that.
///
/// Rows for `ShellRuleView`'s reason, restated because the two shapes landed together: a row that
/// travels alone keeps its facts, and a name lifted out of a `declarable` list into a form has
/// already forgotten which list it came from.
#[derive(serde::Serialize)]
struct DeclarableOpView {
    kind: &'static str,
    half: &'static str,
    declarable: bool,
}

/// Every GitHub operation kind, and whether a project may declare it.
///
/// **The route exists because this set had one way out and it was a refusal.** `post_project_github_op`
/// validates against `declarable_github_ops`, and until now the only place that set reached the wire
/// was inside `undeclarable_op`'s `detail` — so a caller building a picker had to hardcode the list,
/// which drifts from the ceilings in silence, or discover it by POSTing something invalid. Neither
/// is a way to read a constant.
///
/// No project id and no roster check, because there is nothing project-shaped to check: the answer
/// is compiled in. It cannot fail, which is why it returns `Json` and not `Result` — the one route
/// in this family with no database under it.
async fn get_declarable_github_ops() -> Json<Vec<DeclarableOpView>> {
    Json(
        crate::github::every_op()
            .into_iter()
            .map(|standing| DeclarableOpView {
                kind: standing.kind,
                half: standing.half,
                declarable: standing.declarable,
            })
            .collect(),
    )
}

/// What the GitHub manager may do on this project's remote without asking.
///
/// `try_github_ops` and not `github_ops`: this is a DISPLAY, and to a page whose job is showing the
/// owner what their project may do, `[]` is a positive claim that nothing is declared rather than
/// an absence of information. The swallowing reader is right for the classifier's path and wrong
/// here — see its own doc.
async fn get_project_github_ops(
    State(state): State<AppState>,
    Path(id): Path<String>,
) -> Result<Json<Vec<String>>, StatusCode> {
    crate::project_policy::try_github_ops(&state.pool, &id)
        .await
        .map(Json)
        .map_err(|error| {
            tracing::warn!(%error, project_id = %id, "reading a project's github ops failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })
}

/// Which repository on GitHub this project is.
///
/// **The fact the typed reads were missing.** Every `ReadOp` carries a `Repo`, and `Repo::new` was
/// reachable only from `ReadOp::from_request` — so the repository was always something the CALLER
/// named, and nothing in this daemon could answer it for a project on the roster. A page that wanted
/// to show a project's open pull requests had either to invent the mapping itself out of
/// `GET /projects/detect` and a URL parse, or to show nothing. `github::project_repo` is that answer,
/// and this is the door onto it.
///
/// **A 200 for every state but a project nobody has heard of.** A project with no folder, a folder
/// that has moved, a folder git does not know, a repository with no `origin` and a remote that is
/// not GitHub's are five ordinary states and not five failures — §5.1 asks this page to EXPLAIN
/// rather than go blank, and it can only do that if the five arrive distinguishable. Collapsing them
/// into one refusal would leave the page saying "something is wrong" about a project whose only
/// peculiarity is being local-only.
async fn get_project_github_repo(
    State(state): State<AppState>,
    Path(id): Path<String>,
) -> Result<Json<crate::github::ProjectRepo>, StatusCode> {
    let deadline = std::time::Instant::now() + DETECT_GIT_BUDGET;
    match crate::github::project_repo(&state.pool, &id, deadline).await {
        Ok(Some(found)) => Ok(Json(found)),
        Ok(None) => Err(StatusCode::NOT_FOUND),
        Err(error) => {
            tracing::warn!(%error, project_id = %id, "resolving a project's repository failed");
            Err(StatusCode::INTERNAL_SERVER_ERROR)
        }
    }
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct GithubOpTarget {
    op_kind: String,
}

/// Refuses a blank op kind before anything else can name it.
///
/// Its own refusal rather than falling through to `undeclarable_op`, whose message would name the
/// empty string — from the one route family whose stated rule is that a refusal must say what was
/// wrong with what it was given.
fn named_op_kind(op_kind: &str) -> Result<(), (StatusCode, Json<serde_json::Value>)> {
    if op_kind.is_empty() {
        return Err((
            StatusCode::UNPROCESSABLE_ENTITY,
            Json(serde_json::json!({
                "refusal": "empty_op_kind",
                "detail": "a github declaration has to name an operation",
            })),
        ));
    }
    Ok(())
}

/// Grants one GitHub operation to this project without asking.
///
/// **Idempotent, and not by this handler's arithmetic.** `declare_github_op`'s
/// `ON CONFLICT (project_id, op_kind) DO NOTHING` is what makes a second POST leave the first row
/// and its `created_at` alone, rather than raising `UNIQUE constraint failed`;
/// `github_ops_and_land_targets_round_trip_and_forget` declares `run_list` twice to pin it.
///
/// Gated by the emergency stop, because every operation declarable here is one an autonomous run
/// performs without asking — this POST widens, immediately, exactly as an `allow` does. See
/// `declaration_halted`.
///
/// The refusal names the kind AND lists what would have been accepted, because "not a declarable
/// operation" without the set is a sentence that sends the owner to `github.rs`.
///
/// **A declared ACTION is recorded and inert today, and this route accepts it anyway.** The reading
/// half reaches the classifier through `Policy::for_project`; the acting half is only ever consulted
/// by `github::submit`, which reads the machine default because `POST /github/requests` carries no
/// project to look one up by. So `pr_create` here returns 204, is stored, and changes no verdict
/// until the typed door learns which project it is acting for — `Policy::for_project` carries the
/// reasoning and the reason it was not taken here. Inert is the safe direction, which is why this
/// route does not refuse it; what it costs is an owner reading a list of grants that includes one
/// they did not get, so the page has to SAY so beside it rather than showing the two alike.
async fn post_project_github_op(
    State(state): State<AppState>,
    Path(id): Path<String>,
    Json(body): Json<GithubOpTarget>,
) -> Result<StatusCode, (StatusCode, Json<serde_json::Value>)> {
    declaration_halted(&state, &id).await?;
    project_is_on_the_roster(&state, &id).await?;

    let op_kind = body.op_kind.trim();
    within_length("op kind", op_kind)?;
    named_op_kind(op_kind)?;

    let declarable = declarable_github_ops();
    if !declarable.contains(&op_kind) {
        return Err((
            StatusCode::UNPROCESSABLE_ENTITY,
            Json(serde_json::json!({
                "refusal": "undeclarable_op",
                "detail": format!(
                    "`{op_kind}` is not an operation a project may declare; the ceilings admit: {}",
                    declarable.join(", ")
                ),
            })),
        ));
    }

    crate::project_policy::declare_github_op(&state.pool, &id, op_kind)
        .await
        .map_err(|error| {
            tracing::warn!(%error, project_id = %id, "declaring a project github op failed");
            refusal(StatusCode::INTERNAL_SERVER_ERROR, "internal")
        })?;

    Ok(StatusCode::NO_CONTENT)
}

/// Withdraws one GitHub operation. 404 when it was never declared, off the DELETE's own
/// `rows_affected` — for `delete_project_shell_rule`'s reason, and here that is not merely tidier.
/// A presence check through `github_ops` would read an unreadable table as an empty list and tell
/// the owner by name that an operation was never declared, while the row stands and the operation
/// goes on running unattended. That is this route's own stated failure mode arriving through a 404
/// instead of a 204.
///
/// No kill switch, and no declarability check: withdrawing narrows, and an operation stored before
/// the ceilings moved still has to be removable.
async fn delete_project_github_op(
    State(state): State<AppState>,
    Path(id): Path<String>,
    Json(body): Json<GithubOpTarget>,
) -> Result<StatusCode, (StatusCode, Json<serde_json::Value>)> {
    project_is_on_the_roster(&state, &id).await?;

    let op_kind = body.op_kind.trim();
    within_length("op kind", op_kind)?;
    named_op_kind(op_kind)?;

    let forgotten = crate::project_policy::forget_github_op(&state.pool, &id, op_kind)
        .await
        .map_err(|error| {
            tracing::warn!(%error, project_id = %id, "forgetting a project github op failed");
            refusal(StatusCode::INTERNAL_SERVER_ERROR, "internal")
        })?;
    if !forgotten {
        return Err((
            StatusCode::NOT_FOUND,
            Json(serde_json::json!({
                "refusal": "no_such_op",
                "detail": format!("{id} has not declared `{op_kind}`"),
            })),
        ));
    }

    Ok(StatusCode::NO_CONTENT)
}

/// Every operation the shared git queue performs, and whether a project may declare it.
///
/// **The git twin of `get_declarable_github_ops`, and simpler by exactly the gap `vcs::DeclarableGitOp`'s
/// own doc names.** The GitHub catalogue has to serve operations the ceilings refuse, so a caller can
/// draw them as facts rather than as controls; the git queue has no ceiling narrower than
/// `GIT_OP_KINDS` to intersect, so `declarable_git_ops` returns everything it performs and every row
/// comes back `declarable: true`. Nothing here computes a `half` either — every operation in this
/// family is a write the queue performs the same way, never a read in force.
///
/// No project id, for the reason the route comment gives: the answer is compiled into `GIT_OP_KINDS`
/// and is the same for every project on the roster.
async fn get_declarable_git_ops() -> Json<Vec<vcs::DeclarableGitOp>> {
    Json(vcs::declarable_git_ops())
}

/// What the shared git queue may do on this project's repository, for an autonomous run, without
/// asking.
///
/// `try_git_ops` and not `git_ops`, for `get_project_github_ops`'s reason: this is a DISPLAY, and
/// `[]` has to mean "nothing declared" rather than stand in for a read that failed.
async fn get_project_git_ops(
    State(state): State<AppState>,
    Path(id): Path<String>,
) -> Result<Json<Vec<String>>, StatusCode> {
    crate::project_policy::try_git_ops(&state.pool, &id)
        .await
        .map(Json)
        .map_err(|error| {
            tracing::warn!(%error, project_id = %id, "reading a project's git ops failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct GitOpTarget {
    op_kind: String,
}

/// Refuses a blank op kind before anything else can name it — `named_op_kind`'s own reason, worded
/// for this family instead of GitHub's: reusing that message verbatim would tell somebody declaring
/// a git operation that their GitHub declaration was malformed.
fn named_git_op_kind(op_kind: &str) -> Result<(), (StatusCode, Json<serde_json::Value>)> {
    if op_kind.is_empty() {
        return Err((
            StatusCode::UNPROCESSABLE_ENTITY,
            Json(serde_json::json!({
                "refusal": "empty_op_kind",
                "detail": "a git declaration has to name an operation",
            })),
        ));
    }
    Ok(())
}

/// Grants one git operation to this project's autonomous runs without asking.
///
/// The git twin of `post_project_github_op`, and the checks run in the same order: the emergency
/// stop first, because this widens exactly as a GitHub `allow` does; then the roster; then the
/// length cap; then the blank-kind refusal; then the catalogue. Unlike its sibling there is no
/// inert-until-elsewhere caveat to record — `GIT_OP_KINDS` is exactly what the shared git queue
/// consults, with nothing standing between a declared row and the queue honouring it.
async fn post_project_git_op(
    State(state): State<AppState>,
    Path(id): Path<String>,
    Json(body): Json<GitOpTarget>,
) -> Result<StatusCode, (StatusCode, Json<serde_json::Value>)> {
    declaration_halted(&state, &id).await?;
    project_is_on_the_roster(&state, &id).await?;

    let op_kind = body.op_kind.trim();
    within_length("op kind", op_kind)?;
    named_git_op_kind(op_kind)?;

    if !vcs::GIT_OP_KINDS.contains(&op_kind) {
        return Err((
            StatusCode::UNPROCESSABLE_ENTITY,
            Json(serde_json::json!({
                "refusal": "undeclarable_op",
                "detail": format!(
                    "`{op_kind}` is not an operation a project may declare; the queue admits: {}",
                    vcs::GIT_OP_KINDS.join(", ")
                ),
            })),
        ));
    }

    crate::project_policy::declare_git_op(&state.pool, &id, op_kind)
        .await
        .map_err(|error| {
            tracing::warn!(%error, project_id = %id, "declaring a project git op failed");
            refusal(StatusCode::INTERNAL_SERVER_ERROR, "internal")
        })?;

    Ok(StatusCode::NO_CONTENT)
}

/// Withdraws one git operation. 404 when it was never declared, off the DELETE's own
/// `rows_affected` — `delete_project_github_op`'s reason, unchanged here: a presence check through
/// `git_ops` would read an unreadable table as an empty list and report a false 404 while the row,
/// and the operation, stand.
///
/// No kill switch: withdrawing narrows, and an operation declared before this route existed still
/// has to be removable.
async fn delete_project_git_op(
    State(state): State<AppState>,
    Path(id): Path<String>,
    Json(body): Json<GitOpTarget>,
) -> Result<StatusCode, (StatusCode, Json<serde_json::Value>)> {
    project_is_on_the_roster(&state, &id).await?;

    let op_kind = body.op_kind.trim();
    within_length("op kind", op_kind)?;
    named_git_op_kind(op_kind)?;

    let forgotten = crate::project_policy::forget_git_op(&state.pool, &id, op_kind)
        .await
        .map_err(|error| {
            tracing::warn!(%error, project_id = %id, "forgetting a project git op failed");
            refusal(StatusCode::INTERNAL_SERVER_ERROR, "internal")
        })?;
    if !forgotten {
        return Err((
            StatusCode::NOT_FOUND,
            Json(serde_json::json!({
                "refusal": "no_such_op",
                "detail": format!("{id} has not declared `{op_kind}`"),
            })),
        ));
    }

    Ok(StatusCode::NO_CONTENT)
}

/// Everywhere a `--land` may be sent in this project: the integration branch, and the extra targets.
///
/// **Both halves or neither, because half of this answer is a trap.** The extra targets used to be
/// served alone, and the page filled the other half in from `GET /projects/{id}/branches` —
/// `inspect::Branches::integration`, which is `current_branch(project_root)`. Its own doc says what
/// that costs: it is *"a heuristic for this panel"* kept from before `land.rs` existed, and the
/// design that created `land.rs` killed that read *"precisely because a checkout parked on the wrong
/// branch silently redirected every landing"*. So a project whose clone sat on a feature branch had
/// the page name that branch and caption it admissible, while `land::resolve_target` refused it by
/// name and the branch that IS admissible appeared nowhere. Serving the pair from the one route that
/// owns "where a landing may be sent" is what stops the two halves being answered by two different
/// modules with two different definitions.
///
/// **`integration_branch_reading` and NOT `integration_branch`**, and the difference is a write. The
/// landing path records a derived default so that later landings read a column; doing that here
/// would let opening a page pin a project's integration branch to whatever `origin/HEAD` said at
/// that moment. Its own doc carries the argument.
///
/// `try_land_targets` for `get_project_github_ops`' reason: a display must not serve an empty list
/// out of a database error.
async fn get_project_land_targets(
    State(state): State<AppState>,
    Path(id): Path<String>,
) -> Result<Json<LandingView>, StatusCode> {
    let targets = crate::project_policy::try_land_targets(&state.pool, &id)
        .await
        .map_err(|error| {
            tracing::warn!(%error, project_id = %id, "reading a project's land targets failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })?;

    let deadline = std::time::Instant::now() + DETECT_GIT_BUDGET;
    let integration = crate::land::integration_branch_reading(&state.pool, &id, deadline)
        .await
        .map_err(|error| {
            tracing::warn!(%error, project_id = %id, "reading a project's integration branch failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })?;

    Ok(Json(LandingView {
        integration,
        targets,
    }))
}

/// Where this project's work lands: the default, and the alternatives it admits.
///
/// The two are not a list. The integration branch is admissible with no row at all — an empty table
/// means "only the usual place" and never "nowhere" — so folding it into `targets` would make it
/// indistinguishable from a declared row, which is the one thing on that panel that can be closed.
#[derive(Serialize)]
struct LandingView {
    integration: crate::land::IntegrationBranch,
    targets: Vec<String>,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct LandTargetTarget {
    branch: String,
}

/// Opens one more landing target for this project.
///
/// **A branch that does not exist yet is ACCEPTED, and that is deliberate — do not "fix" it.**
/// Existence is checked at the moment of landing, by `land::resolve_target`, which confirms
/// `refs/heads/<branch>` against the repository and refuses by name when it is gone. Declaring a
/// target before creating it is a reasonable order to work in — the branch is often made by the very
/// run that will land into it — and a check here would only be a second, staler copy of one that
/// already runs at the moment it can be right.
///
/// **The NAME, unlike its existence, is checked here.** `vcs::Branch::new` is pure, and
/// `resolve_target` already calls it before it asks git — its own comment says a name `Branch::new`
/// rejects "would otherwise be told it does not exist, which sends the caller looking for a missing
/// branch when the problem is the name". Asking it at declaration time means that sentence is read
/// by the person typing the name rather than by whoever is landing three weeks later. It is the
/// same "a rule stored that can never fire" the shell route refuses, in the one form available here.
///
/// **What that check is and is not.** `Branch::new` is `argv_safe`: it refuses an empty name, a
/// leading `-`, and whitespace or control characters — the properties that decide whether a name may
/// be handed to git as an argument. It is explicitly NOT a ref-name validator, and its own doc
/// refuses to be widened into one, so `..dots.lock` passes here and git rejects it at landing. That
/// residue is git's to own; `git check-ref-format` is the tool for it and is a subprocess, which is
/// the thing this route deliberately does not spawn.
///
/// Idempotent by `declare_land_target`'s `ON CONFLICT (project_id, branch) DO NOTHING`, like its
/// GitHub sibling above. Not gated by the emergency stop: a target binds nothing until a landing is
/// attempted, and a landing goes through the queue, which the stop governs at its own start point.
async fn post_project_land_target(
    State(state): State<AppState>,
    Path(id): Path<String>,
    Json(body): Json<LandTargetTarget>,
) -> Result<StatusCode, (StatusCode, Json<serde_json::Value>)> {
    project_is_on_the_roster(&state, &id).await?;

    let branch = body.branch.trim();
    within_length("branch", branch)?;
    // `Branch::new` refuses an empty name itself, and its message says so — one sentence for the
    // whole shape of a name rather than two that could disagree about the blank case.
    let branch = crate::vcs::Branch::new(branch).map_err(|why| {
        (
            StatusCode::UNPROCESSABLE_ENTITY,
            Json(serde_json::json!({
                "refusal": "unusable_branch",
                "detail": why,
            })),
        )
    })?;

    crate::project_policy::declare_land_target(&state.pool, &id, branch.as_str())
        .await
        .map_err(|error| {
            tracing::warn!(%error, project_id = %id, "declaring a project land target failed");
            refusal(StatusCode::INTERNAL_SERVER_ERROR, "internal")
        })?;

    Ok(StatusCode::NO_CONTENT)
}

/// Closes one landing target. 404 when it was never open, off the DELETE's own `rows_affected` —
/// for `delete_project_github_op`'s reason, including the unreadable-table half.
///
/// `integration_branch` needs no row to stay admissible, so a DELETE naming it answers 404 and takes
/// nothing away — which is the honest answer: there was no target of that name to close.
///
/// No `Branch::new` here, and no kill switch: a target stored before that check existed still has to
/// be closable, and closing one narrows.
async fn delete_project_land_target(
    State(state): State<AppState>,
    Path(id): Path<String>,
    Json(body): Json<LandTargetTarget>,
) -> Result<StatusCode, (StatusCode, Json<serde_json::Value>)> {
    project_is_on_the_roster(&state, &id).await?;

    let branch = body.branch.trim();
    within_length("branch", branch)?;
    if branch.is_empty() {
        return Err((
            StatusCode::UNPROCESSABLE_ENTITY,
            Json(serde_json::json!({
                "refusal": "empty_branch",
                "detail": "a landing target has to name a branch",
            })),
        ));
    }

    let forgotten = crate::project_policy::forget_land_target(&state.pool, &id, branch)
        .await
        .map_err(|error| {
            tracing::warn!(%error, project_id = %id, "forgetting a project land target failed");
            refusal(StatusCode::INTERNAL_SERVER_ERROR, "internal")
        })?;
    if !forgotten {
        return Err((
            StatusCode::NOT_FOUND,
            Json(serde_json::json!({
                "refusal": "no_such_target",
                "detail": format!("{id} has not declared `{branch}` as a landing target"),
            })),
        ));
    }

    Ok(StatusCode::NO_CONTENT)
}

/* ------------------------------------------------------------- workflows -- */

/// Where the library is on this machine, refused as one answer when there is nowhere for it to be.
///
/// A machine with no home directory has no library. `503` rather than `500`: nothing broke, the
/// answer simply does not exist here, and the page says so instead of showing an empty shelf that
/// reads as "you have installed nothing".
fn library_or_refusal(state: &AppState) -> Result<PathBuf, (StatusCode, Json<serde_json::Value>)> {
    state
        .workflow_library
        .clone()
        .ok_or_else(|| refusal(StatusCode::SERVICE_UNAVAILABLE, "no_library"))
}

/// Every bundle on this machine, whatever any project uses.
///
/// House-wide, under `/workflows` and not under a project, because that is what it is: one folder
/// shared by everything. A library route hanging off a project id would answer identically for
/// every project and teach the shell a relationship that does not exist.
async fn get_workflow_library(
    State(state): State<AppState>,
) -> Result<Json<Vec<crate::workflows::Bundle>>, (StatusCode, Json<serde_json::Value>)> {
    let root = library_or_refusal(&state)?;
    tokio::task::spawn_blocking(move || crate::workflows::library(&root))
        .await
        .map_err(|_| refusal(StatusCode::INTERNAL_SERVER_ERROR, "internal"))?
        .map(Json)
        .map_err(|error| {
            tracing::warn!(%error, "reading the workflow library failed");
            refusal(StatusCode::INTERNAL_SERVER_ERROR, "internal")
        })
}

/// What this project uses, measured against the library as it is right now.
///
/// The measurement is the point. A listing that only replayed the pins file would say `referenced`
/// for a bundle somebody has since edited, rewritten or deleted — which is the exact silence §6.1
/// asks this page to break.
async fn get_project_workflows(
    State(state): State<AppState>,
    Path(id): Path<String>,
) -> Result<Json<Vec<crate::workflows::Installed>>, (StatusCode, Json<serde_json::Value>)> {
    let root = resolve_project_root(&state, &id)
        .await
        .map_err(|status| refusal(status, "no_project_root"))?;
    let library = library_or_refusal(&state)?;
    let pins = pins_file(&state, &id)?;
    let shown = crate::project_state::display_path(&id, crate::project_state::PINS_FILE);
    tokio::task::spawn_blocking(move || crate::workflows::installed(&root, &pins, &library))
        .await
        .map_err(|_| refusal(StatusCode::INTERNAL_SERVER_ERROR, "internal"))?
        .map(Json)
        // The parser's own words, the same as `POST /write`'s `invalid`: a pins file that will not
        // load is a file somebody has to fix, and "unprocessable entity" does not say which line.
        // Prefixed with where the file is, because that is no longer the project's folder and the
        // page should not have to know where the daemon keeps it.
        .map_err(|detail| {
            (
                StatusCode::UNPROCESSABLE_ENTITY,
                Json(serde_json::json!({
                    "refusal": "unreadable_pins",
                    "detail": format!("{shown}: {detail}"),
                })),
            )
        })
}

#[derive(Deserialize)]
struct InstallRequest {
    name: String,
    version: String,
}

/// Turn a `workflows::Refused` into the status code that matches what it says.
fn workflow_status(refused: &crate::workflows::Refused) -> (StatusCode, &'static str) {
    match refused {
        crate::workflows::Refused::NoSuchBundle => (StatusCode::NOT_FOUND, "no_such_bundle"),
        crate::workflows::Refused::NotInstalled => (StatusCode::NOT_FOUND, "not_installed"),
        crate::workflows::Refused::BadName => (StatusCode::UNPROCESSABLE_ENTITY, "bad_name"),
        crate::workflows::Refused::AlreadyEjected => (StatusCode::CONFLICT, "already_ejected"),
        // 409 beside it, and its own name: both are "you already have a copy", and they differ in
        // where the copy came from — which decides what the page offers next.
        crate::workflows::Refused::Adopted => (StatusCode::CONFLICT, "adopted"),
        // 404 and not 422: the bundle is fine, it simply does not have a graph in it yet. A
        // "cannot process" would send somebody looking for a syntax error in a file that is not
        // there.
        crate::workflows::Refused::NoGraph => (StatusCode::NOT_FOUND, "no_graph"),
        crate::workflows::Refused::InvalidGraph(_) => {
            (StatusCode::UNPROCESSABLE_ENTITY, "invalid_graph")
        }
        crate::workflows::Refused::Io(_) => (StatusCode::INTERNAL_SERVER_ERROR, "internal"),
    }
}

fn workflow_refusal(refused: crate::workflows::Refused) -> (StatusCode, Json<serde_json::Value>) {
    let (status, name) = workflow_status(&refused);
    (
        status,
        Json(serde_json::json!({ "refusal": name, "detail": refused.to_string() })),
    )
}

/// Find one bundle in the library, or say which half is missing.
fn bundle_or_refusal(
    library: &std::path::Path,
    name: &str,
    version: Option<&str>,
) -> Result<crate::workflows::Bundle, crate::workflows::Refused> {
    if !crate::workflows::valid_name(name) {
        return Err(crate::workflows::Refused::BadName);
    }
    let shelf = crate::workflows::library(library)
        .map_err(|e| crate::workflows::Refused::Io(e.to_string()))?;
    let mut candidates: Vec<_> = shelf
        .into_iter()
        .filter(|bundle| bundle.name == name)
        .filter(|bundle| version.is_none_or(|wanted| bundle.version == wanted))
        .collect();
    // Newest last, so `None` for the version means "the latest there is" — which is what an update
    // asks for when the page offered it a version it read from this same listing.
    candidates.sort_by(|a, b| crate::workflows::compare_versions(&a.version, &b.version));
    candidates
        .pop()
        .ok_or(crate::workflows::Refused::NoSuchBundle)
}

/// This project's pins file, `~/.nucleos/projects/<id>/workflows.yaml`, or the refusal
/// [`project_state_dir`] gives for a project with no state directory.
fn pins_file(state: &AppState, id: &str) -> Result<PathBuf, (StatusCode, Json<serde_json::Value>)> {
    Ok(project_state_dir(state, id)?.join(crate::project_state::PINS_FILE))
}

/// Every route below writes this project's pins, so every one of them asks the same two questions
/// first, in the same order, for the reasons `POST /write` sets out at length.
///
/// **The kill switch first.** These write the project's `workflows.yaml`, and one of them copies a
/// whole bundle into `.ai/workflows/` — bytes in the project's folder, which §7.5 says must go the
/// way an agent's write goes. That is the line `POST /commands` sits on the other side of: that one
/// writes a database row and touches nothing on disk.
///
/// Answers the project root (where an ejected copy goes), the pins file (in the project's state
/// directory, never in the project) and the library.
async fn workflow_write_root(
    state: &AppState,
    id: &str,
) -> Result<(PathBuf, PathBuf, PathBuf), (StatusCode, Json<serde_json::Value>)> {
    let halted = crate::autopilot::kill_switch_engaged(&state.pool)
        .await
        .unwrap_or(true)
        || crate::autopilot::scoped_kill_engaged(&state.pool, "project", id)
            .await
            .unwrap_or(true);
    if halted {
        return Err(refusal(StatusCode::LOCKED, "kill_switch"));
    }
    let root = resolve_project_root(state, id)
        .await
        .map_err(|status| refusal(status, "no_project_root"))?;
    Ok((root, pins_file(state, id)?, library_or_refusal(state)?))
}

/// Pin a bundle to this project.
///
/// The version is required, unlike the update route below. Installing is choosing, and a request
/// that said only `harness` would silently mean something different next week — which is the
/// property a pin exists to remove.
async fn post_project_workflow(
    State(state): State<AppState>,
    Path(id): Path<String>,
    Json(body): Json<InstallRequest>,
) -> Result<StatusCode, (StatusCode, Json<serde_json::Value>)> {
    let (root, pins, library) = workflow_write_root(&state, &id).await?;
    let record = materialized_record(&state, &id)?;
    let project_id = id.clone();

    let (installed, placed) = tokio::task::spawn_blocking(move || {
        let bundle = bundle_or_refusal(&library, &body.name, Some(&body.version))?;
        crate::workflows::install(&pins, &bundle)?;
        let placed = materialize_after_pin(&root, &pins, &library, &record, &bundle.name);
        Ok::<_, crate::workflows::Refused>((bundle, placed))
    })
    .await
    .map_err(|_| refusal(StatusCode::INTERNAL_SERVER_ERROR, "internal"))?
    .map_err(workflow_refusal)?;

    workflow_feed(
        &state,
        &project_id,
        &format!(
            "{}@{} installed from the app{placed}",
            installed.name, installed.version
        ),
    )
    .await;
    Ok(StatusCode::NO_CONTENT)
}

/// This project's materialization record, `~/.nucleos/projects/<id>/materialized.yaml`.
fn materialized_record(
    state: &AppState,
    id: &str,
) -> Result<PathBuf, (StatusCode, Json<serde_json::Value>)> {
    Ok(project_state_dir(state, id)?.join(crate::project_state::MATERIALIZED_FILE))
}

/// Put a just-pinned workflow's files into the project, and say in a few words what happened.
///
/// **After the pin, and never undoing it.** The pin is the decision a person made; placing the
/// files is its consequence, and a file that could not be placed — or one left alone because it
/// was edited — is something to be told about, not a reason to take the decision back. The answer
/// is the tail of the feed line, and `GET .../materialize` shows the whole report.
fn materialize_after_pin(
    root: &std::path::Path,
    pins: &std::path::Path,
    library: &std::path::Path,
    record: &std::path::Path,
    name: &str,
) -> String {
    use crate::workflow_materialize as materialize;
    match materialize::sync(
        root,
        pins,
        library,
        record,
        Some(name),
        materialize::Mode::Apply,
    ) {
        Ok(outcomes) => outcomes
            .into_iter()
            .find_map(|outcome| match (outcome.report, outcome.error) {
                (_, Some(error)) => Some(format!("; its files could not all be placed: {error}")),
                (Some(report), None) if !report.is_empty() => {
                    Some(format!("; files — {}", report.summary()))
                }
                _ => None,
            })
            .unwrap_or_default(),
        Err(error) => {
            tracing::warn!(%error, workflow = name, "a workflow was pinned and its files were not placed");
            format!("; its files were not placed: {error}")
        }
    }
}

/// Stop using a workflow, and take back the files it placed in the project.
///
/// The pin goes first — a project that does not use `name` is refused before a file is touched —
/// and then `workflow_materialize::unmaterialize` removes every file the record says this workflow
/// wrote and that is still exactly what it wrote, the managed block in `AGENTS.md` included. An
/// edited or missing file stays and is named under `kept`; what went is under `removed`.
///
/// **Only the project's own root is cleaned.** A worktree synced from it keeps its copies and its
/// own record under `materialized/` until it is synced again or removed. Never deletes an ejected
/// copy — see `workflows::uninstall`. A cleanup that could not run (an unreadable record) does not
/// undo the decision: the pin stays gone, nothing is removed, and the answer carries `error`.
async fn delete_project_workflow(
    State(state): State<AppState>,
    Path((id, name)): Path<(String, String)>,
) -> Result<Json<serde_json::Value>, (StatusCode, Json<serde_json::Value>)> {
    let (root, pins, _) = workflow_write_root(&state, &id).await?;
    let record = materialized_record(&state, &id)?;
    let stopped = name.clone();

    let cleaned = tokio::task::spawn_blocking(move || {
        crate::workflows::uninstall(&pins, &name)?;
        Ok::<_, crate::workflows::Refused>(crate::workflow_materialize::unmaterialize(
            &root, &record, &name,
        ))
    })
    .await
    .map_err(|_| refusal(StatusCode::INTERNAL_SERVER_ERROR, "internal"))?
    .map_err(workflow_refusal)?;

    let (removal, error) = match cleaned {
        Ok(removal) => (removal, None),
        Err(error) => {
            tracing::warn!(%error, workflow = %stopped, "a workflow was stopped and its files were not removed");
            (Default::default(), Some(error))
        }
    };
    let tail = match (&error, removal.removed.len(), removal.kept.len()) {
        (Some(error), _, _) => format!("; its files were not removed: {error}"),
        (None, 0, 0) => String::new(),
        (None, removed, 0) => format!("; {removed} of its files removed"),
        (None, removed, kept) => {
            format!("; {removed} of its files removed, {kept} left in place")
        }
    };
    workflow_feed(
        &state,
        &id,
        &format!("{stopped} is no longer used here{tail}"),
    )
    .await;
    Ok(Json(serde_json::json!({
        "removed": removal.removed,
        "kept": removal.kept,
        "error": error,
    })))
}

/// Take a copy, and stop receiving updates.
///
/// The one route here that puts a whole tree in somebody's repository, so it is the one the
/// disclosure in §6.3 guards. It refuses rather than overwriting when a copy is already there: the
/// edits in it are the entire reason it exists.
async fn post_project_workflow_eject(
    State(state): State<AppState>,
    Path((id, name)): Path<(String, String)>,
) -> Result<StatusCode, (StatusCode, Json<serde_json::Value>)> {
    let (root, pins, library) = workflow_write_root(&state, &id).await?;
    let now = chrono::Utc::now();
    let ejected = name.clone();

    tokio::task::spawn_blocking(move || {
        // The pinned version and not the newest: ejecting is taking a copy of what this project
        // uses, and quietly taking a copy of something else would be an upgrade nobody asked for
        // performed at the one moment updates stop arriving.
        let pinned = crate::workflows::read_pins(&pins)
            .map_err(crate::workflows::Refused::Io)?
            .workflows
            .into_iter()
            .find(|pin| pin.name == name)
            .ok_or(crate::workflows::Refused::NotInstalled)?;
        let bundle = bundle_or_refusal(&library, &name, Some(&pinned.version))?;
        crate::workflows::eject(&root, &pins, &bundle, now)
    })
    .await
    .map_err(|_| refusal(StatusCode::INTERNAL_SERVER_ERROR, "internal"))?
    .map_err(workflow_refusal)?;

    workflow_feed(
        &state,
        &id,
        &format!("{ejected} ejected: this project now has its own copy"),
    )
    .await;
    Ok(StatusCode::NO_CONTENT)
}

#[derive(Deserialize)]
struct UpdateRequest {
    /// Absent means the newest the library has. The page always sends the version it showed, so
    /// this is the CLI's affordance rather than the shell's.
    #[serde(default)]
    version: Option<String>,
}

/// Take the origin's current bytes.
///
/// For a referenced workflow this re-stamps the pin. **For an ejected one it replaces the project's
/// copy**, which is what update means — and why the page puts the diff in front of the button
/// rather than beside it.
async fn post_project_workflow_update(
    State(state): State<AppState>,
    Path((id, name)): Path<(String, String)>,
    Json(body): Json<UpdateRequest>,
) -> Result<StatusCode, (StatusCode, Json<serde_json::Value>)> {
    let (root, pins, library) = workflow_write_root(&state, &id).await?;
    let record = materialized_record(&state, &id)?;
    let now = chrono::Utc::now();
    let project_id = id.clone();

    let (bundle, placed) = tokio::task::spawn_blocking(move || {
        let bundle = bundle_or_refusal(&library, &name, body.version.as_deref())?;
        crate::workflows::update(&root, &pins, &bundle, now)?;
        let placed = materialize_after_pin(&root, &pins, &library, &record, &bundle.name);
        Ok::<_, crate::workflows::Refused>((bundle, placed))
    })
    .await
    .map_err(|_| refusal(StatusCode::INTERNAL_SERVER_ERROR, "internal"))?
    .map_err(workflow_refusal)?;

    workflow_feed(
        &state,
        &project_id,
        &format!(
            "{}@{} taken from the library{placed}",
            bundle.name, bundle.version
        ),
    )
    .await;
    Ok(StatusCode::NO_CONTENT)
}

/// What this project's copy has that the origin does not.
#[derive(serde::Serialize)]
struct WorkflowDiff {
    /// The bundle both sides were measured against, so the answer names what it compared.
    origin_version: String,
    changes: Vec<crate::workflows::FileChange>,
    /// Files that are identical in both. Counted rather than listed: the interesting half is the
    /// short one, and a hundred unchanged paths would bury it.
    unchanged: usize,
}

/// The diff §6.1 asks for, file by file.
///
/// Only for an ejected workflow, and the 409 says so rather than answering with an empty list. A
/// referenced bundle IS the library's — there is no second copy to compare — so "no differences"
/// would be true and useless, and would read as *your copy matches* to somebody who has no copy.
async fn get_project_workflow_diff(
    State(state): State<AppState>,
    Path((id, name)): Path<(String, String)>,
) -> Result<Json<WorkflowDiff>, (StatusCode, Json<serde_json::Value>)> {
    let root = resolve_project_root(&state, &id)
        .await
        .map_err(|status| refusal(status, "no_project_root"))?;
    let library = library_or_refusal(&state)?;
    let pins = pins_file(&state, &id)?;

    tokio::task::spawn_blocking(move || {
        let pinned = crate::workflows::read_pins(&pins)
            .map_err(crate::workflows::Refused::Io)?
            .workflows
            .into_iter()
            .find(|pin| pin.name == name)
            .ok_or(crate::workflows::Refused::NotInstalled)?;
        let mine = crate::workflows::copy_path(&root, &pinned)
            .filter(|path| path.is_dir())
            .ok_or(crate::workflows::Refused::NotInstalled)?;
        let bundle = bundle_or_refusal(&library, &name, Some(&pinned.version))?;

        let mine = crate::workflows::file_hashes(&mine)
            .map_err(|e| crate::workflows::Refused::Io(e.to_string()))?;
        let theirs = crate::workflows::file_hashes(std::path::Path::new(&bundle.path))
            .map_err(|e| crate::workflows::Refused::Io(e.to_string()))?;
        let changes = crate::workflows::compare(&mine, &theirs);
        Ok::<_, crate::workflows::Refused>(WorkflowDiff {
            origin_version: bundle.version,
            unchanged: mine.len()
                - changes
                    .iter()
                    .filter(|c| c.change != crate::workflows::Change::Removed)
                    .count(),
            changes,
        })
    })
    .await
    .map_err(|_| refusal(StatusCode::INTERNAL_SERVER_ERROR, "internal"))?
    .map(Json)
    .map_err(workflow_refusal)
}

/// The graph a project's canvas draws, with this project's overlay painted on.
#[derive(serde::Serialize)]
struct GraphView {
    /// Which copy this came out of. `project` for an ejected workflow, `library` otherwise.
    ///
    /// Said out loud because it changes what editing the graph would mean: one is this project's
    /// file and the other is shared by every project that references the bundle, which is the whole
    /// of §6.3.
    source: &'static str,
    version: String,
    #[serde(flatten)]
    resolved: crate::workflow_graph::Resolved,
}

/// What this project's workflow looks like, ready to be drawn.
///
/// **The graph comes from the copy the project actually uses.** An ejected workflow is drawn from
/// the folder in the project, because that is the one that would run; a referenced one from the
/// library. Reading the library's for an ejected workflow would draw a picture of somebody else's
/// bundle and label it as theirs.
///
/// Four refusals, and `no_graph` is the one worth naming separately. A bundle with skills and
/// scripts and no sequence yet is an ordinary halfway state, not a broken bundle — and a page that
/// reported it as a parse failure would send somebody looking for a syntax error in a file that is
/// not there.
async fn get_project_workflow_graph(
    State(state): State<AppState>,
    Path((id, name)): Path<(String, String)>,
) -> Result<Json<GraphView>, (StatusCode, Json<serde_json::Value>)> {
    let root = resolve_project_root(&state, &id)
        .await
        .map_err(|status| refusal(status, "no_project_root"))?;
    let library = library_or_refusal(&state)?;
    let pins = pins_file(&state, &id)?;

    tokio::task::spawn_blocking(move || {
        let pinned = crate::workflows::read_pins(&pins)
            .map_err(crate::workflows::Refused::Io)?
            .workflows
            .into_iter()
            .find(|pin| pin.name == name)
            .ok_or(crate::workflows::Refused::NotInstalled)?;

        // `copy_path` and not `ejected_path`: an adopted workflow's copy is the folder the project
        // already had — `.ai/` here — rather than the one an eject would have created. Reading the
        // library instead would draw somebody else's bundle and label it as this project's.
        let mine = crate::workflows::copy_path(&root, &pinned).filter(|path| path.is_dir());
        let (source, from) = match mine {
            Some(path) => ("project", path),
            None => (
                "library",
                std::path::PathBuf::from(
                    bundle_or_refusal(&library, &name, Some(&pinned.version))?.path,
                ),
            ),
        };

        let text = std::fs::read_to_string(from.join(crate::workflow_graph::GRAPH_FILE)).map_err(
            |error| match error.kind() {
                std::io::ErrorKind::NotFound => crate::workflows::Refused::NoGraph,
                _ => crate::workflows::Refused::Io(error.to_string()),
            },
        )?;
        let graph =
            crate::workflow_graph::parse(&text).map_err(crate::workflows::Refused::InvalidGraph)?;

        Ok::<_, crate::workflows::Refused>(GraphView {
            source,
            version: pinned.version,
            resolved: crate::workflow_graph::resolve(&graph, &pinned.nodes),
        })
    })
    .await
    .map_err(|_| refusal(StatusCode::INTERNAL_SERVER_ERROR, "internal"))?
    .map(Json)
    .map_err(workflow_refusal)
}

#[derive(Deserialize)]
struct OverlayRequest {
    /// Absent means *inherit*, which is a third answer that `false` would have collapsed into
    /// "explicitly on". The same reasoning as the fields below.
    #[serde(default)]
    disabled: Option<bool>,
    #[serde(default)]
    model: Option<String>,
    #[serde(default)]
    tool: Option<String>,
    #[serde(default)]
    command: Option<String>,
}

/// Change what this project overrides on one node — or clear it back to inherited.
///
/// **A write, so the stop applies.** It puts bytes in the project's `workflows.yaml`, which the app
/// holds on the project's behalf, and §7.5 says that goes the way an agent's write goes.
///
/// A body in which everything is absent clears the row, because an override that overrides nothing
/// is not an override. That makes "go back to what the bundle says" the same request with an empty
/// body rather than a second route with a different verb.
async fn post_project_workflow_node(
    State(state): State<AppState>,
    Path((id, name, node)): Path<(String, String, String)>,
    Json(body): Json<OverlayRequest>,
) -> Result<StatusCode, (StatusCode, Json<serde_json::Value>)> {
    let (_, pins, _) = workflow_write_root(&state, &id).await?;
    let said = format!("{name}/{node} overridden in this project");

    let overlay = crate::workflows::NodeOverlay {
        disabled: body.disabled,
        // Empty is cleared, not "the empty model". A form that sends "" for a field somebody
        // emptied has to be able to mean *stop overriding this*, and there is no model, tool or
        // command whose name is nothing.
        model: body.model.filter(|value| !value.trim().is_empty()),
        tool: body.tool.filter(|value| !value.trim().is_empty()),
        command: body.command.filter(|value| !value.trim().is_empty()),
    };

    tokio::task::spawn_blocking(move || {
        crate::workflows::set_overlay(&pins, &name, &node, Some(overlay))
    })
    .await
    .map_err(|_| refusal(StatusCode::INTERNAL_SERVER_ERROR, "internal"))?
    .map_err(workflow_refusal)?;

    workflow_feed(&state, &id, &said).await;
    Ok(StatusCode::NO_CONTENT)
}

#[derive(Deserialize)]
struct DetectQuery {
    /// An absolute path to a folder. See `detect.rs` for why this route takes one at all.
    path: String,
}

/// What is already in a folder somebody is about to add.
///
/// **§9's second step.** A project worth adding has a history, commands its people type, and often a
/// written-down way of working — this repository's is `.ai/`, and it built NucleOS. This reports all
/// of it so the wizard can propose rather than interrogate.
///
/// The git half runs even when the folder turns out not to be a repository: `is_git` is a finding
/// and not a refusal, because `set_project_mode` only insists on a repository for `active`, and a
/// wizard that refused to look at a folder would be deciding a question the last step asks.
///
/// In no scope table, like every route under `/projects/{id}/workflows`: it reads a path nobody has
/// vouched for, so `permits` — default-deny — leaves it to the key of the person at the machine.
async fn get_project_detect(
    State(state): State<AppState>,
    Query(query): Query<DetectQuery>,
) -> Result<Json<crate::detect::Detected>, (StatusCode, Json<serde_json::Value>)> {
    let root = std::path::PathBuf::from(query.path.trim());
    if !root.is_absolute() {
        return Err(refusal(StatusCode::BAD_REQUEST, "not_absolute"));
    }

    let root = tokio::fs::canonicalize(&root)
        .await
        .map_err(|_| refusal(StatusCode::NOT_FOUND, "no_such_folder"))?;
    if !root.is_dir() {
        return Err(refusal(StatusCode::UNPROCESSABLE_ENTITY, "not_a_folder"));
    }

    let looking = root.clone();
    let mut found = tokio::task::spawn_blocking(move || crate::detect::inspect_folder(&looking))
        .await
        .map_err(|_| refusal(StatusCode::INTERNAL_SERVER_ERROR, "internal"))?;

    if found.is_git {
        let deadline = std::time::Instant::now() + DETECT_GIT_BUDGET;
        found.branch = crate::git_exec::current_branch(&root, deadline).await.ok();
        let (remote, head) = crate::git_exec::origin_and_head(&root, deadline).await;
        found.remote = remote;
        found.head = head;
    }

    // The one thing here that cannot be seen from the folder. Adding a project twice under two
    // names is the mistake this prevents, and neither name would look wrong on its own.
    found.taken_by = already_registered(&state, &root).await;
    Ok(Json(found))
}

/// How long the three git reads get, together.
///
/// Short on purpose. This runs while somebody waits on a wizard, all three commands are local, and a
/// repository whose `.git` is on a disconnected network share is exactly the case that would
/// otherwise hold the request open. Missing git facts degrade to `None`, which the page shows as
/// "not read" rather than as "there is no remote".
///
/// `get_project_github_repo` shares it rather than naming a second duration. The two are the same
/// proposition — local git reads with a person waiting on a page — and two numbers here is how one
/// of them ends up generous enough to hang the request the other was written to protect.
const DETECT_GIT_BUDGET: std::time::Duration = std::time::Duration::from_secs(10);

/// A project this daemon already keeps at this folder, if any.
///
/// Compared after canonicalising both sides, because the stored root is whatever string was handed
/// in when the project was registered — a trailing slash, a different case on Windows, a path
/// through a junction — and a plain string comparison would report "no" for the same folder.
async fn already_registered(state: &AppState, root: &std::path::Path) -> Option<String> {
    let rows: Vec<(String, Option<String>)> =
        sqlx::query_as("SELECT project_id, project_root FROM autopilot_state")
            .fetch_all(&state.pool)
            .await
            .ok()?;

    for (project_id, stored) in rows {
        let Some(stored) = stored else { continue };
        let Ok(stored) = tokio::fs::canonicalize(&stored).await else {
            continue;
        };
        if stored == root {
            return Some(project_id);
        }
    }
    None
}

#[derive(Deserialize)]
struct AdoptRequest {
    /// What to call it. The project's own choice: an adopted folder has no published name.
    name: String,
    /// The folder, relative to the project root — `.ai`, `.claude`.
    path: String,
}

/// Record a folder this project already has as its workflow.
///
/// **Copies nothing and writes nothing into the folder.** §9's second step exists because a project
/// that already works must not be asked to describe itself again before the app will admit it. So
/// this writes one pin, and the folder stays exactly as it was — no manifest, no rewrite.
///
/// It has no library origin, so it is ejected from birth and can never be updated. That is not a
/// gap: it is what an adopted folder is, and the page says so rather than offering a button that
/// would have to refuse.
async fn post_project_workflow_adopt(
    State(state): State<AppState>,
    Path(id): Path<String>,
    Json(body): Json<AdoptRequest>,
) -> Result<StatusCode, (StatusCode, Json<serde_json::Value>)> {
    let (root, pins, _) = workflow_write_root(&state, &id).await?;
    let now = chrono::Utc::now();
    let said = format!("{} adopted as this project's workflow", body.path);

    tokio::task::spawn_blocking(move || {
        crate::workflows::adopt(&root, &pins, &body.name, &body.path, now)
    })
    .await
    .map_err(|_| refusal(StatusCode::INTERNAL_SERVER_ERROR, "internal"))?
    .map_err(workflow_refusal)?;

    workflow_feed(&state, &id, &said).await;
    Ok(StatusCode::NO_CONTENT)
}

/// Materialize one pinned workflow in `root`, or say only what it would do.
///
/// The pin is looked up first so that a workflow this project does not use is a 404, the same
/// `not_installed` every route beside this one answers, rather than an empty list.
fn materialize_one(
    root: &std::path::Path,
    pins: &std::path::Path,
    library: &std::path::Path,
    record: &std::path::Path,
    name: &str,
    mode: crate::workflow_materialize::Mode,
) -> Result<crate::workflow_materialize::PinOutcome, (StatusCode, Json<serde_json::Value>)> {
    let pinned = crate::workflows::read_pins(pins).map_err(|detail| {
        refusal_with_detail(StatusCode::UNPROCESSABLE_ENTITY, "unreadable_pins", detail)
    })?;
    if !pinned.workflows.iter().any(|pin| pin.name == name) {
        return Err(workflow_refusal(crate::workflows::Refused::NotInstalled));
    }
    crate::workflow_materialize::sync(root, pins, library, record, Some(name), mode)
        .map_err(|detail| {
            refusal_with_detail(
                StatusCode::UNPROCESSABLE_ENTITY,
                "unreadable_record",
                detail,
            )
        })?
        .into_iter()
        .next()
        .ok_or_else(|| workflow_refusal(crate::workflows::Refused::NotInstalled))
}

/// What materializing this workflow into the project would do, with nothing written.
///
/// The preview the page shows before the button, and the one place a conflict can be read in
/// full: both hashes and the bundle's copy of the file, which is enough to diff it.
async fn get_project_workflow_materialize(
    State(state): State<AppState>,
    Path((id, name)): Path<(String, String)>,
) -> Result<Json<crate::workflow_materialize::PinOutcome>, (StatusCode, Json<serde_json::Value>)> {
    let root = resolve_project_root(&state, &id)
        .await
        .map_err(|status| refusal(status, "no_project_root"))?;
    let library = library_or_refusal(&state)?;
    let pins = pins_file(&state, &id)?;
    let record = materialized_record(&state, &id)?;
    tokio::task::spawn_blocking(move || {
        materialize_one(
            &root,
            &pins,
            &library,
            &record,
            &name,
            crate::workflow_materialize::Mode::Preview,
        )
    })
    .await
    .map_err(|_| refusal(StatusCode::INTERNAL_SERVER_ERROR, "internal"))?
    .map(Json)
}

/// Put this workflow's files into the project. Never over a file somebody edited — see
/// `workflow_materialize.rs` — and the answer lists every file left alone and why.
///
/// **The stop first**, through `workflow_write_root` like every workflow write: these are files
/// that govern what an agent does, the same class of write `POST /write` refuses while the kill
/// switch is engaged.
async fn post_project_workflow_materialize(
    State(state): State<AppState>,
    Path((id, name)): Path<(String, String)>,
) -> Result<Json<crate::workflow_materialize::PinOutcome>, (StatusCode, Json<serde_json::Value>)> {
    let (root, pins, library) = workflow_write_root(&state, &id).await?;
    let record = materialized_record(&state, &id)?;
    let outcome = tokio::task::spawn_blocking(move || {
        materialize_one(
            &root,
            &pins,
            &library,
            &record,
            &name,
            crate::workflow_materialize::Mode::Apply,
        )
    })
    .await
    .map_err(|_| refusal(StatusCode::INTERNAL_SERVER_ERROR, "internal"))??;

    let said = match (&outcome.report, &outcome.error, &outcome.skipped) {
        (_, Some(error), _) => format!("{}: files could not all be placed: {error}", outcome.name),
        (Some(report), None, _) => format!("files placed — {}", report.summary()),
        (None, None, Some(why)) => format!("{}: nothing placed — {why}", outcome.name),
        (None, None, None) => format!("{}: nothing placed", outcome.name),
    };
    workflow_feed(&state, &id, &said).await;
    Ok(Json(outcome))
}

#[derive(Deserialize)]
struct WorkflowSyncRequest {
    /// The checkout, absolute. `nucleos-core --workflow-sync` sends its argument or its cwd.
    path: String,
    /// Which project, when more than one rostered project points at the checkout's repository.
    /// Only ever a choice among those: a project the repository does not match is refused.
    #[serde(default)]
    project_id: Option<String>,
}

#[derive(serde::Serialize)]
struct WorkflowSyncAnswer {
    project_id: String,
    outcomes: Vec<crate::workflow_materialize::PinOutcome>,
}

/// Materialize a project's pinned workflows into a checkout somebody made by hand.
///
/// **Which project is decided by the repository, not by the caller.** The checkout's git common
/// directory (`git_exec::repo_key`) is compared against every rostered root's; the one that shares
/// it is the project. A caller naming a project the repository does not match would be a caller
/// able to put one project's workflow into another's checkout, so `project_id` is refused (400,
/// `project_not_a_match`) unless it is one of the matches.
///
/// **More than one match is not guessed.** Two rostered projects can point at one repository, and
/// the first row is not an answer: without a `project_id` the sync is refused with 409
/// `ambiguous_project`, naming every candidate (id and root), and nothing is written.
///
/// A worktree gets its own record under `~/.nucleos/projects/<id>/materialized/`, so a file edited
/// in it is protected exactly as one edited in the main checkout; the main checkout itself, named
/// here, uses the project's record.
async fn post_workflow_sync(
    State(state): State<AppState>,
    Json(body): Json<WorkflowSyncRequest>,
) -> Result<Json<WorkflowSyncAnswer>, (StatusCode, Json<serde_json::Value>)> {
    if crate::autopilot::kill_switch_engaged(&state.pool)
        .await
        .unwrap_or(true)
    {
        return Err(refusal(StatusCode::LOCKED, "kill_switch"));
    }
    let asked = std::path::PathBuf::from(&body.path);
    if !asked.is_absolute() {
        return Err(refusal(
            StatusCode::UNPROCESSABLE_ENTITY,
            "path_not_absolute",
        ));
    }
    let checkout = tokio::fs::canonicalize(&asked)
        .await
        .map_err(|_| refusal(StatusCode::NOT_FOUND, "no_such_path"))?;
    let deadline = std::time::Instant::now() + DETECT_GIT_BUDGET;
    let key = crate::git_exec::repo_key(&checkout, deadline)
        .await
        .map_err(|detail| {
            refusal_with_detail(StatusCode::UNPROCESSABLE_ENTITY, "not_a_checkout", detail)
        })?;

    let rows: Vec<(String, Option<String>)> =
        sqlx::query_as("SELECT project_id, project_root FROM autopilot_state")
            .fetch_all(&state.pool)
            .await
            .map_err(|_| refusal(StatusCode::INTERNAL_SERVER_ERROR, "internal"))?;
    let mut matches = Vec::new();
    for (project_id, root) in rows {
        let Some(root) = root else { continue };
        let root = std::path::PathBuf::from(root);
        if crate::git_exec::repo_key(&root, deadline).await.as_ref() == Ok(&key) {
            matches.push((project_id, root));
        }
    }
    if matches.is_empty() {
        return Err(refusal(StatusCode::NOT_FOUND, "no_project"));
    }
    let (project_id, root) = match body.project_id.as_deref() {
        Some(named) => matches
            .into_iter()
            .find(|(project_id, _)| project_id == named)
            .ok_or_else(|| refusal(StatusCode::BAD_REQUEST, "project_not_a_match"))?,
        None if matches.len() > 1 => {
            let candidates: Vec<serde_json::Value> = matches
                .iter()
                .map(|(project_id, root)| {
                    serde_json::json!({
                        "project_id": project_id,
                        "project_root": root.to_string_lossy(),
                    })
                })
                .collect();
            return Err((
                StatusCode::CONFLICT,
                Json(serde_json::json!({
                    "refusal": "ambiguous_project",
                    "candidates": candidates,
                })),
            ));
        }
        None => matches.remove(0),
    };
    if crate::autopilot::scoped_kill_engaged(&state.pool, "project", &project_id)
        .await
        .unwrap_or(true)
    {
        return Err(refusal(StatusCode::LOCKED, "kill_switch"));
    }

    let library = library_or_refusal(&state)?;
    let state_dir = project_state_dir(&state, &project_id)?;
    let pins = state_dir.join(crate::project_state::PINS_FILE);
    let is_main = tokio::fs::canonicalize(&root).await.ok().as_ref() == Some(&checkout);
    let record = if is_main {
        state_dir.join(crate::project_state::MATERIALIZED_FILE)
    } else {
        crate::workflow_materialize::worktree_record(&state_dir, &checkout)
    };
    let target = checkout.clone();
    let outcomes = tokio::task::spawn_blocking(move || {
        crate::workflow_materialize::sync(
            &target,
            &pins,
            &library,
            &record,
            None,
            crate::workflow_materialize::Mode::Apply,
        )
    })
    .await
    .map_err(|_| refusal(StatusCode::INTERNAL_SERVER_ERROR, "internal"))?
    .map_err(|detail| {
        refusal_with_detail(
            StatusCode::UNPROCESSABLE_ENTITY,
            "unreadable_record",
            detail,
        )
    })?;

    let said: Vec<String> = outcomes
        .iter()
        .map(
            |outcome| match (&outcome.report, &outcome.error, &outcome.skipped) {
                (_, Some(error), _) => format!("{}: {error}", outcome.name),
                (Some(report), None, _) => report.summary(),
                (None, None, why) => format!(
                    "{}: nothing placed ({})",
                    outcome.name,
                    why.as_deref().unwrap_or("no reason given")
                ),
            },
        )
        .collect();
    if !said.is_empty() {
        workflow_feed(
            &state,
            &project_id,
            &format!("synced into {}: {}", checkout.display(), said.join("; ")),
        )
        .await;
    }
    Ok(Json(WorkflowSyncAnswer {
        project_id,
        outcomes,
    }))
}

/// One feed line, after the fact and loudly on failure.
///
/// The same rule `POST /write` follows: a line about a change that then failed claims something
/// that did not happen, and a change whose line was lost is recoverable from the log.
async fn workflow_feed(state: &AppState, project_id: &str, said: &str) {
    if let Err(error) = feed::append(
        &state.pool,
        Some(project_id),
        "workflow_changed",
        said,
        None,
        None,
    )
    .await
    {
        tracing::error!(%error, project_id, "a workflow change was made and its feed line was not recorded");
    }
}

async fn get_project_ls(
    State(state): State<AppState>,
    Path(id): Path<String>,
    Query(query): Query<ReadQuery>,
) -> Result<Json<Vec<inspect::Entry>>, StatusCode> {
    let root = resolve_read_root(&state, &id, query.run).await?;
    let rel = query.path.unwrap_or_default();
    tokio::task::spawn_blocking(move || inspect::ls(&root, &rel))
        .await
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?
        .map(Json)
        .map_err(inspect_status)
}

async fn get_project_cat(
    State(state): State<AppState>,
    Path(id): Path<String>,
    Query(query): Query<ReadQuery>,
) -> Result<String, StatusCode> {
    let root = resolve_read_root(&state, &id, query.run).await?;
    let rel = query.path.unwrap_or_default();
    tokio::task::spawn_blocking(move || inspect::cat(&root, &rel))
        .await
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?
        .map_err(inspect_status)
}

async fn get_project_grep(
    State(state): State<AppState>,
    Path(id): Path<String>,
    Query(query): Query<GrepQuery>,
) -> Result<Json<Vec<inspect::Match>>, StatusCode> {
    let root = resolve_read_root(&state, &id, query.run).await?;
    let q = query.q.unwrap_or_default();
    let rel = query.path.unwrap_or_default();
    tokio::task::spawn_blocking(move || inspect::grep(&root, &q, &rel))
        .await
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?
        .map(Json)
        .map_err(inspect_status)
}

/// A project's recent commits.
///
/// `path` narrows the history and travels the same road every other caller-supplied path here
/// travels: `inspect::log` runs it through `safe_join` before git sees it, because a pathspec that
/// begins with `-` is an option and one containing `..` reaches outside the repository.
async fn get_project_log(
    State(state): State<AppState>,
    Path(id): Path<String>,
    Query(query): Query<LogQuery>,
) -> Result<Json<Vec<inspect::Commit>>, StatusCode> {
    let root = resolve_read_root(&state, &id, query.run).await?;
    let rel = query.path.unwrap_or_default();
    let limit = query.limit.unwrap_or(50);
    tokio::task::spawn_blocking(move || inspect::log(&root, &rel, limit))
        .await
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?
        .map(Json)
        .map_err(inspect_status)
}

/// Every local branch, and how far each is from where work lands.
async fn get_project_branches(
    State(state): State<AppState>,
    Path(id): Path<String>,
) -> Result<Json<inspect::Branches>, StatusCode> {
    let root = resolve_project_root(&state, &id).await?;
    tokio::task::spawn_blocking(move || inspect::branches(&root))
        .await
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?
        .map(Json)
        .map_err(inspect_status)
}

/// The uncommitted diff of the project, or everything one run changed since it branched.
///
/// The two are different questions and the `run` parameter chooses between them. Without it this is
/// what it always was: the main checkout's working tree. With it, the comparison is against the
/// branch point — because a run's checkpoints are commits, and a working-tree diff of a run
/// halfway through a job shows nothing at all.
async fn get_project_diff(
    State(state): State<AppState>,
    Path(id): Path<String>,
    Query(query): Query<ReadQuery>,
) -> Result<String, StatusCode> {
    let rel = query.path.unwrap_or_default();
    let Some(run) = query.run else {
        let root = resolve_project_root(&state, &id).await?;
        return tokio::task::spawn_blocking(move || inspect::diff(&root))
            .await
            .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?
            .map_err(inspect_status);
    };

    let (root, base) = resolve_run_worktree(&state, &id, run).await?;
    tokio::task::spawn_blocking(move || inspect::diff_since(&root, &base, &rel))
        .await
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?
        .map_err(inspect_status)
}

/// The search endpoints never return more than this many rows, even when a caller requests more.
const SEARCH_LIMIT_MAX: i64 = 200;

fn parse_time_bound(
    value: Option<String>,
) -> Result<Option<chrono::DateTime<chrono::Utc>>, StatusCode> {
    value
        .map(|value| {
            chrono::DateTime::parse_from_rfc3339(&value)
                .map(|time| time.with_timezone(&chrono::Utc))
                .map_err(|_| StatusCode::BAD_REQUEST)
        })
        .transpose()
}

fn parse_search_limit(value: Option<String>) -> Result<i64, StatusCode> {
    match value {
        Some(value) => value
            .parse::<i64>()
            .map(|limit| limit.clamp(1, SEARCH_LIMIT_MAX))
            .map_err(|_| StatusCode::BAD_REQUEST),
        None => Ok(50),
    }
}

async fn get_feed(
    State(state): State<AppState>,
    Query(query): Query<FeedQuery>,
) -> Result<Json<Vec<FeedEntry>>, StatusCode> {
    let has_search_filters = query.q.is_some()
        || query.kind.is_some()
        || query.since.is_some()
        || query.until.is_some()
        || query.limit.is_some();
    if !has_search_filters {
        let entries = if query.scope.as_deref() == Some("all") {
            feed::list_all(&state.pool, 50).await
        } else {
            feed::list_feed(&state.pool, query.project_id.as_deref(), 50).await
        };
        return entries
            .map(Json)
            .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR);
    }

    let scope = if query.scope.as_deref() == Some("all") {
        feed::FeedScope::All
    } else if let Some(project_id) = query.project_id {
        feed::FeedScope::Project(project_id)
    } else {
        feed::FeedScope::Global
    };
    let entries = feed::search(
        &state.pool,
        &feed::SearchFilter {
            scope,
            q: query.q,
            kind: query.kind,
            since: parse_time_bound(query.since)?,
            until: parse_time_bound(query.until)?,
            limit: parse_search_limit(query.limit)?,
        },
    )
    .await;
    entries
        .map(Json)
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)
}

async fn get_feed_timeline(
    State(state): State<AppState>,
    Query(query): Query<FeedTimelineQuery>,
) -> Result<Json<feed::Timeline>, StatusCode> {
    let since = parse_time_bound(query.since)?.ok_or(StatusCode::BAD_REQUEST)?;
    let until = parse_time_bound(query.until)?;
    feed::timeline_window(since, until, chrono::Utc::now()).map_err(|_| StatusCode::BAD_REQUEST)?;
    feed::timeline(
        &state.pool,
        since,
        until,
        query.after_id,
        feed::TIMELINE_MAX,
    )
    .await
    .map(Json)
    .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)
}

async fn get_feed_seen(State(state): State<AppState>) -> Result<Json<feed::Seen>, StatusCode> {
    feed::seen(&state.pool)
        .await
        .map(Json)
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)
}

async fn post_feed_seen(
    State(state): State<AppState>,
    Json(body): Json<FeedSeenRequest>,
) -> Result<Json<feed::Seen>, StatusCode> {
    // Refused rather than clamped to zero: no line has a negative id, so a caller sending one has
    // mixed something up, and storing the nearest legal value would hide that from it.
    if body.through < 0 {
        return Err(StatusCode::BAD_REQUEST);
    }
    feed::mark_seen(&state.pool, body.through, chrono::Utc::now())
        .await
        .map(Json)
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)
}

async fn get_runs(
    State(state): State<AppState>,
    Query(query): Query<RunsQuery>,
) -> Result<Json<Vec<runs::RunSearchResult>>, StatusCode> {
    let live = query.live == Some(true);
    // One grouping exists. Anything else is refused, not ignored: a caller that asked for a
    // grouping and got the flat list would read turns as conversations.
    let group_by_chat = match query.group.as_deref() {
        None => false,
        Some("chat") => true,
        Some(_) => return Err(StatusCode::BAD_REQUEST),
    };
    // A live listing with no explicit limit inherits the ceiling of live listings, not search's 50.
    // Without this the daemon would promise a shared constant and hand back the search window — and
    // the client would be the only thing guaranteeing the number, which is no guarantee at all.
    let limit = if live && query.limit.is_none() {
        crate::concurrency::LIVE_LIST_LIMIT
    } else {
        parse_search_limit(query.limit)?
    };
    runs::search(
        &state.pool,
        &runs::SearchFilter {
            project_id: query.project_id,
            status: query.status,
            mode: query.mode,
            q: query.q,
            since: parse_time_bound(query.since)?,
            until: parse_time_bound(query.until)?,
            limit,
            live,
            chat_id: query.chat_id,
            group_by_chat,
        },
    )
    .await
    .map(Json)
    .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)
}

/// What a caller may say when asking the VCS queue for something.
///
/// Two fields the queue needs are deliberately NOT here, and their absence is the security posture:
///
/// - **`project_root`** is resolved by `vcs::resolve_repo`, together with the key the queue locks
///   on, and the two can no longer be set apart from each other. A caller that could name the
///   repository root could point the daemon's git at any directory the daemon can reach, which is
///   the same reason `inspect.rs` "never resolves a root itself".
/// - **`origin`** comes from the bearer token's scope. `hooks.rs` states the rule this follows: a
///   value in the body is a claim the caller makes about itself, and here that claim decides whether
///   a human still has to approve the operation — precisely the thing a caller must not choose.
#[derive(Deserialize)]
struct VcsRequestBody {
    project_id: String,
    operation: vcs::Op,
}

/// Who the queue records as having asked, derived from the key that authenticated the call.
///
/// **`Origin` decides whether a human still has to approve**, so the mapping is a security decision,
/// not bookkeeping. `Human` and `Shell` skip approval; `Run` and `Job` do not.
///
/// `Control` → `Human` is the load-bearing arm, and it is also where the *autonomous* path lands —
/// which is not obvious. An orchestrator turn is handed the control token (`assistant.rs`), and only
/// orchestrator turns are given an `--mcp-config`, so when the MCP door opens its requests arrive as
/// `Control`, not as `Run`. That is spec decision 6 working as intended: a turn acting on an order
/// you just gave carries your approval. It is worth stating plainly because the `Run` arm below
/// looks like the one that handles agents, and it is not.
///
/// `ApiToken(Admin)` → `Human`, deliberately, and **not** `Shell`. In this repo "shell" means the
/// Tauri desktop app — which holds the *control* token and therefore already maps to `Human` — so
/// recording `shell` for a durable API key would put a word in the listing that names the one client
/// that did not make the call. `Human` claims only what is true: a person minted this key on purpose
/// and it carries their approval. Whether an unattended admin key *should* pre-approve a merge is a
/// real question, and it belongs with the chunk that defines durable-key provenance rather than
/// being settled by a name chosen here.
///
/// `Run` cannot reach this route today — a run token opens exactly one route, the safety gate — but
/// mapping it costs nothing and is what the MCP tools will need once a run can submit directly.
/// `Service`, `TeamRun` and the lesser API levels are refused rather than guessed at: `permits`
/// should already have turned them away, so a scope arriving here unaccounted for is a routing bug,
/// and defaulting it would mean guessing about approval.
///
/// `TeamRun` is the sharpest of the three. A department has no `vcs::Origin` because it is not
/// allowed to want one: queueing a merge is the act that makes work survive on a branch other
/// people build on, and the teams design gives a department no authority to act at all. When that
/// authority arrives it arrives as its own spec, with a value here chosen on purpose — which is
/// exactly what a default would have taken away.
fn vcs_origin(scope: &Scope) -> Result<vcs::Origin, StatusCode> {
    match scope {
        Scope::Control | Scope::ApiToken(ApiTokenLevel::Admin) => Ok(vcs::Origin::Human),
        Scope::Run(id) => Ok(vcs::Origin::Run(*id)),
        Scope::Service(_) | Scope::TeamRun(_) | Scope::ApiToken(_) => Err(StatusCode::FORBIDDEN),
    }
}

/// The one handler here that writes, and therefore the one that owes the cancellation question an
/// answer.
///
/// It awaits on both sides of its one write, and the two sides fail differently. **Before** the
/// insert it awaits git: `resolve_repo` runs a `rev-parse` under `git_exec::OPERATION_TIMEOUT`
/// (300s), and a disconnect during it leaves nothing written at all — the safest of the outcomes
/// here, and worth knowing for the other reason, that a pathological repository can hold this
/// handler for five minutes rather than the moment an INSERT takes. **After** the insert it awaits
/// the read that builds the ticket, so a client disconnecting there drops the future with the row
/// already committed. That half is benign **today** and only today: what is left behind is a
/// `queued` row that will still execute, appears in the listing, and holds no repository — the
/// caller loses its reply, not its request. So `http::uncancellable` is not needed yet.
///
/// It stops being benign the moment submitting becomes two writes — the row plus an approval
/// proposal, which is what the approval chunk adds. A disconnect between them would leave a request
/// that can never be approved. Whoever writes that second write moves this through `uncancellable`
/// at the same time.
#[derive(serde::Deserialize)]
struct LandBody {
    /// Anywhere inside the worktree that is asking. Resolved to its root, so a session standing
    /// in a subdirectory asks the same question as one standing at the top.
    cwd: String,
    /// The branch this landing is for, when the caller named one. `None` — every caller until
    /// 2026-09-03 — means the project's integration branch, and that has to keep being what an
    /// absent field means: `--land` alone is the spelling almost every session uses.
    #[serde(default)]
    target: Option<String>,
}

/// "I am finished — take this branch." The one request a worktree could not previously express.
///
/// **A session can only ever have asked for merges INTO its own branch**, because
/// `merge_from_command` takes the target from the worktree it is standing in and there is no other
/// branch it could name. The reverse — landing the work — has no git spelling from inside the
/// worktree at all: you would have to check out the integration branch, which is the isolation
/// violation a worktree session must not commit, and which its harness blocks outright. So this is
/// not a command to be intercepted; it is a request, and it needed a door of its own.
///
/// **Asking is authorisation; it is not scheduling.** The session's own completion is the decision
/// that the work is ready — a person commanding it, or the agent when it has finished — so the row
/// enters `queued` rather than `awaiting_approval`, and no second approval is invented for a
/// judgement that has already been made. What stays with the queue is WHEN, which is the part a
/// session cannot know: one operation per repository, in order, against a repository that may have
/// moved since the asking.
///
/// **Re-evaluation is not added here because it is already how the queue works.** The merge is
/// computed fresh in the integration worktree at the moment of execution, not at the moment of
/// asking, so a branch that has diverged or a merge that has come to conflict aborts before
/// publishing and the row records `failed` with git's own output. A request that can no longer land
/// says so and stops, which is the behaviour wanted rather than a new mechanism.
///
/// The target is `land::integration_branch` — declared once per project — unless the caller named
/// one this project admits, and in neither case is it read off any worktree's HEAD, which is the
/// defect `land.rs` exists to prevent. This handler no longer decides that, or anything else about
/// what the landing means: it resolves *who is asking* (a `cwd`, turned into a worktree root, a
/// branch and a repository) and hands the rest to `land.rs`. Design decision #8 — the ~60 lines
/// this used to carry moved to the module that now owns them.
async fn land_worktree(
    State(state): State<AppState>,
    Json(body): Json<LandBody>,
) -> Result<Json<vcs::Ticket>, (StatusCode, String)> {
    let deadline = std::time::Instant::now() + crate::git_exec::OPERATION_TIMEOUT;
    let refuse = |code: StatusCode, reason: String| (code, reason);

    let root = crate::git_exec::toplevel(std::path::Path::new(&body.cwd), deadline)
        .await
        .map_err(|reason| refuse(StatusCode::UNPROCESSABLE_ENTITY, reason))?;
    let source = crate::git_exec::current_branch(&root, deadline)
        .await
        .map_err(|reason| refuse(StatusCode::UNPROCESSABLE_ENTITY, reason))?;
    if source.trim() == "HEAD" {
        return Err(refuse(
            StatusCode::UNPROCESSABLE_ENTITY,
            "this worktree is on a detached HEAD, so there is no branch to land".to_owned(),
        ));
    }

    let project_id = crate::vcs::project_for_worktree(&state.pool, &root, deadline)
        .await
        .map_err(|reason| refuse(StatusCode::NOT_FOUND, reason))?;
    let repo = crate::vcs::resolve_repo(&state.pool, &project_id)
        .await
        .map_err(|error| {
            tracing::warn!(project_id, ?error, "land: could not resolve the repository");
            refuse(
                StatusCode::UNPROCESSABLE_ENTITY,
                format!("{project_id}'s repository could not be resolved"),
            )
        })?;

    let id = crate::land::submit(
        &state.pool,
        &repo,
        std::path::Path::new(repo.root()),
        source.trim(),
        body.target.as_deref(),
        deadline,
    )
    .await
    .map_err(|refusal| {
        let code = match &refusal {
            crate::land::LandRefusal::AlreadyOnTarget(_)
            | crate::land::LandRefusal::NothingToLand(_) => StatusCode::CONFLICT,
            crate::land::LandRefusal::Refused(_) => StatusCode::UNPROCESSABLE_ENTITY,
            crate::land::LandRefusal::NotAdmitted(error) => {
                tracing::warn!(%error, "land: admitting the request failed");
                StatusCode::INTERNAL_SERVER_ERROR
            }
        };
        refuse(code, refusal.message().to_owned())
    })?;

    vcs_ticket(&state, id, std::time::Duration::ZERO)
        .await
        .map_err(|code| {
            refuse(
                code,
                "the request was admitted but could not be read back".to_owned(),
            )
        })
}

async fn submit_vcs_request(
    State(state): State<AppState>,
    Extension(scope): Extension<Scope>,
    Json(body): Json<VcsRequestBody>,
) -> Result<Json<vcs::Ticket>, StatusCode> {
    let origin = vcs_origin(&scope)?;
    let repo = vcs::resolve_repo(&state.pool, &body.project_id)
        .await
        .map_err(|error| match error {
            vcs::ResolveError::UnknownProject => StatusCode::NOT_FOUND,
            // The caller named a project that exists; what is wrong is the root this daemon has
            // recorded for it. 422 rather than 400 or 500: the request was well-formed and the
            // daemon is working, but the state it would act on is not a repository.
            vcs::ResolveError::NotARepository(reason) => {
                tracing::warn!(project_id = %body.project_id, %reason, "vcs: project root is not a repository");
                StatusCode::UNPROCESSABLE_ENTITY
            }
            vcs::ResolveError::Database(error) => {
                tracing::warn!(%error, "vcs: could not resolve a project");
                StatusCode::INTERNAL_SERVER_ERROR
            }
        })?;
    let id = vcs::submit(&state.pool, &repo, &body.operation, origin)
        .await
        .map_err(|error| {
            tracing::warn!(%error, "submitting a vcs request failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })?;
    // Answered with a zero deadline rather than a bare id: the caller gets the same shape back from
    // submitting as from asking later, so nothing has to special-case the first reply.
    vcs_ticket(&state, id, std::time::Duration::ZERO).await
}

async fn get_vcs_request(
    State(state): State<AppState>,
    Path(id): Path<i64>,
) -> Result<Json<vcs::Ticket>, StatusCode> {
    vcs_ticket(&state, id, std::time::Duration::ZERO).await
}

#[derive(Deserialize)]
struct GithubRequestBody {
    /// The operation, as data. Deserialized through `github`'s validating node types, so a dashed
    /// string is refused HERE rather than reaching an argv.
    op: crate::github::Op,
}

/// A second refusal of a call `auth.rs` has already refused, and deliberately so.
///
/// `POST /github/requests` is absent from both scope tables, so `permits` lets only the control
/// token and an Admin key reach this at all. This is not that boundary and must not be read as one
/// — it is the second of two independent refusals at a place that leaves the machine, which is what
/// `hooks.rs` says one wants at a boundary.
fn github_caller_is_allowed(scope: &Scope) -> Result<(), StatusCode> {
    match scope {
        Scope::Control | Scope::ApiToken(ApiTokenLevel::Admin) => Ok(()),
        Scope::Run(_) | Scope::Service(_) | Scope::TeamRun(_) | Scope::ApiToken(_) => {
            Err(StatusCode::FORBIDDEN)
        }
    }
}

/// The one door both GitHub tools come through.
///
/// **Inside `uncancellable`, and by instruction rather than by precaution.** `submit_vcs_request`'s
/// doc names the exact condition that makes it necessary — "it stops being benign the moment
/// submitting becomes two writes … whoever writes that second write moves this through
/// `uncancellable` at the same time" — and this handler is that second write: it publishes to GitHub
/// and then records a proposal, or it records a proposal that a person will later act on. A client
/// disconnecting between the two would leave a comment posted and nothing saying so.
///
/// The cost is real and not a wrapper for free: `uncancellable` is `tokio::spawn`, so the work must
/// be `Send + 'static` and this body OWNS everything it touches. And it covers DISCONNECTION, not
/// panic — a panicking task becomes a 500 with the task gone, which for a path that has already
/// posted a comment is the same silence it protects against in the other case. Said here so nobody
/// reads the protection as larger than it is.
async fn submit_github_request(
    State(state): State<AppState>,
    Extension(scope): Extension<Scope>,
    Json(body): Json<GithubRequestBody>,
) -> Result<Json<serde_json::Value>, (StatusCode, String)> {
    github_caller_is_allowed(&scope).map_err(|status| {
        (
            status,
            "reaching GitHub is the owner's, not a run's".to_owned(),
        )
    })?;
    let submitted =
        uncancellable(
            async move { crate::github::submit(&state.pool, &state.github, body.op).await },
        )
        .await
        .map_err(|status| (status, "the github task did not finish".to_owned()))?;

    match submitted {
        Ok(crate::github::Submitted::Ran(outcome)) => Ok(Json(serde_json::json!({
            "status": "ran",
            "operation": outcome.kind,
            "exit_code": outcome.exit_code,
            "stdout": outcome.stdout,
            "output_tail": outcome.output_tail,
        }))),
        // 200 and not 202: the turn is not waiting for this and there is nothing to poll. What the
        // caller needs is the number a person will see beside it.
        Ok(crate::github::Submitted::Filed { proposal_id, kind }) => Ok(Json(serde_json::json!({
            "status": "filed_for_approval",
            "operation": kind,
            "proposal_id": proposal_id,
            "detail": format!("filed for approval as #{proposal_id}; the turn continues"),
        }))),
        Err(failure) => Err((github_failure_status(&failure), failure.to_string())),
    }
}

/// Each failure gets the status that sends a reader to the right place.
///
/// A switched-off pillar and an absent `gh` are 503: the request was fine and this machine cannot
/// serve it. A missing token is 403, because somebody has to paste a credential. A timeout is 504.
fn github_failure_status(failure: &crate::github::Failure) -> StatusCode {
    match failure {
        crate::github::Failure::NotConfigured | crate::github::Failure::MissingCli => {
            StatusCode::SERVICE_UNAVAILABLE
        }
        crate::github::Failure::MissingToken => StatusCode::FORBIDDEN,
        crate::github::Failure::TimedOut => StatusCode::GATEWAY_TIMEOUT,
        crate::github::Failure::Unknown(_) => StatusCode::INTERNAL_SERVER_ERROR,
    }
}

#[derive(Deserialize)]
struct VcsListQuery {
    project_id: Option<String>,
}

async fn list_vcs_requests(
    State(state): State<AppState>,
    Query(query): Query<VcsListQuery>,
) -> Result<Json<Vec<vcs::RequestSummary>>, StatusCode> {
    vcs::list(&state.pool, query.project_id.as_deref())
        .await
        .map(Json)
        .map_err(|error| {
            tracing::warn!(%error, "listing vcs requests failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })
}

/// Blocks up to `vcs::DEFAULT_WAIT`, then hands back whatever the ticket says.
///
/// Deliberately NOT wrapped in `uncancellable`: this handler only ever reads, so a client that
/// disconnects mid-wait costs a dropped `SELECT` loop and nothing else. The rule it must keep
/// obeying is the other one — `vcs::drain_once` executes git and must never be awaited from a
/// handler, because a disconnect there would strand a claimed row and jam the repository.
async fn wait_vcs_request(
    State(state): State<AppState>,
    Path(id): Path<i64>,
) -> Result<Json<vcs::Ticket>, StatusCode> {
    vcs_ticket(&state, id, vcs::DEFAULT_WAIT).await
}

async fn vcs_ticket(
    state: &AppState,
    id: i64,
    deadline: std::time::Duration,
) -> Result<Json<vcs::Ticket>, StatusCode> {
    match vcs::wait_for(&state.pool, id, deadline).await {
        Ok(ticket) => Ok(Json(ticket)),
        Err(sqlx::Error::RowNotFound) => Err(StatusCode::NOT_FOUND),
        Err(error) => {
            tracing::warn!(%error, id, "reading a vcs request failed");
            Err(StatusCode::INTERNAL_SERVER_ERROR)
        }
    }
}

fn agent_status(error: &agent::AgentError) -> StatusCode {
    match error {
        agent::AgentError::DuplicateName => StatusCode::CONFLICT,
        // The agent exists and the request is well formed; what refuses is the team standing on it.
        agent::AgentError::InUse => StatusCode::CONFLICT,
        agent::AgentError::Invalid(_) => StatusCode::BAD_REQUEST,
        agent::AgentError::NotFound => StatusCode::NOT_FOUND,
        agent::AgentError::Db(_) => StatusCode::INTERNAL_SERVER_ERROR,
    }
}

async fn list_agents(State(state): State<AppState>) -> Result<Json<Vec<agent::Agent>>, StatusCode> {
    agent::list(&state.pool).await.map(Json).map_err(|error| {
        tracing::warn!(%error, "listing agents failed");
        agent_status(&error)
    })
}

async fn create_agent(
    State(state): State<AppState>,
    Json(request): Json<agent::AgentRequest>,
) -> Result<Json<agent::Agent>, StatusCode> {
    agent::create(&state.pool, request)
        .await
        .map(Json)
        .map_err(|error| {
            tracing::warn!(%error, "creating agent failed");
            agent_status(&error)
        })
}

async fn get_agent(
    State(state): State<AppState>,
    Path(id): Path<String>,
) -> Result<Json<agent::Agent>, StatusCode> {
    match agent::get(&state.pool, &id).await {
        Ok(Some(found)) => Ok(Json(found)),
        Ok(None) => Err(StatusCode::NOT_FOUND),
        Err(error) => {
            tracing::warn!(agent_id = %id, %error, "reading agent failed");
            Err(agent_status(&error))
        }
    }
}

async fn update_agent(
    State(state): State<AppState>,
    Path(id): Path<String>,
    Json(request): Json<agent::AgentRequest>,
) -> Result<Json<agent::Agent>, StatusCode> {
    agent::update(&state.pool, &id, request)
        .await
        .map(Json)
        .map_err(|error| {
            tracing::warn!(agent_id = %id, %error, "updating agent failed");
            agent_status(&error)
        })
}

async fn delete_agent(
    State(state): State<AppState>,
    Path(id): Path<String>,
) -> Result<StatusCode, StatusCode> {
    agent::delete(&state.pool, &id)
        .await
        .map(|()| StatusCode::NO_CONTENT)
        .map_err(|error| {
            tracing::warn!(agent_id = %id, %error, "deleting agent failed");
            agent_status(&error)
        })
}

fn preset_status(error: &presets::PresetError) -> StatusCode {
    match error {
        presets::PresetError::DuplicateName => StatusCode::CONFLICT,
        presets::PresetError::Invalid(_) => StatusCode::BAD_REQUEST,
        presets::PresetError::NotFound => StatusCode::NOT_FOUND,
        presets::PresetError::Db(_) => StatusCode::INTERNAL_SERVER_ERROR,
    }
}

async fn list_presets(
    State(state): State<AppState>,
) -> Result<Json<Vec<presets::Preset>>, StatusCode> {
    presets::list(&state.pool).await.map(Json).map_err(|error| {
        tracing::warn!(%error, "listing presets failed");
        preset_status(&error)
    })
}

async fn create_preset(
    State(state): State<AppState>,
    Json(request): Json<presets::PresetRequest>,
) -> Result<Json<presets::Preset>, StatusCode> {
    presets::create(&state.pool, &request.name, request.run)
        .await
        .map(Json)
        .map_err(|error| {
            tracing::warn!(%error, "creating preset failed");
            preset_status(&error)
        })
}

async fn get_preset(
    State(state): State<AppState>,
    Path(id): Path<i64>,
) -> Result<Json<presets::Preset>, StatusCode> {
    presets::get(&state.pool, id)
        .await
        .map_err(|error| {
            tracing::warn!(preset_id = id, %error, "reading preset failed");
            preset_status(&error)
        })?
        .map(Json)
        .ok_or(StatusCode::NOT_FOUND)
}

async fn update_preset(
    State(state): State<AppState>,
    Path(id): Path<i64>,
    Json(request): Json<presets::PresetRequest>,
) -> Result<Json<presets::Preset>, StatusCode> {
    presets::update(&state.pool, id, &request.name, request.run)
        .await
        .map(Json)
        .map_err(|error| {
            tracing::warn!(preset_id = id, %error, "updating preset failed");
            preset_status(&error)
        })
}

async fn delete_preset(
    State(state): State<AppState>,
    Path(id): Path<i64>,
) -> Result<StatusCode, StatusCode> {
    presets::delete(&state.pool, id)
        .await
        .map(|()| StatusCode::NO_CONTENT)
        .map_err(|error| {
            tracing::warn!(preset_id = id, %error, "deleting preset failed");
            preset_status(&error)
        })
}

async fn run_preset(
    State(state): State<AppState>,
    Path(id): Path<i64>,
) -> Result<Json<runs::CreateRunResponse>, (StatusCode, String)> {
    let preset = presets::get(&state.pool, id)
        .await
        .map_err(|error| {
            tracing::warn!(preset_id = id, %error, "reading preset to run failed");
            (
                preset_status(&error),
                "the preset could not be read; the daemon logged why".to_owned(),
            )
        })?
        .ok_or((StatusCode::NOT_FOUND, format!("there is no preset {id}")))?;

    // Delegate to the sole person-initiated run front door. It owns the fail-closed global kill
    // switch, uncancellable launch window, and conversion from run-domain errors to HTTP status.
    //
    // **Which now includes the project's autopilot mode, and a preset is subject to it like any
    // other request.** A preset stored with an unattended mode against a project since switched off
    // is refused here rather than run — the alternative being a saved button that quietly does what
    // the same request typed by hand would be refused for, which is the shape of hole this door was
    // just closed against.
    //
    // The refusal's own sentence travels back out through this route rather than being flattened to
    // a bare status, which is why this signature changed with the door's.
    runs::create_run(
        State(state),
        Json(runs::CreateRunRequest {
            prompt: preset.prompt,
            project_id: preset.project_id,
            cwd: preset.cwd,
            mode: preset.mode,
            // A preset records what to run, not who may speak into it afterwards, and there is no
            // column here that could say otherwise. Every preset already stored was written before
            // steering existed, so `false` is the answer each of them was saved with — a preset must
            // not become a way to obtain a listening run that its author never asked for.
            steerable: false,
            permission_mode: None,
        }),
    )
    .await
}

async fn list_awaiting_approval_runs(
    State(state): State<AppState>,
) -> Result<Json<Vec<AwaitingRun>>, StatusCode> {
    runs::list_awaiting_approval(&state.pool)
        .await
        .map(Json)
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)
}

#[derive(Deserialize)]
struct RunMessageRequest {
    message: String,
}

/// Delivers one mid-run turn to a live run that asked to be steerable.
///
/// Every condition is read from the run's own recorded facts, never from `run_messages` holding a
/// sender for it. A channel there says a process is listening; it does not say this run was ever
/// meant to be spoken to, and treating the two as the same thing would make the barrier below
/// depend on cleanup timing rather than on a decision anyone made.
///
/// The message is queued, not delivered: the run reads it when it next reads stdin, which is why this
/// answers 202 rather than 200. What is guaranteed by the time it returns is that the text reached
/// the run's own channel and nothing else's.
async fn post_run_message(
    State(state): State<AppState>,
    Path(id): Path<i64>,
    Json(body): Json<RunMessageRequest>,
) -> Result<StatusCode, StatusCode> {
    let run = sqlx::query_as::<_, (String, String, i64)>(
        "SELECT status, mode, steerable FROM runs WHERE id = ?",
    )
    .bind(id)
    .fetch_optional(&state.pool)
    .await
    .map_err(|error| {
        tracing::warn!(run_id = id, %error, "reading a run to steer failed");
        StatusCode::INTERNAL_SERVER_ERROR
    })?;
    let Some((status, mode, steerable)) = run else {
        return Err(StatusCode::NOT_FOUND);
    };

    // Opting in is what gives the CLI a stdin at all. A run without it has no channel to reach, so
    // the answer is no rather than text buffered for a process that will never read it.
    if steerable == 0 {
        return Err(StatusCode::CONFLICT);
    }
    // A finished run has no process left to tell. Accepting anyway would record an instruction
    // against a transcript that ended before it arrived, which reads afterwards as something the run
    // was told and ignored.
    if status != "running" {
        return Err(StatusCode::CONFLICT);
    }
    // Spec §5.5 from the other side. The pillar's premise is that text a stranger wrote never meets a
    // tool; steering adds a second author to a live session, and the one session that must never gain
    // an author is the one already holding a stranger's words. Kept as two questions — where the run
    // came from, and what it may touch — because they coincide only while there is one toolless mode.
    if mode == crate::email::TRIAGE_MODE {
        return Err(StatusCode::FORBIDDEN);
    }
    if runs::tool_policy_for_mode(&mode) == crate::runner::ToolPolicy::None {
        return Err(StatusCode::FORBIDDEN);
    }

    let sender = state.run_messages.lock().unwrap().get(&id).cloned();
    let Some(sender) = sender else {
        return Err(StatusCode::CONFLICT);
    };
    // Raw text, and no pictures: framing a turn as a `stream-json` line is `runner.rs`'s job,
    // because knowing the CLI's wire format is what that module is for, and a second copy of that
    // shape here would drift the day the format does. This route takes a message and nothing else —
    // the door that carries pictures is a conversation's, not a run's.
    sender
        .send(crate::runner::LaterTurn {
            text: body.message,
            images: Vec::new(),
            interrupt: false,
        })
        .map_err(|_| StatusCode::CONFLICT)?;
    Ok(StatusCode::ACCEPTED)
}

/// Says that the turn just sent was the last one, and is what lets a steerable run end at all.
///
/// A run launched with `--input-format stream-json` reads turns until stdin closes, and the daemon
/// holds that stdin open for as long as it holds the run's sender. Without a way to let go of it,
/// such a run could only stop by going silent long enough to trip its progress deadline — and be
/// recorded `timed_out`, a failure status, for having been left listening. Closing the channel gives
/// the CLI its EOF, so the turn ends the way an ordinary run's does and the run is recorded on what
/// it actually did.
///
/// DELETE, and idempotent with it: a channel that is already closed is the state the caller asked
/// for, not a conflict. It answers 204 for any run that exists, whether or not that run was ever
/// listening, because "no such channel" is also what a run that finished a moment ago looks like —
/// and a caller that had to tell those two apart would be handling a race instead of ending a
/// conversation.
///
/// No steering barrier here, deliberately, and it does not narrow the one on `post_run_message`.
/// That barrier exists because steering ADDS an author to a live session; this takes nothing from
/// the caller and puts nothing in the run's context. The only thing it can do is end a conversation,
/// and there is no run for which ending one is the unsafe direction.
async fn delete_run_message(
    State(state): State<AppState>,
    Path(id): Path<i64>,
) -> Result<StatusCode, StatusCode> {
    let known = sqlx::query_scalar::<_, i64>("SELECT 1 FROM runs WHERE id = ?")
        .bind(id)
        .fetch_optional(&state.pool)
        .await
        .map_err(|error| {
            tracing::warn!(run_id = id, %error, "reading a run to close its turns failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })?;
    if known.is_none() {
        return Err(StatusCode::NOT_FOUND);
    }
    runs::close_steering_channel(&state, id);
    Ok(StatusCode::NO_CONTENT)
}

/// One exchange in a chat, as it is read back.
///
/// The reply is the run's stdout and the failure its stderr, which is what the shell was already
/// pulling out of the run detail — carried here so reopening a conversation does not mean one
/// request per turn.
#[derive(serde::Serialize, sqlx::FromRow)]
struct AssistantTurn {
    id: i64,
    asked: String,
    answer: Option<String>,
    error: Option<String>,
    status: String,
    cost_usd: Option<f64>,
    /// Which model answered. Null on turns from before the column existed, and the window must keep
    /// that distinction: it is what stops a "changed model here" mark being drawn against a turn
    /// nothing knows the model of.
    answered_by: Option<String>,
    /// The CLI session this turn ran in.
    ///
    /// Travels to the window so it can say where the conversation RESTARTED. `get_session` refuses
    /// to resume a session that read third-party text, and `POST /fresh-context` drops one on
    /// request; the next turn then mints a fresh id — so a change here is the moment the model
    /// stopped remembering what came before it. Without it, that happens and the transcript above
    /// and below looks like one unbroken conversation, which is the one thing it is not.
    ///
    /// It used to change on SIZE as well, which made this the ordinary fate of any long
    /// conversation. It is now the rare one: a full context is compacted, and `compacted` below is
    /// what says so.
    session_id: Option<String>,
    created_at: String,
    /// When the turn ended, in `created_at`'s format, or null while it runs. The Chats window
    /// counts the prompt cache down from here.
    completed_at: Option<String>,
    /// The model the CLI reported answering with, or null when the stream never said and on
    /// every turn from before it was recorded. Distinct from `answered_by`, which says WHO.
    model: Option<String>,
    /// How long this turn's prompt cache lives: `"5m"`, `"1h"`, or null when unknown.
    cache_ttl: Option<String>,
    /// How much context this turn ran with, as an absolute token count. Null on a turn whose stream
    /// never reported one -- a turn that failed before the CLI said anything, and every turn from
    /// before the column existed.
    context_fill: Option<i64>,
    /// What the turn ran, as the JSON `tools_used` holds. Not serialized: the window is given the
    /// parsed list below, so the shape of the column is this daemon's business and not a format
    /// two codebases have to agree on.
    #[serde(skip)]
    tools_used: Option<String>,
    /// What the turn thought, as the JSON `thought` holds. Not serialized, for the reason above it.
    #[serde(skip)]
    thought: Option<String>,
    /// Where the turn's pictures were kept, as the JSON `prompt_images` holds. Not serialized, for
    /// the reason above it.
    #[serde(skip)]
    prompt_images: Option<String>,
    /// Roughly how many tokens the turn spent thinking, or null when it did not think and on every
    /// turn from before the column. Serialized as it stands: it is a number, not a private shape.
    thought_tokens: Option<i64>,
    /// Whether the CLI summarised its own context while producing this turn.
    ///
    /// This is what replaced the restart mark for the ordinary case. A conversation no longer
    /// changes session when it fills up — it is compacted in place — so the fact the window has
    /// to draw moved from `session_id` to here, and it says a milder and truer thing: the older
    /// exchanges were summarised at this point, not forgotten at this point.
    compacted: bool,
    /// The conversation that handed this turn its words, or null for the ordinary case — somebody
    /// typed them here.
    ///
    /// Without it the window draws a relayed turn under "you", which is the one thing it is not:
    /// the words arrived from another conversation, and a transcript that attributes them to the
    /// person reading it is not a cosmetic problem but a false record of who said what.
    ///
    /// Two columns and not one, because the pair answers two different questions and either can be
    /// absent on its own. The id is what the conversation IS and is always there when a turn was
    /// relayed at all; the title is what somebody called it and is null on every conversation
    /// nobody has named — which is most of them, since a title is written by the daemon only once
    /// a chat has been summarised. A window given only the title could not say anything about an
    /// unnamed conversation; given only the id it would print a uuid at a person.
    relayed_from_chat_id: Option<String>,
    /// What that conversation is called, or null when it has no title yet. See above.
    relayed_from_title: Option<String>,
}

/// One turn as the window receives it: the row, plus what the turn did.
///
/// The parse happens here rather than in the window for the reason it happens in `runner.rs` at
/// all: the column holds a serialisation this daemon chose, and a client re-deriving it would be a
/// second reader of a private shape. A column that will not parse reads as an empty list — the turn
/// is real and its reply is worth showing, and one unreadable field is not worth losing it over.
/// One relay a turn sent: where it went, and what it said.
///
/// Read off `chat_relays` rather than off the tool call the CLI reported, and the difference is not
/// cosmetic. The relay row is what the daemon ADMITTED and wrote; a tool call is what the model
/// asked for, and the two part company every time `relay::admit` refuses — a cycle, a chain too
/// deep, an owner who has gone away. A sender's transcript built from the asks would show messages
/// that never arrived, which is the one thing it must not do.
#[derive(serde::Serialize, sqlx::FromRow)]
struct RelaySent {
    /// The conversation the message went to. Always present; the title beside it may not be.
    chat_id: String,
    /// What that conversation is called, or null when nobody has named it yet.
    title: Option<String>,
    /// The words that travelled, whole. The same string the destination's own turn was created
    /// with, so the two sides of one relay cannot disagree about what was said.
    body: String,
    /// Which turn sent it. Not serialized — the window receives these already grouped under their
    /// turn, and repeating the key inside every value is a second copy of the same fact.
    #[serde(skip)]
    sending_run_id: i64,
}

#[derive(serde::Serialize)]
struct AssistantTurnOut {
    #[serde(flatten)]
    turn: AssistantTurn,
    did: Vec<crate::runner::ToolCall>,
    /// The pictures this turn was sent with, as paths under the files root.
    ///
    /// Paths and not bytes, all the way to the window: it asks the files route for each one, which
    /// means a transcript of forty turns costs forty short strings rather than forty screenshots.
    images: Vec<String>,
    /// What the turn thought before it answered, oldest first.
    ///
    /// Empty both for a turn that thought nothing and for a turn from before the column. The two
    /// are different facts and the row keeps them apart, but a window cannot act on the difference:
    /// either way there is nothing to draw.
    thought: Vec<String>,
    /// The context window this conversation runs in, in tokens.
    ///
    /// It used to be `context_rotates_at`: the count past which the daemon stopped resuming and
    /// minted a fresh session. Nothing rotates now — the CLI compacts inside the session — so the
    /// number means the window rather than the cliff, and the name had to move with it.
    ///
    /// The same on every row of one conversation and NOT the same across conversations, which is
    /// why it still rides here rather than being a constant the window keeps its own copy of: a
    /// chat picked up from the editor runs in a wider window than the default, and a meter drawn
    /// against the default would be wrong for exactly the conversations nearest their limit.
    context_window: i64,
    /// The relays this turn sent, oldest first. Empty for almost every turn.
    ///
    /// The mirror of `relayed_from_chat_id` on the receiving side, and it exists because that side
    /// shipped alone: the conversation certain to be watched by the person who caused a relay was
    /// the one that could not say what it had done.
    relayed_to: Vec<RelaySent>,
    /// What was said INTO this turn while it ran ("Send now"), oldest first. Empty for almost every
    /// turn. The CLI folds such a line into the running turn, so the stream never shows it as
    /// typed and this is the only record.
    said_now: Vec<crate::assistant::SaidDuring>,
}

/// A conversation as it is read back: its turns, and whatever it was handed before the first one.
///
/// An object rather than the bare array this used to be, because a transcript is not only its
/// turns. A chat picked up from a session too large to resume begins with the verbatim tail of that
/// session in front of it, the model answers from that tail — and nothing in the window said so.
/// You asked, it replied knowing a past it never lived, and the reason sat in a column.
///
/// `handoff.rs` states the rule this serves: context pressure must leave an auditable record rather
/// than quietly erase how work continued. A compaction that is stored and never shown is still an
/// erasure from where the person is standing.
#[derive(serde::Serialize)]
struct TranscriptOut {
    /// The exchanges this conversation was handed, oldest first. Empty for an ordinary chat, which
    /// is most of them, and empty rather than absent so a reader never has to branch on missing.
    handed: Vec<(String, String)>,
    turns: Vec<AssistantTurnOut>,
    /// What was said to this conversation while it was busy, and has not been sent yet, each with
    /// the name it can be taken back by.
    ///
    /// Here rather than on its own route because it belongs to the same picture and moves on the
    /// same poll: the window draws it under the last turn, where the answer will land.
    queued: Vec<crate::chats::Waiting>,
    /// What this conversation is waiting to be allowed to do, which is nearly always nothing.
    ///
    /// Here for the reason `queued` is, and one more: this is polled at a turn's own cadence while a
    /// turn is live, which is exactly when a question can appear — a route of its own would need a
    /// second poll at the same speed to say "nothing" almost every time.
    asks: Vec<crate::hooks::Ask>,
    /// Whether there are turns older than the oldest one in `turns`.
    ///
    /// A conversation is read from its recent end and cut at `ASSISTANT_TRANSCRIPT_LIMIT`, and
    /// until this existed the cut was silent: the hundred-and-first turn simply was not there, and
    /// nothing on the page distinguished a conversation that started where you were looking from
    /// one whose first afternoon had been dropped off the top. This is what lets the window offer
    /// to go and get the rest.
    more: bool,
    /// What departments said in this conversation, oldest first. Empty for almost every chat.
    ///
    /// A list of its own beside `turns` rather than folded into them, because a notice is not a
    /// turn: nothing was asked, nothing ran, nothing was spent, and there is no answer. Giving it a
    /// turn's shape would mean inventing a prompt nobody typed. The window interleaves the two by
    /// `created_at`, which is the only place the two orders have to meet.
    notices: Vec<crate::chat_notices::ChatNotice>,
}

/// Which slice of a conversation to read back.
#[derive(serde::Deserialize)]
struct TranscriptQuery {
    /// Read the turns immediately BEFORE this one, rather than the most recent.
    ///
    /// Absent is the ordinary case and means the recent end. A page walks backwards by handing
    /// back the id of the oldest turn it has, which is stable in a way an offset is not: turns are
    /// only ever appended, so an offset from the end shifts under a conversation that answers
    /// while somebody is reading it and a page boundary would repeat or skip a turn.
    before: Option<i64>,
    /// Read only the turns AFTER this one — the poll's incremental read.
    ///
    /// A page that already holds every settled turn up to this id asks only for what lies past it,
    /// rather than having the newest hundred turns, answers and thoughts included, re-sent every
    /// second and a half. `more` keeps its meaning: there were more rows in the window than the
    /// limit returned, which on this read tells the page its watermark is too far behind to catch
    /// up incrementally and a full read is the answer.
    after: Option<i64>,
}

/// How many turns of a conversation are read back. A chat is read from its recent end.
const ASSISTANT_TRANSCRIPT_LIMIT: i64 = 100;

/// The longest query the name completion will act on.
///
/// Not a safety limit — `mentions::matching` walks the same tree whatever it is given. It is a
/// statement about what the field is for: past this, what arrived is not somebody typing a filename
/// and answering it as though it were would be answering the wrong question slowly.
const MENTION_QUERY_LIMIT: usize = 100;

#[derive(serde::Deserialize)]
struct MentionQuery {
    /// What has been typed after the `@`. Absent or empty asks for the top level.
    #[serde(default)]
    q: String,
}

/// The names a conversation offers, and whether it had anywhere to look at all.
///
/// `rooted` is the distinction an empty list cannot draw: "nothing here matches what you typed" and
/// "this conversation has no directory" look identical to a caller and are entirely different
/// facts. Only the second is worth a sentence in the window.
#[derive(serde::Serialize)]
struct MentionsOut {
    rooted: bool,
    #[serde(flatten)]
    found: crate::mentions::Found,
}

/// What a conversation offers for a `/`.
///
/// No `rooted` here, unlike the file route beside it, and the difference is real: a conversation
/// with no directory still has the person's own commands and every installed plugin's. Nowhere to
/// look is a thing that can only be true of files.
#[derive(serde::Serialize)]
struct CommandsOut {
    commands: Vec<crate::commands::Command>,
}

/// The slash commands this conversation can run.
///
/// Three sources, read on the request rather than cached: a command is a file somebody just wrote,
/// and a picker that needed a daemon restart to notice it would be a picker people stop trusting.
/// Measured on this machine at about 7ms for the whole sweep, which is a keystroke's worth.
async fn get_chat_commands(
    State(state): State<AppState>,
    Path(chat_id): Path<String>,
    Query(query): Query<MentionQuery>,
) -> Result<Json<CommandsOut>, StatusCode> {
    let cwd = crate::chats::opened_in(&state.pool, &chat_id)
        .await
        .map_err(|error| {
            tracing::warn!(%error, "reading where a conversation runs failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })?
        .ok_or(StatusCode::NOT_FOUND)?;

    let typed: String = query.q.chars().take(MENTION_QUERY_LIMIT).collect();
    // Off the async runtime, as the file walk is: this reads several directories and every command
    // file's front matter, which is short but is still disk on a request thread.
    let commands = tokio::task::spawn_blocking(move || {
        let available = crate::commands::available(
            cwd.as_deref().map(std::path::Path::new),
            crate::commands::home().as_deref(),
        );
        crate::commands::matching(&available, &typed)
    })
    .await
    .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;

    Ok(Json(CommandsOut { commands }))
}

/// What is different in a conversation's project, as `git diff` writes it.
///
/// The question a person has after a coding turn is "what changed", and answering it used to mean
/// leaving the app: the transcript names the tool and the file and stops there.
///
/// **Not what the turn did, and never labelled as such.** The daemon takes no snapshot before a
/// turn, so this is what is different NOW — the same thing after one turn, and not after three. The
/// honest claim is the one this makes.
///
/// `inspect::diff` and not a `git diff` of its own: that one already turns off every setting a
/// target repository could use to run a command string as the daemon user, and carries the deadline
/// and output ceiling this needs for exactly the same reasons.
async fn get_chat_diff(
    State(state): State<AppState>,
    Path(chat_id): Path<String>,
) -> Result<String, StatusCode> {
    let cwd = crate::chats::opened_in(&state.pool, &chat_id)
        .await
        .map_err(|error| {
            tracing::warn!(%error, "reading a conversation's project failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })?
        .ok_or(StatusCode::NOT_FOUND)?
        // 409 and not an empty answer. An empty diff is a claim — "nothing has changed" — and a
        // conversation with no project is not in a position to make it.
        .ok_or(StatusCode::CONFLICT)?;

    let root = std::path::PathBuf::from(cwd);
    tokio::task::spawn_blocking(move || inspect::diff(&root))
        .await
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?
        // A directory that is not a repository has nothing to say, which is an empty answer rather
        // than a refusal: the conversation is fine, its project simply is not under git.
        .or_else(|error| match error {
            inspect::InspectError::Io(_) => Ok(String::new()),
            other => Err(inspect_status(other)),
        })
}

/// `GET /assistant/chats/{chat_id}/tasks`. The subagents and background tasks this conversation's
/// turns launched, oldest first; 404 for a conversation that does not exist.
async fn get_chat_tasks(
    State(state): State<AppState>,
    Path(chat_id): Path<String>,
) -> Result<Json<Vec<crate::chat_tasks::ChatTask>>, StatusCode> {
    crate::chats::opened_in(&state.pool, &chat_id)
        .await
        .map_err(|error| {
            tracing::warn!(%error, "reading a conversation failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })?
        .ok_or(StatusCode::NOT_FOUND)?;
    crate::chat_tasks::for_chat(&state.pool, &chat_id)
        .await
        .map(Json)
        .map_err(|error| {
            tracing::warn!(%error, "reading a conversation's tasks failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })
}

/// What the window says when somebody answers for a held tool call.
#[derive(serde::Deserialize)]
struct AskAnswer {
    allow: bool,
}

/// Answers a tool call a conversation is being held on.
///
/// 404 when there was nothing to answer, which covers both ways that happens: the window is a poll
/// behind and the turn has moved on, or the question timed out while somebody was reading it. The
/// same answer on purpose — the caller's next read tells them which.
async fn post_ask_answer(
    Path(ask_id): Path<String>,
    Json(body): Json<AskAnswer>,
) -> Result<StatusCode, StatusCode> {
    match crate::hooks::answer_ask(&ask_id, body.allow) {
        true => Ok(StatusCode::NO_CONTENT),
        false => Err(StatusCode::NOT_FOUND),
    }
}

/// What the hook says while it waits.
#[derive(serde::Deserialize)]
struct AskWaitRequest {
    run_id: i64,
}

/// Holds the hook's call open until somebody answers for this turn's tool call.
///
/// The one route here that is SUPPOSED to block. The CLI is sitting on a hook call, the model is
/// sitting behind that, and a person is being asked a question — so the honest shape is a call that
/// does not return until there is an answer or the window closes.
///
/// Refuses on every path that is not a clear yes: nobody answered, the question is gone, this run
/// has none. A turn that cannot be allowed is refused, never allowed by default.
async fn post_ask_wait(
    Extension(scope): Extension<crate::auth::Scope>,
    Json(body): Json<AskWaitRequest>,
) -> Json<crate::hooks::Decision> {
    // The key decides which turn this is, for the reason `pretooluse_decision` gives at length: the
    // body is a claim, and a CLI kept alive across turns claims whatever it was spawned with.
    let run_id = match scope {
        crate::auth::Scope::Run(id) => id,
        _ => body.run_id,
    };

    match crate::hooks::wait_for_run(run_id, crate::hooks::ASK_WINDOW).await {
        Some(true) => Json(crate::hooks::Decision {
            decision: "allow".to_owned(),
            reason: "you allowed this".to_owned(),
        }),
        Some(false) => Json(crate::hooks::Decision {
            decision: "deny".to_owned(),
            reason: "you refused this".to_owned(),
        }),
        None => Json(crate::hooks::Decision {
            decision: "deny".to_owned(),
            reason: "nobody answered for this in time".to_owned(),
        }),
    }
}

/// Where a conversation runs, and whether that gives its turns tools.
#[derive(serde::Serialize)]
struct ChatProjectOut {
    /// The project this conversation is about, or `null` for one that has none.
    cwd: Option<String>,
    /// The session a terminal standing in `cwd` could carry this conversation on in, or `null`.
    ///
    /// `claude --resume <this>` from that directory continues it — measured, with a word said only
    /// to the daemon coming back out of the CLI. The way back was always there and nothing said so.
    ///
    /// `null` when the daemon itself would not resume it: a rotated conversation, or one that has
    /// read a stranger's text. Offering an id the daemon has refused would be sending somebody
    /// somewhere it will not go.
    session: Option<String>,
    /// What this conversation may do without being asked.
    ///
    /// Beside the tools and not beside the title, because it is the same question in the other
    /// direction: one says what this conversation CAN do, the other says what it will choose not to.
    ///
    /// The remembered position of the selector — what the NEXT message runs under. Never the
    /// snapshot on the run, which is a different fact with a different lifetime: that one says what
    /// a turn already in flight started with, and nothing in the window reads it.
    permission_mode: crate::chats::PermissionMode,
    /// Whether a turn here would actually get Bash, Read and Write.
    ///
    /// Not the same fact as having a directory, which is why both travel. `tool_policy_for` wants
    /// the classifier hook wired in that directory too — every fresh worktree lacks it, since
    /// `.claude/` is not committed — so a conversation pointed at one still cannot open a file, and
    /// a window that reported only the directory would be telling the truth and misleading at once.
    tools: bool,
    /// Whether this conversation's turns use the user's ambient MCP servers. Off until somebody
    /// opts in.
    ambient_mcp: bool,
    /// Whether `cwd` is a linked worktree the AI workflow was never copied into while its main
    /// checkout has it — the case "Set up workflow" answers.
    workflow_missing: bool,
}

/// Where a conversation runs, and whether that gives it tools.
async fn read_chat_project(
    State(state): State<AppState>,
    Path(chat_id): Path<String>,
) -> Result<Json<ChatProjectOut>, StatusCode> {
    // `opened_in` and not `cwd_of`, because the two absences are different answers: a chat that is
    // not there is a 404, and one with no directory is a conversation this route has something to
    // say about.
    let opened_in = crate::chats::opened_in(&state.pool, &chat_id)
        .await
        .map_err(|error| {
            tracing::warn!(%error, "reading a conversation's project failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })?
        .ok_or(StatusCode::NOT_FOUND)?;

    // Read for both answers below, because a conversation with no directory can still be carried
    // on somewhere — the terminal just has to be standing where it was had.
    let session = crate::assistant::get_session(&state.pool, &chat_id)
        .await
        .unwrap_or(None);
    let permission_mode = crate::chats::permission_mode_of(&state.pool, &chat_id)
        .await
        .unwrap_or(crate::chats::PermissionMode::Auto);
    let ambient_mcp = crate::chats::ambient_mcp_of(&state.pool, &chat_id)
        .await
        .unwrap_or(false);

    let Some(cwd) = opened_in else {
        return Ok(Json(ChatProjectOut {
            cwd: None,
            session,
            permission_mode,
            tools: false,
            ambient_mcp,
            workflow_missing: false,
        }));
    };

    // An unreadable roster offers nothing: the setup runs a script, so it fails closed.
    let roots = crate::autopilot::rostered_roots(&state.pool)
        .await
        .unwrap_or_default();
    let dir = std::path::PathBuf::from(&cwd);
    let (wired, workflow_missing) = tokio::task::spawn_blocking(move || {
        (
            crate::autopilot::classifier_hook_is_wired(&dir),
            crate::autopilot::workflow_missing(&dir, &roots),
        )
    })
    .await
    .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;

    // Asked of the same function the turn path asks, rather than restated here. A second copy of
    // this rule would be a second thing to keep true, and the one that answers the window is the
    // one that must agree with the one that launches the run.
    // `false`: this answers what the person's OWN next message would get, which is the only thing
    // the window can offer them. A relayed turn's policy is not a property of the conversation and
    // is not previewable here — it is decided per turn, by the turn that carries a relay id.
    let tools = crate::assistant::tool_policy_for(
        Some(cwd.as_str()),
        crate::assistant::Origin::Shell,
        wired,
        false,
    ) == crate::runner::ToolPolicy::Unrestricted;

    Ok(Json(ChatProjectOut {
        cwd: Some(cwd),
        session,
        permission_mode,
        tools,
        ambient_mcp,
        workflow_missing,
    }))
}

/// Wires the classifier hook in a conversation's project, which is what gives its turns tools.
async fn wire_chat_tools(
    State(state): State<AppState>,
    Path(chat_id): Path<String>,
) -> Result<StatusCode, StatusCode> {
    let cwd = crate::chats::opened_in(&state.pool, &chat_id)
        .await
        .map_err(|error| {
            tracing::warn!(%error, "reading a conversation's project failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })?
        .ok_or(StatusCode::NOT_FOUND)?
        // Nothing to wire and nothing to guess. A silent success here would be this route reporting
        // "done" about a directory nobody has named.
        .ok_or(StatusCode::CONFLICT)?;

    let dir = std::path::PathBuf::from(&cwd);
    tokio::task::spawn_blocking(move || crate::autopilot::wire_classifier_hook(&dir))
        .await
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?
        .map_err(|error| {
            tracing::warn!(%error, cwd = %cwd, "could not wire a conversation's project");
            StatusCode::CONFLICT
        })?;

    Ok(StatusCode::NO_CONTENT)
}

#[derive(serde::Deserialize)]
struct SeedWorkflowIn {
    #[serde(default)]
    confirm: bool,
}

/// Copies the AI workflow into a conversation's worktree from its main checkout, then wires the
/// hook. Overwrites the worktree's workflow core, so it runs only on an explicit `confirm: true`.
async fn seed_chat_workflow(
    State(state): State<AppState>,
    Path(chat_id): Path<String>,
    Json(body): Json<SeedWorkflowIn>,
) -> Result<StatusCode, StatusCode> {
    // Checked first: nothing below runs on anything but an explicit yes.
    if !body.confirm {
        return Err(StatusCode::BAD_REQUEST);
    }
    let cwd = crate::chats::opened_in(&state.pool, &chat_id)
        .await
        .map_err(|error| {
            tracing::warn!(%error, "reading a conversation's project failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })?
        .ok_or(StatusCode::NOT_FOUND)?
        .ok_or(StatusCode::CONFLICT)?;

    let roots = crate::autopilot::rostered_roots(&state.pool)
        .await
        .map_err(|error| {
            tracing::warn!(%error, "reading the project roster failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })?;

    match crate::autopilot::seed_workflow(std::path::Path::new(&cwd), &roots).await {
        Ok(()) => Ok(StatusCode::NO_CONTENT),
        Err(
            crate::autopilot::SeedRefusal::NotAWorktree
            | crate::autopilot::SeedRefusal::NoWorkflowInMain
            | crate::autopilot::SeedRefusal::MainNotRostered,
        ) => Err(StatusCode::CONFLICT),
        // Same answer `wire_chat_tools` gives when the hook cannot be written.
        Err(crate::autopilot::SeedRefusal::NotWired(error)) => {
            tracing::warn!(%error, cwd = %cwd, "could not wire a conversation's project after seeding it");
            Err(StatusCode::CONFLICT)
        }
        Err(crate::autopilot::SeedRefusal::Failed(error)) => {
            tracing::warn!(%error, cwd = %cwd, "could not set up the workflow in a conversation's worktree");
            Err(StatusCode::INTERNAL_SERVER_ERROR)
        }
    }
}

/// Takes a message back off a conversation's queue before it is sent.
///
/// 404 when there was nothing to take, which covers both of the ways that happens: a message the
/// drain sent a moment ago, and one that belongs to a different conversation. They are the same
/// answer on purpose — a caller learning which of the two it was would be learning something about
/// somebody else's queue.
async fn delete_queued(
    State(state): State<AppState>,
    Path((chat_id, queued_id)): Path<(String, i64)>,
) -> Result<StatusCode, StatusCode> {
    match crate::chats::drop_queued(&state.pool, &chat_id, queued_id).await {
        Ok(true) => Ok(StatusCode::NO_CONTENT),
        Ok(false) => Err(StatusCode::NOT_FOUND),
        Err(error) => {
            tracing::warn!(%error, "taking a message off a queue failed");
            Err(StatusCode::INTERNAL_SERVER_ERROR)
        }
    }
}

/// Names under this conversation's own working directory, for completing an `@'`.
///
/// The root comes from the chat's row and never from the caller. A route that took a directory
/// would be a route that reads any directory — and there is nothing to gain by it: the only
/// defensible root is where this conversation's turns already run, because the model can open those
/// files anyway and naming them discloses nothing it could not read.
///
/// A directory that is gone reads as `rooted: false` rather than as an empty search. It is the same
/// fact as having none: there is nowhere to look, and saying "no matches" would send somebody
/// hunting for a spelling mistake.
async fn get_chat_files(
    State(state): State<AppState>,
    Path(chat_id): Path<String>,
    Query(query): Query<MentionQuery>,
) -> Result<Json<MentionsOut>, StatusCode> {
    let cwd = crate::chats::opened_in(&state.pool, &chat_id)
        .await
        .map_err(|error| {
            tracing::warn!(%error, "reading where a conversation runs failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })?
        .ok_or(StatusCode::NOT_FOUND)?;

    let Some(cwd) = cwd else {
        return Ok(Json(MentionsOut {
            rooted: false,
            found: crate::mentions::Found {
                hits: Vec::new(),
                truncated: false,
            },
        }));
    };

    let typed: String = query.q.chars().take(MENTION_QUERY_LIMIT).collect();
    // Off the async runtime: this is a directory walk on a keystroke, and holding a runtime thread
    // for it would stall every other request sharing that thread.
    let answered = tokio::task::spawn_blocking(move || {
        let root = std::path::Path::new(&cwd);
        root.is_dir()
            .then(|| crate::mentions::matching(root, &typed))
    })
    .await
    .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;

    Ok(Json(match answered {
        Some(found) => MentionsOut {
            rooted: true,
            found,
        },
        None => MentionsOut {
            rooted: false,
            found: crate::mentions::Found {
                hits: Vec::new(),
                truncated: false,
            },
        },
    }))
}

/// Every relay sent by any of `turns`, in one read.
///
/// An `IN` list built from the turn ids rather than a query per turn: this runs on every transcript
/// poll, which is every second and a half while a turn is live.
///
/// Empty turns answer empty without touching the database — an `IN ()` is not valid SQLite, and
/// building the statement anyway to discover that would be a round trip to learn something already
/// known.
async fn relays_sent_by(
    pool: &sqlx::SqlitePool,
    turns: &[AssistantTurn],
) -> sqlx::Result<Vec<RelaySent>> {
    if turns.is_empty() {
        return Ok(Vec::new());
    }
    // `QueryBuilder` rather than a formatted string, which is the shape this codebase already uses
    // for runtime assembly (`feed.rs`, `notes.rs`). `push_bind` writes the placeholder AND binds the
    // value in one step, so the count of `?` and the count of arguments cannot drift apart — the one
    // mistake a hand-built `IN` list invites.
    let mut query = sqlx::QueryBuilder::<sqlx::Sqlite>::new(
        "SELECT rel.to_chat_id AS chat_id, dst.title AS title, rel.body AS body,
                rel.sending_run_id AS sending_run_id
           FROM chat_relays rel
           LEFT JOIN chats dst ON dst.chat_id = rel.to_chat_id
          WHERE rel.sending_run_id IN (",
    );
    // LEFT JOIN above for the reason the transcript's own join gives: a destination nobody has
    // named has no title and must still resolve, and one archived since still has its row.
    let mut separated = query.separated(", ");
    for turn in turns {
        separated.push_bind(turn.id);
    }
    query.push(") ORDER BY rel.id");
    query.build_query_as::<RelaySent>().fetch_all(pool).await
}

/// A chat's turns, oldest first.
///
/// The daemon has always kept these — a turn is a run — but nothing on the row said which chat it
/// belonged to, so the shell's transcript could only live in the window that made it and died with
/// a reload. Reconstructing it from `/runs?mode=assistant` was never an option: that is every
/// chat's turns at once, the Telegram sidecar's included.
///
/// Ordered by id rather than by `created_at`: two turns of the same conversation can share a
/// timestamp to the second, and a transcript that reorders itself is one you lose your place in.
/// The limit takes the LAST turns and then puts them back in order, so a long conversation opens on
/// its recent end rather than on its beginning.
async fn get_assistant_chat(
    State(state): State<AppState>,
    Path(chat_id): Path<String>,
    Query(query): Query<TranscriptQuery>,
) -> Result<Json<TranscriptOut>, StatusCode> {
    // `?` on a missing bound reads as no bound: `i64::MAX` is above every id this table will ever
    // hold, so one query serves both the recent end and a page above it. Two queries differing by
    // a single clause is how the two come to disagree about ordering.
    let before = query.before.unwrap_or(i64::MAX);
    // Absent reads as 0, below every id, for the same reason `before` reads as `i64::MAX`.
    let after = query.after.unwrap_or(0);
    // One more than asked for, and it is never returned. Whether there is anything above this page
    // is a question about the row after the last one, and asking for it here answers it for the
    // price of a row rather than with a second COUNT over the same index.
    //
    // Two LEFT JOINs, and left rather than inner for the obvious reason and a less obvious one:
    // almost every turn has no relay behind it, and an inner join would return only the relayed
    // ones — but also, a relay row whose source conversation has since been ARCHIVED still has a
    // `chats` row and still resolves, which is what keeps a transcript readable after the far side
    // of a conversation is put away. `src.title` being null is an unnamed conversation, not a
    // missing one; the id beside it always resolves.
    let mut turns = sqlx::query_as::<_, AssistantTurn>(
        "SELECT r.id, r.prompt AS asked, r.stdout AS answer, r.stderr AS error, r.status,
                r.cost_usd, r.answered_by, r.session_id, r.created_at, r.completed_at,
                r.model, r.cache_ttl, r.context_fill,
                r.tools_used, r.thought, r.thought_tokens, r.prompt_images, r.compacted,
                rel.from_chat_id AS relayed_from_chat_id,
                src.title        AS relayed_from_title
           FROM runs r
           LEFT JOIN chat_relays rel ON rel.id = r.from_relay_id
           LEFT JOIN chats src ON src.chat_id = rel.from_chat_id
          WHERE r.chat_id = ? AND r.mode = 'assistant' AND r.id < ? AND r.id > ?
          ORDER BY r.id DESC
          LIMIT ?",
    )
    .bind(&chat_id)
    .bind(before)
    .bind(after)
    .bind(ASSISTANT_TRANSCRIPT_LIMIT + 1)
    .fetch_all(&state.pool)
    .await
    .map_err(|error| {
        tracing::warn!(%error, "reading an assistant chat failed");
        StatusCode::INTERNAL_SERVER_ERROR
    })?;
    let more = turns.len() as i64 > ASSISTANT_TRANSCRIPT_LIMIT;
    turns.truncate(ASSISTANT_TRANSCRIPT_LIMIT as usize);
    turns.reverse();
    // One query for the whole transcript, not one per turn. This route is polled every second and a
    // half while a turn is live, so a per-turn read here would be a hidden multiplier on the most
    // frequent request this daemon serves — for a list that is empty on almost every turn.
    //
    // Empty on a failure rather than a 500, the same trade the queue read below makes: a transcript
    // is the point of this request, and losing the note about what a turn forwarded is a smaller
    // loss than a conversation that will not open.
    let sent = relays_sent_by(&state.pool, &turns)
        .await
        .unwrap_or_default();
    // Empty on a failure, for the same trade: losing the note about what was said mid-turn is a
    // smaller loss than a conversation that will not open.
    let said = crate::assistant::said_during(&state.pool, &chat_id)
        .await
        .unwrap_or_default();
    // Read through `assistant::handed_over` rather than parsed here: that function is already the
    // one reader of the column's shape, and a second one is a second thing to change the day the
    // shape does. A chat that was handed nothing comes back empty, which is the honest answer for
    // every ordinary conversation.
    let handed = crate::assistant::handed_over(&state.pool, &chat_id).await;
    // Read once for the whole transcript rather than per turn: it is a property of the
    // conversation, and forty rows asking the same question of the same row is thirty-nine
    // round trips nobody needs. A failure reads as the default, which is what every conversation
    // that never touched this column runs in anyway.
    let context_window = crate::assistant::window_of(
        crate::chats::answering(&state.pool, &chat_id)
            .await
            .map(|answering| answering.context_window)
            .unwrap_or_default(),
    );
    // Empty on a failure rather than a 500: the transcript is the point of this request, and a
    // conversation nobody can read because its queue would not load is a worse answer than one
    // drawn without a note about what is waiting.
    let queued = crate::chats::queued(&state.pool, &chat_id)
        .await
        .unwrap_or_default();
    Ok(Json(TranscriptOut {
        handed,
        queued,
        asks: crate::hooks::asks_for(&chat_id),
        more,
        // Empty on a failure rather than a 500, the same trade the two reads above make: a
        // transcript is the point of this request, and losing a department's aside is a smaller loss
        // than a conversation that will not open.
        notices: crate::chat_notices::for_chat(&state.pool, &chat_id)
            .await
            .unwrap_or_default(),
        turns: turns
            .into_iter()
            .map(|turn| {
                // Without their answers. See `ToolCall::result`: this list rides a route that is
                // polled once a second while a turn is live, and the answers are fetched per turn
                // by `get_turn_tools` when somebody actually opens one.
                let did: Vec<crate::runner::ToolCall> = turn
                    .tools_used
                    .as_deref()
                    .and_then(|json| {
                        serde_json::from_str::<Vec<crate::runner::ToolCall>>(json).ok()
                    })
                    .unwrap_or_default()
                    .into_iter()
                    .map(crate::runner::ToolCall::without_result)
                    .collect();
                let thought = turn
                    .thought
                    .as_deref()
                    .and_then(|json| serde_json::from_str(json).ok())
                    .unwrap_or_default();
                let images = turn
                    .prompt_images
                    .as_deref()
                    .and_then(|json| serde_json::from_str(json).ok())
                    .unwrap_or_default();
                let relayed_to = sent
                    .iter()
                    .filter(|relay| relay.sending_run_id == turn.id)
                    .map(|relay| RelaySent {
                        chat_id: relay.chat_id.clone(),
                        title: relay.title.clone(),
                        body: relay.body.clone(),
                        sending_run_id: relay.sending_run_id,
                    })
                    .collect();
                let said_now = said
                    .iter()
                    .filter(|said| said.run_id == turn.id)
                    .cloned()
                    .collect();
                AssistantTurnOut {
                    turn,
                    did,
                    images,
                    thought,
                    context_window,
                    relayed_to,
                    said_now,
                }
            })
            .collect(),
    }))
}

/// Stops a chat turn: interrupts it when its process can be spoken to, kills it otherwise.
///
/// Uncancellable for the reason `runs::cancel_run` is: the kill removes the turn's handle before it
/// writes the status, so a request dropped in the middle would leave a `running` row nothing reaches.
async fn post_stop_turn(
    State(state): State<AppState>,
    Path(turn_id): Path<i64>,
) -> Result<Json<serde_json::Value>, StatusCode> {
    match uncancellable(async move { crate::assistant::stop_turn(&state, turn_id).await }).await? {
        crate::assistant::Stopped::Interrupted => {
            Ok(Json(serde_json::json!({ "stopped": "interrupted" })))
        }
        crate::assistant::Stopped::Killed => Ok(Json(serde_json::json!({ "stopped": "killed" }))),
        crate::assistant::Stopped::NotRunning => Err(StatusCode::NOT_FOUND),
    }
}

#[derive(Deserialize)]
struct SayNowRequest {
    text: String,
}

/// Says something into the turn that is running, or sends it the ordinary way when none is.
async fn post_say_now(
    State(state): State<AppState>,
    Path(chat_id): Path<String>,
    Json(body): Json<SayNowRequest>,
) -> Result<Json<serde_json::Value>, (StatusCode, Json<serde_json::Value>)> {
    if body.text.trim().is_empty() {
        return Err(refusal(StatusCode::BAD_REQUEST, "empty"));
    }
    let said =
        uncancellable(async move { crate::assistant::say_now(&state, &chat_id, &body.text).await })
            .await
            .map_err(|status| refusal(status, "internal"))?;
    match said {
        Ok(crate::assistant::SaidNow::Injected) => {
            Ok(Json(serde_json::json!({ "said_now": true })))
        }
        Ok(crate::assistant::SaidNow::Sent(crate::assistant::Sent::Turn(id))) => {
            Ok(Json(serde_json::json!({ "turn_id": id })))
        }
        Ok(crate::assistant::SaidNow::Sent(crate::assistant::Sent::Queued)) => {
            Ok(Json(serde_json::json!({ "queued": true })))
        }
        Err(error) => {
            tracing::warn!(%error, "saying something into a running turn failed");
            Err(refusal(StatusCode::INTERNAL_SERVER_ERROR, "internal"))
        }
    }
}

/// What one turn's tools answered.
///
/// A route of its own rather than a wider transcript, and the reason is arithmetic. The
/// transcript is polled at a live turn's cadence — about once a second while something is
/// running — and a tool answer is capped at two thousand characters. Twenty calls in a turn and a
/// hundred turns in a conversation is four megabytes on the wire every second, paid forever, for
/// something almost nobody has open. So `get_assistant_chat` strips the answers and this hands
/// them over for one turn, when somebody asks.
///
/// `404` for a turn that is not an assistant turn of this daemon's: a job's run id must not open a
/// door into the chat transcript by guessing a number.
async fn get_turn_tools(
    State(state): State<AppState>,
    Path(turn_id): Path<i64>,
) -> Result<Json<TurnToolsOut>, StatusCode> {
    let stored: Option<Option<String>> =
        sqlx::query_scalar("SELECT tools_used FROM runs WHERE id = ? AND mode = 'assistant'")
            .bind(turn_id)
            .fetch_optional(&state.pool)
            .await
            .map_err(|error| {
                tracing::warn!(%error, turn_id, "reading a turn's tools failed");
                StatusCode::INTERNAL_SERVER_ERROR
            })?;
    let Some(tools_used) = stored else {
        return Err(StatusCode::NOT_FOUND);
    };
    // A column that will not parse reads as an empty list, exactly as the transcript treats it: a
    // turn recorded before the column existed acted on nothing as far as anything here can tell,
    // and that is a true statement about what is known rather than an error.
    Ok(Json(TurnToolsOut {
        did: tools_used
            .as_deref()
            .and_then(|json| serde_json::from_str(json).ok())
            .unwrap_or_default(),
    }))
}

#[derive(serde::Serialize)]
struct TurnToolsOut {
    /// Every tool the turn ran, oldest first, WITH what each one answered. See `ToolCall::result`.
    did: Vec<crate::runner::ToolCall>,
}

/// How many hits a search comes back with.
///
/// Small on purpose. This answers "where did we talk about that", and a person scanning for the
/// conversation they half remember reads the first few and refines the words if none of them is
/// it. Two hundred hits is not a better answer to that question; it is the same answer with the
/// useful part further down.
const SEARCH_HITS: i64 = 40;

/// The longest search acted on. Longer than this is a paste, not a search.
const SEARCH_QUERY_MAX: usize = 200;

/// How much of the line around a hit comes back, in characters either side of it.
const EXCERPT_BEFORE: usize = 60;
const EXCERPT_AFTER: usize = 140;

#[derive(serde::Deserialize)]
struct AssistantSearchQuery {
    q: String,
}

/// One thing that was said, and where.
#[derive(serde::Serialize)]
struct SearchHit {
    chat_id: String,
    /// What the conversation is called, or null when nothing has named it.
    title: Option<String>,
    /// The turn it was said in, so the window can scroll to it rather than merely open the chat.
    turn_id: i64,
    /// `asked` or `answered`: which half of the exchange matched.
    ///
    /// Worth saying, because the two are found for different reasons. Somebody looking for
    /// something they asked is retracing their own steps; somebody looking for something the model
    /// said is looking for an answer they were given. A list that merged the two would make the
    /// second kind hunt through the first.
    side: &'static str,
    /// The words around the hit, with an ellipsis on whichever side was cut.
    excerpt: String,
    created_at: String,
}

/// One matched row, before it is read into a hit.
#[derive(sqlx::FromRow)]
struct SearchRow {
    chat_id: String,
    title: Option<String>,
    turn_id: i64,
    asked: String,
    answered: Option<String>,
    created_at: String,
}

/// Something that was SAID, across every conversation this app is holding.
///
/// The window's palette matches titles, which is the right first answer and a useless second one:
/// a title is a summary a model wrote, and what somebody comes back for is a sentence — the name
/// of a function, the error they pasted, the decision they want to quote.
///
/// Archived conversations are left out, for the same reason `chats::list` leaves them out: this
/// answers "which of my conversations", and archiving one is saying it is not among them.
///
/// Case is folded the way SQLite folds it, which is ASCII only — `Parser` finds `parser`, and `Ç`
/// does not find `ç`. Deliberately not worked around here: the excerpt below matches the same way
/// the query does, so what is highlighted is always what was actually found. A search that folded
/// more than the query did would point at a word the query never matched.
async fn search_assistant(
    State(state): State<AppState>,
    Query(query): Query<AssistantSearchQuery>,
) -> Json<Vec<SearchHit>> {
    let needle = query.q.trim();
    // Nothing, rather than every turn in the database. An empty search is a box somebody has not
    // finished typing in, and `%%` matches all of it.
    if needle.is_empty() || needle.chars().count() > SEARCH_QUERY_MAX {
        return Json(Vec::new());
    }
    let pattern = like_pattern(needle);
    let rows = sqlx::query_as::<_, SearchRow>(
        "SELECT r.chat_id AS chat_id, c.title AS title, r.id AS turn_id,
                r.prompt AS asked, r.stdout AS answered, r.created_at AS created_at
           FROM runs r
           JOIN chats c ON c.chat_id = r.chat_id
          WHERE r.mode = 'assistant'
            AND c.archived_at IS NULL
            AND (r.prompt LIKE ?1 ESCAPE '\\' OR r.stdout LIKE ?1 ESCAPE '\\')
          ORDER BY r.id DESC
          LIMIT ?2",
    )
    .bind(&pattern)
    .bind(SEARCH_HITS)
    .fetch_all(&state.pool)
    .await
    .unwrap_or_else(|error| {
        // Nothing found rather than a 500. A search that cannot run is a search with no results
        // from where the person is standing, and a page that refuses to draw because a LIKE went
        // wrong loses them the conversation they still have open.
        tracing::warn!(%error, "searching the conversations failed");
        Vec::new()
    });

    Json(
        rows.into_iter()
            .map(|row| {
                // The question first when it matched, because that is the half a person owns. Only
                // one hit per turn either way: a turn where both halves mention the word is one
                // exchange, and two rows for it would push a different conversation off the list.
                let (side, text) = if find_ascii_ci(&chars(&row.asked), &chars(needle)).is_some() {
                    ("asked", row.asked.as_str())
                } else {
                    ("answered", row.answered.as_deref().unwrap_or(""))
                };
                SearchHit {
                    chat_id: row.chat_id,
                    title: row.title,
                    turn_id: row.turn_id,
                    side,
                    excerpt: excerpt_of(text, needle),
                    created_at: row.created_at,
                }
            })
            .collect(),
    )
}

/// A `LIKE` pattern that matches this text and nothing cleverer.
///
/// `%` and `_` are wildcards in `LIKE`, so a search for `budget_usd` would otherwise match
/// `budgetXusd` — and, worse, a search for `%` would match every turn ever recorded. Escaped, with
/// the escape character escaped first.
fn like_pattern(text: &str) -> String {
    let mut out = String::from("%");
    for ch in text.chars() {
        if matches!(ch, '%' | '_' | '\\') {
            out.push('\\');
        }
        out.push(ch);
    }
    out.push('%');
    out
}

fn chars(text: &str) -> Vec<char> {
    text.chars().collect()
}

/// Where `pin` first occurs in `hay`, folding case the way SQLite's `LIKE` does — ASCII only.
///
/// Deliberately the same folding as the query, so the excerpt always contains the thing that was
/// matched. See `search_assistant`.
fn find_ascii_ci(hay: &[char], pin: &[char]) -> Option<usize> {
    if pin.is_empty() || pin.len() > hay.len() {
        return None;
    }
    hay.windows(pin.len()).position(|window| {
        window
            .iter()
            .zip(pin)
            .all(|(a, b)| a.eq_ignore_ascii_case(b))
    })
}

/// The words around a hit, with an ellipsis on whichever side was cut.
///
/// Around it and not from the top: a match nine hundred characters into an answer is not visible
/// in the first line of that answer, and a list of first lines is a list that does not show what
/// it found. Falls back to the head of the text when the hit cannot be located — which is only
/// reachable if the query and this disagree about folding, and the head of the text is at least
/// true.
fn excerpt_of(text: &str, needle: &str) -> String {
    let hay = chars(text);
    let pin = chars(needle);
    let at = find_ascii_ci(&hay, &pin).unwrap_or(0);
    let start = at.saturating_sub(EXCERPT_BEFORE);
    let end = (at + pin.len() + EXCERPT_AFTER).min(hay.len());
    let mut out = String::new();
    if start > 0 {
        out.push('…');
    }
    out.extend(hay[start..end].iter());
    if end < hay.len() {
        out.push('…');
    }
    out
}

/// A turn while it is still being written: what has been said, and what is being done.
///
/// The distilling happens in `runner.rs` beside `extract_reply`, because knowing the CLI's stream
/// format is that module's job — and this route exists rather than pointing the window at
/// `/runs/{id}/tail` for the same reason: the tail is the raw stream, and a chat bubble is not the
/// place to learn what a `content_block_delta` is.
///
/// Read from byte zero on every poll, not from a cursor. What comes back is not a chunk to append
/// but the turn's whole state — text superseded by completed messages, a tool that has since
/// returned — and that can only be recomputed from the beginning. A turn's stream is small; a job's
/// is not, which is why `/runs/{id}/tail` keeps its cursor.
///
/// `204` when nothing is writing. That is the run having ended or this daemon never having started
/// it, and it is emphatically not "the turn said nothing" — see `read_tail`.
async fn get_assistant_live(
    State(state): State<AppState>,
    Path(turn_id): Path<i64>,
) -> Result<Json<crate::runner::LiveTurn>, StatusCode> {
    let stream =
        crate::runs::read_tail(&state.run_tails, turn_id, 0).ok_or(StatusCode::NO_CONTENT)?;
    Ok(Json(crate::runner::live_from_stream(&stream)))
}

/// Length in bytes of a turn's tail, or `None` once nothing is writing it. Peeks without cloning
/// the text, so the poll loop below costs a pair of lock acquisitions per tick and not a copy.
fn tail_len(tails: &crate::state::RunTails, run_id: i64) -> Option<usize> {
    let tail = tails.lock().unwrap().get(&run_id).cloned()?;
    let len = tail.lock().unwrap().len();
    Some(len)
}

/// `get_assistant_live` as a Server-Sent Events stream: one `live` event per change of the turn's
/// distilled state, then an `end` event when the run stops being written.
///
/// SSE rather than a socket because the traffic is one-way and plain HTTP, so the bearer token
/// travels in the header like on every other route and never in a URL. The events carry the
/// distilled [`crate::runner::LiveTurn`], never the CLI's raw lines, for the reason given on
/// `get_assistant_live`: a chat bubble is not the place to learn what a `content_block_delta` is.
///
/// The tail is polled every 100 ms rather than waited on, so the writers (`runner.rs`) stay as
/// they are and nothing has to learn about subscribers. Only the length is read per tick; the
/// stream is re-distilled when it changed, and an event goes out only if the state differs from
/// the last one sent.
///
/// `204` when no tail exists, same as `/live`: the run ended or this daemon never started it.
async fn get_assistant_live_stream(
    State(state): State<AppState>,
    Path(turn_id): Path<i64>,
) -> Result<axum::response::Response, StatusCode> {
    use tokio::io::AsyncWriteExt;

    crate::runs::read_tail(&state.run_tails, turn_id, 0).ok_or(StatusCode::NO_CONTENT)?;
    let (mut writer, reader) = tokio::io::duplex(64 * 1024);
    let tails = state.run_tails.clone();
    tokio::spawn(async move {
        let mut tick = tokio::time::interval(std::time::Duration::from_millis(100));
        tick.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Skip);
        let mut seen_len: Option<usize> = None;
        let mut last: Option<crate::runner::LiveTurn> = None;
        let mut idle = 0u32;
        loop {
            tick.tick().await;
            let Some(len) = tail_len(&tails, turn_id) else {
                let _ = writer.write_all(b"event: end\ndata: {}\n\n").await;
                break;
            };
            let mut wrote = false;
            if seen_len != Some(len) {
                seen_len = Some(len);
                if let Some(stream) = crate::runs::read_tail(&tails, turn_id, 0) {
                    let live = crate::runner::live_from_stream(&stream);
                    if last.as_ref() != Some(&live) {
                        let Ok(json) = serde_json::to_string(&live) else {
                            break;
                        };
                        let frame = format!("event: live\ndata: {json}\n\n");
                        if writer.write_all(frame.as_bytes()).await.is_err() {
                            break;
                        }
                        last = Some(live);
                        wrote = true;
                    }
                }
            }
            if wrote {
                idle = 0;
            } else {
                idle += 1;
                if idle >= 150 {
                    idle = 0;
                    if writer.write_all(b": keep-alive\n\n").await.is_err() {
                        break;
                    }
                }
            }
        }
    });
    let mut headers = axum::http::HeaderMap::new();
    headers.insert(
        axum::http::header::CONTENT_TYPE,
        axum::http::HeaderValue::from_static("text/event-stream"),
    );
    headers.insert(
        axum::http::header::CACHE_CONTROL,
        axum::http::HeaderValue::from_static("no-cache"),
    );
    Ok((
        headers,
        axum::body::Body::from_stream(tokio_util::io::ReaderStream::new(reader)),
    )
        .into_response())
}

/// Whether this machine has a model that can answer a conversation.
///
/// Exists so a client can offer the choice honestly. Without it the window would show "local" as an
/// option, take the switch, and only discover on the next message that nothing on this machine can
/// answer — leaving the conversation set to a model that does not exist. An option that is not
/// there and an option that is unavailable today are different facts, and only one of them is
/// something the user can act on.
///
/// Reports what STARTUP resolved, not a live probe: `local_assistant` is `Some` only if the daemon
/// managed to build one, and a probe here would be a second, differently-timed opinion about the
/// same thing.
async fn get_local_model(State(state): State<AppState>) -> Json<serde_json::Value> {
    // `state.local_assistant.is_some()` before the migration to the assistant factory: the field
    // this read no longer exists, so this call site is one of the lines that migration is allowed
    // to touch beyond the `AppState` literal.
    let available = state.assistants.serves(crate::chats::Brain::Local).is_ok();
    Json(serde_json::json!({ "available": available }))
}

/// One download of a local model: what it is, where it has got to, and how it ended.
///
/// `outcome` is `None` while it runs, and that single field is what "in flight" means here — there
/// is no separate flag, because two ways to say the same thing is two ways for them to disagree.
/// A finished pull is KEPT rather than cleared: the window polls, and clearing on completion would
/// mean the poll that arrives one tick after a successful download finds nothing and cannot tell
/// "it worked" from "nothing ever happened".
#[derive(Clone)]
struct Pull {
    model: String,
    /// Ollama's own word for what it is doing, carried through untranslated —
    /// `capabilities::PullProgress` explains why.
    status: String,
    completed: u64,
    total: u64,
    outcome: Option<Result<(), String>>,
}

/// The one download this machine is doing, or the last one it did.
///
/// A process-global rather than a field on `AppState`, for the reason `sidecar::SIDECARS` and
/// `assistant::LIVE_CHATS` are: this is not per-request state that a handler was handed, it is a
/// fact about the machine — there is one Ollama on it, one disk, and at most one download being
/// watched. It also sits beside `OLLAMA_TAGS_CLIENT`, which is a static in this module for exactly
/// the same argument.
///
/// **One at a time, deliberately.** Two multi-gigabyte downloads sharing one disk finish later than
/// the same two in sequence, and the window has one progress bar; a second request while one runs
/// is refused rather than queued, because a queue nobody can see or cancel is worse than a refusal
/// somebody can retry.
///
/// The one way this can wedge: a task that panicked between its last progress frame and writing its
/// outcome would leave `outcome: None` forever, and every later pull would be refused until the
/// daemon restarts. What it runs has no panic path — `pull_local_model` returns its failures — and
/// the alternative (keeping the `JoinHandle` to ask `is_finished`) costs this type its `Clone` and
/// the readout its pure test, which is a worse trade for a case that needs a bug to reach.
static LOCAL_PULL: std::sync::LazyLock<std::sync::Mutex<Option<Pull>>> =
    std::sync::LazyLock::new(|| std::sync::Mutex::new(None));

/// PURE: a pull -> what the window is told about it.
///
/// `percent` is `null` and not `0` when nothing has said how big the download is. Every pull opens
/// on `pulling manifest`, which carries no counts, and a bar sitting at 0% says a download is
/// stuck — which one that has not started measuring itself is not.
///
/// `state` collapses to three words because three is what a window can draw. `done` and `failed`
/// stay apart, though both mean "not running": collapsing them would either swallow the reason a
/// download failed or leave a spinner up after one that worked.
fn pull_readout(pull: &Pull) -> serde_json::Value {
    serde_json::json!({
        "model": pull.model,
        "state": match &pull.outcome {
            None => "running",
            Some(Ok(())) => "done",
            Some(Err(_)) => "failed",
        },
        "status": pull.status,
        "percent": (pull.total > 0).then(|| pull.completed * 100 / pull.total),
        "error": match &pull.outcome {
            Some(Err(reason)) => serde_json::Value::String(reason.clone()),
            _ => serde_json::Value::Null,
        },
    })
}

/// The client a download runs on, built once and shared.
///
/// Emphatically NOT `ollama_tags_client()`: that one is built with `OLLAMA_TAGS_TIMEOUT` so a
/// wedged Ollama cannot hold up a menu, and a whole-request timeout of a couple of seconds would
/// abort every download that was working. A pull runs for minutes by design. The connect timeout
/// stays short, because failing to DIAL is still a fast failure and the person is watching.
/// The client the model REGISTRY is read over, built once and shared.
///
/// Also emphatically not `ollama_tags_client()`, and this one is a correction rather than a
/// precaution: the size route shipped reusing that client, which is built for a localhost probe
/// with a two-second whole-request budget. `registry.ollama.ai` is across the internet and behind
/// a TLS handshake. It measured 0.37s from this machine so two seconds was not actually the bug —
/// the bug was the missing TLS backend, and this reuse was simply wrong for a reason that would
/// have surfaced later, on a slower connection, as a size that was sometimes unknown.
///
/// Ten seconds, and a short connect timeout for the same reason the pull client keeps one: failing
/// to dial is a fast failure, and somebody is looking at the row while it happens.
fn model_registry_client() -> &'static reqwest::Client {
    static CLIENT: std::sync::OnceLock<reqwest::Client> = std::sync::OnceLock::new();
    CLIENT.get_or_init(|| {
        reqwest::Client::builder()
            .connect_timeout(std::time::Duration::from_secs(5))
            .timeout(std::time::Duration::from_secs(10))
            .build()
            .expect("HTTP client for the model registry (check TLS and proxy environment)")
    })
}

fn ollama_pull_client() -> &'static reqwest::Client {
    static CLIENT: std::sync::OnceLock<reqwest::Client> = std::sync::OnceLock::new();
    CLIENT.get_or_init(|| {
        reqwest::Client::builder()
            .connect_timeout(std::time::Duration::from_secs(5))
            .build()
            .expect("HTTP client for the /api/pull stream (check TLS and proxy environment)")
    })
}

#[derive(serde::Deserialize)]
struct PullRequest {
    /// A choice id from `GET /assistant/models`, and checked against that list — see the handler.
    model: String,
}

#[derive(serde::Deserialize)]
struct SizeQuery {
    model: String,
}

/// PURE: what the window draws under a model this machine does not have yet.
///
/// Both numbers travel, not just the verdict. "17.4 GB, and this machine has 15.8" is something a
/// person can act on — a smaller quantisation, a different model, more memory — while a bare
/// `too_big` is a wall with no door in it. `null` rather than `0` on either side for the reason
/// `capabilities::interpret_manifest` returns `None`: a zero is a real number that grades as the
/// most permissive verdict there is, which is the last thing a failed read should produce.
fn size_readout(model: &str, bytes: Option<u64>, memory: Option<u64>) -> serde_json::Value {
    let fit = crate::capabilities::model_fit(bytes.unwrap_or(0), memory.unwrap_or(0));
    serde_json::json!({
        "model": model,
        "bytes": bytes,
        "memory": memory,
        "fit": match fit {
            crate::capabilities::Fit::Comfortable => "comfortable",
            crate::capabilities::Fit::Tight => "tight",
            crate::capabilities::Fit::TooBig => "too_big",
            crate::capabilities::Fit::Unknown => "unknown",
        },
        "error": serde_json::Value::Null,
    })
}

/// Whether this daemon KNOWS a model will not run here — never merely suspects it.
///
/// The name says `known` because the answer is asymmetric and the asymmetry is the whole point.
/// `true` requires two successful reads: a size the registry gave and a memory figure Windows gave.
/// Every other outcome is `false` — an unreachable registry, a manifest that did not parse, a
/// machine that could not be measured — because refusing on a failure to MEASURE would hand a third
/// party on the far side of the internet the power to switch downloads off on this machine.
///
/// Its own function rather than a condition inline: the caller is a guard clause whose reader wants
/// to know what is being refused, not how it was determined.
async fn known_too_big(model: &str) -> bool {
    let Ok(bytes) = crate::capabilities::registry_model_size(
        model_registry_client(),
        crate::capabilities::OLLAMA_REGISTRY_URL,
        model,
    )
    .await
    else {
        return false;
    };
    let Some(memory) = crate::capabilities::total_memory_bytes() else {
        return false;
    };
    crate::capabilities::model_fit(bytes, memory) == crate::capabilities::Fit::TooBig
}

/// What a model weighs, and whether this machine can carry it.
///
/// Answers the question the download confirmation needs and cannot ask any other way: the local
/// `/api/tags` knows the size of models already here, which is the case already settled. This reads
/// the public registry — no key, no account — over the same short-timeout client the `/api/tags`
/// probes use, because like them it runs to decorate a menu somebody is looking at.
///
/// Two failures, answered differently on purpose. A name `registry_path` refuses is a `400`: it can
/// never work and will not start working on its own. A registry that could not be reached is a
/// `200` carrying `unknown`, because it is transient and a picker that broke whenever a third party
/// on the far side of the internet was slow would be a feature that breaks the app it decorates.
///
/// Reachable by the control token and an admin key alone — it is in no scope table, and
/// `auth::the_pull_routes_are_out_of_an_agents_reach` is where that is held.
async fn get_local_model_size(
    Query(query): Query<SizeQuery>,
) -> Result<Json<serde_json::Value>, (StatusCode, Json<serde_json::Value>)> {
    if crate::capabilities::registry_path(&query.model).is_none() {
        return Err(refusal(StatusCode::BAD_REQUEST, "unknown_model"));
    }
    let memory = crate::capabilities::total_memory_bytes();
    match crate::capabilities::registry_model_size(
        model_registry_client(),
        crate::capabilities::OLLAMA_REGISTRY_URL,
        &query.model,
    )
    .await
    {
        Ok(bytes) => Ok(Json(size_readout(&query.model, Some(bytes), memory))),
        Err(reason) => {
            let mut readout = size_readout(&query.model, None, memory);
            readout["error"] = serde_json::Value::String(reason);
            Ok(Json(readout))
        }
    }
}

/// Fetch a local model this machine does not have yet.
///
/// Answers `202` the moment the download starts rather than when it finishes, because it finishes
/// in minutes and no HTTP client on either end would wait. The body is the same readout `GET` on
/// this path returns, so the window has a first frame to draw without waiting for its own first
/// poll.
///
/// **`menu()` is the allowlist, not the request body.** This is the one route in this file that
/// makes the machine fetch gigabytes from a name somebody sent, so the name has to be one that was
/// already written into `~/.nucleos/nucleos-models.yaml` or that Ollama already has. Refused with the same
/// `400` a model the catalogue does not offer gets from `patch_chat`, and for the same reason:
/// it is the person's name that is wrong, not this daemon's state.
///
/// Reachable by the control token and an admin key alone — it is in no scope table, and
/// `auth::the_pull_routes_are_out_of_an_agents_reach` is where that is held.
async fn post_local_model_pull(
    Json(body): Json<PullRequest>,
) -> Result<(StatusCode, Json<serde_json::Value>), (StatusCode, Json<serde_json::Value>)> {
    let (_, choices) = menu(Asking::Daemon).await;
    if !choices
        .iter()
        .any(|choice| choice.brain == "local" && choice.id == body.model)
    {
        return Err(refusal(StatusCode::BAD_REQUEST, "unknown_model"));
    }

    // Refused BEFORE the download rather than discovered after it. A model larger than this machine
    // does not become runnable by arriving, so the gigabytes would be spent to prove a thing the
    // registry will say in one small request.
    //
    // Fails OPEN, and that asymmetry is deliberate: only a size this daemon actually read and
    // actually graded `TooBig` stops anything. An unreachable registry, a manifest it could not
    // parse, a machine whose memory it could not measure — all of those proceed, because refusing
    // on a failure to measure would make a third party on the far side of the internet able to
    // switch off downloads here.
    if known_too_big(&body.model).await {
        return Err(refusal(StatusCode::BAD_REQUEST, "model_too_big"));
    }

    let started = {
        // The whole check-and-claim under one lock, so two requests arriving together cannot both
        // find the slot free. Nothing is awaited inside it.
        let mut slot = LOCAL_PULL
            .lock()
            .map_err(|_| refusal(StatusCode::INTERNAL_SERVER_ERROR, "pull_state_poisoned"))?;
        if slot.as_ref().is_some_and(|pull| pull.outcome.is_none()) {
            return Err(refusal(StatusCode::CONFLICT, "pull_in_flight"));
        }
        let started = Pull {
            model: body.model.clone(),
            status: "starting".to_owned(),
            completed: 0,
            total: 0,
            outcome: None,
        };
        *slot = Some(started.clone());
        started
    };

    let model = body.model;
    // The download in a task of its own, awaited by this one, so a panic inside it still closes
    // the slot. A slot left with no outcome reads as `pull_in_flight` to every later request, and
    // nothing short of a restart would ever clear it.
    tokio::spawn(async move {
        let outcome = tokio::spawn(async move {
            crate::capabilities::pull_local_model(
                ollama_pull_client(),
                crate::runner::OLLAMA_BASE_URL,
                &model,
                |frame| {
                    if let Ok(mut slot) = LOCAL_PULL.lock()
                        && let Some(pull) = slot.as_mut()
                    {
                        pull.status = frame.status;
                        pull.completed = frame.completed;
                        pull.total = frame.total;
                    }
                },
            )
            .await
        })
        .await
        .unwrap_or_else(|error| {
            tracing::error!(%error, "the local model download's task ended without a result");
            Err(format!("the download ended without a result: {error}"))
        });
        // A panic inside the progress callback poisons the lock while holding it; the slot it
        // guards is still whole, so it is taken back and the poison cleared rather than leaving
        // every later request on `pull_state_poisoned`.
        let mut slot = LOCAL_PULL
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        if let Some(pull) = slot.as_mut() {
            pull.outcome = Some(outcome);
        }
        drop(slot);
        LOCAL_PULL.clear_poison();
    });

    Ok((StatusCode::ACCEPTED, Json(pull_readout(&started))))
}

/// How the download is going.
///
/// `204` when this daemon has not been asked to fetch anything since it started — the same way
/// `get_assistant_live` above answers a turn nothing is writing. It is emphatically not "the
/// download failed": a window that read it as one would put an error up on every fresh install.
async fn get_local_model_pull() -> Result<Json<serde_json::Value>, StatusCode> {
    let slot = LOCAL_PULL
        .lock()
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    let pull = slot.as_ref().ok_or(StatusCode::NO_CONTENT)?;
    Ok(Json(pull_readout(pull)))
}

#[derive(serde::Deserialize)]
struct ListChatsQuery {
    /// Archived conversations instead of the live list.
    #[serde(default)]
    archived: bool,
}

/// The conversations the app opened, most recently active first.
///
/// The Telegram sidecar's chats are absent from this, and no line here says so. They are absent
/// because nothing ever created a row for them — the only door into `chats` is `create_chat` below.
/// A filter naming Telegram would have to be kept correct as clients are added; an absence needs no
/// maintenance.
async fn list_chats(
    State(state): State<AppState>,
    Query(query): Query<ListChatsQuery>,
) -> Result<Json<Vec<crate::chats::ChatSummary>>, StatusCode> {
    let rows = if query.archived {
        crate::chats::list_archived(&state.pool).await
    } else {
        crate::chats::list(&state.pool).await
    };
    rows.map(|rows| {
        Json(
            rows.into_iter()
                .map(|row| {
                    let asks = crate::hooks::asks_for(&row.chat_id).len();
                    crate::chats::settle(row, asks)
                })
                .collect(),
        )
    })
    .map_err(|error| {
        tracing::warn!(%error, "listing chats failed");
        StatusCode::INTERNAL_SERVER_ERROR
    })
}

#[derive(serde::Deserialize)]
struct CreateChatRequest {
    /// Absent means cloud, matching the column default and every caller written before this.
    brain: Option<String>,
    /// The id of a session already had in the IDE, which this conversation continues.
    ///
    /// The ID and nothing else. The directory it runs in is looked up from the transcript, never
    /// accepted here — a caller that could name its own working directory could name one where the
    /// classifier hook is wired and collect the tools that come with it.
    continue_session: Option<String>,
    /// Which model answers it, as a choice id from `GET /assistant/models`.
    ///
    /// Here as well as on the PATCH because the front door has no conversation to PATCH yet: a
    /// person picks a model, types, and sends, and without this the window would have to open a
    /// chat on the default and correct it a round trip later — visibly, and wrongly if the second
    /// call failed.
    ///
    /// A plain `Option` and not the PATCH's `Option<Option<_>>`: there is no conversation here to
    /// unpin, so absent and null both mean the same thing and the third state does not exist.
    model: Option<String>,
    /// How hard it is asked to think, on the same footing.
    effort: Option<String>,
    /// What the conversation may do without asking, from its first message.
    ///
    /// Here for the same reason `model` is -- the front door has nothing to PATCH yet -- and,
    /// unlike `model`, it is written INTO the row rather than applied a step later. A rung that
    /// failed to take would leave the conversation on `auto`, which is wider than what was asked
    /// for; see `chats::create_on`.
    ///
    /// Absent means `auto`, which is the column's own default and what every conversation opened
    /// before this field existed already holds. A spelling outside the five fails the request
    /// rather than falling back, on the PATCH's reasoning: the reader's leniency exists for rows
    /// written before the column did, and applying it to a request would let a typo widen what a
    /// conversation may do.
    permission_mode: Option<crate::chats::PermissionMode>,
    /// Who answers when the chosen model is unavailable, as choice ids in the order to try them.
    #[serde(default)]
    fallback_model: Vec<String>,
    /// Absolute paths this conversation's tools may also reach.
    #[serde(default)]
    extra_dirs: Vec<String>,
    /// The most one turn may spend, in dollars.
    turn_budget_usd: Option<f64>,
    /// The helpers it may hand work to, added to the ones the CLI finds in the project itself.
    #[serde(default)]
    agents: Vec<crate::runner::Subagent>,
    /// Standing instructions appended to its system prompt.
    system_prompt: Option<String>,
    /// Built-in tools it may not reach for.
    #[serde(default)]
    denied_tools: Vec<String>,
}

/// One session as it is OFFERED: what it is, plus what continuing it would be able to do.
///
/// The second half is not decoration. A conversation continued in a directory with no classifier
/// hook runs on the MCP server alone — no `Read`, no `Edit`, no `Bash` — so picking up a coding
/// session there gets a model that cannot open the file being discussed. That was invisible until
/// the first turn came back empty-handed, and it is the single thing that made continuing a
/// session feel like nothing had happened.
#[derive(serde::Serialize)]
struct OfferedSession {
    #[serde(flatten)]
    session: crate::sessions::IdeSession,
    /// Whether a turn continued here would get the project's tools.
    ///
    /// Answered by asking `tool_policy_for` — the same function the turn itself asks — rather than
    /// by restating the rule here. A second opinion about this would be a window promising tools
    /// the turn then does not get.
    tools: bool,
}

/// The judge as the window reads it.
///
/// Tagged rather than flattened into two nullable fields, because the three states are what this
/// type is FOR and `{"brain": null}` cannot tell "nobody has chosen" from "somebody chose nobody" —
/// which is the whole distinction `project_policy::Judge` exists to keep.
#[derive(serde::Serialize)]
#[serde(tag = "state", rename_all = "snake_case")]
enum JudgeView {
    /// No row. The local brain, on the model it is already configured with.
    Default,
    /// Somebody switched it off. Every question goes to a person.
    Off,
    /// Somebody named one.
    Named {
        brain: String,
        model: Option<String>,
    },
}

impl From<crate::project_policy::Judge> for JudgeView {
    fn from(judge: crate::project_policy::Judge) -> Self {
        match judge {
            crate::project_policy::Judge::Default => Self::Default,
            crate::project_policy::Judge::Off => Self::Off,
            crate::project_policy::Judge::Named { brain, model } => Self::Named {
                brain: brain.as_str().to_owned(),
                model,
            },
        }
    }
}

/// What `POST /projects/{id}/judge` accepts. A null brain switches the judge off.
#[derive(serde::Deserialize)]
struct JudgeRequest {
    /// `local` or `openrouter`. Null means nobody answers but a person.
    brain: Option<String>,
    /// Which model, when a brain is named. Null means that brain's configured one.
    ///
    /// A choice id from `GET /assistant/models`, checked against that list and against the brain
    /// beside it — the same menu `patch_chat` validates a pinned model against, and for a sharper
    /// version of the same reason. There a wrong name costs a turn that dies at spawn, which is
    /// visible. Here it costs nothing visible at all: an unservable judge is indistinguishable
    /// from no judge, so the mistake would present as the feature simply not working.
    model: Option<String>,
}

/// Names this project's judge, or switches it off.
///
/// **Both halves of the request are checked against something real, and that is what makes a picker
/// safe to build on this route.** Until this check existed the route took any brain spelling and
/// any model string under 4 KiB, and stored them. Neither failure was loud: an unservable model
/// makes `assistant_for` refuse, `judge_for` return `None`, and the person be asked — which is the
/// SAME behaviour as having no judge at all. So somebody who mistyped a model name would configure
/// a judge, see the panel say a judge was configured, and never once be answered by it.
///
/// The brain arm is subtler and is why it is not a two-line match. `Brain::from_wire` folds
/// anything it cannot parse to `Cloud` — documented, deliberate, and safe for a column default —
/// and `declare_judge` refuses `Cloud` with a sentence about the CLI re-entering this hook. Fold a
/// typo through both and somebody who wrote `lokal` is told, truthfully and uselessly, about the
/// cloud route. A word this daemon has no route for is refused as that; `cloud` is passed through
/// to `declare_judge`, which owns the reason it cannot judge.
///
/// The refusal for `cloud` therefore still comes back from `declare_judge` rather than being
/// restated here: the reason is about what a cloud brain IS, and a second copy of that sentence in
/// the routing layer is a second copy free to drift from the first.
async fn post_project_judge(
    State(state): State<AppState>,
    Path(id): Path<String>,
    Json(body): Json<JudgeRequest>,
) -> Result<StatusCode, (StatusCode, Json<serde_json::Value>)> {
    project_is_on_the_roster(&state, &id).await?;

    let brain = match body.brain.as_deref().map(str::trim) {
        None | Some("") => None,
        Some(named) => {
            let route = crate::chats::Brain::from_wire(named);
            if route == crate::chats::Brain::Cloud && named != crate::chats::Brain::Cloud.as_str() {
                return Err(unusable_judge(format!(
                    "`{named}` is not a route this daemon has; a judge is `local` or `openrouter`"
                )));
            }
            Some(route)
        }
    };

    if let Some(model) = body.model.as_deref() {
        within_length("model", model)?;
    }
    // Blank is nothing, not a name. The column already means "that brain's configured model" when
    // it is NULL, and storing an empty string would be a second spelling of the same state that
    // only `assistant_for` would ever discover was not one.
    let model = body
        .model
        .as_deref()
        .map(str::trim)
        .filter(|model| !model.is_empty());

    // Only when a brain was named. `brain: null` is the switch-off, and `declare_judge` drops the
    // model beside it — so a model there is not a judge's model and has nothing to be checked
    // against.
    if let (Some(named), Some(model)) = (brain, model) {
        match chosen_brain(&state, model, Asking::Daemon).await {
            Ok(route) if route == named => {}
            Ok(route) => {
                return Err(unusable_judge(format!(
                    "`{model}` is answered by the {} route, not {}",
                    route.as_str(),
                    named.as_str()
                )));
            }
            Err(BrainRefusal::UnknownModel) => {
                return Err(unusable_judge(format!(
                    "nothing on this daemon's model menu is called `{model}`"
                )));
            }
            Err(BrainRefusal::NeedsRoot) => {
                return Err(unusable_judge(CODEX_NEEDS_A_ROOT.to_string()));
            }
            // `can_serve`'s own words, carried through rather than summarised — it is the layer that
            // knows WHY, and the two cases that reach here are the ordinary ones: a local model
            // this machine has not pulled, and a hosted model named with no key stored.
            Err(BrainRefusal::CannotServe(why)) => return Err(unusable_judge(why)),
        }
    }

    crate::project_policy::declare_judge(&state.pool, &id, brain, model)
        .await
        .map_err(unusable_judge)?;

    Ok(StatusCode::NO_CONTENT)
}

/// The one refusal this route gives, so its three callers cannot spell the code three ways.
fn unusable_judge(detail: String) -> (StatusCode, Json<serde_json::Value>) {
    (
        StatusCode::UNPROCESSABLE_ENTITY,
        Json(serde_json::json!({ "refusal": "unusable_judge", "detail": detail })),
    )
}

/// Puts the project back on the default judge.
///
/// 404 when there was no row, off the DELETE's own `rows_affected` — the same shape
/// `delete_project_land_target` uses, and the same honesty: a project that never named a judge is
/// already on the default, and reporting a deletion that did not happen would be a lie the window
/// would draw as a change.
async fn delete_project_judge(
    State(state): State<AppState>,
    Path(id): Path<String>,
) -> Result<StatusCode, (StatusCode, Json<serde_json::Value>)> {
    project_is_on_the_roster(&state, &id).await?;

    let cleared = crate::project_policy::clear_judge(&state.pool, &id)
        .await
        .map_err(|error| {
            tracing::warn!(%error, project_id = %id, "clearing a project judge failed");
            refusal(StatusCode::INTERNAL_SERVER_ERROR, "internal")
        })?;

    if cleared {
        Ok(StatusCode::NO_CONTENT)
    } else {
        Err(refusal(StatusCode::NOT_FOUND, "no_judge"))
    }
}

/// The conversations already had in the IDE that this daemon could continue.
///
/// Ones already continued are dropped: a second conversation resuming the same session would put
/// two threads on one context, and the window would show them as unrelated.
async fn list_ide_sessions(
    State(state): State<AppState>,
) -> Result<Json<Vec<OfferedSession>>, StatusCode> {
    let Some(root) = crate::sessions::default_root() else {
        return Ok(Json(Vec::new()));
    };
    let taken = crate::chats::picked_up(&state.pool)
        .await
        .map_err(|error| {
            tracing::warn!(%error, "listing the sessions already continued failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })?;

    // Read on the request rather than kept warm in memory. The store is the CLI's, it changes
    // whenever a session is typed into, and a cache would be a second copy of somebody else's truth.
    let found = tokio::task::spawn_blocking(move || {
        crate::sessions::discover(&root, IDE_SESSIONS_SHOWN)
            .into_iter()
            .filter(|session| !taken.contains(&session.session_id))
            .map(|session| {
                // Read here and never cached: the hook can be wired between two openings of this
                // list, including by the route below, and a stale `false` would go on offering to
                // fix what is already fixed.
                let wired =
                    crate::autopilot::classifier_hook_is_wired(std::path::Path::new(&session.cwd));
                // `false` for the reason the route above gives: an offered session is something
                // the person would type into themselves.
                let policy = crate::assistant::tool_policy_for(
                    Some(session.cwd.as_str()),
                    crate::assistant::Origin::Shell,
                    wired,
                    false,
                );
                OfferedSession {
                    session,
                    tools: policy == crate::runner::ToolPolicy::Unrestricted,
                }
            })
            .collect::<Vec<_>>()
    })
    .await
    .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;

    Ok(Json(found))
}

/// Puts this daemon's classifier hook into the project a session was had in.
///
/// The most consequential thing this daemon does to a directory it does not own: afterwards every
/// session had there — this one, and the ones opened in the editor — has its tool calls routed
/// through the classifier, and conversations continued there get the CLI's whole tool surface
/// instead of the MCP server alone. So it is a POST somebody presses, never something inferred
/// from picking a session up.
///
/// The directory comes from the transcript by way of `sessions::find`, exactly as `create_chat`
/// gets it and for a sharper version of the same reason: a caller that could name the directory
/// could have this daemon write an executable hook into any folder on the machine.
///
/// A 409 for a settings file this cannot parse. That is not the daemon failing — it is the project
/// saying no — and the one thing the caller can do about it is go and look at that file.
async fn wire_ide_session_tools(Path(session_id): Path<String>) -> Result<StatusCode, StatusCode> {
    let root = crate::sessions::default_root().ok_or(StatusCode::NOT_FOUND)?;
    let session = tokio::task::spawn_blocking(move || crate::sessions::find(&root, &session_id))
        .await
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?
        .ok_or(StatusCode::NOT_FOUND)?;

    let dir = std::path::PathBuf::from(&session.cwd);
    tokio::task::spawn_blocking(move || crate::autopilot::wire_classifier_hook(&dir))
        .await
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?
        .map_err(|error| {
            tracing::warn!(%error, cwd = %session.cwd, "could not wire the classifier hook");
            StatusCode::CONFLICT
        })?;

    Ok(StatusCode::NO_CONTENT)
}

/// What was said in one conversation had in the editor, oldest first.
///
/// Read off disk on the request, like the list above and for the same reason: the store is the
/// CLI's and changes whenever a session is typed into, so anything kept here would be a second copy
/// of somebody else's truth. This one reads a whole file rather than its head, which is why it is
/// on the blocking pool.
///
/// Not behind a chat id, though the window only ever asks about sessions it holds one for. The
/// session is the thing that has a conversation in it; a chat merely points at one, and two routes
/// for the same bytes would be two places for the bounds to differ.
///
/// A transcript this machine does not have is a 404. An empty conversation is a 200 with nothing in
/// it, and the window says different things about the two — "nothing was said here" is a claim, and
/// it must not be made about a file that was never found.
async fn read_ide_session(
    Path(session_id): Path<String>,
) -> Result<Json<IdeConversationOut>, StatusCode> {
    let root = crate::sessions::default_root().ok_or(StatusCode::NOT_FOUND)?;
    let found =
        tokio::task::spawn_blocking(move || crate::sessions::conversation(&root, &session_id))
            .await
            .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;

    found
        .map(|conversation| {
            Json(IdeConversationOut {
                conversation,
                largest_window: crate::assistant::LARGEST_WINDOW_TOKENS
                    - crate::assistant::COMPACTION_HEADROOM,
            })
        })
        .ok_or(StatusCode::NOT_FOUND)
}

/// A conversation had in the editor, and the largest one this daemon can pick up whole.
///
/// The number rides with it for the reason it rides with a turn: it is a property of this daemon
/// and not of the session, and the window keeping its own copy of a rule this side owns is a second
/// source of truth that drifts silently the day the constant changes. Here it also answers the
/// question the estimate is being asked for — whether picking this up continues it or hands it on.
///
/// It is the LARGEST window minus the CLI's own compaction headroom, and not the default window,
/// because a picked-up conversation is given a window wide enough to hold it. What it cannot be
/// given is a window wider than the model has, and that is the line this names.
#[derive(serde::Serialize)]
struct IdeConversationOut {
    #[serde(flatten)]
    conversation: crate::sessions::Conversation,
    largest_window: i64,
}

/// How many exchanges a conversation too large to resume is handed.
///
/// The same count `recent_exchanges` replays for a rotated conversation, and deliberately: this is
/// the rotation's mechanism reaching a conversation whose past happens to live in somebody else's
/// file rather than in our runs. A different number here would be a second policy about the same
/// question.
const HANDOVER_EXCHANGES: usize = 6;

/// How many past sessions the list offers.
///
/// There are hundreds on this machine and they are ordered by recency, so this is a question about
/// how far back a person reaches for a conversation they mean to continue — not about completeness.
const IDE_SESSIONS_SHOWN: usize = 40;

/// Opens a conversation, and answers with the id it was given.
///
/// The id is minted by the daemon rather than accepted from the body: `chat_id` reaches a filename
/// in `assistant.rs`'s temporary MCP config, and while that path encodes what it is handed, there is
/// no reason to open a second door for arbitrary strings when this one can simply not exist.
async fn create_chat(
    State(state): State<AppState>,
    Json(body): Json<CreateChatRequest>,
) -> Result<Json<serde_json::Value>, ChatRefusal> {
    // A named model decides the route, and outranks any `brain` sent beside it — the same
    // precedence `patch_chat` applies, for the same reason: a row saying `local` while naming a
    // cloud model would be sent to Ollama under a name it has never heard.
    let brain = match body.model.as_deref() {
        Some(id) => chosen_brain(&state, id, Asking::Chat { rooted: false }).await?,
        None => crate::chats::Brain::from_wire(body.brain.as_deref().unwrap_or("cloud")),
    };
    // Checked before the row exists, so a bad level leaves no conversation behind to explain. The
    // three below are checked here for the same reason and in the same breath.
    if let Some(level) = body.effort.as_deref()
        && !crate::config::is_effort_level(&models_config(), level)
    {
        return Err(StatusCode::BAD_REQUEST.into());
    }
    checked_fallback(&body.fallback_model)?;
    checked_dirs(&body.extra_dirs).await?;
    if let Some(amount) = body.turn_budget_usd {
        checked_budget(amount)?;
    }
    checked_agents(&body.agents)?;
    if let Some(text) = body.system_prompt.as_deref() {
        checked_instructions(text)?;
    }
    checked_denials(&body.denied_tools)?;

    // Resolved BEFORE the row is written, so a session the daemon cannot find leaves nothing behind
    // — rather than a conversation that looks continued and starts a fresh context on its first turn.
    let continued = match body.continue_session.clone() {
        None => None,
        Some(session_id) => {
            let root = crate::sessions::default_root().ok_or(StatusCode::NOT_FOUND)?;
            let found =
                tokio::task::spawn_blocking(move || crate::sessions::find(&root, &session_id))
                    .await
                    .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
            Some(found.ok_or(StatusCode::NOT_FOUND)?)
        }
    };

    let chat_id = crate::chats::create_on(
        &state.pool,
        brain,
        continued.as_ref(),
        body.permission_mode
            .unwrap_or(crate::chats::PermissionMode::Auto),
    )
    .await
    .map_err(|error| {
        tracing::warn!(%error, "opening a chat failed");
        StatusCode::INTERNAL_SERVER_ERROR
    })?;

    // After the row exists rather than as arguments to `create`, which takes the facts a
    // conversation cannot be opened without. These two are preferences: a conversation with neither
    // is the ordinary case and has been since the table was made, and threading them through the
    // constructor would make every existing caller name a choice it does not have.
    //
    // A failure here is logged and not fatal. The conversation is open and usable on the configured
    // model; refusing the whole request would throw away a chat that exists, and answering 500
    // would tell the window nothing was created when something was.
    if body.model.is_some() || body.effort.is_some() {
        if let Err(error) =
            crate::chats::set_model(&state.pool, &chat_id, body.model.as_deref()).await
        {
            tracing::warn!(%error, chat_id = %chat_id, "the new conversation kept the configured model");
        }
        if let Err(error) =
            crate::chats::set_effort(&state.pool, &chat_id, body.effort.as_deref()).await
        {
            tracing::warn!(%error, chat_id = %chat_id, "the new conversation kept the default effort");
        }
    }
    // Each of these reads "the caller sent one, AND writing it failed" — the guard short-circuits,
    // so a caller who sent nothing still writes nothing, exactly as the nesting these replaced did.
    if !body.fallback_model.is_empty()
        && let Err(error) =
            crate::chats::set_fallback(&state.pool, &chat_id, &body.fallback_model).await
    {
        tracing::warn!(%error, chat_id = %chat_id, "the new conversation kept no fallback");
    }
    if !body.extra_dirs.is_empty()
        && let Err(error) =
            crate::chats::set_extra_dirs(&state.pool, &chat_id, &body.extra_dirs).await
    {
        tracing::warn!(%error, chat_id = %chat_id, "the new conversation reaches only its own directory");
    }
    if body.turn_budget_usd.is_some()
        && let Err(error) =
            crate::chats::set_turn_budget(&state.pool, &chat_id, body.turn_budget_usd).await
    {
        tracing::warn!(%error, chat_id = %chat_id, "the new conversation kept no ceiling");
    }
    if !body.agents.is_empty()
        && let Err(error) = crate::chats::set_agents(&state.pool, &chat_id, &body.agents).await
    {
        tracing::warn!(%error, chat_id = %chat_id, "the new conversation defined no helpers");
    }
    if body.system_prompt.is_some()
        && let Err(error) =
            crate::chats::set_system_prompt(&state.pool, &chat_id, body.system_prompt.as_deref())
                .await
    {
        tracing::warn!(%error, chat_id = %chat_id, "the new conversation kept the default instructions");
    }
    if !body.denied_tools.is_empty()
        && let Err(error) =
            crate::chats::set_denied_tools(&state.pool, &chat_id, &body.denied_tools).await
    {
        tracing::warn!(%error, chat_id = %chat_id, "the new conversation denied no tools of its own");
    }

    // Measured once, here, where the file is read anyway and where the answer can still change what
    // happens: a picked-up session is the one case where a conversation arrives already full, and
    // the window it is given has to be wide enough to hold what it is carrying.
    //
    // This measurement used to decide whether to pick the session up AT ALL — anything over 140k
    // was refused and handed six exchanges instead — and that ceiling was written after a real
    // incident: about 180k of context, re-sent uncached as fresh input, $1.72 for a one-word
    // answer. What it bought was not what it looked like. The expense there is a COLD CACHE on a
    // large context, which a window ceiling does not prevent and a stump does not either; what a
    // stump prevented was the conversation. The bound that does hold is the one the CLI applies
    // for itself: it never sends more than its window, and it compacts to stay under it. So the
    // number below is now a window to widen rather than a line to refuse at, and the only refusal
    // left is for a session larger than any window a model has — which is arithmetic, not policy.
    if let Some(session) = &continued {
        let read = {
            let session_id = session.session_id.clone();
            match crate::sessions::default_root() {
                Some(root) => tokio::task::spawn_blocking(move || {
                    crate::sessions::conversation(&root, &session_id)
                })
                .await
                .ok()
                .flatten(),
                None => None,
            }
        };
        let carries = read.as_ref().and_then(|read| read.context_estimate);
        // Against the LARGEST window less the CLI's own compaction headroom, because that is the
        // point at which the CLI would refuse the context outright rather than summarise it. An
        // unreadable session file answers `None` and is picked up: a file this daemon could not
        // measure is not evidence that it is too big, and the CLI reads the same file for itself.
        let ceiling =
            crate::assistant::LARGEST_WINDOW_TOKENS - crate::assistant::COMPACTION_HEADROOM;
        let resumable = carries.is_none_or(|carries| carries <= ceiling);

        if resumable {
            // Widened to fit BEFORE the session is attached, so the first turn already runs in a
            // window that can hold what it inherited. Only upward, and clamped by `window_of` when
            // it is read back: an ordinary conversation picked up small keeps the default and
            // compacts at the default, which is the cheaper of the two and the right one for it.
            if let Some(carries) = carries
                && carries > crate::assistant::CONTEXT_WINDOW_TOKENS
                && let Err(error) = crate::chats::widen_window(
                    &state.pool,
                    &chat_id,
                    (carries + crate::assistant::COMPACTION_HEADROOM)
                        .min(crate::assistant::LARGEST_WINDOW_TOKENS),
                )
                .await
            {
                tracing::warn!(
                    %error,
                    chat_id = %chat_id,
                    "the conversation was picked up but kept the default window; it will compact sooner"
                );
            }
            // Written after the chat exists, because it is what `get_session` reads to decide the
            // first turn resumes rather than starts clean. A failure here is not a failed request:
            // the conversation is real and usable, it simply begins a context of its own — so it is
            // logged as the thing it is rather than rolled back into a 500 nobody can act on.
            if let Err(error) = crate::assistant::upsert_session(
                &state.pool,
                &chat_id,
                &session.session_id,
                &chrono::Utc::now().to_rfc3339(),
            )
            .await
            {
                tracing::warn!(
                    %error,
                    chat_id = %chat_id,
                    session_id = %session.session_id,
                    "the conversation was opened but could not be attached to its session; it will start clean"
                );
            }
        } else if let Some(read) = &read {
            // Larger than any window a model has, so there is nothing to resume INTO and it is
            // handed the tail instead. Rare now, and no longer the ordinary fate of a long
            // conversation. Stored rather than re-read: the file can be tens of megabytes, the
            // turn path must not go near it, and a handover that lives in a row is one somebody
            // can read afterwards.
            let tail = crate::sessions::exchanges(&read.said, HANDOVER_EXCHANGES);
            if !tail.is_empty()
                && let Ok(stored) = serde_json::to_string(&tail)
                && let Err(error) = crate::chats::set_handover(&state.pool, &chat_id, &stored).await
            {
                tracing::warn!(
                    %error,
                    chat_id = %chat_id,
                    "the conversation was opened but could not be handed its predecessor's tail"
                );
            }
        }
    }

    Ok(Json(serde_json::json!({ "chat_id": chat_id })))
}

/// The pinned model names as they are on disk right now.
///
/// Re-read per request rather than held on `AppState`, which every caller of this depends on: a
/// pinned choice travels as `--model` on the turn itself, so a name added to the file is one this
/// daemon can already run — and a catalogue cached at startup would spend a whole daemon lifetime
/// refusing it. `scripts/refresh-models.py` rewrites this file, and nothing should have to be
/// restarted for that to take.
///
/// An unreadable or missing file answers with the built-in defaults rather than an error, matching
/// what startup does: a picker that fails closed leaves somebody unable to change a model because
/// of a typo in a key that has nothing to do with models.
fn models_config() -> crate::config::ModelsConfig {
    crate::config::models_config_now()
}

/// Every named model is on the menu AND is one the agent CLI could take over, or a refusal.
///
/// The same allowlist a pinned model goes through, for the same reason: a fallback naming something
/// the daemon would not run is a turn that dies at spawn on the day the primary is overloaded —
/// which is to say, on the worst day, and only then.
///
/// Cloud only, which the pinned model deliberately is not. `--fallback-model` is a flag on the
/// agent CLI; the local route is a different process that has never heard of it, so a local choice
/// here is a name handed to a CLI that cannot resolve it — the exact failure this check exists to
/// prevent, arriving from the one direction the id check alone let through.
fn checked_fallback(names: &[String]) -> Result<(), StatusCode> {
    let config = models_config();
    for name in names {
        cloud_choice(&config, name).ok_or(StatusCode::BAD_REQUEST)?;
    }
    Ok(())
}

/// The catalogue entry a name refers to, if it is one the agent CLI could be handed.
///
/// Takes the config rather than reading it, which is what makes the rule testable: `models_config`
/// reads a fixed path, so a test running from the crate root gets the built-in defaults and those
/// have no local model in them — the exact case this exists to refuse would be unreachable.
///
/// "Cloud" here means the agent CLI, not "not on this machine". Both `--fallback-model` and the
/// per-helper `model` inside `--agents` are flags on that CLI; the local route is a different
/// process that has never heard of either, so a local choice in one of those places is a name
/// handed to something that cannot resolve it. The conversation's OWN model is deliberately not
/// filtered this way — picking it is how a conversation moves onto the local route at all.
fn cloud_choice(
    config: &crate::config::ModelsConfig,
    id: &str,
) -> Option<crate::config::AssistantChoice> {
    config
        .catalogue()
        .into_iter()
        .find(|choice| choice.id == id)
        .filter(|choice| {
            crate::chats::Brain::from_wire(&choice.brain) == crate::chats::Brain::Cloud
        })
}

/// The largest `--agents` value this daemon will write, in characters.
///
/// A helper set travels as ONE argv element, and Windows caps an entire command line at 32767
/// characters — the prompt, every flag and this. Refused at the door rather than at spawn, because
/// over the line `CreateProcess` fails with an error about nothing in particular and the turn looks
/// broken rather than too big. Somebody who needs more has the CLI's own answer: files in the
/// project's `.claude/agents/`, which this merges with rather than replaces.
///
/// A helper's `tools` list counts toward this same total — it is serialised inside the same object,
/// on the way to the same argv element — but does not move the number. Measured against 49 built-in
/// names at up to 22 characters each, granting a helper every one of them costs roughly 1,200
/// characters; the ceiling was sized for prompts, which dwarf that, so it stays unchanged. A
/// conversation defining enough helpers with a full list each to approach 8,000 hits the refusal
/// this constant already gives, which is the ceiling doing its one job, not a new failure mode.
const AGENTS_JSON_CEILING: usize = 8_000;

/// The longest standing instructions this daemon will write, in characters.
///
/// The same command-line ceiling `AGENTS_JSON_CEILING` guards, counted separately because they are
/// separate argv elements and a person hitting one should not be told about the other. Windows caps
/// a whole command line at 32767: these two together are 16000 of it, and the message itself is
/// also on that line — which is a limit this daemon has always had and does not introduce here.
const INSTRUCTIONS_CEILING: usize = 8_000;

/// Standing instructions that will fit on a command line, or a refusal.
///
/// Length is the whole of it. There is nothing else to check: the text becomes ONE element of an
/// argument vector, never a shell word, so no character in it means anything to anything but the
/// model reading it.
fn checked_instructions(text: &str) -> Result<(), StatusCode> {
    if text.len() > INSTRUCTIONS_CEILING {
        return Err(StatusCode::BAD_REQUEST);
    }
    Ok(())
}

/// Every named tool is one this daemon knows how to deny, or a refusal.
///
/// Names only, never the CLI's `Bash(git *)` patterns. Not because a pattern is dangerous — it can
/// only ever deny — but because a pattern is a rule language, and a rule that matches nothing is
/// reported as one line on stderr that nobody using this app will ever read. A name off the list is
/// a refusal somebody can act on; a pattern with a typo is a restriction that silently is not one.
fn checked_denials(names: &[String]) -> Result<(), StatusCode> {
    for name in names {
        if !crate::runner::BUILTIN_TOOLS.contains(&name.as_str()) {
            return Err(StatusCode::BAD_REQUEST);
        }
    }
    Ok(())
}

/// Every helper is one the CLI would actually build, or a refusal.
///
/// The door checks this because the CLI does NOT. Measured against 2.1.198, it parses the flag
/// inside a try/catch and answers a throw with an EMPTY agent list: a single bad definition costs
/// you every helper you defined, silently, with the run continuing as though you had asked for
/// none. There is no message and no exit code to notice. So what could not survive is refused here,
/// where there is somebody to tell.
fn checked_agents(agents: &[crate::runner::Subagent]) -> Result<(), StatusCode> {
    let config = models_config();
    let mut seen: Vec<&str> = Vec::new();

    for agent in agents {
        // A name the CLI would reject, or one that is not a name. `-` first is its own documented
        // rule — a leading dash reads as a flag. The rest is this daemon's: the name is what a model
        // types to delegate, so a space or a quote in it is a helper nothing can call by hand.
        let name = agent.name.trim();
        if name.is_empty()
            || name.len() > 64
            || name.starts_with('-')
            || !name
                .chars()
                .all(|c| c.is_ascii_alphanumeric() || c == '-' || c == '_')
        {
            return Err(StatusCode::BAD_REQUEST);
        }
        // Two helpers of one name collapse into one on the way into the object the flag takes, and
        // the person watches the other vanish without being told. Refused here so nothing is lost
        // quietly. Case-sensitive, because that is what actually collapses: the CLI keys on the
        // exact string, so `Reviewer` and `reviewer` are genuinely two helpers, and refusing them
        // would be this daemon inventing a rule the CLI does not have.
        if seen.contains(&name) {
            return Err(StatusCode::BAD_REQUEST);
        }
        seen.push(name);

        // Both are `min(1)` in the CLI's own schema. The description is load-bearing beyond that:
        // it is the whole of what the parent model reads to decide whether to delegate, so a helper
        // without one is defined, listed, and never used.
        if agent.description.trim().is_empty() || agent.prompt.trim().is_empty() {
            return Err(StatusCode::BAD_REQUEST);
        }

        // Reuses `BUILTIN_TOOLS` for a different job than `checked_denials` puts it to: there it is
        // the vocabulary of what a CONVERSATION may be denied, here it is the vocabulary of what a
        // HELPER may be granted — same list, because both are naming the one set of tools this
        // daemon knows about. Names only, never the CLI's `Bash(git *)` patterns, for the reason
        // `checked_denials` already gives: a pattern is a rule language, and a typo in one is a
        // restriction that silently is not one. `Some(vec![])` is checked and accepted here, not
        // skipped — a helper granted no tools at all is a coherent, explicit thing to ask for, and
        // treating it like `None` would make that restriction vanish.
        if let Some(tools) = &agent.tools {
            checked_denials(tools)?;
        }

        // A helper runs INSIDE the agent CLI, so its model has to be one that CLI can take — the
        // same reason the fallback is cloud-only, and not the same question as which route the
        // conversation itself is on.
        let named = match &agent.model {
            None => None,
            Some(id) => Some(cloud_choice(&config, id).ok_or(StatusCode::BAD_REQUEST)?),
        };

        // Against the levels the helper's OWN model takes when it named one, and against the union
        // when it did not. This is the one place the narrow check is honest: a helper's model and
        // its effort arrive in the same object, in one request, so they cannot drift apart between
        // two calls the way a conversation's can — which is exactly why `is_effort_level` checks the
        // union and this does not.
        if let Some(level) = agent.effort.as_deref() {
            let takes = match &named {
                Some(choice) => choice.efforts.iter().any(|have| have == level),
                None => crate::config::is_effort_level(&config, level),
            };
            if !takes {
                return Err(StatusCode::BAD_REQUEST);
            }
        }
    }

    if crate::runner::agents_json(agents).len() > AGENTS_JSON_CEILING {
        return Err(StatusCode::BAD_REQUEST);
    }
    Ok(())
}

/// Every path is absolute and is a directory that is there, or a refusal.
///
/// Checked here rather than at the first turn, matching `cwd`: a conversation pointed at a typo
/// looks exactly like one pointed at a project until somebody asks it to read a file, and the
/// answer comes back as a model's confusion rather than as a refusal anybody can act on.
///
/// Absolute because a relative path resolves against the DAEMON's working directory, which is not a
/// place the caller knows or meant — and this grants tool access, so a path nobody verified is a
/// directory nobody chose. Stored as given rather than canonicalised, for the reason `cwd` gives:
/// on Windows a canonical path carries a `\\?\` prefix that a raw one does not.
async fn checked_dirs(paths: &[String]) -> Result<(), StatusCode> {
    for raw in paths {
        let path = std::path::Path::new(raw);
        let is_directory = tokio::fs::metadata(path)
            .await
            .map(|found| found.is_dir())
            .unwrap_or(false);
        if !path.is_absolute() || !is_directory {
            return Err(StatusCode::BAD_REQUEST);
        }
    }
    Ok(())
}

/// A ceiling that is a real amount of money, or a refusal.
///
/// `is_finite` and not just a range check: JSON carries infinities and NaN through some encoders,
/// and `format!("{ceiling}")` would hand the CLI the word `inf` as a dollar amount. Zero is refused
/// as well — a ceiling of nothing is a conversation that cannot answer, which is what clearing it
/// is for and says so plainly.
fn checked_budget(amount: f64) -> Result<(), StatusCode> {
    if !amount.is_finite() || amount <= 0.0 {
        return Err(StatusCode::BAD_REQUEST);
    }
    Ok(())
}

/// How long the `/api/tags` menu probe waits, and no more.
///
/// A couple of seconds, not `runner::OLLAMA_EXCHANGE_TIMEOUT` (120s) — that timeout is sized for a
/// COLD MODEL LOADING before it can answer a generation request, which has nothing to do with this
/// probe. `get_assistant_models` and `chosen_brain` are called whenever a menu opens and the window
/// may poll either, so a wedged or unreachable Ollama must cost the menu a brief pause and then
/// today's menu — never a hung window while a person is only trying to see what is on offer.
const OLLAMA_TAGS_TIMEOUT: std::time::Duration = std::time::Duration::from_secs(2);

/// The one shared client every `/api/tags` probe goes through, built once rather than once per
/// request — the same one-client-per-route argument `assistants::ConfiguredAssistants` already
/// makes for the turn-serving routes: `reqwest::Client::new()` (or a fresh `builder()`) per request
/// rebuilds a whole connection pool and TLS backend every time, and these two routes are called
/// often enough (whenever a menu opens, possibly polled) for that cost to be worth avoiding.
static OLLAMA_TAGS_CLIENT: std::sync::OnceLock<reqwest::Client> = std::sync::OnceLock::new();

/// Builds `OLLAMA_TAGS_CLIENT` the first time it is asked for, and hands back the same client every
/// time after — never a fresh one per call, per this module's own constraint above.
fn ollama_tags_client() -> &'static reqwest::Client {
    OLLAMA_TAGS_CLIENT.get_or_init(|| {
        reqwest::Client::builder()
            .timeout(OLLAMA_TAGS_TIMEOUT)
            .build()
            .expect("HTTP client for the /api/tags probe (check TLS and proxy environment)")
    })
}

/// The menu both the picker and the door work from: the configured catalogue, merged with what
/// this machine actually has pulled.
///
/// The one place `models_config()` and `installed_local_models` are read together, so
/// `chosen_brain` and `get_assistant_models` cannot each assemble their own copy of this join and
/// drift apart the day somebody changes one of them — a filter, a sort, a source — and not the
/// other. Read from the file on every call rather than cached in `AppState`: a pinned choice travels
/// as `--model` on the turn itself, so a name added to the file is one the daemon can already run,
/// and a catalogue cached at startup would spend a whole daemon lifetime refusing it.
///
/// Fails closed on every kind of Ollama trouble (unreachable daemon, non-2xx, unreadable body) to
/// `catalogue()`'s own menu rather than an error or a hang: `installed_local_models` answers an
/// empty list on failure, `catalogue_with_installed` with an empty list IS `catalogue()`, and
/// `OLLAMA_TAGS_CLIENT` — built once and reused, never a fresh client per call — bounds how long a
/// wedged Ollama can hold up either caller to `OLLAMA_TAGS_TIMEOUT`.
async fn menu(
    asking: Asking,
) -> (
    crate::config::ModelsConfig,
    Vec<crate::config::AssistantChoice>,
) {
    let config = models_config();
    // "Which models has `ollama pull` fetched?" is an Ollama question, asked of `/api/tags`, which
    // only Ollama serves. On any other resolved engine — and on a refused one, whose local rows
    // `catalogue_scoped` drops entirely — the probe is a dial nothing reads, paid on every menu
    // open against a server that does not answer it, so the list is simply empty instead.
    let installed = if matches!(
        config.local_engine(),
        Ok(crate::config::ResolvedLocalEngine {
            engine: crate::config::LocalEngine::Ollama,
            ..
        })
    ) {
        crate::capabilities::installed_local_models(
            ollama_tags_client(),
            crate::runner::OLLAMA_BASE_URL,
        )
        .await
    } else {
        Vec::new()
    };
    let choices = match asking {
        Asking::Daemon => config.catalogue_with_installed(&installed),
        Asking::Chat { rooted } => config.catalogue_for_chat(&installed, rooted),
    };
    (config, choices)
}

/// Why `chosen_brain` could not hand back a route the caller may actually use.
enum BrainRefusal {
    /// No catalogue entry — the current `menu()`, installed models included — names this id.
    UnknownModel,
    /// A Codex model needs a rooted conversation with its classifier hook wired.
    NeedsRoot,
    /// The id names a real choice, but this machine cannot serve what it names —
    /// `Assistants::can_serve`'s own reason, carried verbatim into the refusal body of both
    /// doors that ask — opening a conversation and re-pointing one — so somebody who picked a
    /// model this machine cannot run is told which one and why, not handed a bare 503.
    CannotServe(String),
}

/// The reason Codex cannot answer an unrooted conversation.
const CODEX_NEEDS_A_ROOT: &str =
    "A Codex model answers only a conversation rooted in a project whose classifier hook is wired.";

/// The caller whose available models are being selected.
#[derive(Clone, Copy, Debug)]
enum Asking {
    /// The daemon's project-independent model menu.
    Daemon,
    /// A chat menu constrained by whether the conversation is rooted.
    Chat { rooted: bool },
}

/// Whether the asker is a rooted chat: `None` for the daemon's own menu.
fn rooted_of(asking: Asking) -> Option<bool> {
    match asking {
        Asking::Daemon => None,
        Asking::Chat { rooted } => Some(rooted),
    }
}

/// Which route a choice id names and can actually run, or a refusal.
///
/// One function because two routes ask — opening a conversation and re-pointing one — and sharing
/// `menu()` (above) with `get_assistant_models` is how the two are kept from disagreeing about which
/// names are real: the menu the picker is served and the menu the door validates against are the
/// same read, not two copies that could come apart.
///
/// Checks the cheap, file-only `catalogue()` first, and only reaches for `menu()` — installed models
/// included, over `OLLAMA_TAGS_CLIENT` — when the id is not there. This is safe because
/// `catalogue_with_installed` is documented on `config.rs` to always return a SUPERSET of
/// `catalogue()`: the merge only ever adds local entries, and none at all when
/// `local_assistant_model` is unset. So an id found in the cheap set would have been found in the
/// merged one too — no id changes its answer, no refusal changes — while the common cases (every
/// cloud model, the hosted model, the already-configured local model) never touch the network at
/// all. Do not drop this fast path or flip the order: either would put a 2s Ollama probe back in
/// front of every chat creation and patch, cloud models included.
///
/// Once the id resolves to a route, `state.assistants.can_serve` is asked whether this machine can
/// actually run it. Only `Refusal::CannotServe` is surfaced as a refusal here: the other three
/// variants (`RouteNotConfigured`, `HostedModelNamedButNoKey`, `NotServedByThisFactory`) answer "is
/// this ROUTE configured or reachable at all", which is `serves`'s question, asked at turn time —
/// not this door's. `ConfiguredAssistants::can_serve` never returns any of those three for a route
/// this catalogue actually named a choice for, but a double standing in for "nothing is configured"
/// (`assistants::NoAssistants`) may, and treating that as a capability refusal here would refuse
/// every cloud pick the moment `state.assistants` is not fully wired — the wrong door, not a
/// capability gap.
async fn chosen_brain(
    state: &AppState,
    id: &str,
    asking: Asking,
) -> Result<crate::chats::Brain, BrainRefusal> {
    chosen_brain_in(state, &models_config(), id, asking).await
}

/// Resolves a model choice for one caller using a supplied model configuration.
async fn chosen_brain_in(
    state: &AppState,
    config: &crate::config::ModelsConfig,
    id: &str,
    asking: Asking,
) -> Result<crate::chats::Brain, BrainRefusal> {
    if matches!(asking, Asking::Chat { rooted: false })
        && config
            .runner_of(id)
            .or_else(|| crate::model_catalog::runner_by_id(id))
            == Some("codex")
    {
        return Err(BrainRefusal::NeedsRoot);
    }

    let cheap_choices = match asking {
        Asking::Daemon => config.catalogue(),
        Asking::Chat { rooted } => config.catalogue_for_chat(&[], rooted),
    };
    let brain = if let Some(choice) = cheap_choices.into_iter().find(|choice| choice.id == id) {
        crate::chats::Brain::from_wire(&choice.brain)
    } else if crate::model_catalog::cached_or_fallback()
        .iter()
        .any(|found| {
            found.id == id
                && crate::model_catalog::admits(
                    config.active_runner(),
                    rooted_of(asking),
                    found.runner,
                )
        })
    {
        // A model the vendor lists (or the built-in catalogue names) that no config row does.
        // Looked up without the network, like the cheap catalogue above.
        crate::chats::Brain::Cloud
    } else {
        let (_, choices) = menu(asking).await;
        choices
            .into_iter()
            .find(|choice| choice.id == id)
            .map(|choice| crate::chats::Brain::from_wire(&choice.brain))
            .ok_or(BrainRefusal::UnknownModel)?
    };

    if let Err(crate::assistants::Refusal::CannotServe(reason)) =
        state.assistants.can_serve(brain, id).await
    {
        return Err(BrainRefusal::CannotServe(reason));
    }

    Ok(brain)
}

/// Query parameters for the assistant model menu.
#[derive(serde::Deserialize)]
struct ModelsQuery {
    chat: Option<String>,
}

/// Which models a conversation may be moved to, and how hard each can be asked to think.
///
/// Built from the same `menu()` `chosen_brain` uses, above — installed models included, over
/// `OLLAMA_TAGS_CLIENT` — rather than a second copy of the merge; see `menu()`'s doc comment for the
/// fail-closed reasoning. Always pays for the installed-models read, unlike `chosen_brain`'s fast
/// path: this route serves the WHOLE menu, so there is no cheap subset it could answer from instead.
///
/// Each choice is then marked (`config::marked_with`) with what `state.assistants.declared_for`
/// found — grouped by route because that trait method answers for one `Brain` at a time, and this
/// menu mixes cloud, local and hosted choices in one list. A route with no choices on the menu
/// (the common case for the hosted route, and for local when nothing is configured) is skipped
/// rather than asked with an empty slice, so an untouched install costs this route nothing beyond
/// the network read `menu()` already pays for.
async fn get_assistant_models(
    State(state): State<AppState>,
    Query(query): Query<ModelsQuery>,
) -> Json<serde_json::Value> {
    let asking = match query.chat {
        Some(chat_id) => Asking::Chat {
            rooted: crate::assistant::may_answer_on_codex(
                crate::chats::cwd_of(&state.pool, &chat_id)
                    .await
                    .ok()
                    .flatten()
                    .as_deref(),
            ),
        },
        None => Asking::Daemon,
    };
    let (config, choices) = menu(asking).await;

    let mut declared: std::collections::HashMap<String, crate::capabilities::Declared> =
        std::collections::HashMap::new();
    for brain in [
        crate::chats::Brain::Cloud,
        crate::chats::Brain::Local,
        crate::chats::Brain::OpenRouter,
    ] {
        let ids: Vec<String> = choices
            .iter()
            .filter(|choice| crate::chats::Brain::from_wire(&choice.brain) == brain)
            .map(|choice| choice.id.clone())
            .collect();
        if ids.is_empty() {
            continue;
        }
        declared.extend(state.assistants.declared_for(brain, &ids).await);
    }
    let choices = crate::config::marked_with(choices, &declared);

    Json(serde_json::json!({
        // Each choice carries its OWN effort levels, which is what the picker draws: they differ
        // per model, and a menu built from the union below would offer levels that die at spawn.
        "choices": choices,
        // What an unpinned conversation runs on, so the window can NAME that state rather than
        // showing an empty selection and letting a person guess.
        "configured": config.configured_model(),
        // The same model as a person reads it, from the daemon's one naming function.
        "configured_label": crate::model_catalog::display_name(config.configured_model()),
        // The union, for the one case with no model chosen yet — the front door before anybody
        // picks. Also what the door validates against. Unaffected by the installed merge: an
        // installed model carries no effort levels of its own, `effort_levels()` keeps calling the
        // sync `catalogue()`, and there is nothing for the network read to add here.
        "efforts": config.effort_levels(),
    }))
}

/// Query parameters for `GET /models/latest`.
#[derive(serde::Deserialize)]
struct LatestModelsQuery {
    vendor: Option<String>,
}

/// The newest models per vendor, for the `latest_models` agent tool. The same snapshot the picker
/// serves, so there is one list; `current()` only waits on the process's very first call.
async fn get_latest_models(
    Query(query): Query<LatestModelsQuery>,
) -> (StatusCode, Json<serde_json::Value>) {
    let snapshot = crate::model_catalog::current().await;
    match crate::model_catalog::latest(&snapshot, query.vendor.as_deref()) {
        Ok(body) => (StatusCode::OK, Json(body)),
        Err(error) => (
            StatusCode::BAD_REQUEST,
            Json(serde_json::json!({ "error": error })),
        ),
    }
}

/// The picker as groups: provider and family, newest first, named as a person reads them.
///
/// The config's cloud choices come first and win; the discovered models (live vendor lists, or the
/// built-in catalogue when there is no key or the vendor does not answer) are appended when the
/// runner may answer them. Never carries a key.
async fn get_model_groups(
    State(state): State<AppState>,
    Query(query): Query<ModelsQuery>,
) -> Json<serde_json::Value> {
    let asking = match query.chat {
        Some(chat_id) => Asking::Chat {
            rooted: crate::assistant::may_answer_on_codex(
                crate::chats::cwd_of(&state.pool, &chat_id)
                    .await
                    .ok()
                    .flatten()
                    .as_deref(),
            ),
        },
        None => Asking::Daemon,
    };
    let (config, choices) = menu(asking).await;
    let mut cloud: Vec<crate::config::AssistantChoice> = choices
        .into_iter()
        .filter(|choice| choice.brain == "cloud")
        .map(|mut choice| {
            if choice.label == choice.id {
                choice.label = crate::model_catalog::display_name(&choice.id);
            }
            choice
        })
        .collect();
    let snapshot = crate::model_catalog::current().await;
    let mut created = std::collections::HashMap::new();
    // Codex models this caller may not pick are still listed, and named here, so the picker shows
    // the whole vendor list and says why a row is closed instead of leaving the vendor out.
    let mut needs_root: Vec<String> = Vec::new();
    for found in &snapshot.models {
        if let Some(at) = found.created {
            created.insert(found.id.clone(), at);
        }
        if cloud.iter().any(|choice| choice.id == found.id) {
            continue;
        }
        if crate::model_catalog::admits(config.active_runner(), rooted_of(asking), found.runner) {
            cloud.push(crate::model_catalog::as_choice(found));
        } else if found.runner == "codex"
            && crate::model_catalog::admits(config.active_runner(), Some(true), found.runner)
        {
            needs_root.push(found.id.clone());
            cloud.push(crate::model_catalog::as_choice(found));
        }
    }
    Json(serde_json::json!({
        "groups": crate::model_catalog::group(cloud, &created),
        "needs_root": needs_root,
        "source": snapshot.source,
        "sources": snapshot.sources,
        "catalogue_version": crate::model_catalog::CATALOGUE_VERSION,
        "fetched_at": snapshot.fetched_at,
    }))
}

/// Starts this conversation's next turn on a fresh window, with a replay of what was recently said.
///
/// This app's `/clear` more than its `/compact`, and the distinction sharpened when the CLI took
/// over compaction: the CLI SUMMARISES a full context and carries on in the same session, which is
/// what a `/compact` means and what now happens on its own. This drops the session entirely — the
/// next turn starts clean and is handed a few hundred tokens of recent exchanges — which is what
/// somebody means when the conversation has gone somewhere they do not want it to follow.
///
/// It stays because that is a real thing to want and nothing else offers it. What it is no longer
/// is the escape hatch from an expensive context: a conversation that grows now compacts on its
/// own, so nobody has to throw one away to stop paying for it.
async fn post_fresh_context(
    State(state): State<AppState>,
    Path(chat_id): Path<String>,
) -> Result<StatusCode, StatusCode> {
    chat_must_exist(&state, &chat_id).await?;
    // A live turn writes its session back when it ends (`upsert_session`), so forgetting one now
    // would be undone in a minute by the turn that is still running — the request would report
    // success and change nothing. 409 is the same answer `POST /assistant/message` gives.
    if crate::assistant::is_busy(&chat_id) {
        return Err(StatusCode::CONFLICT);
    }

    crate::assistant::forget_session(&state.pool, &chat_id)
        .await
        .map_err(|error| {
            tracing::warn!(%error, "starting a conversation on a fresh context failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })?;
    Ok(StatusCode::NO_CONTENT)
}

/// Starts the next turn clean and tells it nothing about what came before — this app's `/clear`.
///
/// The stronger of the two, and the difference is the whole point: `/fresh-context` moves the
/// conversation onto a new window and replays what was recently said; this moves the floor of that
/// replay to now, so there is nothing to replay. It also hides the tail an editor session was
/// picked up with, which is older than every turn here and would otherwise be the one thing a clear
/// did not clear.
///
/// The turns are not deleted. Every one of them stays readable in the window and stays in `runs`
/// costing what it cost — clearing decides what the MODEL is shown, not what happened. That is the
/// same position `handoff.rs` takes about rewriting history.
async fn post_clear_context(
    State(state): State<AppState>,
    Path(chat_id): Path<String>,
) -> Result<StatusCode, StatusCode> {
    chat_must_exist(&state, &chat_id).await?;
    // For the reason above, and one more: the floor is the id of the LAST run, and a turn in flight
    // already has a row. Clearing now would put the floor above a turn that has not answered yet,
    // so its answer would arrive into a conversation that had already forgotten the question.
    if crate::assistant::is_busy(&chat_id) {
        return Err(StatusCode::CONFLICT);
    }

    crate::chats::clear_context(&state.pool, &chat_id)
        .await
        .map_err(|error| {
            tracing::warn!(%error, "clearing what a conversation is shown failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })?;
    // Both, and in this order. The cut decides what a fresh turn is TOLD; forgetting the session is
    // what makes the next turn fresh at all. Without the second, the next turn would resume the old
    // window and the cut would have changed nothing anybody could see.
    crate::assistant::forget_session(&state.pool, &chat_id)
        .await
        .map_err(|error| {
            tracing::warn!(%error, "forgetting a cleared conversation's session failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })?;
    Ok(StatusCode::NO_CONTENT)
}

/// A 404 for a conversation this daemon does not have — never opened here, or archived.
///
/// Answered before anything is written, for the reason `patch_chat` gives at length: without it a
/// route reports success for an UPDATE that matched no row, which is the API saying "done" about
/// something it did not do.
async fn chat_must_exist(state: &AppState, chat_id: &str) -> Result<(), StatusCode> {
    match crate::chats::get(&state.pool, chat_id).await {
        Ok(Some(_)) => Ok(()),
        Ok(None) => Err(StatusCode::NOT_FOUND),
        Err(_) => Err(StatusCode::INTERNAL_SERVER_ERROR),
    }
}

/// The commands a slash offers before there is a conversation to offer them for.
///
/// The front door has a box you type into and no chat behind it yet, so the chat-scoped route
/// cannot answer — and until this, a slash there did nothing at all. Typing `/` where you land is
/// the first thing anybody does.
///
/// The same `available` the chat route calls, with no project: personal commands and installed
/// plugins' travel wherever the conversation ends up, and a project's belong to a directory this
/// conversation does not have yet. So the front door offers exactly what will still be true after
/// the first message, and never a command that stops existing the moment the chat is opened.
async fn get_commands(Query(query): Query<MentionQuery>) -> Json<serde_json::Value> {
    let typed: String = query.q.chars().take(MENTION_QUERY_LIMIT).collect();
    // Off the async runtime like its chat-scoped twin: this reads several directories and every
    // command file's front matter, which is short and is still disk on a request thread.
    let commands = tokio::task::spawn_blocking(move || {
        let available = crate::commands::available(None, crate::commands::home().as_deref());
        crate::commands::matching(&available, &typed)
    })
    .await
    .unwrap_or_default();

    Json(serde_json::json!({ "commands": commands }))
}

/// Which built-in tools a conversation can be told not to reach for.
///
/// Served rather than hardcoded in the window, because there is exactly one list and it is the one
/// `cli_args` writes into the flag. A second copy in the UI would offer a name the door refuses, or
/// — worse — stop offering one the daemon can still deny, so a restriction somebody set becomes
/// invisible and unremovable.
///
/// The list is deliberately WIDER than any single CLI version's tool set: see `BUILTIN_TOOLS`,
/// where the margin is the point. Denying a name this CLI does not have costs one line on stderr;
/// missing one it does have costs the restriction.
async fn get_deniable_tools() -> Json<serde_json::Value> {
    Json(serde_json::json!({ "tools": crate::runner::BUILTIN_TOOLS }))
}

/// Tells an absent field from one explicitly sent as `null`.
///
/// `Option<Option<T>>` alone does NOT do this. Serde maps a JSON `null` onto the OUTER option, so
/// `{"model": null}` and `{}` both arrive as `None` and the unpin is silently dropped — the field
/// has three states in the type and two on the wire. Deserializing the inner option and wrapping it
/// in `Some` is what makes the third reachable: absent never calls this at all and falls to
/// `Default`, while `null` calls it and comes back `Some(None)`.
///
/// Found by a test that pinned a value and then cleared it. The ones that only cleared an already
/// empty field passed either way, which is the shape of test that agrees with any implementation.
fn sent_even_if_null<'de, T, D>(deserializer: D) -> Result<Option<Option<T>>, D::Error>
where
    T: serde::Deserialize<'de>,
    D: serde::Deserializer<'de>,
{
    <Option<T> as serde::Deserialize>::deserialize(deserializer).map(Some)
}

#[derive(serde::Deserialize)]
struct PatchChatRequest {
    title: Option<String>,
    brain: Option<String>,
    /// What this conversation may do without being asked, from here on.
    ///
    /// Five rungs where there used to be a checkbox with two states. The old `plan_only` field is
    /// gone rather than kept as an alias: the only client of this API is this application's own
    /// window, and an alias would be a second way to say one thing, maintained for nobody.
    ///
    /// A spelling outside the five fails the whole request rather than falling to a default. The
    /// reader's "unknown reads as auto" rule exists for rows written before the column did, and
    /// applying it to a request would let a typo quietly widen what a conversation may do.
    permission_mode: Option<crate::chats::PermissionMode>,
    /// The project this conversation is about, as an absolute path to a directory.
    ///
    /// The only way a conversation opened in the window ever gets tools: `tool_policy_for` grants
    /// them on a directory plus a wired classifier hook, and without this there was no directory to
    /// give it.
    cwd: Option<String>,
    /// Which model answers this conversation from here on.
    ///
    /// `Option<Option<_>>` and not `Option<_>`, because three states have to be distinguishable and
    /// two of them look identical to the simpler type: the field ABSENT means "leave it alone", an
    /// explicit `null` means "unpin, follow the configured model again", and a string pins. With a
    /// single `Option` the unpin is unsayable — it arrives as absence, which is the one thing it is
    /// not.
    ///
    /// The string is a choice id from `GET /assistant/models` and is checked against that list. Not
    /// because an unknown one is dangerous — it becomes one element of an argument vector, never a
    /// shell word — but because it is a turn that dies at spawn, on the person's next message, for a
    /// reason the window could have given them here.
    #[serde(default, deserialize_with = "sent_even_if_null")]
    model: Option<Option<String>>,
    /// How hard the model is asked to think: `low | medium | high | xhigh | max`, or `null` for the
    /// CLI's own default. Same three states as `model`, for the same reason.
    #[serde(default, deserialize_with = "sent_even_if_null")]
    effort: Option<Option<String>>,
    /// Who answers when the chosen model is unavailable, as choice ids in the order to try them.
    /// `null` or an empty list clears it. Same three states as `model`, for the same reason.
    #[serde(default, deserialize_with = "sent_even_if_null")]
    fallback_model: Option<Option<Vec<String>>>,
    /// Absolute paths this conversation's tools may also reach. `null` or empty clears them.
    #[serde(default, deserialize_with = "sent_even_if_null")]
    extra_dirs: Option<Option<Vec<String>>>,
    /// The most one TURN may spend, in dollars. `null` clears the ceiling.
    ///
    /// Per turn, not per conversation: the CLI's flag bounds one invocation and this daemon spawns
    /// one per turn. The field is named for what it bounds so nobody reads it as a total.
    #[serde(default, deserialize_with = "sent_even_if_null")]
    turn_budget_usd: Option<Option<f64>>,
    /// The helpers this conversation may hand work to. `null` or an empty list clears them.
    ///
    /// The WHOLE set every time, not one helper added or removed. A conversation's helpers are read
    /// and drawn as a list, and a client that could add one without naming the others would have to
    /// be told what happens when two requests cross — this way the last writer wins and says so.
    #[serde(default, deserialize_with = "sent_even_if_null")]
    agents: Option<Option<Vec<crate::runner::Subagent>>>,
    /// Standing instructions appended to this conversation's system prompt. `null` or blank clears
    /// them.
    ///
    /// Appended and never substituted: the flag that REPLACES the CLI's system prompt exists and is
    /// deliberately not reachable from here, because it would drop the tool descriptions and the
    /// safety framing with it.
    #[serde(default, deserialize_with = "sent_even_if_null")]
    system_prompt: Option<Option<String>>,
    /// Built-in tools this conversation may not reach for. `null` or an empty list clears them.
    ///
    /// The whole set every time, like `agents`, and for the same reason.
    #[serde(default, deserialize_with = "sent_even_if_null")]
    denied_tools: Option<Option<Vec<String>>>,
    /// Whether this conversation's turns may use the user's ambient MCP servers.
    ///
    /// Turning it on needs a project: a conversation with no directory is `McpOnly` and never
    /// reaches those servers, so offering the switch there would promise something it cannot do.
    ambient_mcp: Option<bool>,
}

/// What the two doors onto a conversation refuse with. Every path that had no body keeps none
/// (`Status`); the one path that has something to say — a model this machine cannot serve — carries
/// the reason in the body (`WithDetail`), the `{"detail": ...}` shape this crate already uses for a
/// refusal with a reason (see the `"detail"` sites around invalid ownership claims and unreadable
/// pins). One enum rather than widening every existing `StatusCode` return in this function to a
/// body-carrying tuple: every one of those keeps compiling unchanged through the `From<StatusCode>`
/// impl below, so this stays the smallest change that gets that one path its body.
///
/// `create_chat` answered a bare 503 here for one release, because the packet that added the
/// check had no test asking for the body and would not widen a response without one. Opening a
/// conversation on a model the machine cannot run is the FIRST place somebody meets this
/// refusal, though, so it is the last place a bare status is any use.
enum ChatRefusal {
    Status(StatusCode),
    WithDetail(StatusCode, String),
}

impl IntoResponse for ChatRefusal {
    fn into_response(self) -> axum::response::Response {
        match self {
            ChatRefusal::Status(status) => status.into_response(),
            ChatRefusal::WithDetail(status, detail) => {
                (status, Json(serde_json::json!({ "detail": detail }))).into_response()
            }
        }
    }
}

impl From<StatusCode> for ChatRefusal {
    fn from(status: StatusCode) -> Self {
        ChatRefusal::Status(status)
    }
}

impl From<BrainRefusal> for ChatRefusal {
    fn from(refusal: BrainRefusal) -> Self {
        match refusal {
            BrainRefusal::UnknownModel => ChatRefusal::Status(StatusCode::BAD_REQUEST),
            BrainRefusal::NeedsRoot => {
                ChatRefusal::WithDetail(StatusCode::BAD_REQUEST, CODEX_NEEDS_A_ROOT.to_string())
            }
            // Not a 500, for the same reason `BrainRefusal`'s own `From<StatusCode>` impl gives:
            // nothing broke, this machine simply cannot run what was asked for.
            BrainRefusal::CannotServe(reason) => {
                ChatRefusal::WithDetail(StatusCode::SERVICE_UNAVAILABLE, reason)
            }
        }
    }
}

/// Renames a conversation, changes which model answers it, or both.
///
/// The two halves are deliberately not symmetric. A rename touches nothing but the row; a model
/// change also drops the chat's resumable session, because the model taking over has not seen the
/// turns the other one answered and resuming across that gap would hand it a context missing them.
/// That is done here rather than asked of the caller: a client that forgets the step poisons the
/// conversation for the next model, and the shell will not be the only client.
async fn patch_chat(
    State(state): State<AppState>,
    Path(chat_id): Path<String>,
    Json(body): Json<PatchChatRequest>,
) -> Result<StatusCode, ChatRefusal> {
    // Answered before anything is written. Without it a PATCH against a chat that was never opened
    // — or was archived — reports `204 No Content` for an UPDATE that matched no row, which is the
    // API saying "done" about something it did not do.
    if crate::chats::get(&state.pool, &chat_id)
        .await
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?
        .is_none()
    {
        return Err(StatusCode::NOT_FOUND.into());
    }

    // All three move something a turn in flight is already using, and nothing else records any of
    // them. `answered_by` is written when a turn's row is born, so changing the brain under a live
    // turn makes that column lie about who answered it; the chat's `cwd` is the ONLY record of where
    // a turn ran — the assistant path never writes `runs.cwd` — so moving it under a live turn makes
    // the row the wrong answer to "where did this happen". 409 rather than a queue: the same answer
    // `POST /assistant/message` gives for the same reason.
    //
    // A rename moves neither and is left alone.
    if (body.brain.is_some()
        || body.model.is_some()
        || body.effort.is_some()
        || body.cwd.is_some()
        || body.permission_mode.is_some()
        || body.ambient_mcp.is_some())
        && crate::assistant::is_busy(&chat_id)
    {
        return Err(StatusCode::CONFLICT.into());
    }

    if let Some(cwd) = body.cwd.as_deref() {
        // Absolute, and a directory that is there. Checked HERE rather than at the first turn: a
        // conversation pointed at a typo would look exactly like one pointed at a project until
        // somebody asked it to read a file, and the answer would arrive as a model's confusion
        // rather than as a refusal anybody could act on.
        //
        // Absolute because a relative path would be resolved against the DAEMON's working
        // directory, which is not a place the caller knows or meant. Stored as given rather than
        // canonicalised: on Windows a canonical path carries a `\\?\` prefix that a raw one does
        // not, and this string is handed to the CLI as its working directory and compared against a
        // living process's own.
        let path = std::path::Path::new(cwd);
        let is_directory = tokio::fs::metadata(path)
            .await
            .map(|found| found.is_dir())
            .unwrap_or(false);
        if !path.is_absolute() || !is_directory {
            return Err(StatusCode::BAD_REQUEST.into());
        }

        crate::chats::set_cwd(&state.pool, &chat_id, cwd)
            .await
            .map_err(|error| {
                tracing::warn!(%error, "pointing a conversation at a project failed");
                StatusCode::INTERNAL_SERVER_ERROR
            })?;

        // For the reason the brain does, and one more. The CLI keeps its transcripts as
        // `<root>/<project>/<session>.jsonl` — one directory per project — so a session had in one
        // tree is not somewhere a run in another tree would look for it. And its context is about
        // the old tree regardless: continuing it here would answer questions about this project out
        // of the last one's files.
        crate::assistant::forget_session(&state.pool, &chat_id)
            .await
            .map_err(|error| {
                tracing::warn!(%error, "forgetting a moved conversation's session failed");
                StatusCode::INTERNAL_SERVER_ERROR
            })?;
    }

    if let Some(brain) = body.brain.as_deref() {
        crate::chats::set_brain(&state.pool, &chat_id, crate::chats::Brain::from_wire(brain))
            .await
            .map_err(|error| {
                tracing::warn!(%error, "changing a chat's model failed");
                StatusCode::INTERNAL_SERVER_ERROR
            })?;
        crate::assistant::forget_session(&state.pool, &chat_id)
            .await
            .map_err(|error| {
                tracing::warn!(%error, "forgetting a chat's session failed");
                StatusCode::INTERNAL_SERVER_ERROR
            })?;
    }

    // After the brain block above, and that order is the whole point: a choice names its own route,
    // so when a client sends both and they disagree, the one that cannot be wrong is the one that
    // lands last. A row saying `local` while naming a cloud model would be sent to Ollama under a
    // name it has never heard.
    if let Some(model) = &body.model {
        let brain = match model {
            Some(id) => {
                let cwd = crate::chats::cwd_of(&state.pool, &chat_id)
                    .await
                    .map_err(|error| {
                        tracing::warn!(%error, "reading a conversation's project failed");
                        StatusCode::INTERNAL_SERVER_ERROR
                    })?;
                let rooted = crate::assistant::may_answer_on_codex(cwd.as_deref());
                Some(chosen_brain(&state, id, Asking::Chat { rooted }).await?)
            }
            // Unpinning says nothing about the route. The conversation goes back to following the
            // configured model, and `brain` keeps whatever it already had — changing it here would
            // be this route inventing a decision nobody expressed.
            None => None,
        };

        crate::chats::set_model(&state.pool, &chat_id, model.as_deref())
            .await
            .map_err(|error| {
                tracing::warn!(%error, "pinning a conversation to a model failed");
                StatusCode::INTERNAL_SERVER_ERROR
            })?;

        if let Some(brain) = brain {
            crate::chats::set_brain(&state.pool, &chat_id, brain)
                .await
                .map_err(|error| {
                    tracing::warn!(%error, "routing a conversation to its model's brain failed");
                    StatusCode::INTERNAL_SERVER_ERROR
                })?;
        }

        // For the reason the brain block gives: the model taking over has not seen the turns the
        // other one answered, and resuming across that gap hands it a context missing them.
        crate::assistant::forget_session(&state.pool, &chat_id)
            .await
            .map_err(|error| {
                tracing::warn!(%error, "forgetting a re-modelled chat's session failed");
                StatusCode::INTERNAL_SERVER_ERROR
            })?;
    }

    // None of the three below joins the 409 guard above, and that is a per-column answer rather than
    // an oversight. `cwd` and the brain are guarded because a live turn's record would come to
    // disagree with them — the chat row is the only note of where a turn ran, and `answered_by` is
    // written when the row is born. Nothing records a run's fallback, its extra directories or its
    // ceiling, and all three are read at LAUNCH, so a turn already running has its own copy and
    // cannot be made to lie by changing them. Refusing here would only stop somebody setting up
    // their next turn while waiting for this one.
    if let Some(fallback) = &body.fallback_model {
        let names = fallback.clone().unwrap_or_default();
        checked_fallback(&names)?;
        crate::chats::set_fallback(&state.pool, &chat_id, &names)
            .await
            .map_err(|error| {
                tracing::warn!(%error, "naming a conversation's fallback model failed");
                StatusCode::INTERNAL_SERVER_ERROR
            })?;
    }

    if let Some(dirs) = &body.extra_dirs {
        let paths = dirs.clone().unwrap_or_default();
        checked_dirs(&paths).await?;
        crate::chats::set_extra_dirs(&state.pool, &chat_id, &paths)
            .await
            .map_err(|error| {
                tracing::warn!(%error, "widening what a conversation may reach failed");
                StatusCode::INTERNAL_SERVER_ERROR
            })?;
    }

    if let Some(ceiling) = &body.turn_budget_usd {
        if let Some(amount) = ceiling {
            checked_budget(*amount)?;
        }
        crate::chats::set_turn_budget(&state.pool, &chat_id, *ceiling)
            .await
            .map_err(|error| {
                tracing::warn!(%error, "setting what a turn may spend failed");
                StatusCode::INTERNAL_SERVER_ERROR
            })?;
    }

    // Read at launch like the three above, so it stays out of the 409 for the reason they do. A
    // turn already running holds the helper set it was spawned with; nothing here can reach in and
    // change what it was given.
    if let Some(agents) = &body.agents {
        let defined = agents.clone().unwrap_or_default();
        checked_agents(&defined)?;
        crate::chats::set_agents(&state.pool, &chat_id, &defined)
            .await
            .map_err(|error| {
                tracing::warn!(%error, "defining a conversation's helpers failed");
                StatusCode::INTERNAL_SERVER_ERROR
            })?;
    }

    if let Some(instructions) = &body.system_prompt {
        if let Some(text) = instructions {
            checked_instructions(text)?;
        }
        crate::chats::set_system_prompt(&state.pool, &chat_id, instructions.as_deref())
            .await
            .map_err(|error| {
                tracing::warn!(%error, "writing a conversation's standing instructions failed");
                StatusCode::INTERNAL_SERVER_ERROR
            })?;
    }

    if let Some(denied) = &body.denied_tools {
        let names = denied.clone().unwrap_or_default();
        checked_denials(&names)?;
        crate::chats::set_denied_tools(&state.pool, &chat_id, &names)
            .await
            .map_err(|error| {
                tracing::warn!(%error, "narrowing what a conversation may reach for failed");
                StatusCode::INTERNAL_SERVER_ERROR
            })?;
    }

    // No `forget_session`. Effort changes how hard the same model thinks, not who is thinking — the
    // context the session holds is still that model's own, and dropping it would make a dial nobody
    // considers destructive silently restart the conversation.
    if let Some(effort) = &body.effort {
        if let Some(level) = effort
            && !crate::config::is_effort_level(&models_config(), level)
        {
            return Err(StatusCode::BAD_REQUEST.into());
        }
        crate::chats::set_effort(&state.pool, &chat_id, effort.as_deref())
            .await
            .map_err(|error| {
                tracing::warn!(%error, "changing how hard a conversation thinks failed");
                StatusCode::INTERNAL_SERVER_ERROR
            })?;
    }

    if let Some(permission_mode) = body.permission_mode {
        crate::chats::set_permission_mode(&state.pool, &chat_id, permission_mode)
            .await
            .map_err(|error| {
                tracing::warn!(%error, "changing what a conversation may do without asking failed");
                StatusCode::INTERNAL_SERVER_ERROR
            })?;
    }

    if let Some(on) = body.ambient_mcp {
        // Only a conversation with a project can use the ambient servers; one without a
        // directory is `McpOnly`, which drops them whatever is stored here.
        if on
            && crate::chats::cwd_of(&state.pool, &chat_id)
                .await
                .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?
                .is_none()
        {
            return Err(StatusCode::BAD_REQUEST.into());
        }
        crate::chats::set_ambient_mcp(&state.pool, &chat_id, on)
            .await
            .map_err(|error| {
                tracing::warn!(%error, "changing a conversation's ambient MCP servers failed");
                StatusCode::INTERNAL_SERVER_ERROR
            })?;
        // The next turn respawns with or without `--strict-mcp-config`.
        crate::assistant::evict_live(&chat_id);
    }

    if let Some(title) = body.title.as_deref() {
        crate::chats::rename(&state.pool, &chat_id, Some(title))
            .await
            .map_err(|error| {
                tracing::warn!(%error, "renaming a chat failed");
                StatusCode::INTERNAL_SERVER_ERROR
            })?;
    }

    Ok(StatusCode::NO_CONTENT)
}

/// How much of a model's answer may become a title.
///
/// A model asked for five words can answer with a paragraph, and the answer goes straight into a
/// sidebar. Cut here rather than in CSS: what is stored is what other clients will read, and a
/// paragraph in that column is a paragraph everywhere.
const TITLE_LIMIT: usize = 80;

/// The first thing the model said that could be a name, bounded.
fn title_from(reply: &str) -> String {
    reply
        .lines()
        .map(str::trim)
        .find(|line| !line.is_empty())
        .unwrap_or_default()
        .chars()
        .take(TITLE_LIMIT)
        .collect()
}

/// Names a conversation using the local model.
///
/// Local only, and 503 rather than a cloud fallback when there is none: a title is decoration, and
/// decoration is not worth a billed cloud call — every turn on the other path is a run with a price
/// on it. The same 503 covers a model that answered with nothing usable, because from the caller's
/// side "the local model could not name this" is one fact either way.
///
/// The history comes from `recent_exchanges`, so this reads the conversation under the same barrier
/// a local turn does: nothing from before the last turn that read third-party text. A title drawn
/// from a stranger's mail would be that mail choosing what this conversation is called.
async fn post_chat_title(
    State(state): State<AppState>,
    Path(chat_id): Path<String>,
) -> Result<StatusCode, StatusCode> {
    // `state.local_assistant.clone()` before the migration to the assistant factory: the field this
    // read no longer exists, so this call site is one of the lines that migration is allowed to
    // touch beyond the `AppState` literal.
    let assistant = state
        .assistants
        .assistant_for(crate::chats::Brain::Local, None)
        .map_err(|_| StatusCode::SERVICE_UNAVAILABLE)?;
    let history = crate::assistant::recent_exchanges(&state.pool, &chat_id)
        .await
        .map_err(|error| {
            tracing::warn!(%error, "reading a chat before naming it failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })?;
    // Nothing has been said, so there is nothing to name it after. Asking anyway would be the model
    // guessing about a conversation that has not happened.
    if history.is_empty() {
        return Err(StatusCode::CONFLICT);
    }

    // The prompt asks for no tools; the model still has them. This is what says whether it used one
    // to read a stranger's words on the way to an answer.
    let taint = std::sync::atomic::AtomicBool::new(false);
    let turn = assistant
        .answer(
            &history,
            "Name this conversation in at most five words, in the language it is being had in. \
             Answer with the name alone, on one line, and call no tools — everything you need is \
             already above.",
            &taint,
        )
        .await
        .map_err(|error| {
            tracing::warn!(%error, "the local model could not name a chat");
            StatusCode::SERVICE_UNAVAILABLE
        })?;

    // Naming a conversation is NOT a run, so there is no row to mark and nothing downstream that
    // would refuse this answer later — `mark_untrusted_context`, which is what a local turn does
    // here, has nothing to write against. The fail-closed move left is to drop the title: one drawn
    // from a mail body would be its sender naming this conversation, in the sidebar, for good.
    //
    // Reported as the same 503 as a model that could not answer, because from the caller's side
    // both are "the local model could not name this". The distinction that matters is for whoever
    // reads the log, and it is in the line below.
    if taint.load(std::sync::atomic::Ordering::SeqCst) {
        tracing::warn!(chat_id = %chat_id, "a chat's proposed name read third-party text; dropping it");
        return Err(StatusCode::SERVICE_UNAVAILABLE);
    }

    let title = title_from(&turn.answer);
    if title.is_empty() {
        return Err(StatusCode::SERVICE_UNAVAILABLE);
    }
    crate::chats::rename(&state.pool, &chat_id, Some(&title))
        .await
        .map_err(|error| {
            tracing::warn!(%error, "storing a chat's name failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })?;
    Ok(StatusCode::NO_CONTENT)
}

/// Records that this conversation has been read.
///
/// Its own route rather than a field on `PATCH`, and the reason is the 409 that one answers. A
/// model cannot move under a live turn, so `PATCH` refuses while a chat is busy — and reading a
/// conversation while it is mid-turn is the ordinary case: you sent the message and you are
/// watching it. Folded together, the answer you were looking straight at would come back marked
/// unread.
///
/// Takes no body. Where the watermark lands is `chats::mark_seen`'s to decide, because a client
/// naming its own could mark a turn it has not drawn yet — a list read that overtook the transcript
/// would silently swallow the very answer it was meant to announce.
async fn post_chat_seen(
    State(state): State<AppState>,
    Path(chat_id): Path<String>,
) -> Result<StatusCode, StatusCode> {
    // Answered before anything is written, for the reason `patch_chat` gives: `204` over an UPDATE
    // that matched no row is the API saying "done" about something it did not do.
    if crate::chats::get(&state.pool, &chat_id)
        .await
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?
        .is_none()
    {
        return Err(StatusCode::NOT_FOUND);
    }

    crate::chats::mark_seen(&state.pool, &chat_id)
        .await
        .map(|()| StatusCode::NO_CONTENT)
        .map_err(|error| {
            tracing::warn!(%error, "marking a chat read failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })
}

/// Puts an archived conversation back on the list: 204, or 404 when it was not archived.
async fn post_chat_restore(
    State(state): State<AppState>,
    Path(chat_id): Path<String>,
) -> Result<StatusCode, StatusCode> {
    match crate::chats::restore(&state.pool, &chat_id).await {
        Ok(true) => Ok(StatusCode::NO_CONTENT),
        Ok(false) => Err(StatusCode::NOT_FOUND),
        Err(error) => {
            tracing::warn!(%error, "restoring a chat failed");
            Err(StatusCode::INTERNAL_SERVER_ERROR)
        }
    }
}

/// Chat groups (P4): the list, create, rename, delete and assign handlers.
async fn list_chat_groups(
    State(state): State<AppState>,
) -> Result<Json<Vec<crate::chat_groups::ChatGroup>>, StatusCode> {
    crate::chat_groups::list(&state.pool)
        .await
        .map(Json)
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)
}

#[derive(serde::Deserialize)]
struct ChatGroupName {
    name: String,
}

fn group_refusal(error: crate::chat_groups::GroupError) -> (StatusCode, Json<serde_json::Value>) {
    use crate::chat_groups::GroupError;
    match error {
        GroupError::Blank => refusal(StatusCode::BAD_REQUEST, "blank_name"),
        GroupError::TooLong => refusal(StatusCode::BAD_REQUEST, "name_too_long"),
        GroupError::NoGroup | GroupError::NoChat => refusal(StatusCode::NOT_FOUND, "not_found"),
        GroupError::Db(error) => {
            tracing::warn!(%error, "chat group operation failed");
            refusal(StatusCode::INTERNAL_SERVER_ERROR, "internal")
        }
    }
}

async fn create_chat_group(
    State(state): State<AppState>,
    Json(body): Json<ChatGroupName>,
) -> Result<(StatusCode, Json<crate::chat_groups::ChatGroup>), (StatusCode, Json<serde_json::Value>)>
{
    crate::chat_groups::create(&state.pool, &body.name)
        .await
        .map(|group| (StatusCode::CREATED, Json(group)))
        .map_err(group_refusal)
}

async fn rename_chat_group(
    State(state): State<AppState>,
    Path(group_id): Path<i64>,
    Json(body): Json<ChatGroupName>,
) -> Result<Json<crate::chat_groups::ChatGroup>, (StatusCode, Json<serde_json::Value>)> {
    crate::chat_groups::rename(&state.pool, group_id, &body.name)
        .await
        .map(Json)
        .map_err(group_refusal)
}

async fn delete_chat_group(
    State(state): State<AppState>,
    Path(group_id): Path<i64>,
) -> Result<StatusCode, StatusCode> {
    match crate::chat_groups::delete(&state.pool, group_id).await {
        Ok(true) => Ok(StatusCode::NO_CONTENT),
        Ok(false) => Err(StatusCode::NOT_FOUND),
        Err(_) => Err(StatusCode::INTERNAL_SERVER_ERROR),
    }
}

#[derive(serde::Deserialize)]
struct ChatGroupAssignment {
    group_id: Option<i64>,
}

async fn put_chat_group(
    State(state): State<AppState>,
    Path(chat_id): Path<String>,
    Json(body): Json<ChatGroupAssignment>,
) -> Result<StatusCode, (StatusCode, Json<serde_json::Value>)> {
    crate::chat_groups::assign(&state.pool, &chat_id, body.group_id)
        .await
        .map(|()| StatusCode::NO_CONTENT)
        .map_err(group_refusal)
}

/// Takes a conversation off the list, and leaves every turn of it in place.
///
/// Archive rather than delete, because every turn is a billed run: removing the rows would hide
/// money spent from the table that records it. The transcript stays readable to anything that asks
/// for the chat by id.
async fn delete_chat(
    State(state): State<AppState>,
    Path(chat_id): Path<String>,
) -> Result<StatusCode, StatusCode> {
    crate::chats::archive(&state.pool, &chat_id)
        .await
        .map(|()| StatusCode::NO_CONTENT)
        .map_err(|error| {
            tracing::warn!(%error, "archiving a chat failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })
}

async fn get_proposals(
    State(state): State<AppState>,
) -> Result<Json<Vec<crate::proposals::Proposal>>, StatusCode> {
    crate::proposals::list_pending(&state.pool)
        .await
        .map(Json)
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)
}

/// What the night decided not to do, and why.
///
/// The half of the skip that was missing. A job's node that hits an action needing approval marks
/// its item `skipped`, reverts the tree and lets the queue carry on — and files a `skipped-item`
/// proposal so the morning knows what was set aside. `list_pending` deliberately does not carry
/// those (approving one would resume nothing), which left the record with no door at all: measured
/// on 2026-08-08, two items skipped and the only way to read either was to open the database.
/// How many of each decision list are waiting on a person — `GET /waiting/count`.
///
/// One field per list the shell's `countWaitingDecisions` sums, counted the way that function
/// counts it. A list that fails to read is `null` rather than a 500, because the shell already
/// treats a partial count as more useful than a blank one.
#[derive(Debug, Default, serde::Serialize)]
struct WaitingCount {
    wheel: Option<usize>,
    approvals: Option<usize>,
    team_actions: Option<usize>,
    recruits: Option<usize>,
    merges: Option<usize>,
    exclusions: Option<usize>,
    git: Option<usize>,
}

/// The badge every page of the shell draws, as one read.
///
/// It used to be seven polls from every window, each shipping a whole list only for its length to
/// be taken. The lists themselves stay where they were for the pages that draw them; this is only
/// the number.
async fn get_waiting_count(State(state): State<AppState>) -> Json<WaitingCount> {
    let pool = &state.pool;
    let (wheel, approvals, team_actions, recruits, merges, exclusions, git) = tokio::join!(
        crate::browser::open_sessions(pool),
        crate::proposals::list_pending(pool),
        crate::proposals::list_pending_team_actions(pool),
        crate::proposals::list_pending_recruits(pool, None),
        crate::contacts::pending_merges(pool),
        crate::exclusion::pending_requests(pool),
        vcs::waiting_on_a_person(pool),
    );
    Json(WaitingCount {
        // The shell's `isWheelRequest`: an agent asked for the wheel and a proposal stands behind it.
        wheel: wheel.ok().map(|sessions| {
            sessions
                .iter()
                .filter(|session| {
                    session.mode == "wheel-requested" && session.proposal_id.is_some()
                })
                .count()
        }),
        approvals: approvals.ok().map(|rows| rows.len()),
        team_actions: team_actions.ok().map(|rows| rows.len()),
        recruits: recruits.ok().map(|rows| rows.len()),
        merges: merges.ok().map(|rows| rows.len()),
        exclusions: exclusions.ok().map(|rows| rows.len()),
        git: git.ok().map(|rows| rows.len()),
    })
}

/// The git requests that still want a person, uncapped: the same predicate the badge counts, so the
/// Waiting page and its number cannot disagree. Admin-only by default-deny, like `/waiting/count`
/// — no scope table entry.
async fn get_waiting_git(
    State(state): State<AppState>,
) -> Result<Json<Vec<vcs::RequestSummary>>, StatusCode> {
    vcs::waiting_on_a_person(&state.pool)
        .await
        .map(Json)
        .map_err(|error| {
            tracing::warn!(%error, "listing the git requests that want a person failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })
}

/// Puts an open git request away without touching its status: 204, 404 for an unknown id, 409 for
/// one that is not open (succeeded, running, or already settled). Admin-only by default-deny, like
/// `/waiting/count` — no scope table entry.
async fn post_vcs_request_dismiss(
    State(state): State<AppState>,
    Path(id): Path<i64>,
) -> Result<StatusCode, StatusCode> {
    match vcs::dismiss(&state.pool, id).await {
        Ok(()) => Ok(StatusCode::NO_CONTENT),
        Err(vcs::DismissError::NotFound) => Err(StatusCode::NOT_FOUND),
        Err(vcs::DismissError::NotOpen) => Err(StatusCode::CONFLICT),
        Err(vcs::DismissError::Db(error)) => {
            tracing::warn!(request_id = id, %error, "dismissing a git request failed");
            Err(StatusCode::INTERNAL_SERVER_ERROR)
        }
    }
}

/// The owner approves the test map change a paused merge carries (spec 2026-10-05 §3.4): 204,
/// 404 for an unknown id, 409 for a row that is not waiting for the owner. Admin-only by
/// default-deny, like `/dismiss`.
async fn post_vcs_request_approve(
    State(state): State<AppState>,
    Path(id): Path<i64>,
) -> Result<StatusCode, StatusCode> {
    owner_decision_status(
        id,
        "approving",
        vcs::approve_for_owner(&state.pool, id).await,
    )
}

/// The owner refuses it; the row ends `rejected`. Same answers as approving.
async fn post_vcs_request_refuse(
    State(state): State<AppState>,
    Path(id): Path<i64>,
) -> Result<StatusCode, StatusCode> {
    owner_decision_status(id, "refusing", vcs::refuse_for_owner(&state.pool, id).await)
}

fn owner_decision_status(
    id: i64,
    verb: &str,
    decided: Result<(), vcs::DismissError>,
) -> Result<StatusCode, StatusCode> {
    match decided {
        Ok(()) => Ok(StatusCode::NO_CONTENT),
        Err(vcs::DismissError::NotFound) => Err(StatusCode::NOT_FOUND),
        Err(vcs::DismissError::NotOpen) => Err(StatusCode::CONFLICT),
        Err(vcs::DismissError::Db(error)) => {
            tracing::warn!(request_id = id, %error, "{verb} a paused git request failed");
            Err(StatusCode::INTERNAL_SERVER_ERROR)
        }
    }
}

async fn get_skipped_items(
    State(state): State<AppState>,
) -> Result<Json<Vec<crate::proposals::Proposal>>, StatusCode> {
    crate::proposals::list_skipped_items(&state.pool)
        .await
        .map(Json)
        .map_err(|error| {
            tracing::warn!(%error, "listing skipped items failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })
}

/// What the injection barrier refused, and what it was going to do.
///
/// The same shape as the listing above and for the same reason: neither kind can be approved into
/// happening, so neither belongs on `/proposals`, whose two buttons answer 409 for anything but an
/// `action-approval`. Its own route rather than sharing `/proposals/skipped-items`, because those
/// are a job's items and the shell renders them inside a job graph — a refused email has
/// no graph to sit in and would arrive there as an orphan.
async fn get_refused_actions(
    State(state): State<AppState>,
) -> Result<Json<Vec<crate::proposals::Proposal>>, StatusCode> {
    crate::proposals::list_refused_actions(&state.pool)
        .await
        .map(Json)
        .map_err(|error| {
            tracing::warn!(%error, "listing refused actions failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })
}

/// Puts a read skipped item away. Its own door, not a third arm of `/reject`.
///
/// Nothing is being refused here and nothing is released — the job let go of the item and the
/// worktree when it skipped, hours before anyone read this. Sharing `/reject` would give the two a
/// single button whose label is wrong for one of them, and `reject_proposal` guards on
/// `kind = 'action-approval'`, so that button would answer 409 half the time.
async fn post_proposal_dismiss(
    State(state): State<AppState>,
    Path(id): Path<i64>,
) -> Result<StatusCode, StatusCode> {
    match crate::proposals::dismiss_skipped_item(&state.pool, id).await {
        Ok(()) => Ok(StatusCode::NO_CONTENT),
        Err(crate::proposals::RejectError::NotFound) => Err(StatusCode::NOT_FOUND),
        // Also the answer for a proposal of any other kind: nothing else is dismissable, and a
        // caller that aimed this at an action approval wanted `/reject`.
        Err(crate::proposals::RejectError::NotPending) => Err(StatusCode::CONFLICT),
        Err(crate::proposals::RejectError::Db(error)) => {
            tracing::warn!(proposal_id = id, %error, "dismissing a skipped item failed");
            Err(StatusCode::INTERNAL_SERVER_ERROR)
        }
    }
}

/// Turns a merge decision's outcome into the answer the caller gets.
///
/// The conflict is a 409 with a body, not a bare status: it is the one refusal here that names
/// something the person can go and change, and a status code cannot say which two instructions
/// disagree.
///
/// **That sentence was written before the body was, and described the opposite of what the code
/// did** — every arm returned a bare `StatusCode`, which axum renders with no body at all. Recorded
/// rather than quietly corrected, because a comment promising a guarantee the code does not keep is
/// the exact failure this whole handler was changed to end, and `post_proposal_approve` below was
/// carrying its own version of it.
fn merge_decision_response(
    outcome: Result<crate::contacts::MergeOutcome, crate::contacts::DecisionError>,
) -> Result<Json<serde_json::Value>, (StatusCode, String)> {
    match outcome {
        Ok(crate::contacts::MergeOutcome::Merged) => {
            Ok(Json(serde_json::json!({ "merged": true })))
        }
        Ok(crate::contacts::MergeOutcome::RefusedConflictingVerdicts { keep, absorb }) => {
            tracing::info!(%keep, %absorb, "refused a contact merge with conflicting verdicts");
            Err((
                StatusCode::CONFLICT,
                format!(
                    "these two people carry standing decisions that disagree — {keep} against {absorb}; settle one of them and decide this again"
                ),
            ))
        }
        Err(crate::contacts::DecisionError::NotPending) => Err((
            StatusCode::CONFLICT,
            "this suggestion has already been decided".to_owned(),
        )),
        Err(crate::contacts::DecisionError::Db(error)) => {
            tracing::warn!(%error, "deciding a contact merge failed");
            Err((
                StatusCode::INTERNAL_SERVER_ERROR,
                "the decision could not be recorded".to_owned(),
            ))
        }
    }
}

/// **Every refusal here carries a sentence, and that is the whole reason this returns a tuple.**
///
/// This route can answer 409 for two reasons that mean opposite things to the person who clicked:
/// the proposal is no longer pending (somebody already decided it, and the right response is to
/// stop) or the approval cannot resume (the run's worktree is gone, and the right response is to
/// start the work again). A status code cannot tell them apart, and the `NotResumable` arm below
/// used to say so in a comment while logging the reason server-side and sending nothing —
/// `create_job` had already settled the shape this follows.
///
/// The case that made it worth doing is real rather than hypothetical: `mode: "real"` is the API's
/// DEFAULT and creates no worktree, so approving a merge in such a run is refused by a mechanism
/// nobody can see, and the refusal is indistinguishable from a button that did not fire.
/// The body `approve` accepts, and the only kind that reads one.
///
/// `Option` and last in the argument list, so every existing caller — which sends no body at all —
/// is unaffected. A recruitment is a SUGGESTION: the director knows the name, the speciality and
/// the prompt well, and knows the engine, the model and the tool policy badly, because those are
/// what cost money per turn and what widen a surface. So the person approving may correct them, and
/// `agent::validate` runs over the correction.
#[derive(Default, Deserialize)]
#[serde(default)]
struct ApproveBody {
    hire: Option<crate::agent::AgentRequest>,
    /// Only a browser-wheel approval reads it: `"shell"` or `"window"`.
    seat: Option<String>,
}

async fn post_proposal_approve(
    State(state): State<AppState>,
    Path(id): Path<i64>,
    // Last, because axum requires a body extractor to be — and optional, because four of the five
    // kinds through this door send nothing.
    body: Option<Json<ApproveBody>>,
) -> Result<Json<serde_json::Value>, (StatusCode, String)> {
    let (edited, seat) = match body {
        Some(Json(body)) => (body.hire, body.seat),
        None => (None, None),
    };
    // Two kinds of proposal share this table and this door, and they are decided by entirely
    // different machinery: an action approval resumes a paused run, a contact merge joins two
    // people and touches no run at all. Reading the kind first is only a dispatch — the kind never
    // changes, and both paths below are compare-and-set on `status = 'pending'`, so a second
    // decision racing this one still loses there rather than here.
    let proposal = crate::proposals::get(&state.pool, id)
        .await
        .map_err(|error| {
            tracing::warn!(proposal_id = id, %error, "reading a proposal to approve failed");
            (
                StatusCode::INTERNAL_SERVER_ERROR,
                "the proposal could not be read".to_owned(),
            )
        })?
        .ok_or_else(|| (StatusCode::NOT_FOUND, format!("there is no proposal {id}")))?;
    let kind = proposal.kind.clone();
    if kind == "contact-merge" {
        // Uncancellable for the same reason the resume below is: the decision commits, and a
        // request dropped mid-flight must not leave the record disagreeing with what happened.
        let state = state.clone();
        let outcome =
            uncancellable(async move { crate::contacts::approve_merge(&state.pool, id).await })
                .await
                .map_err(|status| (status, "the merge task did not finish".to_owned()))?;
        return merge_decision_response(outcome);
    }
    if kind == "refinement" {
        // Fifth kind through this door, and the third that starts no run: approving activates the
        // refinement and decides the proposal in one transaction. Uncancellable for the reason the
        // others give — a dropped request must not leave the proposal and the layer disagreeing
        // about whether the agent was allowed to learn something.
        let state = state.clone();
        let activated =
            uncancellable(async move { crate::knowledge::approve(&state.pool, id).await })
                .await
                .map_err(|status| (status, "the approval task did not finish".to_owned()))?;
        return match activated {
            Ok(refinement_id) => Ok(Json(serde_json::json!({ "refinement_id": refinement_id }))),
            Err(crate::knowledge::DecisionError::NotFound) => {
                Err((StatusCode::NOT_FOUND, format!("there is no proposal {id}")))
            }
            Err(crate::knowledge::DecisionError::NotPending) => Err((
                StatusCode::CONFLICT,
                "this proposal has already been decided".to_owned(),
            )),
            Err(crate::knowledge::DecisionError::Malformed) => Err((
                StatusCode::UNPROCESSABLE_ENTITY,
                "this proposal does not name a refinement".to_owned(),
            )),
        };
    }
    if kind == "calendar-event" {
        // Third kind through this door, and the second that starts no run: approving writes the
        // event and the decision in one transaction. Uncancellable for the same reason as the
        // other two — a dropped request must not leave the proposal and the calendar disagreeing.
        let state = state.clone();
        let created =
            uncancellable(
                async move { crate::calendar::approve_proposed_event(&state.pool, id).await },
            )
            .await
            .map_err(|status| (status, "the approval task did not finish".to_owned()))?;
        return match created {
            Ok(event_id) => Ok(Json(serde_json::json!({ "event_id": event_id }))),
            Err(crate::calendar::DecisionError::NotFound) => {
                Err((StatusCode::NOT_FOUND, format!("there is no proposal {id}")))
            }
            Err(crate::calendar::DecisionError::NotPending) => Err((
                StatusCode::CONFLICT,
                "this proposal has already been decided".to_owned(),
            )),
            Err(crate::calendar::DecisionError::Malformed) => {
                tracing::warn!(
                    proposal_id = id,
                    "a calendar proposal carried no usable event"
                );
                Err((
                    StatusCode::UNPROCESSABLE_ENTITY,
                    "this proposal carries no usable event, so there is nothing to create"
                        .to_owned(),
                ))
            }
            Err(crate::calendar::DecisionError::Db(error)) => {
                tracing::warn!(proposal_id = id, %error, "approving a calendar proposal failed");
                Err((
                    StatusCode::INTERNAL_SERVER_ERROR,
                    "the event could not be written".to_owned(),
                ))
            }
        };
    }

    if kind == "github-action" {
        // The kind through this door that ACTS on approval, where `team-action` waits for a tick.
        // A pillar answering synchronously has no later pass to be picked up on, so without this the
        // button would approve nothing.
        //
        // Uncancellable for the reason all of its neighbours are, and here it carries more: the work
        // between the claim and the note is a live call to GitHub, and a request dropped across it
        // would leave a comment published and the row saying only that somebody said yes.
        let state = state.clone();
        let ran = uncancellable(async move {
            crate::github::approve_proposed_operation(&state.pool, &state.github, id).await
        })
        .await
        .map_err(|status| (status, "the approval task did not finish".to_owned()))?;
        return match ran {
            Ok(outcome) => Ok(Json(serde_json::json!({
                "operation": outcome.kind,
                "exit_code": outcome.exit_code,
                "stdout": outcome.stdout,
                "output_tail": outcome.output_tail,
            }))),
            Err(crate::github::DecisionError::NotFound) => {
                Err((StatusCode::NOT_FOUND, format!("there is no proposal {id}")))
            }
            Err(crate::github::DecisionError::NotPending) => Err((
                StatusCode::CONFLICT,
                "this proposal has already been decided".to_owned(),
            )),
            Err(crate::github::DecisionError::Malformed) => {
                tracing::warn!(
                    proposal_id = id,
                    "a github proposal carried no usable operation"
                );
                Err((
                    StatusCode::UNPROCESSABLE_ENTITY,
                    "this proposal carries no usable operation, so there is nothing to run"
                        .to_owned(),
                ))
            }
            // The proposal is already `approved` and the note beneath it says what happened. The
            // status is the failure's own, so a missing token does not read as a broken daemon.
            Err(crate::github::DecisionError::Failed(failure)) => Err((
                github_failure_status(&failure),
                format!("approved, and it did not run: {failure}"),
            )),
            Err(crate::github::DecisionError::Db(error)) => {
                tracing::warn!(proposal_id = id, %error, "approving a github proposal failed");
                Err((
                    StatusCode::INTERNAL_SERVER_ERROR,
                    "the decision could not be recorded".to_owned(),
                ))
            }
        };
    }

    if kind == "browser-wheel" {
        return approve_browser_wheel(state, id, seat).await;
    }

    if kind == "fleet-exclusion" {
        // Fifth kind through this door, fourth that starts no run. Uncancellable for the reason the
        // others are: the rule and the decision that authorised it commit together, and a
        // request dropped mid-flight must not leave a job parked by a rule whose proposal still
        // reads `pending` beside it.
        let state = state.clone();
        let decided =
            uncancellable(async move { crate::exclusion::approve(&state.pool, id).await })
                .await
                .map_err(|status| (status, "the approval task did not finish".to_owned()))?;
        return match decided {
            Ok(crate::exclusion::Approved::Written(exclusion_id)) => {
                Ok(Json(serde_json::json!({ "exclusion_id": exclusion_id })))
            }
            // 200 and not an error: the person answered, and the answer was recorded. What changed
            // is that the question had stopped mattering while it waited, and a screen that showed
            // this as a failure would send them looking for a rule that was right not to be written.
            Ok(crate::exclusion::Approved::Stale) => Ok(Json(serde_json::json!({
                "exclusion_id": serde_json::Value::Null,
                "closed": "the jobs it named have ended, so no rule was written",
            }))),
            Err(crate::exclusion::DecisionError::NotFound) => {
                Err((StatusCode::NOT_FOUND, format!("there is no proposal {id}")))
            }
            Err(crate::exclusion::DecisionError::NotPending) => Err((
                StatusCode::CONFLICT,
                "this proposal has already been decided".to_owned(),
            )),
            Err(crate::exclusion::DecisionError::Malformed) => {
                tracing::warn!(
                    proposal_id = id,
                    "an exclusion request carried no usable pair"
                );
                Err((
                    StatusCode::UNPROCESSABLE_ENTITY,
                    "this request names no usable pair of jobs".to_owned(),
                ))
            }
            Err(crate::exclusion::DecisionError::Db(error)) => {
                tracing::warn!(proposal_id = id, %error, "approving an exclusion failed");
                Err((
                    StatusCode::INTERNAL_SERVER_ERROR,
                    "the rule could not be written".to_owned(),
                ))
            }
        };
    }

    if kind == "agent-recruit" {
        // The sixth kind, and the only one that grows the house rather than releasing something:
        // approving writes an `agents` row and a `team_members` row in one transaction with the
        // decision. Uncancellable for the reason all of them are — a dropped request must not leave
        // an agent hired into a team nobody agreed to.
        let state = state.clone();
        let hired =
            uncancellable(
                async move { crate::team::approve_recruit(&state.pool, id, edited).await },
            )
            .await
            .map_err(|status| (status, "the approval task did not finish".to_owned()))?;
        return match hired {
            Ok(agent_id) => Ok(Json(serde_json::json!({ "agent_id": agent_id }))),
            Err(crate::team::HireError::NotFound) => {
                Err((StatusCode::NOT_FOUND, format!("there is no proposal {id}")))
            }
            Err(crate::team::HireError::NotPending) => Err((
                StatusCode::CONFLICT,
                "this proposal has already been decided".to_owned(),
            )),
            Err(crate::team::HireError::Malformed) => Err((
                StatusCode::UNPROCESSABLE_ENTITY,
                "this request does not describe an agent this daemon can create".to_owned(),
            )),
            // 409 and a sentence: the team went away while the request waited, and the person can
            // still dismiss the proposal or recreate the team. Neither is obvious from a bare code.
            Err(crate::team::HireError::NoSuchTeam(team_id)) => Err((
                StatusCode::CONFLICT,
                format!("`{team_id}` no longer exists, so there is no team to hire them into"),
            )),
            Err(crate::team::HireError::Refused(why)) => Err((StatusCode::CONFLICT, why)),
            Err(crate::team::HireError::Db(error)) => {
                tracing::warn!(proposal_id = id, %error, "hiring an agent failed");
                Err((
                    StatusCode::INTERNAL_SERVER_ERROR,
                    "the agent could not be written".to_owned(),
                ))
            }
        };
    }

    if kind == "team-action" {
        // Fifth kind through this door, and the only one where approving DOES NOTHING but say yes.
        // The action is carried out by `team::execute_due_actions` on the next tick, and that is the
        // design rather than an omission: an HTTP handler that sends an email holds the connection
        // open while a slow SMTP thinks, and a daemon restarted in the middle loses the action with
        // no trace. A `pending` row survives a restart; an `await` in a handler does not.
        //
        // Uncancellable all the same, for the reason the four above are: the decision commits.
        let state = state.clone();
        let decided = uncancellable(async move {
            crate::proposals::transition(&state.pool, id, "approved", "approved by user").await
        })
        .await
        .map_err(|status| (status, "the approval task did not finish".to_owned()))?;
        return match decided {
            Ok(true) => Ok(Json(serde_json::json!({
                "queued": "the department's action will be carried out shortly",
            }))),
            // The compare-and-set lost: somebody decided this while the request was in flight.
            Ok(false) => Err((
                StatusCode::CONFLICT,
                "this proposal has already been decided".to_owned(),
            )),
            Err(error) => {
                tracing::warn!(proposal_id = id, %error, "approving a team action failed");
                Err((
                    StatusCode::INTERNAL_SERVER_ERROR,
                    "the approval could not be recorded".to_owned(),
                ))
            }
        };
    }

    // Uncancellable: the approval commits a transaction and only then spawns the resumed run, so a
    // request dropped in between leaves a `running` run nothing will ever drive.
    let pool = state.pool.clone();
    match uncancellable(async move { crate::runs::resume_approved_run(&state, id).await })
        .await
        .map_err(|status| (status, "the approval task did not finish".to_owned()))?
    {
        Ok(resume_id) => {
            // Spec B D12: a person's approval is the label of the park the resolver observed.
            if let Some(run_id) = proposal.run_id {
                crate::judge::resolve_review::label_from_decision(
                    &pool,
                    run_id,
                    proposal.tool_input.as_deref(),
                    crate::judge::resolve_review::PersonsDecision::Approve,
                )
                .await;
            }
            Ok(Json(serde_json::json!({ "resume_run_id": resume_id })))
        }
        Err(crate::runs::ResumeError::ProposalNotFound) => {
            Err((StatusCode::NOT_FOUND, format!("there is no proposal {id}")))
        }
        Err(crate::runs::ResumeError::ProposalNotPending) => Err((
            StatusCode::CONFLICT,
            "this proposal has already been decided".to_owned(),
        )),
        // The two 409s above and below mean opposite things — "somebody already answered this" and
        // "this can never be answered" — and the reason is the only thing that separates them. It
        // was already being built and was going only to the log.
        Err(crate::runs::ResumeError::NotResumable(reason)) => {
            tracing::warn!(
                proposal_id = id,
                reason,
                "approved proposal is not resumable"
            );
            Err((
                StatusCode::CONFLICT,
                format!("this approval cannot resume the run: {reason}"),
            ))
        }
        // The approval never returns this, but the `match` is exhaustive. Its own answer is the
        // decline door's: two different replies for the owner (spec B D12).
        Err(crate::runs::ResumeError::BelongsToAJob) => Err((
            StatusCode::CONFLICT,
            "this run is a job's node, and the job's own policy decides what happens to it"
                .to_owned(),
        )),
        Err(crate::runs::ResumeError::Db(error)) => {
            tracing::warn!(proposal_id = id, %error, "approving a proposal failed");
            Err((
                StatusCode::INTERNAL_SERVER_ERROR,
                "the approval could not be recorded".to_owned(),
            ))
        }
    }
}

/// A person took the wheel (spec §4.4, rules 1 and 3).
///
/// The `transition` below is the load-bearing line, and its position is the argument: it is a
/// compare-and-set on `status = 'pending'`, so exactly one of two concurrent approvals wins — and the
/// one that wins is the one that then hands over the browser. Handing over first and recording
/// afterwards would let both callers open a window; recording without handing over would leave a
/// proposal saying a person is driving something that was never started.
///
/// Uncancellable for the same reason as the three arms above: a request dropped in between would
/// leave the decision recorded and the window unopened.
async fn approve_browser_wheel(
    state: AppState,
    id: i64,
    seat: Option<String>,
) -> Result<Json<serde_json::Value>, (StatusCode, String)> {
    let choice = match seat.as_deref() {
        None => None,
        Some("shell") => Some(crate::browser_wheel::SeatChoice::Shell),
        Some("window") => Some(crate::browser_wheel::SeatChoice::Window),
        Some(_) => {
            return Err((
                StatusCode::BAD_REQUEST,
                "seat must be \"shell\" or \"window\"".to_owned(),
            ));
        }
    };
    let session_id = crate::proposals::get(&state.pool, id)
        .await
        .map_err(|error| {
            tracing::warn!(proposal_id = id, %error, "reading a wheel request failed");
            (
                StatusCode::INTERNAL_SERVER_ERROR,
                "the proposal could not be read".to_owned(),
            )
        })?
        .and_then(|proposal| proposal.tool_input)
        .and_then(|input| serde_json::from_str::<serde_json::Value>(&input).ok())
        .and_then(|input| input.get("session_id").and_then(serde_json::Value::as_i64))
        .ok_or_else(|| {
            (
                StatusCode::UNPROCESSABLE_ENTITY,
                "this wheel request names no session".to_owned(),
            )
        })?;

    // An explicit shell seat that is not on offer is refused BEFORE the decision is made: once the
    // proposal is approved, a refusal would strand the row in `wheel-requested`. Reads only the
    // database, so it does not depend on the pillar being on.
    if choice == Some(crate::browser_wheel::SeatChoice::Shell) {
        let offered = crate::browser::session_row(&state.pool, session_id)
            .await
            .map_err(|error| {
                tracing::warn!(proposal_id = id, %error, "reading a wheel session failed");
                (
                    StatusCode::INTERNAL_SERVER_ERROR,
                    "the session could not be read".to_owned(),
                )
            })?
            .is_some_and(|row| row.closed_at.is_none() && row.shell_eligible);
        if !offered {
            return Err((
                StatusCode::CONFLICT,
                serde_json::json!({ "error": "seat_unavailable" }).to_string(),
            ));
        }
    }

    let transitioned = crate::proposals::transition(&state.pool, id, "approved", "wheel accepted")
        .await
        .map_err(|error| {
            tracing::warn!(proposal_id = id, %error, "accepting a wheel request failed");
            (
                StatusCode::INTERNAL_SERVER_ERROR,
                "the decision could not be recorded".to_owned(),
            )
        })?;
    if !transitioned {
        return Err((
            StatusCode::CONFLICT,
            "this proposal has already been decided".to_owned(),
        ));
    }

    let handover = state.clone();
    match uncancellable(async move {
        crate::browser_wheel::accept_with_seat(&handover, session_id, choice).await
    })
    .await
    .map_err(|status| (status, "the handover task did not finish".to_owned()))?
    {
        Ok((row, nonce)) => {
            let mut answer = serde_json::json!({ "session": row });
            if let Some(nonce) = nonce {
                answer["seat_nonce"] = serde_json::Value::String(nonce);
            }
            Ok(Json(answer))
        }
        Err(crate::browser_wheel::WheelError::NoSuchSession) => Err((
            StatusCode::NOT_FOUND,
            "the session this wheel was asked for is gone".to_owned(),
        )),
        // The window did not open (spec §4.4a). The session is recorded as a failed delivery and the
        // proposal carries the reason; it does NOT go back to the agent.
        Err(error) => Err((StatusCode::BAD_GATEWAY, error.to_string())),
    }
}

/// The wheel was not given (spec §4.4), and the session goes with the refusal.
///
/// Spec §4.4's diagram draws an arrow back to `agente_conduz`, and this is deliberately narrower —
/// `browser_wheel`'s module comment carries the reasoning. In short: the wall that caused the request
/// is still there, §4.5 already says the run continues without that page, and giving the wheel back
/// would need a second place where the two processes can disagree about who is driving.
async fn reject_browser_wheel(state: AppState, id: i64) -> Result<StatusCode, StatusCode> {
    let session_id = crate::proposals::get(&state.pool, id)
        .await
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?
        .and_then(|proposal| proposal.tool_input)
        .and_then(|input| serde_json::from_str::<serde_json::Value>(&input).ok())
        .and_then(|input| input.get("session_id").and_then(serde_json::Value::as_i64));

    if !crate::proposals::transition(&state.pool, id, "rejected", "wheel refused")
        .await
        .map_err(|error| {
            tracing::warn!(proposal_id = id, %error, "rejecting a wheel request failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })?
    {
        return Err(StatusCode::CONFLICT);
    }
    if let Some(session_id) = session_id
        && let Err(error) = crate::browser_wheel::refuse(&state, session_id).await
    {
        // Logged and not returned. The refusal is recorded and that is the part the person asked
        // for; a session left open by a sidecar that did not answer is retired on its next restart.
        tracing::warn!(session = session_id, error = %error, "closing a refused wheel's session failed");
    }
    Ok(StatusCode::NO_CONTENT)
}

/// Spec B D12: refuse only the action and let the run continue without it. Only for a pending
/// `action-approval` of a run outside a job; uncancellable for `post_proposal_approve`'s reason —
/// it commits a transaction and only then launches the continued run.
async fn post_proposal_decline_action(
    State(state): State<AppState>,
    Path(id): Path<i64>,
) -> Result<Json<serde_json::Value>, (StatusCode, String)> {
    let proposal = crate::proposals::get(&state.pool, id)
        .await
        .map_err(|error| {
            tracing::warn!(proposal_id = id, %error, "reading a proposal to decline failed");
            (
                StatusCode::INTERNAL_SERVER_ERROR,
                "the proposal could not be read".to_owned(),
            )
        })?
        .ok_or_else(|| (StatusCode::NOT_FOUND, format!("there is no proposal {id}")))?;
    let pool = state.pool.clone();
    match uncancellable(async move { crate::runs::decline_action(&state, id).await })
        .await
        .map_err(|status| (status, "the decline task did not finish".to_owned()))?
    {
        Ok(run_id) => {
            // Spec B D12: declining only the action is the label `explain` of the park it answered.
            if let Some(proposal_run_id) = proposal.run_id {
                crate::judge::resolve_review::label_from_decision(
                    &pool,
                    proposal_run_id,
                    proposal.tool_input.as_deref(),
                    crate::judge::resolve_review::PersonsDecision::Decline,
                )
                .await;
            }
            Ok(Json(serde_json::json!({ "resume_run_id": run_id })))
        }
        Err(crate::runs::ResumeError::ProposalNotFound) => {
            Err((StatusCode::NOT_FOUND, format!("there is no proposal {id}")))
        }
        Err(crate::runs::ResumeError::ProposalNotPending) => Err((
            StatusCode::CONFLICT,
            "this proposal has already been decided".to_owned(),
        )),
        Err(crate::runs::ResumeError::BelongsToAJob) => Err((
            StatusCode::CONFLICT,
            "this run is a job's node; approve or reject it, and the job's own policy decides the rest"
                .to_owned(),
        )),
        Err(crate::runs::ResumeError::NotResumable(reason)) => Err((
            StatusCode::CONFLICT,
            format!("this run cannot continue: {reason}"),
        )),
        Err(crate::runs::ResumeError::Db(error)) => {
            tracing::warn!(proposal_id = id, %error, "declining an action failed");
            Err((
                StatusCode::INTERNAL_SERVER_ERROR,
                "the decline could not be recorded".to_owned(),
            ))
        }
    }
}

async fn post_proposal_reject(
    State(state): State<AppState>,
    Path(id): Path<i64>,
) -> Result<StatusCode, StatusCode> {
    let kind = crate::proposals::get(&state.pool, id)
        .await
        .map_err(|error| {
            tracing::warn!(proposal_id = id, %error, "reading a proposal to reject failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })?
        .ok_or(StatusCode::NOT_FOUND)?
        .kind;
    if kind == "browser-wheel" {
        return reject_browser_wheel(state, id).await;
    }
    if kind == "contact-merge" {
        // `reject_merge` records the refused pair in the same transaction as the status, which is
        // what stops the heuristic asking the identical question forever. Wiring the approval
        // without this would have been worse than wiring neither: the suggestion you refused would
        // come back on every sweep, and a suggestion that ignores your answer is not a suggestion.
        let state = state.clone();
        let rejected =
            uncancellable(async move { crate::contacts::reject_merge(&state.pool, id).await })
                .await?;
        return match rejected {
            Ok(()) => Ok(StatusCode::NO_CONTENT),
            // The guarded SELECT and the compare-and-set both report a proposal that is no longer
            // pending this way; either means another decision got there first.
            Err(sqlx::Error::RowNotFound) => Err(StatusCode::CONFLICT),
            Err(error) => {
                tracing::warn!(proposal_id = id, %error, "rejecting a contact merge failed");
                Err(StatusCode::INTERNAL_SERVER_ERROR)
            }
        };
    }

    if kind == "refinement" {
        // Unlike the calendar's refusal below, this one leaves a row: `refine::reject` marks the
        // refinement `rejected` rather than dropping it, because what the agent kept trying to
        // learn and was told no to is the record the layer's history exists to keep.
        let state = state.clone();
        let refused = uncancellable(async move { crate::knowledge::reject(&state.pool, id).await })
            .await
            .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
        return match refused {
            Ok(_) => Ok(StatusCode::NO_CONTENT),
            Err(crate::knowledge::DecisionError::NotFound) => Err(StatusCode::NOT_FOUND),
            Err(crate::knowledge::DecisionError::NotPending) => Err(StatusCode::CONFLICT),
            Err(crate::knowledge::DecisionError::Malformed) => {
                Err(StatusCode::UNPROCESSABLE_ENTITY)
            }
        };
    }

    if kind == "calendar-event" {
        // Refusing a suggested block leaves nothing behind: it is a suggestion declined, not a
        // meeting cancelled, so the calendar never learns it was offered.
        let state = state.clone();
        let rejected =
            uncancellable(
                async move { crate::calendar::reject_proposed_event(&state.pool, id).await },
            )
            .await?;
        return match rejected {
            Ok(()) => Ok(StatusCode::NO_CONTENT),
            Err(crate::calendar::DecisionError::NotFound) => Err(StatusCode::NOT_FOUND),
            Err(crate::calendar::DecisionError::NotPending) => Err(StatusCode::CONFLICT),
            Err(crate::calendar::DecisionError::Malformed) => Err(StatusCode::UNPROCESSABLE_ENTITY),
            Err(crate::calendar::DecisionError::Db(error)) => {
                tracing::warn!(proposal_id = id, %error, "rejecting a calendar proposal failed");
                Err(StatusCode::INTERNAL_SERVER_ERROR)
            }
        };
    }

    if kind == "fleet-exclusion" {
        // Refusing an edge leaves nothing behind, because drawing it changed nothing: no rule was
        // written, no run was paused, no worktree is held. It is the one refusal on this route with
        // no second half to undo.
        let state = state.clone();
        let rejected =
            uncancellable(async move { crate::exclusion::reject(&state.pool, id).await }).await?;
        return match rejected {
            Ok(()) => Ok(StatusCode::NO_CONTENT),
            Err(crate::exclusion::DecisionError::NotFound) => Err(StatusCode::NOT_FOUND),
            Err(crate::exclusion::DecisionError::NotPending) => Err(StatusCode::CONFLICT),
            Err(crate::exclusion::DecisionError::Malformed) => {
                Err(StatusCode::UNPROCESSABLE_ENTITY)
            }
            Err(crate::exclusion::DecisionError::Db(error)) => {
                tracing::warn!(proposal_id = id, %error, "rejecting an exclusion failed");
                Err(StatusCode::INTERNAL_SERVER_ERROR)
            }
        };
    }

    if kind == "agent-recruit" {
        // Refusing leaves nothing behind, because nothing was created: no agent, no roster row, no
        // run held. And it is deliberately not a permanent no — the NEXT run of that department
        // meets the same gap and may ask again, which is right. Nobody said the director should
        // stop asking; they said not this one.
        let state = state.clone();
        let rejected = uncancellable(async move {
            crate::proposals::transition(&state.pool, id, "rejected", "not hired").await
        })
        .await?;
        return match rejected {
            Ok(true) => Ok(StatusCode::NO_CONTENT),
            Ok(false) => Err(StatusCode::CONFLICT),
            Err(error) => {
                tracing::warn!(proposal_id = id, %error, "refusing a recruitment failed");
                Err(StatusCode::INTERNAL_SERVER_ERROR)
            }
        };
    }

    if kind == "github-action" {
        // Refusing leaves nothing behind, because nothing was done: `github::submit` files the
        // proposal and returns, and the operation reaches `gh` only on the approval path. So this is
        // a status flip with no second half — the opposite of the approve side, which claims the row
        // BEFORE spawning precisely because there IS one there.
        //
        // Its absence was invisible until somebody refused one by hand. The fallback below knows
        // only `action-approval`, so a `github-action` fell through to it and came back 409 saying
        // NotPending about a proposal sitting there pending; `/dismiss`, which knows only
        // `skipped-item`, answered the same. An operation the owner could approve and could not
        // refuse waited for a decision that had no way to arrive.
        let state = state.clone();
        let rejected = uncancellable(async move {
            crate::proposals::transition(&state.pool, id, "rejected", "rejected by user").await
        })
        .await?;
        return match rejected {
            Ok(true) => Ok(StatusCode::NO_CONTENT),
            Ok(false) => Err(StatusCode::CONFLICT),
            Err(error) => {
                tracing::warn!(proposal_id = id, %error, "refusing a github action failed");
                Err(StatusCode::INTERNAL_SERVER_ERROR)
            }
        };
    }

    if kind == "team-action" {
        // Refusing closes the action as well as the proposal, in that order: the proposal is the
        // decision and the action is what is left to do about it, and leaving the second `pending`
        // would keep it in the department's queue ceiling forever, blocking the next request over a
        // question already answered.
        let state = state.clone();
        let rejected = uncancellable(async move {
            let decided =
                crate::proposals::transition(&state.pool, id, "rejected", "rejected by user")
                    .await?;
            if decided {
                crate::team::refuse_action(&state.pool, id).await?;
            }
            Ok::<bool, sqlx::Error>(decided)
        })
        .await?;
        return match rejected {
            Ok(true) => Ok(StatusCode::NO_CONTENT),
            Ok(false) => Err(StatusCode::CONFLICT),
            Err(error) => {
                tracing::warn!(proposal_id = id, %error, "rejecting a team action failed");
                Err(StatusCode::INTERNAL_SERVER_ERROR)
            }
        };
    }

    // Uncancellable: rejecting flips the proposal first and discards the paused run second, and the
    // first half cannot be replayed — a retry finds the proposal no longer `pending` and answers 409.
    match uncancellable(async move { crate::proposals::reject_proposal(&state.pool, id).await })
        .await?
    {
        Ok(()) => Ok(StatusCode::NO_CONTENT),
        Err(crate::proposals::RejectError::NotFound) => Err(StatusCode::NOT_FOUND),
        Err(crate::proposals::RejectError::NotPending) => Err(StatusCode::CONFLICT),
        Err(crate::proposals::RejectError::Db(error)) => {
            tracing::warn!(proposal_id = id, %error, "rejecting a proposal failed");
            Err(StatusCode::INTERNAL_SERVER_ERROR)
        }
    }
}

/// How many jobs one listing returns.
///
/// Finished jobs are included, so this is a window rather than a queue: a job that stopped for the
/// budget or ran out of clock is exactly the one the user needs to see, and filtering to live ones
/// would make it vanish at the moment it started mattering.
const JOB_LIST_LIMIT: i64 = 20;

#[derive(serde::Deserialize)]
struct JobsQuery {
    project_id: Option<String>,
    /// Only the work in flight, without the `JOB_LIST_LIMIT` ceiling.
    ///
    /// A parameter rather than a route of its own because it is the same question with a filter.
    /// Absent, the answer is byte for byte today's — which is what leaves the Autopilot tab, which
    /// calls this every 3 seconds, exactly as it is.
    live: Option<bool>,
}

async fn get_jobs(
    State(state): State<AppState>,
    Query(query): Query<JobsQuery>,
) -> Result<Json<Vec<crate::job::JobSummary>>, StatusCode> {
    let listed = if query.live == Some(true) {
        crate::job::list_live(
            &state.pool,
            query.project_id.as_deref(),
            crate::concurrency::LIVE_LIST_LIMIT,
        )
        .await
    } else {
        crate::job::list(&state.pool, query.project_id.as_deref(), JOB_LIST_LIMIT).await
    };
    listed
        .map(Json)
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)
}

#[derive(serde::Serialize)]
struct CreateJobResponse {
    job_id: i64,
}

/// `POST /jobs` — asks for a job the way `POST /runs` asks for a run.
///
/// Follows `create_run` step for step, and the order of those steps is the interesting part.
///
/// The **global** kill switch is checked first and alone. The scoped kills, the budget and the WIP
/// limit pace proactive autonomy, and a person asking for a job through the shell or the Telegram
/// assistant is not that; the global switch is the emergency stop, and an emergency stop with
/// exemptions is not one. It fails closed — a switch that cannot be read refuses.
///
/// The whole creation is **uncancellable**. The job row is INSERTed `planning` before its worktree
/// exists, and `git worktree add` holds that window open for as long as git takes. A request
/// dropped inside it would strand a live job with no worktree, which the tick then drives forever
/// while holding one of the project's concurrency slots, which nothing but the sweep gives back.
/// Same window `create_run` documents, and wider here, because provisioning a job's worktree is
/// the slowest thing this route does.
///
/// A second job for a project that already has one is a 409, from the unique index rather than from
/// a check here. That stays the right answer until Chunk 4 replaces the index with numbered slots.
async fn create_job(
    State(state): State<AppState>,
    Json(request): Json<crate::job::CreateJobRequest>,
) -> Result<(StatusCode, Json<CreateJobResponse>), (StatusCode, String)> {
    match crate::autopilot::kill_switch_engaged(&state.pool).await {
        Ok(false) => {}
        Ok(true) => {
            return Err((
                StatusCode::CONFLICT,
                "the kill switch is engaged; nothing autonomous starts".to_string(),
            ));
        }
        Err(error) => {
            tracing::warn!(%error, "create_job: could not read the kill switch — refusing");
            return Err((
                StatusCode::SERVICE_UNAVAILABLE,
                "the kill switch could not be read".to_string(),
            ));
        }
    }

    let roster = crate::autopilot::project_roster(&state.pool)
        .await
        .map_err(|error| {
            tracing::warn!(%error, "create_job: could not read the project roster");
            (
                StatusCode::INTERNAL_SERVER_ERROR,
                "the project roster could not be read".to_string(),
            )
        })?;
    let resolved = crate::job::resolve_start(&roster, &request.project_id).map_err(|refusal| {
        let status = match refusal {
            crate::job::StartRefusal::UnknownProject => StatusCode::NOT_FOUND,
            _ => StatusCode::UNPROCESSABLE_ENTITY,
        };
        (status, refusal.reason(&request.project_id))
    })?;

    // Read the same way the scheduler reads it. `None` when git will not answer, which crash
    // recovery reads as "cannot prove the tree stayed put" — the correct meaning rather than the
    // convenient one.
    let head_sha = crate::repo_trigger::current_branch_sha(
        std::path::Path::new(&resolved.project_root),
        "HEAD",
        false,
    )
    .await;

    let outcome = uncancellable(async move {
        crate::job::start(
            &state,
            &crate::job::StartRequest {
                project_id: &request.project_id,
                project_root: &resolved.project_root,
                // Nobody scheduled this one.
                rule_name: None,
                prompt: &request.prompt,
                // The daemon's ceiling, never a number the caller chose — which is why the request
                // has no field for it. The project's `autopilot.yaml` may only lower the fan-out,
                // and an HTTP
                // body filled in by a model is reviewed even less than that file is.
                max_items: crate::config::MAX_ITEMS_CEILING as i64,
                // These two DO come from the caller, unlike `max_items`, and the asymmetry is the
                // point. `max_items` is fan-out per round and has a hard ceiling nobody may raise;
                // these are how long and how much, which are the caller's to choose — under
                // `MAX_ROUNDS_CEILING` and under the house budget, both applied on the way in.
                max_rounds: request.max_rounds,
                budget_usd: request.budget_usd,
                // What a rule that said nothing gets: only the last item is gated.
                gate_each: false,
                review: true,
                // The answer a rule that said nothing about retries gets, and for the same reason:
                // nobody asked, and one more implement run told what the gate said is cheaper than
                // the item it saves. Not the caller's to choose either — the request has no field
                // for it, exactly as it has none for `max_items`.
                gate_retries: crate::config::DEFAULT_GATE_RETRIES as i64,
                head_sha: head_sha.as_deref(),
                // The caller's, like `max_rounds` and `budget_usd` above and unlike `max_items`.
                // Whether it names a team that exists is `job::start`'s to answer and not this
                // route's: the catalogue can change between a request being written and it landing,
                // and the answer has to be read where the row is made.
                team_id: request.team_id.as_deref(),
            },
        )
        .await
    })
    .await
    .map_err(|status| (status, "the job could not be started".to_string()))?;

    match outcome {
        crate::job::JobStart::Started(job_id) => {
            Ok((StatusCode::CREATED, Json(CreateJobResponse { job_id })))
        }
        // Still a 409, and still not a 500: no room is a state the asker can act on by waiting. The
        // reason travels because the two ceilings have different remedies — one waits for this
        // project's own work, the other for anybody's.
        crate::job::JobStart::NoRoom(reason) => Err((StatusCode::CONFLICT, reason)),
        // 422 and not 404: the URL is right and the project exists, and it is one field of the body
        // that names something that does not. The same status `resolve_start` gives a project that
        // is real but configured differently from what the request assumed.
        crate::job::JobStart::NoTeam(reason) => Err((StatusCode::UNPROCESSABLE_ENTITY, reason)),
        // Past the INSERT: the row existed and `fail_early` retired it and said so in the feed. 500
        // rather than 409, because nothing the caller could change would have helped.
        crate::job::JobStart::Failed => Err((
            StatusCode::INTERNAL_SERVER_ERROR,
            "the job was created and could not be provisioned; it has been retired".to_string(),
        )),
    }
}

async fn get_job(
    State(state): State<AppState>,
    Path(id): Path<i64>,
) -> Result<Json<crate::job::JobDetail>, StatusCode> {
    match crate::job::detail(&state.pool, id).await {
        Ok(Some(detail)) => Ok(Json(detail)),
        Ok(None) => Err(StatusCode::NOT_FOUND),
        Err(_) => Err(StatusCode::INTERNAL_SERVER_ERROR),
    }
}

async fn cancel_job(
    State(state): State<AppState>,
    Path(id): Path<i64>,
) -> Result<StatusCode, StatusCode> {
    // Uncancellable: this terminates the node in flight and only then retires the job. A request
    // dropped in between would leave a job nothing drives with a node still running inside it.
    match uncancellable(async move { crate::job::cancel(&state, id).await }).await? {
        Ok(crate::job::CancelOutcome::Cancelled) => Ok(StatusCode::NO_CONTENT),
        // Already over. Not success: "I stopped it" and "it had already finished" are different
        // answers to the question the user just asked.
        Ok(crate::job::CancelOutcome::NotLive) => Err(StatusCode::CONFLICT),
        Ok(crate::job::CancelOutcome::NotFound) => Err(StatusCode::NOT_FOUND),
        Err(_) => Err(StatusCode::INTERNAL_SERVER_ERROR),
    }
}

#[derive(serde::Deserialize)]
struct LeaveNoteRequest {
    body: String,
}

#[derive(serde::Serialize)]
struct LeaveNoteResponse {
    note_id: i64,
}

/// Everything the layer holds, in every status.
///
/// Not filtered to `active`, deliberately: the reviewable history IS the feature, and a screen that
/// showed only what is in force could not answer "what did it try to learn that I said no to".
async fn list_knowledge(
    State(state): State<AppState>,
) -> Result<Json<Vec<crate::knowledge::Known>>, StatusCode> {
    crate::knowledge::all(&state.pool)
        .await
        .map(Json)
        .map_err(|error| {
            tracing::warn!(%error, "listing refinements failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })
}

async fn get_run_knowledge(
    State(state): State<AppState>,
    Path(id): Path<i64>,
) -> Result<Json<crate::brief::RunTrace>, StatusCode> {
    match crate::brief::trace_of(&state.pool, id).await {
        Ok(Some(trace)) => Ok(Json(trace)),
        Ok(None) => Err(StatusCode::NOT_FOUND),
        Err(error) => {
            tracing::warn!(run_id = id, %error, "reading what a run was told failed");
            Err(StatusCode::INTERNAL_SERVER_ERROR)
        }
    }
}

/// One refinement, read the way a person decides about it: the text, every decision it has been
/// through, what it replaced, and what replaced it.
///
/// The chain is the half `GET /knowledge` cannot give you. A list answers "what is in force";
/// this answers "what did it say before I changed it, and would I want that back" — which is the
/// question somebody asks at the moment they are considering a revert.
async fn get_knowledge(
    State(state): State<AppState>,
    Path(id): Path<i64>,
) -> Result<Json<crate::knowledge::History>, StatusCode> {
    match crate::knowledge::history(&state.pool, id).await {
        Ok(Some(history)) => Ok(Json(history)),
        Ok(None) => Err(StatusCode::NOT_FOUND),
        Err(error) => {
            tracing::warn!(knowledge_id = id, %error, "reading the history of what is known failed");
            Err(StatusCode::INTERNAL_SERVER_ERROR)
        }
    }
}

/// Taking one back. The half that makes approving safe to do at all.
async fn revert_knowledge(
    State(state): State<AppState>,
    Path(id): Path<i64>,
    Json(request): Json<RevertKnowledgeRequest>,
) -> Result<StatusCode, StatusCode> {
    let note = request
        .note
        .unwrap_or_else(|| "reverted by the owner".to_owned());
    match crate::knowledge::revert(&state.pool, id, &note).await {
        // 409 and not 404: the row may well exist and simply not be active, which is a different
        // thing for the caller to do about it.
        Ok(true) => Ok(StatusCode::NO_CONTENT),
        Ok(false) => Err(StatusCode::CONFLICT),
        Err(error) => {
            tracing::warn!(knowledge_id = id, %error, "reverting what is known failed");
            Err(StatusCode::INTERNAL_SERVER_ERROR)
        }
    }
}

#[derive(serde::Deserialize)]
struct RevertKnowledgeRequest {
    note: Option<String>,
}

/// `POST /jobs/{id}/notes` — leaves words for whichever of this job's nodes comes next.
///
/// **Admin, by being in no scope table at all.** `auth::permits` is default-deny, so a route nobody
/// lists is reachable only by Control and Admin, and that is the grade this one wants. The table it
/// must not be added to is `RUN_CREATING_ROUTES`, where `POST /jobs` sits one path segment away:
/// creating a job authorises the prompt supplied at that moment, in advance of the work existing,
/// while a note adds a second author to work already running past every check its creation went
/// through. That is exactly why `POST /runs/{id}/message` is kept out of the same table, and a note
/// is steering with a longer wait.
///
/// The author is [`notes::OWNER`] and never a field of the body. Only Control and Admin arrive here
/// and both of them are the person, so there is nothing for a caller to claim to be — and a note
/// that could name its own author is the first half of a run leaving notes for another run.
///
/// 201 rather than 204 because the note now has an id and a life the caller can watch: it appears in
/// `GET /jobs/{id}` while it waits, and carries the run it eventually reached once it has been read
/// out. The acknowledgement says only that the words were accepted — nothing has read them yet, and
/// the next node may be minutes away or may be the review at the end of the night.
///
/// A note left on a job that has already finished is accepted and never delivered. Refusing it would
/// mean deciding here what "still able to hear you" means, and the honest place to see that is the
/// job detail, where the note sits visibly undelivered beside a job that is over.
async fn post_job_note(
    State(state): State<AppState>,
    Path(id): Path<i64>,
    Json(request): Json<LeaveNoteRequest>,
) -> Result<(StatusCode, Json<LeaveNoteResponse>), StatusCode> {
    // A note with no words is not a note: it would be an entry in the queue that delivers nothing
    // and can never be delivered again.
    let body = request.body.trim();
    if body.is_empty() {
        return Err(StatusCode::BAD_REQUEST);
    }

    // Asked before the insert so a note for a job that does not exist is a 404 and not the 500 the
    // foreign key would otherwise make of it.
    let job: Option<i64> = sqlx::query_scalar("SELECT id FROM jobs WHERE id = ?")
        .bind(id)
        .fetch_optional(&state.pool)
        .await
        .map_err(|error| {
            tracing::warn!(job_id = id, %error, "reading a job to leave a note on it failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })?;
    if job.is_none() {
        return Err(StatusCode::NOT_FOUND);
    }

    crate::notes::leave(&state.pool, id, body, crate::notes::OWNER)
        .await
        .map(|note_id| (StatusCode::CREATED, Json(LeaveNoteResponse { note_id })))
        .map_err(|error| {
            tracing::warn!(job_id = id, %error, "leaving a note on a job failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })
}

/// Body of `POST /owner-notes`. The field is `note_text` in Rust so the redact scan keeps it out of
/// any tracing call, and `text` on the wire. No `author`: a note is the owner's by construction.
#[derive(serde::Deserialize)]
struct PostOwnerNoteRequest {
    #[serde(rename = "text")]
    note_text: String,
    origin: Option<String>,
}

#[derive(serde::Deserialize)]
struct PatchOwnerNoteRequest {
    #[serde(rename = "text")]
    note_text: Option<String>,
    state: Option<String>,
}

#[derive(serde::Deserialize)]
struct OwnerNoteListQuery {
    state: Option<String>,
}

#[derive(serde::Deserialize)]
struct OwnerNoteSearchQuery {
    q: Option<String>,
}

#[derive(serde::Deserialize)]
struct OwnerNoteGraphQuery {
    include_archived: Option<bool>,
}

#[derive(serde::Deserialize)]
struct PostOwnerNoteLinkRequest {
    link_type: String,
    target_kind: String,
    target_ref: String,
}

/// Body of `POST /owner-notes/{id}/teach`. Every field is optional: the kind defaults to `memory`
/// and the title to the note's first line.
#[derive(serde::Deserialize)]
struct TeachOwnerNoteRequest {
    kind: Option<String>,
    title: Option<String>,
    project_id: Option<String>,
}

/// The status a note failure answers with. Never logs the text: only the id and the database error.
fn owner_note_status(error: &crate::owner_notes::NoteError, note_id: Option<i64>) -> StatusCode {
    use crate::owner_notes::NoteError;
    match error {
        NoteError::Empty | NoteError::UnknownOrigin | NoteError::UnknownState => {
            StatusCode::BAD_REQUEST
        }
        NoteError::NotFound => StatusCode::NOT_FOUND,
        NoteError::Db(error) => {
            tracing::warn!(note_id, %error, "an owner note operation failed");
            StatusCode::INTERNAL_SERVER_ERROR
        }
    }
}

fn owner_note_db_status(error: &sqlx::Error, note_id: Option<i64>) -> StatusCode {
    tracing::warn!(note_id, %error, "reading the owner notes failed");
    StatusCode::INTERNAL_SERVER_ERROR
}

async fn post_owner_note(
    State(state): State<AppState>,
    Json(request): Json<PostOwnerNoteRequest>,
) -> Result<(StatusCode, Json<serde_json::Value>), StatusCode> {
    let origin = request.origin.as_deref().unwrap_or("shell");
    let id = crate::owner_notes::create(&state.pool, &request.note_text, origin)
        .await
        .map_err(|error| owner_note_status(&error, None))?;
    Ok((StatusCode::CREATED, Json(serde_json::json!({ "id": id }))))
}

