    fn email_batch(messages: serde_json::Value) -> Body {
        Body::from(
            serde_json::json!({
                "mailbox": "INBOX",
                "uidvalidity": 1,
                "max_uid_examined": 10,
                "messages": messages,
            })
            .to_string(),
        )
    }

    fn email_batch_directed(direction: serde_json::Value, messages: serde_json::Value) -> Body {
        Body::from(
            serde_json::json!({
                "mailbox": "INBOX",
                "uidvalidity": 1,
                "max_uid_examined": 10,
                "direction": direction,
                "messages": messages,
            })
            .to_string(),
        )
    }

    fn email_batch_from(
        mailbox: &str,
        direction: serde_json::Value,
        messages: serde_json::Value,
    ) -> Body {
        Body::from(
            serde_json::json!({
                "mailbox": mailbox,
                "uidvalidity": 1,
                "max_uid_examined": 10,
                "direction": direction,
                "messages": messages,
            })
            .to_string(),
        )
    }

    fn one_message() -> serde_json::Value {
        serde_json::json!([{
            "message_id": "<a@b>",
            "uid": 10,
            "from_addr": "ana@company.com",
            "received_at": "2026-07-28T11:00:00+00:00",
            "body_text": "hello",
        }])
    }

    async fn post_email(state: AppState, token: Option<&str>, body: Body) -> StatusCode {
        let mut request = Request::builder()
            .method("POST")
            .uri("/email/incoming")
            .header("Content-Type", "application/json");
        if let Some(token) = token {
            request = request.header("Authorization", format!("Bearer {token}"));
        }
        build_router(state)
            .oneshot(request.body(body).unwrap())
            .await
            .unwrap()
            .status()
    }

