    /// The library is listed, a pin records the hash, and a bundle edited under it reads as drift.
    ///
    /// The whole of §6.1's second requirement in one pass. The listing is a *measurement* against
    /// the library as it is right now, not a replay of the file: replaying it would say
    /// `referenced` for a bundle somebody has since rewritten, which is the exact silence this page
    /// exists to break.
    #[tokio::test]
    async fn a_pin_records_the_hash_and_a_bundle_edited_under_it_reads_as_drift() {
        let mut state = test_state().await;
        let (_lib, library) = library_with(&[("harness", "1.0", "description: the .ai harness\n")]);
        state.workflow_library = Some(library.clone());
        let _home = with_project_home(&mut state);
        let _dir = project_with_rules(&state, "alpha", "gate_command: cargo test\n").await;

        let (status, shelf) = workflow_call(state.clone(), "GET", "/workflows/library", None).await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(shelf.as_array().unwrap().len(), 1);
        assert_eq!(shelf[0]["origin"], "library:harness@1.0");

        let (status, _) = workflow_call(
            state.clone(),
            "POST",
            "/projects/alpha/workflows",
            Some(serde_json::json!({ "name": "harness", "version": "1.0" })),
        )
        .await;
        assert_eq!(status, StatusCode::NO_CONTENT);

        let (_, installed) =
            workflow_call(state.clone(), "GET", "/projects/alpha/workflows", None).await;
        assert_eq!(installed[0]["standing"], "referenced");
        assert_eq!(installed[0]["origin"], "library:harness@1.0");
        assert_eq!(installed[0]["hash"], shelf[0]["hash"]);

        // Somebody edits the bundle in place, under a pin that claims to know what it says.
        std::fs::write(library.join("harness/1.0/graph.yaml"), "# changed\n").unwrap();
        let (_, installed) =
            workflow_call(state.clone(), "GET", "/projects/alpha/workflows", None).await;
        assert_eq!(installed[0]["standing"], "drifted");
        assert_ne!(installed[0]["hash"], installed[0]["origin_hash"]);
        // Drift is not an update on offer: nobody published a new version.
        assert!(installed[0]["update_available"].is_null());
    }

    /// A library bundle that provides files, for the materialization routes.
    fn providing_library() -> (tempfile::TempDir, std::path::PathBuf) {
        let (dir, library) = library_with(&[(
            "dev",
            "1.0",
            "owns:\n  - .ai/workflow/\n  - .claude/settings.json\n",
        )]);
        let at = library.join("dev/1.0");
        std::fs::create_dir_all(at.join(".ai/workflow")).unwrap();
        std::fs::write(at.join(".ai/workflow/workflow.md"), "the pipeline").unwrap();
        std::fs::create_dir_all(at.join(".claude")).unwrap();
        std::fs::write(at.join(".claude/settings.json"), "{}").unwrap();
        (dir, library)
    }

    /// Installing puts the bundle's files where agents read them, recorded outside the project; a
    /// later edit is left alone by the next materialization and named in its answer; the preview
    /// writes nothing.
    #[tokio::test]
    async fn installing_places_the_files_and_an_edit_is_never_placed_over() {
        let mut state = test_state().await;
        let (_lib, library) = providing_library();
        state.workflow_library = Some(library.clone());
        let home = with_project_home(&mut state);
        let project = project_with_rules(&state, "alpha", "gate_command: cargo test\n").await;

        let (status, _) = workflow_call(
            state.clone(),
            "POST",
            "/projects/alpha/workflows",
            Some(serde_json::json!({ "name": "dev", "version": "1.0" })),
        )
        .await;
        assert_eq!(status, StatusCode::NO_CONTENT);
        let placed = project.path().join(".ai/workflow/workflow.md");
        assert_eq!(std::fs::read_to_string(&placed).unwrap(), "the pipeline");
        assert!(
            home.path()
                .join("projects/alpha")
                .join(crate::project_state::MATERIALIZED_FILE)
                .is_file(),
            "the record is the project's state, outside the project"
        );

        std::fs::write(&placed, "mine").unwrap();
        let (status, preview) = workflow_call(
            state.clone(),
            "GET",
            "/projects/alpha/workflows/dev/materialize",
            None,
        )
        .await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(preview["report"]["applied"], false);
        assert_eq!(preview["report"]["conflicts"][0]["kind"], "edited");

        let (status, answer) = workflow_call(
            state.clone(),
            "POST",
            "/projects/alpha/workflows/dev/materialize",
            None,
        )
        .await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(
            answer["report"]["conflicts"][0]["path"],
            ".ai/workflow/workflow.md"
        );
        assert!(answer["report"]["conflicts"][0]["bundle_file"].is_string());
        assert_eq!(std::fs::read_to_string(&placed).unwrap(), "mine");

        let (status, _) = workflow_call(
            state,
            "GET",
            "/projects/alpha/workflows/nope/materialize",
            None,
        )
        .await;
        assert_eq!(status, StatusCode::NOT_FOUND);
    }

    /// Stopping a workflow takes back the files it placed and left untouched, keeps an edited one,
    /// and names both in the answer.
    #[tokio::test]
    async fn stopping_a_workflow_removes_its_untouched_files_and_keeps_edited_ones() {
        let mut state = test_state().await;
        let (_lib, library) = providing_library();
        state.workflow_library = Some(library.clone());
        let _home = with_project_home(&mut state);
        let project = project_with_rules(&state, "alpha", "gate_command: cargo test\n").await;
        let install = || {
            workflow_call(
                state.clone(),
                "POST",
                "/projects/alpha/workflows",
                Some(serde_json::json!({ "name": "dev", "version": "1.0" })),
            )
        };
        let placed = project.path().join(".ai/workflow/workflow.md");

        assert_eq!(install().await.0, StatusCode::NO_CONTENT);
        assert!(placed.is_file());
        let (status, answer) = workflow_call(
            state.clone(),
            "DELETE",
            "/projects/alpha/workflows/dev",
            None,
        )
        .await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(
            answer["removed"],
            serde_json::json!([".ai/workflow/workflow.md"])
        );
        assert_eq!(answer["kept"], serde_json::json!([]));
        assert!(!placed.exists());
        assert!(!project.path().join(".ai/workflow").exists());

        assert_eq!(install().await.0, StatusCode::NO_CONTENT);
        std::fs::write(&placed, "mine").unwrap();
        let (status, answer) = workflow_call(
            state.clone(),
            "DELETE",
            "/projects/alpha/workflows/dev",
            None,
        )
        .await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(answer["removed"], serde_json::json!([]));
        assert_eq!(answer["kept"][0]["path"], ".ai/workflow/workflow.md");
        assert_eq!(answer["kept"][0]["reason"], "modified");
        assert_eq!(std::fs::read_to_string(&placed).unwrap(), "mine");

        let (status, _) =
            workflow_call(state, "DELETE", "/projects/alpha/workflows/dev", None).await;
        assert_eq!(status, StatusCode::NOT_FOUND);
    }

    /// Materializing writes files that govern agents, so the stop refuses it before a byte lands.
    #[tokio::test]
    async fn materializing_waits_for_the_stop() {
        let mut state = test_state().await;
        let (_lib, library) = providing_library();
        state.workflow_library = Some(library);
        let _home = with_project_home(&mut state);
        let project = project_with_rules(&state, "alpha", "gate_command: cargo test\n").await;
        crate::workflows::install(
            &state
                .machine_config_root
                .clone()
                .unwrap()
                .join("projects/alpha")
                .join(crate::project_state::PINS_FILE),
            &crate::workflows::read_bundle(
                &state.workflow_library.clone().unwrap().join("dev/1.0"),
                "dev",
                "1.0",
            )
            .unwrap()
            .unwrap(),
        )
        .unwrap();
        crate::autopilot::set_kill_switch(&state.pool, true)
            .await
            .unwrap();

        for (method, uri) in [
            ("POST", "/projects/alpha/workflows/dev/materialize"),
            ("POST", "/workflows/sync"),
        ] {
            let body = (uri == "/workflows/sync")
                .then(|| serde_json::json!({ "path": project.path().to_string_lossy() }));
            let (status, answer) = workflow_call(state.clone(), method, uri, body).await;
            assert_eq!(status, StatusCode::LOCKED, "{uri}");
            assert_eq!(answer["refusal"], "kill_switch");
        }
        assert!(!project.path().join(".ai/workflow/workflow.md").exists());
    }

    /// A worktree made by hand is matched to its project through the repository they share, and
    /// gets a record of its own, so an edit in it is protected exactly as one in the main checkout.
    #[tokio::test]
    async fn a_hand_made_worktree_is_synced_by_the_repository_it_shares() {
        let git = |dir: &std::path::Path, args: &[&str]| {
            let ok = std::process::Command::new("git")
                .arg("-C")
                .arg(dir)
                .args(["-c", "user.name=t", "-c", "user.email=t@t"])
                .args(args)
                .output()
                .map(|output| output.status.success())
                .unwrap_or(false);
            assert!(ok, "git {args:?}");
        };
        let mut state = test_state().await;
        let (_lib, library) = providing_library();
        state.workflow_library = Some(library.clone());
        let home = with_project_home(&mut state);
        let project = project_with_rules(&state, "alpha", "gate_command: cargo test\n").await;
        git(project.path(), &["init", "--quiet"]);
        std::fs::write(project.path().join("README.md"), "x").unwrap();
        git(project.path(), &["add", "README.md"]);
        git(project.path(), &["commit", "--quiet", "-m", "init"]);
        let trees = tempfile::tempdir().unwrap();
        let tree = trees.path().join("by-hand");
        git(
            project.path(),
            &[
                "worktree",
                "add",
                "--quiet",
                "-b",
                "side",
                &tree.to_string_lossy(),
            ],
        );
        crate::workflows::install(
            &home
                .path()
                .join("projects/alpha")
                .join(crate::project_state::PINS_FILE),
            &crate::workflows::read_bundle(&library.join("dev/1.0"), "dev", "1.0")
                .unwrap()
                .unwrap(),
        )
        .unwrap();

        let (status, answer) = workflow_call(
            state.clone(),
            "POST",
            "/workflows/sync",
            Some(serde_json::json!({ "path": tree.to_string_lossy() })),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "{answer}");
        assert_eq!(answer["project_id"], "alpha");
        assert_eq!(
            std::fs::read_to_string(tree.join(".ai/workflow/workflow.md")).unwrap(),
            "the pipeline"
        );
        // The daemon's own hook file is never a bundle's to place.
        assert!(!tree.join(".claude/settings.json").exists());
        assert_eq!(
            answer["outcomes"][0]["report"]["reserved"][0],
            ".claude/settings.json"
        );
        let records = home
            .path()
            .join("projects/alpha")
            .join(crate::project_state::WORKTREE_RECORDS_DIR);
        assert_eq!(std::fs::read_dir(&records).unwrap().count(), 1);
        // The main checkout was not touched by a sync of its worktree.
        assert!(!project.path().join(".ai/workflow/workflow.md").exists());

        let (status, answer) = workflow_call(
            state,
            "POST",
            "/workflows/sync",
            Some(serde_json::json!({ "path": trees.path().to_string_lossy() })),
        )
        .await;
        assert_eq!(status, StatusCode::UNPROCESSABLE_ENTITY);
        assert_eq!(answer["refusal"], "not_a_checkout");
    }

    /// Two rostered projects on one repository, both pinning the providing bundle: the setup the
    /// ambiguity tests share. Returns the guards and the main checkout both projects point at.
    async fn two_projects_on_one_repository(
        state: &mut AppState,
    ) -> (tempfile::TempDir, tempfile::TempDir, tempfile::TempDir) {
        let git = |dir: &std::path::Path, args: &[&str]| {
            let ok = std::process::Command::new("git")
                .arg("-C")
                .arg(dir)
                .args(["-c", "user.name=t", "-c", "user.email=t@t"])
                .args(args)
                .output()
                .map(|output| output.status.success())
                .unwrap_or(false);
            assert!(ok, "git {args:?}");
        };
        let (lib, library) = providing_library();
        state.workflow_library = Some(library.clone());
        let home = with_project_home(state);
        let project = project_with_rules(state, "alpha", "gate_command: cargo test\n").await;
        git(project.path(), &["init", "--quiet"]);
        std::fs::write(project.path().join("README.md"), "x").unwrap();
        git(project.path(), &["add", "README.md"]);
        git(project.path(), &["commit", "--quiet", "-m", "init"]);
        sqlx::query(
            "INSERT INTO autopilot_state (project_id, mode, project_root) VALUES ('beta', 'shadow', ?)",
        )
        .bind(project.path().to_string_lossy().to_string())
        .execute(&state.pool)
        .await
        .unwrap();
        for id in ["alpha", "beta"] {
            crate::workflows::install(
                &home
                    .path()
                    .join("projects")
                    .join(id)
                    .join(crate::project_state::PINS_FILE),
                &crate::workflows::read_bundle(&library.join("dev/1.0"), "dev", "1.0")
                    .unwrap()
                    .unwrap(),
            )
            .unwrap();
        }
        (lib, home, project)
    }

    /// Two projects sharing the repository is a question only the caller can answer: the sync
    /// refuses, names both, and writes nothing, rather than picking whichever row came first.
    #[tokio::test]
    async fn a_repository_two_projects_share_is_refused_with_both_named() {
        let mut state = test_state().await;
        let (_lib, home, project) = two_projects_on_one_repository(&mut state).await;

        let (status, answer) = workflow_call(
            state,
            "POST",
            "/workflows/sync",
            Some(serde_json::json!({ "path": project.path().to_string_lossy() })),
        )
        .await;
        assert_eq!(status, StatusCode::CONFLICT, "{answer}");
        assert_eq!(answer["refusal"], "ambiguous_project");
        let mut named: Vec<&str> = answer["candidates"]
            .as_array()
            .unwrap()
            .iter()
            .map(|candidate| candidate["project_id"].as_str().unwrap())
            .collect();
        named.sort_unstable();
        assert_eq!(named, ["alpha", "beta"]);
        assert!(answer["candidates"][0]["project_root"].is_string());
        assert!(!project.path().join(".ai/workflow/workflow.md").exists());
        for id in ["alpha", "beta"] {
            assert!(
                !home
                    .path()
                    .join("projects")
                    .join(id)
                    .join(crate::project_state::MATERIALIZED_FILE)
                    .exists()
            );
        }
    }

    /// Naming one of the projects the repository matches settles it; naming one it does not is
    /// refused, so the choice can never put one project's workflow into another's checkout.
    #[tokio::test]
    async fn a_named_project_settles_the_choice_only_among_the_matches() {
        let mut state = test_state().await;
        let (_lib, home, project) = two_projects_on_one_repository(&mut state).await;
        let _stranger = project_with_rules(&state, "gamma", "gate_command: cargo test\n").await;

        let (status, answer) = workflow_call(
            state.clone(),
            "POST",
            "/workflows/sync",
            Some(serde_json::json!({
                "path": project.path().to_string_lossy(),
                "project_id": "gamma",
            })),
        )
        .await;
        assert_eq!(status, StatusCode::BAD_REQUEST, "{answer}");
        assert_eq!(answer["refusal"], "project_not_a_match");
        assert!(!project.path().join(".ai/workflow/workflow.md").exists());

        let (status, answer) = workflow_call(
            state,
            "POST",
            "/workflows/sync",
            Some(serde_json::json!({
                "path": project.path().to_string_lossy(),
                "project_id": "beta",
            })),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "{answer}");
        assert_eq!(answer["project_id"], "beta");
        assert_eq!(
            std::fs::read_to_string(project.path().join(".ai/workflow/workflow.md")).unwrap(),
            "the pipeline"
        );
        let record = |id: &str| {
            home.path()
                .join("projects")
                .join(id)
                .join(crate::project_state::MATERIALIZED_FILE)
        };
        assert!(record("beta").is_file());
        assert!(!record("alpha").exists());
    }

    /// A credential goes in, and only its presence ever comes back.
    ///
    /// The value is asserted absent from the whole response body rather than from the field it
    /// would have been put in: a future handler that added `"value"` beside `"present"` would pass
    /// a narrower check, and the point of this one is that no shape of leak passes it.
    #[tokio::test]
    async fn a_credential_is_stored_and_only_its_presence_is_ever_reported() {
        let state = test_state().await;

        let (_, before) = workflow_call(state.clone(), "GET", "/config/secrets", None).await;
        let row = |body: &serde_json::Value| {
            body["secrets"]
                .as_array()
                .unwrap()
                .iter()
                .find(|row| row["key"] == "github-token")
                .unwrap()
                .clone()
        };
        assert_eq!(row(&before)["present"], false);

        let (status, _) = workflow_call(
            state.clone(),
            "PUT",
            "/config/secrets/github-token",
            Some(serde_json::json!({ "value": "ghp_a_real_looking_token" })),
        )
        .await;
        assert_eq!(status, StatusCode::NO_CONTENT);

        let (_, after) = workflow_call(state, "GET", "/config/secrets", None).await;
        assert_eq!(row(&after)["present"], true);
        assert!(
            !after.to_string().contains("ghp_a_real_looking_token"),
            "no route may serve a credential back"
        );
    }

    /// The daemon's own token is not a credential this app may set.
    ///
    /// It is the app's key to the daemon: overwriting it through the API would lock out the caller
    /// making the request, and the recovery is a restart plus a credential the app can no longer be
    /// told. It is absent from `SECRETS`, so it refuses by the ordinary path rather than by a
    /// special case somebody could delete.
    #[tokio::test]
    async fn the_daemon_token_cannot_be_written_through_the_api() {
        let state = test_state().await;
        for method in ["PUT", "DELETE"] {
            let (status, body) = workflow_call(
                state.clone(),
                method,
                "/config/secrets/daemon-token",
                Some(serde_json::json!({ "value": "a-new-token" })),
            )
            .await;
            assert_eq!(status, StatusCode::FORBIDDEN, "{method} must be refused");
            assert_eq!(body["refusal"], "not_ours");
        }

        // And it is not listed either, so nothing invites somebody to try.
        let (_, listing) = workflow_call(state, "GET", "/config/secrets", None).await;
        assert!(!listing.to_string().contains("daemon-token"));
    }

    /// An empty value is refused rather than stored.
    ///
    /// Storing one leaves a credential that exists and does not work, which reads as "configured"
    /// everywhere it is asked about — the worst of the three available states.
    #[tokio::test]
    async fn an_empty_value_is_refused_rather_than_stored() {
        let state = test_state().await;
        let (status, body) = workflow_call(
            state.clone(),
            "PUT",
            "/config/secrets/openrouter-api-key",
            Some(serde_json::json!({ "value": "" })),
        )
        .await;
        assert_eq!(status, StatusCode::UNPROCESSABLE_ENTITY);
        assert_eq!(body["refusal"], "invalid");
        assert!(body["detail"].as_str().unwrap().contains("DELETE"));

        let (_, listing) = workflow_call(state, "GET", "/config/secrets", None).await;
        let row = listing["secrets"]
            .as_array()
            .unwrap()
            .iter()
            .find(|row| row["key"] == "openrouter-api-key")
            .unwrap()
            .clone();
        assert_eq!(row["present"], false, "nothing was stored");
    }

    /// Forgetting is idempotent, because "forgotten" and "was not there" call for the same next
    /// step and a page that had to tell them apart would be asking a question with one answer.
    #[tokio::test]
    async fn forgetting_a_credential_is_idempotent() {
        let state = test_state().await;
        for _ in 0..2 {
            let (status, _) = workflow_call(
                state.clone(),
                "DELETE",
                "/config/secrets/telegram-token",
                None,
            )
            .await;
            assert_eq!(status, StatusCode::NO_CONTENT);
        }
    }

    /// The kill switch stops a credential being written, for the reason it stops a settings write:
    /// the control token reaches here, and a credential is a capability.
    #[tokio::test]
    async fn the_kill_switch_stops_a_credential_being_written() {
        let state = test_state().await;
        let (status, _) = workflow_call(
            state.clone(),
            "POST",
            "/autopilot/kill",
            Some(serde_json::json!({ "engaged": true })),
        )
        .await;
        assert_eq!(status, StatusCode::NO_CONTENT);

        let (status, body) = workflow_call(
            state,
            "PUT",
            "/config/secrets/github-token",
            Some(serde_json::json!({ "value": "ghp_something" })),
        )
        .await;
        assert_eq!(status, StatusCode::LOCKED);
        assert_eq!(body["refusal"], "kill_switch");
    }

    /// A state whose machine-settings root is a directory this test owns.
    ///
    /// The `TempDir` is returned rather than dropped, for the reason the other helpers here give:
    /// its drop is what deletes the directory, so a test that let it fall would be asserting
    /// against a root that had already gone.
    async fn state_with_machine_root() -> (AppState, tempfile::TempDir) {
        let temp = tempfile::tempdir().unwrap();
        let mut state = test_state().await;
        state.machine_config_root = Some(temp.path().to_path_buf());
        (state, temp)
    }

    /// The fence lists every row, including the pillars nobody has ever configured.
    ///
    /// "This has never been set up" is the answer the page most needs and an absent row cannot
    /// give it — the same reason `GET /projects/{id}/ownership` serves claims rather than files.
    /// The resolved path is asserted too, because it is the page's answer to "which file is this",
    /// and so is the `~/.nucleos/` spelling a person is shown instead of a username-bearing one.
    #[tokio::test]
    async fn the_fence_lists_every_setting_including_the_ones_never_configured() {
        let (state, temp) = state_with_machine_root().await;
        let (status, body) = workflow_call(state, "GET", "/config/machine", None).await;
        assert_eq!(status, StatusCode::OK);

        let rows = body["settings"].as_array().unwrap();
        assert_eq!(rows.len(), crate::machine_config::SETTINGS.len());
        for row in rows {
            assert_eq!(row["exists"], false, "{} should not exist yet", row["path"]);
            assert!(row["contents"].is_null());
            assert!(!row["what"].as_str().unwrap().is_empty());
            assert!(!row["takes_effect"].as_str().unwrap().is_empty());
            assert!(
                row["resolved"]
                    .as_str()
                    .unwrap()
                    .starts_with(temp.path().to_str().unwrap()),
                "every row must name the file it would actually write"
            );
            assert_eq!(
                row["display"],
                format!("~/.nucleos/{}", row["path"].as_str().unwrap()),
                "a person is shown the tilde spelling, never a username-bearing path"
            );
        }
        assert_eq!(body["root_display"], "~/.nucleos");
    }

    /// The first write on a machine that has never had a settings directory creates it.
    ///
    /// `~/.nucleos/` exists only once something has been put in it, and `safe_write_target`
    /// canonicalises the root before it answers — so without the route creating it, the very first
    /// setting anybody saved from the page would be refused for a directory nobody was asked for.
    #[tokio::test]
    async fn the_first_write_creates_the_settings_directory() {
        let temp = tempfile::tempdir().unwrap();
        let root = temp.path().join(".nucleos");
        let mut state = test_state().await;
        state.machine_config_root = Some(root.clone());

        let (status, _) = workflow_call(
            state.clone(),
            "POST",
            "/config/machine",
            Some(serde_json::json!({ "path": "calendar.yaml", "contents": "" })),
        )
        .await;
        assert_eq!(status, StatusCode::NO_CONTENT);
        assert!(root.join("calendar.yaml").is_file());

        // And the feed line names the file the way a person is shown it.
        let summary: String = sqlx::query_scalar(
            "SELECT summary FROM feed WHERE kind = 'config_written' ORDER BY id DESC LIMIT 1",
        )
        .fetch_one(&state.pool)
        .await
        .unwrap();
        assert_eq!(summary, "~/.nucleos/calendar.yaml written from the app");
    }

    /// A write lands, and the next read is the file rather than what the caller said it was.
    #[tokio::test]
    async fn a_setting_is_written_and_read_back() {
        let (state, temp) = state_with_machine_root().await;
        let (status, _) = workflow_call(
            state.clone(),
            "POST",
            "/config/machine",
            Some(serde_json::json!({
                "path": "calendar.yaml",
                "contents": "working_hours_start: \"10:00\"\n",
            })),
        )
        .await;
        assert_eq!(status, StatusCode::NO_CONTENT);

        // On disk, under the root the state named — not merely in the answer.
        let written = std::fs::read_to_string(temp.path().join("calendar.yaml")).unwrap();
        assert!(written.contains("10:00"));

        let (_, body) = workflow_call(state, "GET", "/config/machine", None).await;
        let row = body["settings"]
            .as_array()
            .unwrap()
            .iter()
            .find(|row| row["path"] == "calendar.yaml")
            .unwrap()
            .clone();
        assert_eq!(row["exists"], true);
        assert!(row["contents"].as_str().unwrap().contains("10:00"));
    }

    /// A file that does not parse is refused, and — the half that matters — the good file that was
    /// already there is still there.
    ///
    /// Validate-then-write is the whole contract of this route. A route that wrote first and
    /// validated after would turn one bad keystroke into a pillar that stays off after the next
    /// restart, and the loaders are fail-soft precisely so that nobody would be told.
    #[tokio::test]
    async fn a_file_that_does_not_parse_is_refused_and_the_old_one_survives() {
        let (state, temp) = state_with_machine_root().await;
        let good = "enabled: true\nmax_sessions: 3\n";
        let (status, _) = workflow_call(
            state.clone(),
            "POST",
            "/config/machine",
            Some(serde_json::json!({ "path": "browser.yaml", "contents": good })),
        )
        .await;
        assert_eq!(status, StatusCode::NO_CONTENT);

        let (status, body) = workflow_call(
            state,
            "POST",
            "/config/machine",
            Some(serde_json::json!({
                "path": "browser.yaml",
                "contents": "max_sessions: \"not a number\"\n",
            })),
        )
        .await;
        assert_eq!(status, StatusCode::UNPROCESSABLE_ENTITY);
        assert_eq!(body["refusal"], "invalid");
        // The parser's own words, so somebody can fix the line rather than guess at it.
        assert!(!body["detail"].as_str().unwrap().is_empty());

        assert_eq!(
            std::fs::read_to_string(temp.path().join("browser.yaml")).unwrap(),
            good,
            "a refused write must not have touched the file"
        );
    }

    /// A path this machine does not configure is refused, whichever way it is spelled.
    ///
    /// The three here are three different mistakes: a file that belongs to the `.ai/` workflow
    /// harness, a file that is a PROJECT's and has its own door, and traversal. All three get
    /// `not_ours` because from this route's point of view they are the same answer — the table
    /// does not name them.
    #[tokio::test]
    async fn a_path_this_machine_does_not_configure_is_refused() {
        let (state, temp) = state_with_machine_root().await;
        for path in [
            ".ai/project.yaml",
            // A project's rules, by the name the project door knows them and by where they sit
            // under this same root. Neither is this machine's; the project door writes them.
            "autopilot.yaml",
            "projects/alpha/autopilot.yaml",
            "../voice.yaml",
            // The spelling every row had before the files moved to `~/.nucleos/`. A caller still
            // sending it would be writing a file the daemon no longer reads.
            ".ai/voice.yaml",
        ] {
            let (status, body) = workflow_call(
                state.clone(),
                "POST",
                "/config/machine",
                Some(serde_json::json!({ "path": path, "contents": "enabled: true\n" })),
            )
            .await;
            assert_eq!(status, StatusCode::FORBIDDEN, "{path} must be refused");
            assert_eq!(body["refusal"], "not_ours");
        }
        assert!(
            std::fs::read_dir(temp.path()).unwrap().next().is_none(),
            "a refused write must not have created so much as a directory"
        );
    }

    /// The kill switch stops a settings write, and the reason is not symmetry with the project
    /// route — it is that the control token reaches here and `assistant.rs` hands that token to an
    /// MCP-only assistant turn. `~/.nucleos/github.yaml` names what a run may do without asking.
    #[tokio::test]
    async fn the_kill_switch_stops_a_settings_write() {
        let (state, _temp) = state_with_machine_root().await;
        let (status, _) = workflow_call(
            state.clone(),
            "POST",
            "/autopilot/kill",
            Some(serde_json::json!({ "engaged": true })),
        )
        .await;
        assert_eq!(status, StatusCode::NO_CONTENT);

        let (status, body) = workflow_call(
            state,
            "POST",
            "/config/machine",
            Some(serde_json::json!({ "path": "calendar.yaml", "contents": "" })),
        )
        .await;
        assert_eq!(status, StatusCode::LOCKED);
        assert_eq!(body["refusal"], "kill_switch");
    }

    /// Without a root, both routes refuse by name rather than guessing at one.
    ///
    /// A daemon on a machine with no home directory has nowhere these files belong, and picking some
    /// other directory — the working one, say, which is where they used to be — would be editing a
    /// file the daemon does not read.
    #[tokio::test]
    async fn without_a_root_every_settings_route_refuses() {
        let state = test_state().await;
        assert!(state.machine_config_root.is_none());

        let (status, body) = workflow_call(state.clone(), "GET", "/config/machine", None).await;
        assert_eq!(status, StatusCode::INTERNAL_SERVER_ERROR);
        assert_eq!(body["refusal"], "no_machine_root");

        let (status, body) = workflow_call(
            state,
            "POST",
            "/config/machine",
            Some(serde_json::json!({ "path": "calendar.yaml", "contents": "" })),
        )
        .await;
        assert_eq!(status, StatusCode::INTERNAL_SERVER_ERROR);
        assert_eq!(body["refusal"], "no_machine_root");
    }

    /// An installed workflow's declared file is in the fence and cannot be written from here.
    ///
    /// §12's middle state, end to end: `writable: false` on the row, and `another_author` rather
    /// than `not_ours` from the write route. The two refusals send somebody to two different
    /// places — one file has nobody this app writes as, the other has an author standing right
    /// there — so collapsing them would be the page telling somebody to give up on a file that has
    /// an owner they can go and edit.
    #[tokio::test]
    async fn a_workflows_own_file_is_shown_in_the_fence_and_refused_by_the_write_route() {
        let mut state = test_state().await;
        let (_lib, library) = library_with(&[(
            "harness",
            "1.0",
            "description: the .ai harness\nowns:\n  - .ai/models.yaml\n",
        )]);
        state.workflow_library = Some(library);
        let _home = with_project_home(&mut state);
        let _dir = project_with_rules(&state, "alpha", "gate_command: cargo test\n").await;

        workflow_call(
            state.clone(),
            "POST",
            "/projects/alpha/workflows",
            Some(serde_json::json!({ "name": "harness", "version": "1.0" })),
        )
        .await;

        let (_, claims) =
            workflow_call(state.clone(), "GET", "/projects/alpha/ownership", None).await;
        let claims = claims.as_array().unwrap();
        assert_eq!(claims.len(), 3);
        let theirs = claims
            .iter()
            .find(|claim| claim["path"] == ".ai/models.yaml")
            .expect("an installed workflow's file must be in the fence");
        assert_eq!(theirs["owner"], "harness");
        assert_eq!(theirs["writable"], false);

        let (status, body) = workflow_call(
            state.clone(),
            "POST",
            "/projects/alpha/write",
            Some(serde_json::json!({ "path": ".ai/models.yaml", "contents": "plan: opus\n" })),
        )
        .await;
        assert_eq!(status, StatusCode::FORBIDDEN);
        assert_eq!(body["refusal"], "another_author");
        assert!(body["detail"].as_str().unwrap().contains("harness"));

        // And the file the app DOES author still saves, so the refusal above is about authorship
        // rather than about the route having stopped working.
        let (status, _) = workflow_call(
            state,
            "POST",
            "/projects/alpha/write",
            Some(serde_json::json!({ "path": "workflows.yaml", "contents": "workflows: []\n" })),
        )
        .await;
        assert_eq!(status, StatusCode::NO_CONTENT);
    }

    /// Ejecting is a one-way door, and pressing it twice does not walk back through it.
    ///
    /// The edits in an ejected copy are the entire reason it exists. A second eject that
    /// overwrote them would be the one operation here that destroys work, reachable by a
    /// double-click.
    #[tokio::test]
    async fn ejecting_twice_is_a_conflict_and_leaves_the_first_copy_alone() {
        let mut state = test_state().await;
        let (_lib, library) = library_with(&[("harness", "1.0", "description: x\n")]);
        state.workflow_library = Some(library);
        let _home = with_project_home(&mut state);
        let dir = project_with_rules(&state, "alpha", "gate_command: cargo test\n").await;

        workflow_call(
            state.clone(),
            "POST",
            "/projects/alpha/workflows",
            Some(serde_json::json!({ "name": "harness", "version": "1.0" })),
        )
        .await;
        let (status, _) = workflow_call(
            state.clone(),
            "POST",
            "/projects/alpha/workflows/harness/eject",
            None,
        )
        .await;
        assert_eq!(status, StatusCode::NO_CONTENT);

        let mine = dir.path().join(".ai/workflows/harness/graph.yaml");
        std::fs::write(&mine, "# mine now\n").unwrap();

        let (status, body) = workflow_call(
            state.clone(),
            "POST",
            "/projects/alpha/workflows/harness/eject",
            None,
        )
        .await;
        assert_eq!(status, StatusCode::CONFLICT);
        assert_eq!(body["refusal"], "already_ejected");
        assert_eq!(std::fs::read_to_string(&mine).unwrap(), "# mine now\n");

        // And the diff is the thing that now has something to say.
        let (status, diff) =
            workflow_call(state, "GET", "/projects/alpha/workflows/harness/diff", None).await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(diff["origin_version"], "1.0");
        assert_eq!(diff["changes"][0]["path"], "graph.yaml");
        assert_eq!(diff["changes"][0]["change"], "changed");
    }

    /// A referenced workflow has no second copy, so the diff refuses rather than answering "none".
    ///
    /// An empty list would be true and useless: it reads as *your copy matches* to somebody who has
    /// no copy at all.
    #[tokio::test]
    async fn the_diff_refuses_for_a_workflow_this_project_has_no_copy_of() {
        let mut state = test_state().await;
        let (_lib, library) = library_with(&[("harness", "1.0", "description: x\n")]);
        state.workflow_library = Some(library);
        let _home = with_project_home(&mut state);
        let _dir = project_with_rules(&state, "alpha", "gate_command: cargo test\n").await;
        workflow_call(
            state.clone(),
            "POST",
            "/projects/alpha/workflows",
            Some(serde_json::json!({ "name": "harness", "version": "1.0" })),
        )
        .await;

        let (status, body) =
            workflow_call(state, "GET", "/projects/alpha/workflows/harness/diff", None).await;
        assert_eq!(status, StatusCode::NOT_FOUND);
        assert_eq!(body["refusal"], "not_installed");
    }

    /// The stop stops these too, and that is the line `POST /commands` sits on the other side of.
    ///
    /// These put bytes in the project's own folder — one of them copies a whole tree in — which
    /// §7.5 says must go the way an agent's write goes. Declaring a command writes a database row
    /// and touches nothing on disk, so it does not ask.
    #[tokio::test]
    async fn a_workflow_cannot_be_installed_or_ejected_while_the_stop_is_engaged() {
        let mut state = test_state().await;
        let (_lib, library) = library_with(&[("harness", "1.0", "description: x\n")]);
        state.workflow_library = Some(library);
        let _home = with_project_home(&mut state);
        let _dir = project_with_rules(&state, "alpha", "gate_command: cargo test\n").await;
        crate::autopilot::set_kill_switch(&state.pool, true)
            .await
            .unwrap();

        for (method, uri, body) in [
            (
                "POST",
                "/projects/alpha/workflows",
                Some(serde_json::json!({ "name": "harness", "version": "1.0" })),
            ),
            ("POST", "/projects/alpha/workflows/harness/eject", None),
            (
                "POST",
                "/projects/alpha/workflows/harness/update",
                Some(serde_json::json!({})),
            ),
            ("DELETE", "/projects/alpha/workflows/harness", None),
        ] {
            let (status, refused) = workflow_call(state.clone(), method, uri, body).await;
            assert_eq!(status, StatusCode::LOCKED, "{method} {uri}");
            assert_eq!(refused["refusal"], "kill_switch");
        }

        // Reading is not writing: the page still says what this project uses while the stop is on,
        // which is exactly when somebody is trying to work out what would have run.
        let (status, _) = workflow_call(state, "GET", "/projects/alpha/workflows", None).await;
        assert_eq!(status, StatusCode::OK);
    }

    /// A machine with no library says so instead of showing an empty shelf.
    ///
    /// `503` and not `200 []`. Nothing broke — the answer does not exist here — and an empty list
    /// would read as "you have installed nothing", which sends somebody looking for an install
    /// button that cannot work.
    #[tokio::test]
    async fn a_machine_with_no_library_says_so_rather_than_showing_an_empty_shelf() {
        let state = test_state().await;
        let _dir = project_with_rules(&state, "alpha", "gate_command: cargo test\n").await;
        let (status, body) = workflow_call(state, "GET", "/workflows/library", None).await;
        assert_eq!(status, StatusCode::SERVICE_UNAVAILABLE);
        assert_eq!(body["refusal"], "no_library");
    }

    /// The canvas reads the copy that would actually run, and says which one that was.
    ///
    /// An ejected workflow is drawn from the folder in the project. Reading the library's for one
    /// would draw a picture of somebody else's bundle and label it as this project's — and it is
    /// also the difference §6.3 turns on: editing one file affects this project, editing the other
    /// affects every project that references the bundle.
    #[tokio::test]
    async fn the_canvas_reads_the_copy_that_would_actually_run() {
        let mut state = test_state().await;
        let (_lib, library) = library_with(&[("harness", "1.0", "description: x\n")]);
        std::fs::write(library.join("harness/1.0/graph.yaml"), TWO_NODE_GRAPH).unwrap();
        state.workflow_library = Some(library);
        let _home = with_project_home(&mut state);
        let dir = project_with_rules(&state, "alpha", "gate_command: cargo test\n").await;

        workflow_call(
            state.clone(),
            "POST",
            "/projects/alpha/workflows",
            Some(serde_json::json!({ "name": "harness", "version": "1.0" })),
        )
        .await;

        let (status, graph) = workflow_call(
            state.clone(),
            "GET",
            "/projects/alpha/workflows/harness/graph",
            None,
        )
        .await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(graph["source"], "library");
        assert_eq!(graph["nodes"].as_array().unwrap().len(), 2);
        assert_eq!(graph["nodes"][0]["type"], "agent");
        // The gate is a role read off the edges, and nothing branches on this one yet.
        assert_eq!(graph["nodes"][1]["role"], "plain");

        workflow_call(
            state.clone(),
            "POST",
            "/projects/alpha/workflows/harness/eject",
            None,
        )
        .await;
        // The project's copy is now the one that would run, so it is the one that is drawn — and a
        // change to it shows up while the library's is untouched.
        std::fs::write(
            dir.path().join(".ai/workflows/harness/graph.yaml"),
            "nodes:\n  - {id: only, type: agent}\n",
        )
        .unwrap();

        let (_, graph) = workflow_call(
            state,
            "GET",
            "/projects/alpha/workflows/harness/graph",
            None,
        )
        .await;
        assert_eq!(graph["source"], "project");
        assert_eq!(graph["nodes"].as_array().unwrap().len(), 1);
        assert_eq!(graph["nodes"][0]["id"], "only");
    }

    /// §6.2 through the route: the overlay is painted, and what the origin said travels with it.
    #[tokio::test]
    async fn the_overlay_reaches_the_canvas_as_a_seal_and_not_as_a_substitution() {
        let mut state = test_state().await;
        let (_lib, library) = library_with(&[("harness", "1.0", "description: x\n")]);
        std::fs::write(library.join("harness/1.0/graph.yaml"), TWO_NODE_GRAPH).unwrap();
        state.workflow_library = Some(library);
        let _home = with_project_home(&mut state);
        let _dir = project_with_rules(&state, "alpha", "gate_command: cargo test\n").await;

        workflow_call(
            state.clone(),
            "POST",
            "/projects/alpha/workflows",
            Some(serde_json::json!({ "name": "harness", "version": "1.0" })),
        )
        .await;

        // Through the route that writes it, rather than by editing the file in the test: the
        // shape of the pins file is `render_pins`'s business, and a test that hand-indented it
        // would break the day that changed, for a reason that has nothing to do with overlays.
        for (node, body) in [
            ("plan", serde_json::json!({ "model": "haiku" })),
            ("council", serde_json::json!({ "disabled": true })),
        ] {
            let (status, _) = workflow_call(
                state.clone(),
                "POST",
                &format!("/projects/alpha/workflows/harness/nodes/{node}"),
                Some(body),
            )
            .await;
            assert_eq!(status, StatusCode::NO_CONTENT);
        }

        let (status, graph) = workflow_call(
            state,
            "GET",
            "/projects/alpha/workflows/harness/graph",
            None,
        )
        .await;
        assert_eq!(status, StatusCode::OK);

        let plan = &graph["nodes"][0];
        assert_eq!(plan["overridden"], true);
        let model = plan["fields"]
            .as_array()
            .unwrap()
            .iter()
            .find(|field| field["name"] == "model")
            .unwrap();
        assert_eq!(model["value"], "haiku");
        assert_eq!(model["origin"], "opus");

        // An override for a node this bundle does not have is reported, never dropped: it is the
        // only moment somebody learns it stopped applying.
        assert_eq!(graph["orphaned"][0], "council");
    }

    /// A bundle with no graph is a halfway state, not a broken bundle, and it gets its own answer.
    ///
    /// A parse failure would send somebody looking for a syntax error in a file that is not there.
    #[tokio::test]
    async fn a_bundle_with_no_graph_says_so_rather_than_reporting_a_parse_failure() {
        let mut state = test_state().await;
        let (_lib, library) = library_with(&[("harness", "1.0", "description: x\n")]);
        std::fs::remove_file(library.join("harness/1.0/graph.yaml")).unwrap();
        state.workflow_library = Some(library.clone());
        let _home = with_project_home(&mut state);
        let _dir = project_with_rules(&state, "alpha", "gate_command: cargo test\n").await;
        workflow_call(
            state.clone(),
            "POST",
            "/projects/alpha/workflows",
            Some(serde_json::json!({ "name": "harness", "version": "1.0" })),
        )
        .await;

        let (status, body) = workflow_call(
            state.clone(),
            "GET",
            "/projects/alpha/workflows/harness/graph",
            None,
        )
        .await;
        assert_eq!(status, StatusCode::NOT_FOUND);
        assert_eq!(body["refusal"], "no_graph");

        // And one that IS there and will not parse comes back with the parser's words, because a
        // refusal that does not say where the file broke sends somebody to an editor anyway.
        std::fs::write(
            library.join("harness/1.0/graph.yaml"),
            "nodes:\n  - {id: plan, type: agent}\nedges:\n  - {from: plan, to: nowhere}\n",
        )
        .unwrap();
        let (status, body) = workflow_call(
            state,
            "GET",
            "/projects/alpha/workflows/harness/graph",
            None,
        )
        .await;
        assert_eq!(status, StatusCode::UNPROCESSABLE_ENTITY);
        assert_eq!(body["refusal"], "invalid_graph");
        assert!(body["detail"].as_str().unwrap().contains("nowhere"));
    }

    /// §9's second step, end to end: the app looks at a folder and reports what is already in it.
    ///
    /// The harness is the half that matters. This repository's `.ai/` built NucleOS, and an app that
    /// asked for it to be recreated in a graph editor before admitting the project exists would be
    /// asking for a day's work to describe a thing that is sitting right there.
    #[tokio::test]
    async fn a_folder_is_read_for_what_it_already_has_rather_than_interrogated() {
        let state = test_state().await;
        let temp = tempfile::tempdir().unwrap();
        std::fs::create_dir_all(temp.path().join(".ai")).unwrap();
        std::fs::write(temp.path().join(".ai/workflow.md"), "the pipeline").unwrap();
        std::fs::write(
            temp.path().join("package.json"),
            r#"{"scripts": {"test": "vitest run"}}"#,
        )
        .unwrap();

        let (status, found) = workflow_call(
            state,
            "GET",
            &format!(
                "/projects/detect?path={}",
                urlencoding(&temp.path().to_string_lossy())
            ),
            None,
        )
        .await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(found["harnesses"][0]["path"], ".ai");
        assert_eq!(found["commands"][0]["name"], "test");
        assert_eq!(found["commands"][0]["command"], "npm run test");
        // Not a repository is a finding, not a refusal — the last step is what decides whether that
        // matters, because only `active` insists on one.
        assert_eq!(found["is_git"], false);
        assert!(found["taken_by"].is_null());
    }

    /// Adding one folder twice under two names is the mistake nothing else here can catch: neither
    /// name looks wrong on its own, and the folder cannot say it has been claimed.
    #[tokio::test]
    async fn a_folder_this_daemon_already_watches_says_which_project_has_it() {
        let state = test_state().await;
        let dir = project_with_rules(&state, "alpha", "gate_command: cargo test\n").await;

        let (_, found) = workflow_call(
            state,
            "GET",
            &format!(
                "/projects/detect?path={}",
                urlencoding(&dir.path().to_string_lossy())
            ),
            None,
        )
        .await;
        assert_eq!(found["taken_by"], "alpha");
    }

    /// A path that is not there, and one that is not a folder, are two different answers.
    #[tokio::test]
    async fn a_path_that_is_not_a_folder_is_refused_by_name() {
        let state = test_state().await;
        let temp = tempfile::tempdir().unwrap();
        std::fs::write(temp.path().join("a-file"), "x").unwrap();

        for (path, code) in [
            (
                temp.path().join("nowhere").to_string_lossy().into_owned(),
                "no_such_folder",
            ),
            (
                temp.path().join("a-file").to_string_lossy().into_owned(),
                "not_a_folder",
            ),
        ] {
            let (_, body) = workflow_call(
                state.clone(),
                "GET",
                &format!("/projects/detect?path={}", urlencoding(&path)),
                None,
            )
            .await;
            assert_eq!(body["refusal"], code, "{path}");
        }

        // A relative path is refused before the filesystem is touched at all: there is no root it
        // could be relative TO, so resolving it would resolve it against the daemon's own cwd.
        let (_, body) = workflow_call(state, "GET", "/projects/detect?path=.ai", None).await;
        assert_eq!(body["refusal"], "not_absolute");
    }

    /// The mapping the typed reads were missing: a project id in, `owner/name` out.
    ///
    /// Before this route there was no route at all — `Repo::new` was reachable only from
    /// `ReadOp::from_request`, so the repository a read carried was always something the CALLER
    /// named, and a page wanting to show a project's own remote had to invent the mapping. That is
    /// the whole of what this asserts: the daemon now holds it.
    #[tokio::test]
    async fn a_project_says_which_repository_on_github_it_is() {
        let state = test_state().await;
        let dir = project_with_repo(&state, "alpha", "gate_command: cargo test\n").await;
        git_in_project(
            dir.path(),
            &["remote", "add", "origin", "git@github.com:owner/name.git"],
        );

        let (status, body) = workflow_call(state, "GET", "/projects/alpha/github-repo", None).await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(body["state"], "known");
        assert_eq!(body["repo"], "owner/name");
        // The URL travels beside the slug, because they answer different questions: one is what a
        // read is sent, the other is what somebody checks it against when the slug surprises them.
        assert_eq!(body["remote"], "git@github.com:owner/name.git");
    }

    /// The five states that are not a repository on GitHub are five different answers.
    ///
    /// **This is the assertion §5.1 argues for, one layer below the page.** *«um painel vazio é
    /// indistinguível de um repositório sem PRs»* — and a route that collapsed these into one
    /// refusal would make the page's explanation impossible to write, because every one of them
    /// would arrive as the same word. None of them is an error: a project in `off` mode has had its
    /// root cleared, a folder can be moved, `set_project_mode` only insists on a repository for
    /// `active`, a local-only project is a project, and a project on GitLab is a project this app
    /// has nothing to say about.
    #[tokio::test]
    async fn every_reason_a_project_has_no_github_repository_is_its_own_answer() {
        let state = test_state().await;

        // Registered, never pointed anywhere — `charlie`'s shape, and the state `off` leaves behind.
        sqlx::query(
            "INSERT INTO autopilot_state (project_id, mode, project_root) VALUES (?, 'off', NULL)",
        )
        .bind("rootless")
        .execute(&state.pool)
        .await
        .unwrap();

        // A folder that was named and is not there. The directory is deleted after registration, so
        // the row is exactly what a project whose checkout somebody moved looks like.
        let gone = tempfile::tempdir().unwrap();
        let gone_path = gone.path().to_path_buf();
        project_with_rules(&state, "moved", "gate_command: cargo test\n").await;
        sqlx::query("UPDATE autopilot_state SET project_root = ? WHERE project_id = 'moved'")
            .bind(gone_path.join("elsewhere").to_string_lossy().to_string())
            .execute(&state.pool)
            .await
            .unwrap();

        let _plain = project_with_rules(&state, "plain", "gate_command: cargo test\n").await;
        let _local = project_with_repo(&state, "local", "gate_command: cargo test\n").await;
        let elsewhere = project_with_repo(&state, "elsewhere", "gate_command: cargo test\n").await;
        git_in_project(
            elsewhere.path(),
            &[
                "remote",
                "add",
                "origin",
                "https://gitlab.com/owner/name.git",
            ],
        );

        for (project, expected) in [
            ("rootless", "no_root"),
            ("moved", "root_missing"),
            ("plain", "not_a_repository"),
            ("local", "no_remote"),
            ("elsewhere", "not_github"),
        ] {
            let (status, body) = workflow_call(
                state.clone(),
                "GET",
                &format!("/projects/{project}/github-repo"),
                None,
            )
            .await;
            assert_eq!(
                status,
                StatusCode::OK,
                "{project} is a state, not a failure"
            );
            assert_eq!(body["state"], expected, "{project}");
        }

        // And a project the roster has never heard of is the one thing here that IS an error: there
        // is nothing to describe, so there is no state to name.
        let (status, _) = workflow_call(state, "GET", "/projects/ghost/github-repo", None).await;
        assert_eq!(status, StatusCode::NOT_FOUND);
    }

    /// Adopting records a pin and touches nothing in the folder.
    ///
    /// The canvas then says the bundle has no graph, which is true and is the honest halfway state:
    /// the app recognises the way of working that is there without pretending to have parsed it.
    #[tokio::test]
    async fn adopting_the_folder_a_project_already_has_writes_one_pin_and_nothing_else() {
        let mut state = test_state().await;
        let (_lib, library) = library_with(&[]);
        state.workflow_library = Some(library);
        let _home = with_project_home(&mut state);
        let dir = project_with_rules(&state, "alpha", "gate_command: cargo test\n").await;
        // The folder this project already has. Nothing of the app's lives in it any more, so the
        // test makes it rather than finding it made.
        std::fs::create_dir_all(dir.path().join(".ai")).unwrap();
        std::fs::write(dir.path().join(".ai/workflow.md"), "the pipeline").unwrap();

        let (status, _) = workflow_call(
            state.clone(),
            "POST",
            "/projects/alpha/workflows/adopt",
            Some(serde_json::json!({ "name": "harness", "path": ".ai" })),
        )
        .await;
        assert_eq!(status, StatusCode::NO_CONTENT);

        let (_, installed) =
            workflow_call(state.clone(), "GET", "/projects/alpha/workflows", None).await;
        assert_eq!(installed[0]["standing"], "ejected");
        assert_eq!(installed[0]["origin"], "adopted:.ai");
        assert!(installed[0]["origin_hash"].is_null());

        // Untouched: no manifest written into somebody else's folder.
        assert!(!dir.path().join(".ai/bundle.yaml").exists());
        assert_eq!(
            std::fs::read_to_string(dir.path().join(".ai/workflow.md")).unwrap(),
            "the pipeline"
        );

        let (status, body) = workflow_call(
            state,
            "GET",
            "/projects/alpha/workflows/harness/graph",
            None,
        )
        .await;
        assert_eq!(status, StatusCode::NOT_FOUND);
        assert_eq!(body["refusal"], "no_graph");
    }

    /* ----------------------------------------------------- project commands -- */

    async fn declare_command(
        state: AppState,
        id: &str,
        body: serde_json::Value,
    ) -> (StatusCode, serde_json::Value) {
        let response = build_router(state)
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri(format!("/projects/{id}/commands"))
                    .header("Authorization", "Bearer test-token")
                    .header("Content-Type", "application/json")
                    .body(Body::from(body.to_string()))
                    .unwrap(),
            )
            .await
            .unwrap();
        let status = response.status();
        let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
            .await
            .unwrap();
        (
            status,
            serde_json::from_slice(&bytes).unwrap_or(serde_json::Value::Null),
        )
    }

    async fn list_commands(state: AppState, id: &str) -> serde_json::Value {
        let response = build_router(state)
            .oneshot(
                Request::builder()
                    .uri(format!("/projects/{id}/commands"))
                    .header("Authorization", "Bearer test-token")
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
            .await
            .unwrap();
        serde_json::from_slice(&bytes).unwrap_or(serde_json::Value::Null)
    }

    async fn run_command(
        state: AppState,
        id: &str,
        command_id: i64,
    ) -> (StatusCode, serde_json::Value) {
        let response = build_router(state)
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri(format!("/projects/{id}/commands/{command_id}/run"))
                    .header("Authorization", "Bearer test-token")
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        let status = response.status();
        let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
            .await
            .unwrap();
        (
            status,
            serde_json::from_slice(&bytes).unwrap_or(serde_json::Value::Null),
        )
    }

    /// Waits for a command's row to stop saying `running`.
    ///
    /// The route answers 202 and the work happens on a spawned task, which is the whole design — so
    /// a test that asserted immediately would be asserting the claim rather than the result. Bounded
    /// at ten seconds: the commands below are `git --version` and a program that does not exist.
    async fn settled(
        state: &AppState,
        id: &str,
        command_id: i64,
    ) -> crate::project_commands::LastRun {
        for _ in 0..200 {
            if let Ok(Some(row)) = crate::project_commands::get(&state.pool, id, command_id).await
                && let Some(last) = row.last
                && last.outcome != crate::project_commands::Outcome::Running
            {
                return last;
            }
            tokio::time::sleep(std::time::Duration::from_millis(50)).await;
        }
        panic!("the command never settled");
    }

    /// Declared, listed, run, and forgotten — with the verdict and the feed line the run leaves
    /// behind.
    ///
    /// `git --version` rather than `echo`, and the choice is not incidental: on Windows the only
    /// real `echo.exe` is Git's and it is on PATH only if somebody put it there, which is already
    /// the documented cause of five confusing failures in this suite. `git` is required by every
    /// test in `inspect.rs`, so a machine that cannot run this one could not run those either.
    #[tokio::test]
    async fn a_command_is_declared_run_and_recorded_with_what_it_said() {
        let state = test_state().await;
        let _dir = project_with_rules(&state, "alpha", "gate_command: cargo test\n").await;

        let (status, body) = declare_command(
            state.clone(),
            "alpha",
            serde_json::json!({ "name": "version", "command": "git --version", "is_gate": true }),
        )
        .await;
        assert_eq!(status, StatusCode::OK);
        let command_id = body["id"].as_i64().unwrap();

        // Listed, with no result at all — which is not a result of zero and not a failure.
        let listed = list_commands(state.clone(), "alpha").await;
        assert_eq!(listed.as_array().unwrap().len(), 1);
        assert_eq!(listed[0]["name"], "version");
        assert_eq!(listed[0]["is_gate"], true);
        assert!(listed[0]["last"].is_null());
        // Absent from the request, so the safe default: only a person.
        assert_eq!(listed[0]["runnable_by"], "person");

        let (status, _) = run_command(state.clone(), "alpha", command_id).await;
        assert_eq!(
            status,
            StatusCode::ACCEPTED,
            "the answer comes before the work"
        );

        let last = settled(&state, "alpha", command_id).await;
        assert_eq!(last.outcome, crate::project_commands::Outcome::Passed);
        assert_eq!(last.exit_code, Some(0));
        assert!(last.ended_at.is_some());

        let summary: String = sqlx::query_scalar(
            "SELECT summary FROM feed WHERE project_id = 'alpha' AND kind = 'command_finished'",
        )
        .fetch_one(&state.pool)
        .await
        .unwrap();
        assert_eq!(summary, "version passed");

        let response = build_router(state.clone())
            .oneshot(
                Request::builder()
                    .method("DELETE")
                    .uri(format!("/projects/alpha/commands/{command_id}"))
                    .header("Authorization", "Bearer test-token")
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::NO_CONTENT);
        assert!(
            list_commands(state, "alpha")
                .await
                .as_array()
                .unwrap()
                .is_empty()
        );
    }

    /// A command that could not start is `errored`, never `failed` — the distinction the whole
    /// outcome enum exists for. A missing binary says nothing about whether the project works, and
    /// reporting it as a failure would stop the wrong work.
    #[tokio::test]
    async fn a_command_that_could_not_start_is_errored_and_never_failed() {
        let state = test_state().await;
        let _dir = project_with_rules(&state, "alpha", "gate_command: cargo test\n").await;

        let (_, body) = declare_command(
            state.clone(),
            "alpha",
            serde_json::json!({
                "name": "ghost",
                "command": "nucleos-no-such-program --please",
            }),
        )
        .await;
        let command_id = body["id"].as_i64().unwrap();

        assert_eq!(
            run_command(state.clone(), "alpha", command_id).await.0,
            StatusCode::ACCEPTED
        );
        let last = settled(&state, "alpha", command_id).await;
        assert_eq!(last.outcome, crate::project_commands::Outcome::Errored);
        // No exit code at all, because there was no process to exit.
        assert_eq!(last.exit_code, None);
        assert!(last.output.unwrap().contains("failed to start"));

        let summary: String = sqlx::query_scalar(
            "SELECT summary FROM feed WHERE project_id = 'alpha' AND kind = 'command_finished'",
        )
        .fetch_one(&state.pool)
        .await
        .unwrap();
        assert_eq!(summary, "ghost could not be measured");
    }

    /// A declaration that could only ever fail is refused while the person who typed it is looking
    /// at it, and the refusal says which part was wrong.
    #[tokio::test]
    async fn a_declaration_that_could_never_run_is_refused_with_the_reason() {
        let state = test_state().await;
        let _dir = project_with_rules(&state, "alpha", "gate_command: cargo test\n").await;

        for (body, expected) in [
            (
                serde_json::json!({ "name": "", "command": "git --version" }),
                "needs a name",
            ),
            (
                serde_json::json!({ "name": "x", "command": "  " }),
                "something to run",
            ),
            (
                serde_json::json!({ "name": "x", "command": "bash -c \"cargo test" }),
                "quote",
            ),
            (
                serde_json::json!({ "name": "x", "command": "git --version", "cwd": "../elsewhere" }),
                "inside the project",
            ),
        ] {
            let (status, refused) = declare_command(state.clone(), "alpha", body).await;
            assert_eq!(status, StatusCode::UNPROCESSABLE_ENTITY);
            assert_eq!(refused["refusal"], "invalid");
            let detail = refused["detail"].as_str().unwrap();
            assert!(detail.contains(expected), "got: {detail}");
        }

        // A folder that is spelled safely and is simply not there is a different refusal, because
        // it is a different thing to fix.
        let (status, refused) = declare_command(
            state.clone(),
            "alpha",
            serde_json::json!({ "name": "x", "command": "git --version", "cwd": "nowhere" }),
        )
        .await;
        assert_eq!(status, StatusCode::UNPROCESSABLE_ENTITY);
        assert_eq!(refused["refusal"], "cwd_missing");

        assert!(
            list_commands(state, "alpha")
                .await
                .as_array()
                .unwrap()
                .is_empty()
        );
    }

    /// The emergency stop stops a button spawning a process, which is the least surprising thing an
    /// emergency stop could do. Both brakes, because a project held on its own is held for this too.
    #[tokio::test]
    async fn the_emergency_stop_holds_a_command_the_app_would_run() {
        let state = test_state().await;
        let _dir = project_with_rules(&state, "alpha", "gate_command: cargo test\n").await;
        let (_, body) = declare_command(
            state.clone(),
            "alpha",
            serde_json::json!({ "name": "version", "command": "git --version" }),
        )
        .await;
        let command_id = body["id"].as_i64().unwrap();

        crate::autopilot::set_kill_switch(&state.pool, true)
            .await
            .unwrap();
        let (status, refused) = run_command(state.clone(), "alpha", command_id).await;
        assert_eq!(status, StatusCode::LOCKED);
        assert_eq!(refused["refusal"], "kill_switch");

        crate::autopilot::set_kill_switch(&state.pool, false)
            .await
            .unwrap();
        crate::autopilot::set_scoped_kill(&state.pool, "project", "alpha", true)
            .await
            .unwrap();
        assert_eq!(
            run_command(state.clone(), "alpha", command_id).await.0,
            StatusCode::LOCKED
        );

        // Nothing was claimed, so nothing has a result — the refusal is not a run that failed.
        let row = crate::project_commands::get(&state.pool, "alpha", command_id)
            .await
            .unwrap()
            .unwrap();
        assert_eq!(row.last, None);
    }

    /// Two clicks landing together must not both start the suite in one folder. The claim is a
    /// conditional UPDATE, so the second one loses and is told why.
    #[tokio::test]
    async fn a_command_already_running_is_refused_rather_than_started_twice() {
        let state = test_state().await;
        let _dir = project_with_rules(&state, "alpha", "gate_command: cargo test\n").await;
        let (_, body) = declare_command(
            state.clone(),
            "alpha",
            serde_json::json!({ "name": "version", "command": "git --version" }),
        )
        .await;
        let command_id = body["id"].as_i64().unwrap();

        assert!(
            crate::project_commands::mark_running(&state.pool, "alpha", command_id)
                .await
                .unwrap()
        );
        let (status, refused) = run_command(state.clone(), "alpha", command_id).await;
        assert_eq!(status, StatusCode::CONFLICT);
        assert_eq!(refused["refusal"], "already_running");
    }

    /// A claim the database could not make is a 500, not a `409 already_running`: nothing is
    /// running, and saying so would send the owner looking for a second click.
    #[tokio::test]
    async fn a_claim_the_database_refuses_is_an_error_not_already_running() {
        let state = test_state().await;
        let _dir = project_with_rules(&state, "alpha", "gate_command: cargo test\n").await;
        let (_, body) = declare_command(
            state.clone(),
            "alpha",
            serde_json::json!({ "name": "version", "command": "git --version" }),
        )
        .await;
        let command_id = body["id"].as_i64().unwrap();

        // The read before the claim still works; only the claim's UPDATE fails.
        sqlx::query(
            "CREATE TRIGGER refuse_claim BEFORE UPDATE ON project_commands
             BEGIN SELECT RAISE(ABORT, 'storage refused'); END",
        )
        .execute(&state.pool)
        .await
        .unwrap();

        let (status, refused) = run_command(state.clone(), "alpha", command_id).await;
        assert_eq!(status, StatusCode::INTERNAL_SERVER_ERROR);
        assert_eq!(refused["refusal"], "internal");
    }

    /// Another project's id does not reach this project's command, and a command that is not there
    /// is the same answer — an integer in a URL names nothing on its own.
    #[tokio::test]
    async fn a_command_belongs_to_its_project_and_to_no_other() {
        let state = test_state().await;
        let _alpha = project_with_rules(&state, "alpha", "gate_command: cargo test\n").await;
        let _beta = project_with_rules(&state, "beta", "gate_command: cargo test\n").await;
        let (_, body) = declare_command(
            state.clone(),
            "alpha",
            serde_json::json!({ "name": "version", "command": "git --version" }),
        )
        .await;
        let command_id = body["id"].as_i64().unwrap();

        let (status, refused) = run_command(state.clone(), "beta", command_id).await;
        assert_eq!(status, StatusCode::NOT_FOUND);
        assert_eq!(refused["refusal"], "no_such_command");
        assert!(
            list_commands(state, "beta")
                .await
                .as_array()
                .unwrap()
                .is_empty()
        );
    }

    /// `runnable_by` is enforced against the caller's key, and the handler is called directly
    /// because nothing can reach it as an agent through the router.
    ///
    /// That is the point rather than a workaround: `auth.rs` gives a run's key exactly one route,
    /// so this field is belt and braces today. Calling the handler with the scope a run would carry
    /// is the only way to prove the belt is fastened — and the day a run is given a way in, this is
    /// already the test that says what happens.
    #[tokio::test]
    async fn a_command_marked_for_people_refuses_a_key_that_is_an_agents() {
        let state = test_state().await;
        let _dir = project_with_rules(&state, "alpha", "gate_command: cargo test\n").await;

        let (_, mine) = declare_command(
            state.clone(),
            "alpha",
            serde_json::json!({ "name": "mine", "command": "git --version" }),
        )
        .await;
        let (_, theirs) = declare_command(
            state.clone(),
            "alpha",
            serde_json::json!({
                "name": "theirs",
                "command": "git --version",
                "runnable_by": "agent",
            }),
        )
        .await;

        let refused = post_project_command_run(
            State(state.clone()),
            Extension(crate::auth::Scope::Run(7)),
            Path(("alpha".to_owned(), mine["id"].as_i64().unwrap())),
        )
        .await
        .expect_err("a person-only command must refuse an agent's key");
        assert_eq!(refused.0, StatusCode::FORBIDDEN);
        assert_eq!(refused.1.0["refusal"], "person_only");

        // The one that says agents may, does.
        let allowed = post_project_command_run(
            State(state.clone()),
            Extension(crate::auth::Scope::Run(7)),
            Path(("alpha".to_owned(), theirs["id"].as_i64().unwrap())),
        )
        .await
        .expect("a command marked for agents accepts one");
        assert_eq!(allowed, StatusCode::ACCEPTED);

        // And the human's key opens the person-only one, which is what makes the refusal above
        // about WHO is asking rather than about the command.
        assert_eq!(
            run_command(state, "alpha", mine["id"].as_i64().unwrap())
                .await
                .0,
            StatusCode::ACCEPTED
        );
    }

    /* --------------------------------------- the reach a project declares -- */

    /// Puts a project on the roster with `mode = 'off'` and NO root, which is what
    /// `autopilot::set_project_mode` persists for `Mode::Off`.
    ///
    /// Deliberately the `off` shape rather than `project_with_rules`' `shadow` one: it is the case
    /// `resolve_project_root` would 404, so every test below doubles as proof that these routes ask
    /// the weaker roster question instead. Declaring what a project may do while it is switched off
    /// is the ordinary order of work, not an edge case.
    async fn project_on_the_roster(state: &AppState, id: &str) {
        sqlx::query(
            "INSERT INTO autopilot_state (project_id, mode, project_root) VALUES (?, 'off', NULL)",
        )
        .bind(id)
        .execute(&state.pool)
        .await
        .unwrap();
    }

    /// One request to the twelve, body and all.
    ///
    /// One helper for the DELETEs as well as the POSTs, because a DELETE here carries what it
    /// deletes in the body — a shell prefix is not a safe path segment.
    async fn reach_request(
        state: AppState,
        method: &str,
        path: &str,
        body: Option<serde_json::Value>,
    ) -> (StatusCode, serde_json::Value) {
        let response = api_token_request(state, method, path, "test-token", body).await;
        let status = response.status();
        let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
            .await
            .unwrap();
        (
            status,
            serde_json::from_slice(&bytes).unwrap_or(serde_json::Value::Null),
        )
    }

    /// The prefixes on one side of a project's shell list, out of the ROWS `GET /shell-rules` serves.
    ///
    /// The route serves a row per rule rather than two lists of prefixes — `ShellRuleView` argues
    /// why. Every assertion below that only ever cared *which side a prefix landed on* still asks
    /// exactly that, through here, instead of thirteen restatements of the wire shape. The tests
    /// that are about the shape itself read the fields directly.
    fn prefixes_on<'a>(listed: &'a serde_json::Value, verdict: &str) -> Vec<&'a str> {
        listed
            .as_array()
            .expect("the shell rules route serves an array of rules")
            .iter()
            .filter(|rule| rule["verdict"] == verdict)
            .map(|rule| rule["prefix"].as_str().expect("every rule names a prefix"))
            .collect()
    }

    /// Declared, listed on its own side, and withdrawn — with the fold visible in what comes back.
    ///
    /// The prefixes are typed mixed-case and double-spaced on purpose. What the route serves is what
    /// is ENFORCED, and `project_policy::fold_prefix` is the reason those are the same string; a GET
    /// that echoed the typed spelling would show an owner a `Remove-Item` the classifier knows only
    /// as `remove-item`.
    #[tokio::test]
    async fn a_declared_shell_rule_comes_back_folded_and_then_goes() {
        let state = test_state().await;
        project_on_the_roster(&state, "alpha").await;

        for body in [
            serde_json::json!({ "prefix": "bash scripts/gates.sh", "verdict": "allow" }),
            serde_json::json!({
                "prefix": "  Remove-Item   -Recurse ",
                "verdict": "deny",
                "note": "never from a worktree",
            }),
        ] {
            let (status, _) = reach_request(
                state.clone(),
                "POST",
                "/projects/alpha/shell-rules",
                Some(body),
            )
            .await;
            assert_eq!(status, StatusCode::NO_CONTENT);
        }

        // The fold is visible in what comes back, on the side each rule was declared on.
        let (status, listed) =
            reach_request(state.clone(), "GET", "/projects/alpha/shell-rules", None).await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(prefixes_on(&listed, "allow"), ["bash scripts/gates.sh"]);
        assert_eq!(prefixes_on(&listed, "deny"), ["remove-item -recurse"]);

        // Declared again with the OTHER verdict, which has to MOVE the prefix from one list to the
        // other: the identity of a rule is the prefix it names, so changing your mind is an EDIT.
        //
        // What `DO UPDATE` prevents is not a second row: the unique index on (project_id, prefix)
        // cannot hold two, so the two ways of losing it both end somewhere else. With no
        // `ON CONFLICT` clause at all it is `UNIQUE constraint failed` — loud, and a 500. With
        // `DO NOTHING`, which is what `declare_github_op` and `declare_land_target` both spell and
        // therefore what anyone harmonising the three would reach for, it is SILENT: the first
        // verdict stands, and the caller is told 204 over a change that did not happen. This assert
        // is the one that catches the silent half, which is why it is written on the side the prefix
        // has to LEAVE rather than on the side it has to arrive at.
        //
        // Asserted through the route rather than only at `project_policy`'s level, because the
        // handler is the layer that decides what a caller sees when a rule is redeclared.
        let (status, _) = reach_request(
            state.clone(),
            "POST",
            "/projects/alpha/shell-rules",
            Some(serde_json::json!({ "prefix": "bash scripts/gates.sh", "verdict": "deny" })),
        )
        .await;
        assert_eq!(status, StatusCode::NO_CONTENT);

        let (_, listed) =
            reach_request(state.clone(), "GET", "/projects/alpha/shell-rules", None).await;
        assert!(
            prefixes_on(&listed, "allow").is_empty(),
            "a redeclared prefix has to LEAVE the side it was on, not sit on both"
        );
        assert_eq!(
            prefixes_on(&listed, "deny"),
            ["bash scripts/gates.sh", "remove-item -recurse"]
        );

        // Withdrawn under a THIRD spelling of the same rule, which is the only way to show that the
        // DELETE's `WHERE` and the table's key are computed by the same fold. A `forget` that only
        // trimmed would match nothing here and answer 404 over a rule that is plainly there.
        let (status, _) = reach_request(
            state.clone(),
            "DELETE",
            "/projects/alpha/shell-rules",
            Some(serde_json::json!({ "prefix": "REMOVE-ITEM  -recurse" })),
        )
        .await;
        assert_eq!(status, StatusCode::NO_CONTENT);

        let (_, listed) =
            reach_request(state.clone(), "GET", "/projects/alpha/shell-rules", None).await;
        assert!(prefixes_on(&listed, "allow").is_empty());
        assert_eq!(prefixes_on(&listed, "deny"), ["bash scripts/gates.sh"]);

        // And withdrawing it a second time is a 404, not a 204. A 204 over a delete that matched
        // nothing is the daemon agreeing a rule is gone while it goes on deciding.
        let (status, refused) = reach_request(
            state,
            "DELETE",
            "/projects/alpha/shell-rules",
            Some(serde_json::json!({ "prefix": "remove-item -recurse" })),
        )
        .await;
        assert_eq!(status, StatusCode::NOT_FOUND);
        assert_eq!(refused["refusal"], "no_such_rule");
    }

    /// **The note comes back off the GET, and so does the day the rule was declared.**
    ///
    /// `POST` has always taken a `note`; the GET served two lists of prefixes, so the column
    /// migration `0128` calls "a única defesa contra uma lista que daqui a seis meses ninguém sabe
    /// justificar" could be written and never read. A defence nobody can read defends nothing — and
    /// it left a trap with no way out of it from a client: `declare_shell_rule` rewrites the note on
    /// every declaration, so an editor changing a verdict must send the existing note back, and had
    /// no route to fetch it from.
    ///
    /// **`created_at` is asserted across a redeclaration, and that is the assertion worth having.**
    /// The seeded row carries a date nothing that runs today could produce, so a `DO UPDATE` that
    /// touched the column would be caught — where two writes a second apart would agree either way
    /// and pin nothing. What it pins is the caption: this is when the prefix was FIRST declared, and
    /// a page labelling it "last changed" would be inventing a fact the daemon does not hold.
    #[tokio::test]
    async fn a_rules_note_and_the_day_it_was_declared_come_back() {
        let state = test_state().await;
        project_on_the_roster(&state, "alpha").await;

        // Raw SQL rather than the route, for the `created_at` half: the column is written by
        // `datetime('now')` and only a value from outside today can show that a redeclaration
        // leaves it alone.
        sqlx::query(
            "INSERT INTO project_shell_rules (project_id, prefix, verdict, note, created_at)
             VALUES ('alpha', 'cargo fmt', 'allow', 'formatting cannot break anything',
                     '2020-01-01 00:00:00')",
        )
        .execute(&state.pool)
        .await
        .unwrap();

        // A second rule declared through the route with NO note at all, because "nobody said why"
        // is a real state of the column and has to be distinguishable from a shape a page could not
        // parse.
        let (status, _) = reach_request(
            state.clone(),
            "POST",
            "/projects/alpha/shell-rules",
            Some(serde_json::json!({ "prefix": "git push", "verdict": "deny" })),
        )
        .await;
        assert_eq!(status, StatusCode::NO_CONTENT);

        let (status, listed) =
            reach_request(state.clone(), "GET", "/projects/alpha/shell-rules", None).await;
        assert_eq!(status, StatusCode::OK);

        let rules = listed.as_array().unwrap();
        assert_eq!(rules.len(), 2);

        // `ORDER BY tool, prefix`, and both rules are about a command, so `cargo fmt` is first. The
        // row is asserted WHOLE: the five fields together are what makes a rule editable without
        // losing anything, and asserting the note alone would pass a shape that had dropped the
        // verdict. `tool` is `null` here and it is asserted rather than skipped — a rule about a
        // command has no tool, and an omitted field is a shape a page would have to guess at.
        assert_eq!(
            rules[0],
            serde_json::json!({
                "prefix": "cargo fmt",
                "tool": serde_json::Value::Null,
                "verdict": "allow",
                "note": "formatting cannot break anything",
                "created_at": "2020-01-01 00:00:00",
            }),
            "the note is the reason this route serves rows; without it the column is write-only"
        );
        assert_eq!(
            rules[1]["prefix"],
            serde_json::json!("git push"),
            "{listed}"
        );
        assert_eq!(
            rules[1]["note"],
            serde_json::Value::Null,
            "a rule declared with no justification says so with `null`, not by omitting the field"
        );
        assert!(
            !rules[1]["created_at"].as_str().unwrap().is_empty(),
            "every row carries the day it was declared: {listed}"
        );

        // Re-verdicted with the note sent back, which is the operation the missing GET made
        // impossible to do correctly.
        let (status, _) = reach_request(
            state.clone(),
            "POST",
            "/projects/alpha/shell-rules",
            Some(serde_json::json!({
                "prefix": "Cargo  Fmt",
                "verdict": "deny",
                "note": "formatting cannot break anything",
            })),
        )
        .await;
        assert_eq!(status, StatusCode::NO_CONTENT);

        let (_, listed) = reach_request(state, "GET", "/projects/alpha/shell-rules", None).await;
        let rules = listed.as_array().unwrap();
        assert_eq!(rules[0]["verdict"], serde_json::json!("deny"));
        assert_eq!(
            rules[0]["note"],
            serde_json::json!("formatting cannot break anything"),
            "the note a caller read off the GET and sent back has to survive the edit"
        );
        assert_eq!(
            rules[0]["created_at"],
            serde_json::json!("2020-01-01 00:00:00"),
            "`DO UPDATE` sets `verdict` and `note` and nothing else: this column is when the \
             prefix was first declared, not when it was last touched"
        );
    }

    /// A note of nothing is no note, and it is stored as `NULL` rather than as an empty string.
    ///
    /// **Two spellings of one absence is a distinction with nothing behind it, and the page can see
    /// it.** `RuleList` renders `null` as "no justification" and an empty string as a blank space,
    /// so the two rows would read differently while meaning the same thing — and the column exists
    /// to be *"a única defesa contra uma lista que daqui a seis meses ninguém sabe justificar"*,
    /// which an empty string is not. Whitespace goes the same way: a note of three spaces is not a
    /// justification either.
    #[tokio::test]
    async fn a_note_of_nothing_is_stored_as_no_note_at_all() {
        let state = test_state().await;
        project_on_the_roster(&state, "alpha").await;

        for (prefix, note) in [("cargo fmt", ""), ("cargo test", "   ")] {
            let (status, _) = reach_request(
                state.clone(),
                "POST",
                "/projects/alpha/shell-rules",
                Some(serde_json::json!({
                    "prefix": prefix,
                    "verdict": "allow",
                    "note": note,
                })),
            )
            .await;
            assert_eq!(status, StatusCode::NO_CONTENT, "{prefix}");
        }

        let (_, listed) = reach_request(state, "GET", "/projects/alpha/shell-rules", None).await;
        for rule in listed.as_array().unwrap() {
            assert_eq!(
                rule["note"],
                serde_json::Value::Null,
                "an empty justification is an ABSENT one: {rule}"
            );
        }
    }

    /// Both halves of "where a landing may be sent" come from the one route that owns the question.
    ///
    /// **The integration branch is not in `targets`, and that is the shape doing work.** It is
    /// admissible with no row — an empty table means "only the usual place" and never "nowhere" — so
    /// folding it into the list would make it indistinguishable from a declared row, which is the
    /// one thing on that panel that can be closed.
    ///
    /// A project with no folder answers `unknown` rather than refusing: it is on the roster, it has
    /// landing targets, and it simply has nothing to derive a default from.
    #[tokio::test]
    async fn where_a_landing_goes_and_what_else_it_may_name_arrive_together() {
        let state = test_state().await;
        project_on_the_roster(&state, "alpha").await;

        let (status, _) = reach_request(
            state.clone(),
            "POST",
            "/projects/alpha/land-targets",
            Some(serde_json::json!({ "branch": "release/2.0" })),
        )
        .await;
        assert_eq!(status, StatusCode::NO_CONTENT);

        let (status, landing) =
            reach_request(state, "GET", "/projects/alpha/land-targets", None).await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(landing["targets"], serde_json::json!(["release/2.0"]));
        // `project_on_the_roster` records no folder, so there is nothing to ask git — and the arm
        // says so in words rather than answering `null`, which a page cannot caption.
        assert_eq!(landing["integration"]["state"], "unknown");
        assert!(
            landing["integration"]["why"]
                .as_str()
                .unwrap()
                .contains("no folder"),
            "{landing}"
        );
    }

    /// An `allow` the classifier's shape guards would never consult is refused HERE, and the
    /// refusal says which prefix.
    ///
    /// `classify_segment` reads `shell_form_is_readable(&normalized) && rules.allows(&normalized)`,
    /// so a permission of one of these shapes is stored and never fires. That is a rule the owner
    /// believes they wrote and nothing will ever read.
    #[tokio::test]
    async fn an_allow_that_could_never_fire_is_refused_and_named() {
        let state = test_state().await;
        project_on_the_roster(&state, "alpha").await;

        for prefix in [
            "cargo test ; rm -rf /",
            "git log --output=/tmp/x",
            "rg --pre ./payload.sh pattern",
            "find . -exec sh -c 'x' ;",
        ] {
            let (status, refused) = reach_request(
                state.clone(),
                "POST",
                "/projects/alpha/shell-rules",
                Some(serde_json::json!({ "prefix": prefix, "verdict": "allow" })),
            )
            .await;
            assert_eq!(status, StatusCode::UNPROCESSABLE_ENTITY, "{prefix}");
            assert_eq!(refused["refusal"], "unmatchable_prefix", "{prefix}");
            assert!(
                refused["detail"].as_str().unwrap().contains(prefix),
                "the refusal has to name the prefix, or the owner reads source code to \
                 find out what was wrong with it: {refused}"
            );
        }

        // A blank one is its own sentence rather than the same one.
        let (status, refused) = reach_request(
            state.clone(),
            "POST",
            "/projects/alpha/shell-rules",
            Some(serde_json::json!({ "prefix": "   ", "verdict": "allow" })),
        )
        .await;
        assert_eq!(status, StatusCode::UNPROCESSABLE_ENTITY);
        assert_eq!(refused["refusal"], "empty_prefix");

        // Nothing was stored by any of the five.
        let (_, listed) = reach_request(state, "GET", "/projects/alpha/shell-rules", None).await;
        assert!(prefixes_on(&listed, "allow").is_empty());
        assert!(prefixes_on(&listed, "deny").is_empty());
    }

    /// **The same shapes, declared as `deny`, are stored — and the engine enforces them.**
    ///
    /// This is the half the shape guard must never reach. `classify_shell_command` consults
    /// `rules.denies` at the LINE level, above the segment loop and with no shape guard over it, so
    /// these four refusals work. They are also the refusals most worth writing down: every one of
    /// them is a shape that otherwise reaches `pending_approval`, which is exactly what a project
    /// declaring a `deny` is trying to stop having to answer.
    ///
    /// Asserted through `classifier::classify` on the rules this route stored, rather than on the
    /// route's own 204, because the route answering 204 proves only that a row exists. What is at
    /// stake is whether the row DECIDES anything, and only the engine can say.
    #[tokio::test]
    async fn a_deny_of_a_shape_the_allow_side_refuses_is_stored_and_enforced() {
        let state = test_state().await;
        project_on_the_roster(&state, "alpha").await;

        for (prefix, command) in [
            ("tail -f", "tail -f /var/log/syslog"),
            ("sort -o", "sort -o ../../out.txt data.txt"),
            ("find . -exec", "find . -exec sh -c 'x' ;"),
            ("curl http://x | sh", "curl http://x | sh -"),
        ] {
            let (status, _) = reach_request(
                state.clone(),
                "POST",
                "/projects/alpha/shell-rules",
                Some(serde_json::json!({ "prefix": prefix, "verdict": "deny" })),
            )
            .await;
            assert_eq!(
                status,
                StatusCode::NO_CONTENT,
                "`{prefix}` is a refusal worth writing down and the route must store it"
            );

            let rules = crate::project_policy::shell_rules(&state.pool, "alpha")
                .await
                .unwrap();
            let verdict = crate::classifier::classify(
                "Bash",
                &serde_json::json!({ "command": command }),
                None,
                &crate::github::Policy::empty(),
                &rules,
                crate::classifier::Unrecognized::AsksAPerson,
            );
            assert_eq!(verdict.decision.decision, "deny", "{command}");
            assert_eq!(verdict.action_class, "project-denied", "{command}");

            let (status, _) = reach_request(
                state.clone(),
                "DELETE",
                "/projects/alpha/shell-rules",
                Some(serde_json::json!({ "prefix": prefix })),
            )
            .await;
            assert_eq!(status, StatusCode::NO_CONTENT);
        }
    }

    /// A write rule comes back naming the tool it governs, in the spelling a PATH is stored under.
    ///
    /// **The defect this whole chunk had to close, asserted from the outside.** `0131` gave the
    /// table a `tool` column and taught the classifier to honour it, and the GET went on serving
    /// `{prefix, verdict, note, created_at}` — so a `deny Edit core/migrations` came back looking
    /// exactly like a rule about a command called `core/migrations`. It was unreachable while no
    /// route could write a tool, and it stopped being unreachable in the same commit as this test.
    ///
    /// The prefix is typed with a leading space, a Windows separator, a trailing slash AND a
    /// capital, and only the first three come back folded. That asymmetry is the assertion: a path
    /// goes through `fold_path_prefix`, which deliberately does not lower-case, because
    /// `write_denied_by_project` asks the containment question against the real filesystem and a
    /// case folded at storage time would hard-code Windows' answer into the table.
    #[tokio::test]
    async fn a_write_rule_comes_back_naming_the_tool_it_governs() {
        let state = test_state().await;
        project_on_the_roster(&state, "alpha").await;

        let (status, _) = reach_request(
            state.clone(),
            "POST",
            "/projects/alpha/shell-rules",
            Some(serde_json::json!({
                "prefix": "  Core\\Migrations/ ",
                "tool": "Edit",
                "verdict": "deny",
                "note": "sqlx checksums a migration that has already been applied",
            })),
        )
        .await;
        assert_eq!(status, StatusCode::NO_CONTENT);

        let (status, listed) =
            reach_request(state, "GET", "/projects/alpha/shell-rules", None).await;
        assert_eq!(status, StatusCode::OK);
        let rules = listed
            .as_array()
            .expect("the route serves an array of rules");
        assert_eq!(rules.len(), 1);
        assert_eq!(rules[0]["tool"], "Edit");
        assert_eq!(
            rules[0]["prefix"], "Core/Migrations",
            "a path is folded by `fold_path_prefix`, which keeps its case"
        );
        assert_eq!(rules[0]["verdict"], "deny");
        assert_eq!(
            rules[0]["note"],
            "sqlx checksums a migration that has already been applied"
        );
    }

    /// A rule about a command still comes back with the field, saying `null`.
    ///
    /// Asserted as PRESENT-and-null rather than merely not `"Edit"`, because the two shapes are
    /// different promises to a page: an omitted field is one a client has to guess about, and a
    /// `null` says the daemon looked and there is no tool. `serde` would omit it under a
    /// `skip_serializing_if`, which is the one edit that could make this quietly wrong again.
    #[tokio::test]
    async fn a_shell_rule_still_comes_back_with_no_tool_at_all() {
        let state = test_state().await;
        project_on_the_roster(&state, "alpha").await;

        let (status, _) = reach_request(
            state.clone(),
            "POST",
            "/projects/alpha/shell-rules",
            Some(serde_json::json!({ "prefix": "npm ci", "verdict": "allow" })),
        )
        .await;
        assert_eq!(status, StatusCode::NO_CONTENT);

        let (_, listed) = reach_request(state, "GET", "/projects/alpha/shell-rules", None).await;
        let rule = &listed.as_array().expect("an array of rules")[0];
        assert!(
            rule.get("tool").is_some(),
            "the field is SERVED on every row: an absent field is a shape a page has to guess at"
        );
        assert_eq!(rule["tool"], serde_json::Value::Null);
    }

    /// An `allow` that names a tool is refused at the door, and told what would have worked.
    ///
    /// **The rule this chunk is built around, at the only place a person meets it.** The núcleo
    /// enforces it twice already and silently both times: `classify` has no allow branch on a write
    /// path, and `shell_rules` drops such a row on the way out with a log line. Stored, the rule
    /// would leave an owner holding a permission that decides nothing — which is worse than a
    /// refusal, because there is nothing to act on.
    ///
    /// The detail is asserted for the ESCAPE and not only for the complaint: `unmatchable_prefix`
    /// set the house style by naming what would be enforced instead, and a refusal that only says
    /// no sends somebody to read `classifier.rs` to find out what to type next.
    #[tokio::test]
    async fn an_allow_that_names_a_tool_is_refused_and_told_what_would_work() {
        let state = test_state().await;
        project_on_the_roster(&state, "alpha").await;

        let (status, refused) = reach_request(
            state.clone(),
            "POST",
            "/projects/alpha/shell-rules",
            Some(serde_json::json!({
                "prefix": ".ai",
                "tool": "Edit",
                "verdict": "allow",
            })),
        )
        .await;
        assert_eq!(status, StatusCode::UNPROCESSABLE_ENTITY);
        assert_eq!(refused["refusal"], "unenforceable_allow");
        let detail = refused["detail"]
            .as_str()
            .expect("a sentence to put on screen");
        assert!(detail.contains("`Edit`"), "{detail}");
        assert!(detail.contains("`.ai`"), "{detail}");
        assert!(
            detail.contains("`deny`"),
            "the refusal has to say what WOULD be enforced: {detail}"
        );

        // And nothing was written. A 422 over a row that landed anyway is the failure this guard
        // exists to prevent, and only the table can say.
        let (_, listed) = reach_request(state, "GET", "/projects/alpha/shell-rules", None).await;
        assert_eq!(listed.as_array().expect("an array").len(), 0);
    }

    /// A tool this núcleo cannot deny for is refused by name, before the column's CHECK sees it.
    ///
    /// `NotebookEdit` used to be the value worth using here and stopped being one on 2026-09-08,
    /// when it joined `classifier::WRITE_TOOLS`. It moved to the test below rather than being
    /// deleted: a name that crosses from the refused list to the accepted one is the single case
    /// where both halves have to be asserted, or the widening is only half-done in exactly the
    /// way nobody notices — the door opens and the column still says no, or the reverse.
    ///
    /// `Bash` is what remains of the same idea and is the better example anyway: it is a real
    /// tool, it is governed by this file, and its rules are COMMAND rules, so naming it as the
    /// subject of a write rule is a category error somebody will make. The empty string is the
    /// other half — `''` is what the column stores for "no tool", and a client that sent it
    /// explicitly would otherwise have declared a shell rule by a spelling
    /// `DeclaredShellRule::tool` exists to keep out of everyone's hands.
    ///
    /// Refused HERE and not at the table, for `empty_prefix`'s reason: a `CHECK` failure comes back
    /// through the `internal` arm as a 500 that names nothing.
    #[tokio::test]
    async fn a_tool_nobody_can_deny_is_refused_by_name() {
        let state = test_state().await;
        project_on_the_roster(&state, "alpha").await;

        for tool in ["Bash", "edit", ""] {
            let (status, refused) = reach_request(
                state.clone(),
                "POST",
                "/projects/alpha/shell-rules",
                Some(serde_json::json!({
                    "prefix": "core/migrations",
                    "tool": tool,
                    "verdict": "deny",
                })),
            )
            .await;
            assert_eq!(status, StatusCode::UNPROCESSABLE_ENTITY, "{tool}");
            assert_eq!(refused["refusal"], "unknown_tool", "{tool}");
            let detail = refused["detail"].as_str().expect("a sentence");
            assert!(detail.contains(&format!("`{tool}`")), "{detail}");
            // Every tool that DOES exist, named — otherwise the next thing to try is a guess.
            // Read off the list the guard itself asks, so a name added there without being
            // offered in the refusal fails here rather than shipping a sentence one short.
            for governed in crate::classifier::WRITE_TOOLS {
                assert!(detail.contains(&format!("`{governed}`")), "{detail}");
            }
        }

        let (_, listed) = reach_request(state, "GET", "/projects/alpha/shell-rules", None).await;
        assert_eq!(listed.as_array().expect("an array").len(), 0);
    }

    /// Every tool the write chain governs can be named in a rule, and the column agrees.
    ///
    /// The other half of the refusal above, and it exists because the two lists cannot be one:
    /// the guard asks `classifier::WRITE_TOOLS`, the column carries a `CHECK` written in SQL, and
    /// SQL cannot read a Rust const. Nothing but a round trip can tell whether they still agree.
    ///
    /// The loop is over the const rather than over a literal list, so admitting the next write
    /// tool fails HERE — with a 500 from the CHECK that a migration was not written — instead
    /// of in a project six weeks later. That 500 is the failure mode `a_tool_nobody_can_deny` is
    /// positioned to prevent for a REFUSED name; this is the same trap on the accepted side,
    /// where no guard stands in front of the column at all.
    ///
    /// Read back rather than trusted: a 201 over a row that did not land is the mirror of the 422
    /// over a row that did, and only the table can say which happened.
    #[tokio::test]
    async fn every_tool_the_write_chain_governs_can_carry_a_rule() {
        let state = test_state().await;
        project_on_the_roster(&state, "alpha").await;

        for tool in crate::classifier::WRITE_TOOLS {
            let (status, _) = reach_request(
                state.clone(),
                "POST",
                "/projects/alpha/shell-rules",
                Some(serde_json::json!({
                    "prefix": format!("core/{tool}"),
                    "tool": tool,
                    "verdict": "deny",
                })),
            )
            .await;
            assert!(status.is_success(), "{tool}: {status}");
        }

        let (_, listed) = reach_request(state, "GET", "/projects/alpha/shell-rules", None).await;
        let listed = listed.as_array().expect("an array");
        assert_eq!(listed.len(), crate::classifier::WRITE_TOOLS.len());
        for tool in crate::classifier::WRITE_TOOLS {
            assert!(
                listed.iter().any(|rule| rule["tool"] == *tool),
                "{tool} was accepted and is not in the table: {listed:?}"
            );
        }
    }

    /// A path prefix that the fold empties is refused BY NAME, and never by a 500.
    ///
    /// **The one input that could still reach the column's CHECK.** `empty_prefix` guards the raw
    /// trim, which was the whole of it while there was one fold: `fold_prefix` is
    /// `classifier::normalize_command`, and collapsing whitespace cannot empty a string that
    /// survived `trim()`. `fold_path_prefix` can — it rewrites `\` as `/` and only then drops the
    /// trailing `/`, so every spelling below arrives non-empty, passes the trim check and folds to
    /// `""` on its way into `prefix CHECK (prefix <> '')`. That failure comes back through the
    /// `internal` arm as a 500 that names nothing, and a 500 is the one answer this handler's
    /// refusals exist to prevent: the owner is told the núcleo broke when what happened is that
    /// they typed a prefix it cannot store.
    ///
    /// Both halves of the fold are exercised on purpose. `/` reaches the empty through the trailing
    /// strip alone; `\` reaches it only because the rewrite runs FIRST, so a guard written against
    /// `/` alone would pass this test and still 500 on the Windows spelling — which is the spelling
    /// somebody pasting a path on this machine will produce.
    #[tokio::test]
    async fn a_path_prefix_that_folds_to_nothing_is_refused_by_name_and_not_by_a_five_hundred() {
        let state = test_state().await;
        project_on_the_roster(&state, "alpha").await;

        for prefix in ["/", "//", "\\", "\\\\", "///", " / ", "/\\/"] {
            let (status, refused) = reach_request(
                state.clone(),
                "POST",
                "/projects/alpha/shell-rules",
                Some(serde_json::json!({
                    "prefix": prefix,
                    "tool": "Edit",
                    "verdict": "deny",
                })),
            )
            .await;
            assert_eq!(
                status,
                StatusCode::UNPROCESSABLE_ENTITY,
                "`{prefix}` folds to nothing and has to be refused by name, not by a 500: {refused}"
            );
            assert_eq!(refused["refusal"], "empty_prefix", "{prefix}");
            let detail = refused["detail"]
                .as_str()
                .expect("a sentence to put on screen");
            // The house style: name the offending value, then say what would work instead.
            assert!(detail.contains(prefix.trim()), "{detail}");
            assert!(detail.contains("project root"), "{detail}");
        }

        // A path that only LOOKS like one of those keeps working — the guard is about a prefix made
        // of nothing but separators, and `/core` is a directory somebody may well want to close.
        let (status, _) = reach_request(
            state.clone(),
            "POST",
            "/projects/alpha/shell-rules",
            Some(serde_json::json!({
                "prefix": "/core",
                "tool": "Edit",
                "verdict": "deny",
            })),
        )
        .await;
        assert_eq!(status, StatusCode::NO_CONTENT);

        // And nothing but that one landed. A 422 over a row stored anyway is the failure the guard
        // exists to prevent, and only the table can say.
        let (_, listed) = reach_request(state, "GET", "/projects/alpha/shell-rules", None).await;
        let rows = listed.as_array().expect("an array");
        assert_eq!(rows.len(), 1, "{listed}");
        assert_eq!(rows[0]["prefix"], "/core");
    }

    /// A path that could never match is refused the way an unmatchable command is, and for the
    /// same reason said about a different comparison.
    ///
    /// `~`, `$` and `%` are the three `classifier::lands_inside_the_workspace` refuses in a `cd` or
    /// `mkdir` target: nothing expands them on this side of the decision, so `normalize_path` glues
    /// them onto the workspace as ordinary names and the stored refusal is about a directory that
    /// cannot exist. A refusal that cannot match is an ALLOW — the asymmetry `fold_prefix` was
    /// written to close, arrived at from the path side.
    ///
    /// **The other half is the assertion that keeps the guard honest**: a path is not a shell line,
    /// so it is not asked to look like one. `docs/r&d` is a perfectly ordinary directory and
    /// `shell_form_is_readable` refuses it for the `&`, which is why that guard stays on the shell
    /// arm — and a `$` in a COMMAND deny is still stored, because a deny is compared at the line
    /// level with no shape guard above it.
    #[tokio::test]
    async fn a_path_that_could_never_match_is_refused_the_way_an_unmatchable_command_is() {
        let state = test_state().await;
        project_on_the_roster(&state, "alpha").await;

        for prefix in ["~/notes", "$HOME/notes", "%USERPROFILE%/notes"] {
            let (status, refused) = reach_request(
                state.clone(),
                "POST",
                "/projects/alpha/shell-rules",
                Some(serde_json::json!({
                    "prefix": prefix,
                    "tool": "Write",
                    "verdict": "deny",
                })),
            )
            .await;
            assert_eq!(status, StatusCode::UNPROCESSABLE_ENTITY, "{prefix}");
            assert_eq!(refused["refusal"], "unmatchable_prefix", "{prefix}");
            assert!(
                refused["detail"]
                    .as_str()
                    .is_some_and(|detail| detail.contains(prefix)),
                "the refusal names the value: {refused}"
            );
        }

        // A directory whose name a shell would read as two commands is still a directory.
        for body in [
            serde_json::json!({ "prefix": "docs/r&d", "tool": "Edit", "verdict": "deny" }),
            serde_json::json!({ "prefix": "echo $HOME", "verdict": "deny" }),
        ] {
            let (status, _) = reach_request(
                state.clone(),
                "POST",
                "/projects/alpha/shell-rules",
                Some(body.clone()),
            )
            .await;
            assert_eq!(
                status,
                StatusCode::NO_CONTENT,
                "each guard belongs to one kind of prefix and must not reach the other: {body}"
            );
        }
    }

    /// Two rules may share a prefix, and a DELETE that names no tool takes the command one.
    ///
    /// **The row a delete lands on is decided by the tool, and there is no safe default but this
    /// one.** The unique index is `(project_id, tool, prefix)`, so `migrations` as a command and
    /// `migrations` as a path are two rules a project may hold at once. Every DELETE written before
    /// the field existed meant the command — it was the only thing that could be declared — so an
    /// absent tool has to mean exactly that, and never "whichever row sorts first", which is a
    /// delete that lands on a rule nobody named while answering 204.
    ///
    /// The 404s at the end are the other half: with two rules able to share a prefix, "there is no
    /// rule for `migrations`" is a sentence that can be false on the very screen it is read on.
    #[tokio::test]
    async fn a_delete_that_names_no_tool_takes_the_command_rule_and_leaves_the_write_rule() {
        let state = test_state().await;
        project_on_the_roster(&state, "alpha").await;

        for body in [
            serde_json::json!({ "prefix": "migrations", "verdict": "deny" }),
            serde_json::json!({ "prefix": "migrations", "tool": "Edit", "verdict": "deny" }),
        ] {
            assert_eq!(
                reach_request(
                    state.clone(),
                    "POST",
                    "/projects/alpha/shell-rules",
                    Some(body.clone()),
                )
                .await
                .0,
                StatusCode::NO_CONTENT,
                "{body}"
            );
        }

        // Both stand. `ON CONFLICT (project_id, tool, prefix)` names the triple, so the second
        // declaration is not an edit of the first — they are two claims about two different things.
        let (_, listed) =
            reach_request(state.clone(), "GET", "/projects/alpha/shell-rules", None).await;
        assert_eq!(listed.as_array().expect("an array").len(), 2);

        let (status, _) = reach_request(
            state.clone(),
            "DELETE",
            "/projects/alpha/shell-rules",
            Some(serde_json::json!({ "prefix": "migrations" })),
        )
        .await;
        assert_eq!(status, StatusCode::NO_CONTENT);

        let (_, listed) =
            reach_request(state.clone(), "GET", "/projects/alpha/shell-rules", None).await;
        let rules = listed.as_array().expect("an array");
        assert_eq!(rules.len(), 1, "only the command rule was named");
        assert_eq!(rules[0]["tool"], "Edit");

        // Asked again, the command rule is gone and the sentence says so without a tool in it.
        let (status, refused) = reach_request(
            state.clone(),
            "DELETE",
            "/projects/alpha/shell-rules",
            Some(serde_json::json!({ "prefix": "migrations" })),
        )
        .await;
        assert_eq!(status, StatusCode::NOT_FOUND);
        assert_eq!(refused["refusal"], "no_such_rule");
        let detail = refused["detail"].as_str().expect("a sentence");
        assert!(detail.contains("no rule for `migrations`"), "{detail}");

        // A tool that declared nothing here is a 404 that NAMES it, which is what answers "I
        // deleted it and it is still there" — the rule still on screen belongs to the other tool.
        let (status, refused) = reach_request(
            state.clone(),
            "DELETE",
            "/projects/alpha/shell-rules",
            Some(serde_json::json!({ "prefix": "migrations", "tool": "Write" })),
        )
        .await;
        assert_eq!(status, StatusCode::NOT_FOUND);
        assert!(
            refused["detail"]
                .as_str()
                .is_some_and(|detail| detail.contains("`Write` rule")),
            "the 404 names the tool: {refused}"
        );

        // And named, the write rule goes.
        let (status, _) = reach_request(
            state.clone(),
            "DELETE",
            "/projects/alpha/shell-rules",
            Some(serde_json::json!({ "prefix": "migrations", "tool": "Edit" })),
        )
        .await;
        assert_eq!(status, StatusCode::NO_CONTENT);

        let (_, listed) = reach_request(state, "GET", "/projects/alpha/shell-rules", None).await;
        assert_eq!(listed.as_array().expect("an array").len(), 0);
    }

    /// The declarable set is the ops intersected with the ceilings, computed rather than listed.
    ///
    /// Written as an exact set because the exclusion that looks like a bug is the point: `run_logs`
    /// is a `ReadOp` whose argv carries `--log`, which `REFUSED_READ_FLAGS` refuses in a Bash call
    /// and refuses here for the same reason.
    ///
    /// `workflow_list` is in this list and was not, and it moved without this function being
    /// touched: the ceiling always named `gh workflow list`, and adding `ReadOp::WorkflowList` was
    /// the whole change. That is the intersection doing the work it was written to do.
    #[test]
    fn the_declarable_github_ops_are_the_ceilings_intersected_with_the_operations() {
        let mut declarable = declarable_github_ops();
        declarable.sort_unstable();
        assert_eq!(
            declarable,
            vec![
                "issue_close",
                "pr_comment",
                "pr_create",
                "pr_list",
                "run_list",
                "run_rerun",
                "run_status",
                "workflow_list",
                "workflow_run",
            ]
        );

        for excluded in [
            // Decision #7: outside `ACTION_CEILING`, so not even the owner's file can turn it on —
            // and a project able to declare it would be that ceiling with a different door. It is
            // the only `ActOp` kind excluded, and `github::ACTION_CEILING` argues why.
            "api_read",
            // Two reasons, and they were under one label until a reviewer split them. `run_logs`
            // matches `gh run view`, which IS in `READ_CEILING`, and loses on the `--log` its argv
            // carries — the `REFUSED_READ_FLAGS` half of the read ceiling doing its half.
            "run_logs",
            // These two lose earlier and more simply: `gh pr view` and `gh issue view` are not in
            // `READ_CEILING` at all, so no flag analysis is ever reached. Same outcome, different
            // constant, and a comment that blamed `--log` for all three would send whoever changes
            // one of them to the wrong list.
            "pr_view",
            "issue_view",
        ] {
            assert!(
                !declarable.contains(&excluded),
                "{excluded} must not be declarable"
            );
        }
    }

    /// **The set that used to reach the wire only inside a refusal now has a route, and it carries
    /// the operations it says no to as well.**
    ///
    /// Before this, a page building a picker had two options and both were wrong: hardcode the
    /// names, which drifts from the compiled ceilings in silence and in the direction that offers
    /// something the daemon refuses, or POST something invalid and read the list out of
    /// `undeclarable_op`'s prose.
    ///
    /// **The `declarable: true` half is asserted as an EXACT set against `declarable_github_ops`**,
    /// which is the assertion that bites. Serving one extra kind as declarable — `api_read`, say,
    /// which no route and no owner's file can turn on — would put a control on screen for something
    /// outside `ACTION_CEILING`, and a `contains` check would let it through.
    ///
    /// The `declarable: false` half is asserted by name because it is the reason the route serves
    /// every operation rather than the admitted ones alone: an operation outside the ceiling has to
    /// be showable as a FACT — it exists, it is refused, and nothing on that screen decides it.
    #[tokio::test]
    async fn the_declarable_ops_route_carries_the_ceilings_verdict_on_every_operation() {
        let state = test_state().await;

        let (status, listed) = reach_request(state, "GET", "/github/declarable-ops", None).await;
        assert_eq!(status, StatusCode::OK);
        let served = listed.as_array().unwrap();

        // Every operation this núcleo can build is here — the catalogue is `Op::all`, not the
        // admitted subset of it.
        let mut names: Vec<&str> = served
            .iter()
            .map(|op| op["kind"].as_str().unwrap())
            .collect();
        let mut every: Vec<&str> = crate::github::Op::all()
            .iter()
            .map(|op| op.kind())
            .collect();
        names.sort_unstable();
        every.sort_unstable();
        assert_eq!(names, every, "the catalogue has to name every operation");

        let mut admitted: Vec<&str> = served
            .iter()
            .filter(|op| op["declarable"] == serde_json::json!(true))
            .map(|op| op["kind"].as_str().unwrap())
            .collect();
        admitted.sort_unstable();
        let mut expected = declarable_github_ops();
        expected.sort_unstable();
        assert_eq!(
            admitted, expected,
            "what this route calls declarable must be exactly what the POST accepts, or the \
             picker offers something the daemon refuses"
        );

        // The four the ceilings exclude, each present and each flagged false. `api_read` is outside
        // `ACTION_CEILING` entirely; the other three lose in `READ_CEILING`, `run_logs` on the
        // `--log` its argv carries and the two `view`s by never being in the ceiling at all.
        for excluded in ["api_read", "run_logs", "pr_view", "issue_view"] {
            let row = served
                .iter()
                .find(|op| op["kind"] == serde_json::json!(excluded))
                .unwrap_or_else(|| panic!("{excluded} has to be SHOWN, as a fact: {listed}"));
            assert_eq!(row["declarable"], serde_json::json!(false), "{excluded}");
        }

        // Which door each goes through, because the two are not the same promise once declared: a
        // declared read binds the very next decision, a declared action is stored and inert. It is
        // asserted on one of each, and on the pair most likely to be confused — `api_read` reads
        // and is an ACTION, `run_logs` is a read that is not declarable.
        let half = |kind: &str| -> String {
            served
                .iter()
                .find(|op| op["kind"] == serde_json::json!(kind))
                .unwrap()["half"]
                .as_str()
                .unwrap()
                .to_owned()
        };
        assert_eq!(half("api_read"), "action");
        assert_eq!(half("run_logs"), "read");
        assert_eq!(half("pr_comment"), "action");
        assert_eq!(half("run_list"), "read");
    }

    /// The ceiling entry that granted nothing now grants an operation, and the route in accepts it.
    ///
    /// Both halves matter and only together. That `workflow_list` is in the set says the
    /// intersection found it; that `POST /projects/{id}/github-ops` takes it says a project can
    /// actually reach what the owner's ceiling had been offering to nobody.
    #[tokio::test]
    async fn workflow_list_is_declarable_now_that_an_operation_builds_it() {
        assert!(
            declarable_github_ops().contains(&"workflow_list"),
            "`gh workflow list` is in `READ_CEILING` and `ReadOp::WorkflowList` builds it"
        );

        let state = test_state().await;
        project_on_the_roster(&state, "alpha").await;
        let (status, _) = reach_request(
            state.clone(),
            "POST",
            "/projects/alpha/github-ops",
            Some(serde_json::json!({ "op_kind": "workflow_list" })),
        )
        .await;
        assert_eq!(status, StatusCode::NO_CONTENT);

        let (_, listed) = reach_request(state, "GET", "/projects/alpha/github-ops", None).await;
        assert_eq!(listed, serde_json::json!(["workflow_list"]));
    }

    /// Declared, listed, and withdrawn — with the second declaration proving `DO NOTHING`.
    #[tokio::test]
    async fn a_declared_github_op_comes_back_and_then_goes() {
        let state = test_state().await;
        project_on_the_roster(&state, "alpha").await;

        for _ in 0..2 {
            let (status, _) = reach_request(
                state.clone(),
                "POST",
                "/projects/alpha/github-ops",
                Some(serde_json::json!({ "op_kind": "run_list" })),
            )
            .await;
            assert_eq!(
                status,
                StatusCode::NO_CONTENT,
                "declaring the same op twice is a no-op, not a constraint error"
            );
        }

        let (status, listed) =
            reach_request(state.clone(), "GET", "/projects/alpha/github-ops", None).await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(listed, serde_json::json!(["run_list"]));

        let (status, _) = reach_request(
            state.clone(),
            "DELETE",
            "/projects/alpha/github-ops",
            Some(serde_json::json!({ "op_kind": "run_list" })),
        )
        .await;
        assert_eq!(status, StatusCode::NO_CONTENT);

        let (_, listed) =
            reach_request(state.clone(), "GET", "/projects/alpha/github-ops", None).await;
        assert_eq!(listed, serde_json::json!([]));

        let (status, refused) = reach_request(
            state,
            "DELETE",
            "/projects/alpha/github-ops",
            Some(serde_json::json!({ "op_kind": "run_list" })),
        )
        .await;
        assert_eq!(status, StatusCode::NOT_FOUND);
        assert_eq!(refused["refusal"], "no_such_op");
    }

    /// An operation the ceilings do not admit is refused, and the refusal names it.
    #[tokio::test]
    async fn an_op_outside_the_ceilings_is_refused_and_named() {
        let state = test_state().await;
        project_on_the_roster(&state, "alpha").await;

        // `workflow_list` was here while `READ_CEILING` named a prefix no `ReadOp` could build, and
        // `pr_create` while `ACTION_CEILING` excluded it. Both are declarable now and left this list
        // rather than the ceilings leaving them; `api_read` is the one that never moves.
        for op_kind in ["api_read", "pr_view", "run_logs", "not_an_op_at_all"] {
            let (status, refused) = reach_request(
                state.clone(),
                "POST",
                "/projects/alpha/github-ops",
                Some(serde_json::json!({ "op_kind": op_kind })),
            )
            .await;
            assert_eq!(status, StatusCode::UNPROCESSABLE_ENTITY, "{op_kind}");
            assert_eq!(refused["refusal"], "undeclarable_op", "{op_kind}");
            assert!(
                refused["detail"].as_str().unwrap().contains(op_kind),
                "the refusal has to name the op: {refused}"
            );
        }

        // A blank kind gets its own sentence rather than a refusal naming nothing.
        for method in ["POST", "DELETE"] {
            let (status, refused) = reach_request(
                state.clone(),
                method,
                "/projects/alpha/github-ops",
                Some(serde_json::json!({ "op_kind": "  " })),
            )
            .await;
            assert_eq!(status, StatusCode::UNPROCESSABLE_ENTITY, "{method}");
            assert_eq!(refused["refusal"], "empty_op_kind", "{method}");
        }

        let (_, listed) = reach_request(state, "GET", "/projects/alpha/github-ops", None).await;
        assert_eq!(listed, serde_json::json!([]));
    }

