    /// The whole life of a `PUT /notifications/policy`, at the route level: it replaces (never
    /// merges), a refusal names the offending selector, and — the property `replace` not calling
    /// `validate` exists for — a rejected payload leaves the stored policy exactly as it was.
    #[tokio::test]
    async fn a_policy_put_replaces_and_a_refusal_writes_nothing() {
        let state = test_state().await;

        async fn put_policy(
            state: &AppState,
            body: serde_json::Value,
        ) -> (StatusCode, serde_json::Value) {
            let response = build_router(state.clone())
                .oneshot(
                    Request::builder()
                        .method("PUT")
                        .uri("/notifications/policy")
                        .header("Authorization", "Bearer test-token")
                        .header("content-type", "application/json")
                        .body(Body::from(body.to_string()))
                        .unwrap(),
                )
                .await
                .unwrap();
            let status = response.status();
            let body = if status == StatusCode::NO_CONTENT {
                serde_json::Value::Null
            } else {
                json_body(response).await
            };
            (status, body)
        }

        // A brand-new install answers empty arrays, not 404.
        let fresh = get_json(&state, "/notifications/policy").await;
        assert_eq!(fresh, serde_json::json!({"families": [], "kinds": []}));

        // Write a first policy.
        let (status, _) = put_policy(
            &state,
            serde_json::json!({
                "families": [{"selector": "job_", "enabled": false}],
                "kinds": []
            }),
        )
        .await;
        assert_eq!(status, StatusCode::NO_CONTENT);
        let after_first = get_json(&state, "/notifications/policy").await;
        assert_eq!(
            after_first,
            serde_json::json!({
                "families": [{"selector": "job_", "enabled": false}],
                "kinds": []
            })
        );

        // A refusal: an empty selector. Names the scope, and writes nothing.
        let (status, body) = put_policy(
            &state,
            serde_json::json!({
                "families": [{"selector": "", "enabled": true}],
                "kinds": []
            }),
        )
        .await;
        assert_eq!(status, StatusCode::BAD_REQUEST);
        assert_eq!(body["refusal"], "empty_selector");
        // Under `detail`, because that is the key the shell reads beside a `refusal`. Named
        // `message` this field is silently dropped and the page shows the code twice.
        assert!(
            body["detail"]
                .as_str()
                .unwrap_or_default()
                .contains("family"),
            "the refusal must name what it objected to: {body}"
        );
        assert_eq!(
            get_json(&state, "/notifications/policy").await,
            after_first,
            "the refused write left the stored policy untouched"
        );

        // A second, different policy REPLACES rather than merges: the family rule above is gone.
        let (status, _) = put_policy(
            &state,
            serde_json::json!({
                "families": [],
                "kinds": [{"selector": "job_failed", "enabled": true}]
            }),
        )
        .await;
        assert_eq!(status, StatusCode::NO_CONTENT);
        assert_eq!(
            get_json(&state, "/notifications/policy").await,
            serde_json::json!({
                "families": [],
                "kinds": [{"selector": "job_failed", "enabled": true}]
            })
        );
    }

    /// Seeds a project enforcing the judge with ten approved allows and one pending allow, so that
    /// rejecting the pending one takes agreement to 10/11 (under the bar). Returns its verdict id.
    async fn enforcing_project_with_a_pending_allow(pool: &sqlx::SqlitePool) -> i64 {
        sqlx::query(
            "INSERT INTO autopilot_state (project_id, mode, judge) VALUES ('a', 'active', 'enforce')",
        )
        .execute(pool)
        .await
        .unwrap();
        let mut last = 0;
        for index in 0..11 {
            let run_id = sqlx::query(
                "INSERT INTO runs (project_id, prompt, status, mode, created_at)
                 VALUES ('a', 'x', 'completed', 'worktree', '2026-09-27T00:00:00Z')",
            )
            .execute(pool)
            .await
            .unwrap()
            .last_insert_rowid();
            let human = if index < 10 { Some("approve") } else { None };
            last = sqlx::query(
                "INSERT INTO judge_verdicts
                 (run_id, tool_name, tool_input_digest, action_class, classifier_decision, judge,
                  model, questions_version, band, final_decision, human_verdict, created_at)
                 VALUES (?, 'Bash', ?, 'unrecognized', 'pending_approval', 'enforce', 'jev-latest',
                         1, 'allow', 'allow', ?, '2026-09-27T00:00:00Z')",
            )
            .bind(run_id)
            .bind(format!("digest-{index}"))
            .bind(human)
            .execute(pool)
            .await
            .unwrap()
            .last_insert_rowid();
        }
        last
    }

    async fn post_judge_verdict_status(state: AppState, id: i64, verdict: &str) -> StatusCode {
        build_router(state)
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri(format!("/judge-verdicts/{id}/verdict"))
                    .header("Authorization", "Bearer test-token")
                    .header("Content-Type", "application/json")
                    .body(Body::from(
                        serde_json::to_vec(&serde_json::json!({ "verdict": verdict })).unwrap(),
                    ))
                    .unwrap(),
            )
            .await
            .unwrap()
            .status()
    }

    #[tokio::test]
    async fn a_judge_verdict_that_breaks_the_bar_demotes_in_the_same_write() {
        let state = test_state().await;
        let id = enforcing_project_with_a_pending_allow(&state.pool).await;
        let status = post_judge_verdict_status(state.clone(), id, "reject").await;
        assert_eq!(status, StatusCode::NO_CONTENT);
        let judge: String =
            sqlx::query_scalar("SELECT judge FROM autopilot_state WHERE project_id = 'a'")
                .fetch_one(&state.pool)
                .await
                .unwrap();
        assert_eq!(judge, "observe");
        let kinds: Vec<String> = sqlx::query_scalar("SELECT kind FROM feed WHERE project_id = 'a'")
            .fetch_all(&state.pool)
            .await
            .unwrap();
        assert_eq!(kinds, vec!["judge_demoted".to_owned()]);
    }

    /// The verdict and the demotion are one write: when holding the bar fails, nothing is recorded.
    #[tokio::test]
    async fn a_judge_verdict_is_not_recorded_when_holding_the_bar_fails() {
        let state = test_state().await;
        let id = enforcing_project_with_a_pending_allow(&state.pool).await;
        // The demotion's feed line cannot be written, so the demotion fails as a whole.
        sqlx::query("DROP TABLE feed")
            .execute(&state.pool)
            .await
            .unwrap();
        let status = post_judge_verdict_status(state.clone(), id, "reject").await;
        assert_eq!(status, StatusCode::INTERNAL_SERVER_ERROR);
        let human: Option<String> =
            sqlx::query_scalar("SELECT human_verdict FROM judge_verdicts WHERE id = ?")
                .bind(id)
                .fetch_one(&state.pool)
                .await
                .unwrap();
        assert_eq!(human, None);
        let judge: String =
            sqlx::query_scalar("SELECT judge FROM autopilot_state WHERE project_id = 'a'")
                .fetch_one(&state.pool)
                .await
                .unwrap();
        assert_eq!(judge, "enforce");
    }

